window.__CH("c29",["<div class=\"hw\">T, t</div><div class=\"pos\"><i>indecl n</i></div><div class=\"def\">ラテン語アルファベットの第19字.</div>\r\n","<div class=\"hw\">T.</div><div class=\"def\">《略》=<a href=\"entry://Titus\">Titus</a>.</div>\r\n","<div class=\"hw\">Tabae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">タバエ《 (1) Caria の町.(2) Paraetacene の町》.</div>\r\n","<div class=\"hw\">tabella</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[tabula]</div><div class=\"def\"><num>①</num> (小さな)板.</div><div class=\"def\"><num>②</num> 投票札.</div><div class=\"def\"><num>③</num> (通例, 蝋引きした)書字板.</div><div class=\"def\"><num>④</num> (通例 <i>pl</i>)文書《手紙, 契約書, 記録など》</div><div class=\"ex\"><i>tabellae dotis</i> (<author>S<small>UET</small></author>)<span class=\"ext\">持参金契約書.</span></div><div class=\"def\"><num>⑤</num> 掲示[告知]板.</div><div class=\"def\"><num>⑥</num> 描画版;絵.</div><div class=\"def\"><num>⑦</num> (神に感謝するための)奉納額.</div>\r\n","<div class=\"hw\">tabelliō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[tabella]</div><div class=\"def\">(司法)代書人.</div>\r\n","<div class=\"hw\">tabellārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://tabella\">tabella</a>]</div><div class=\"def\"><num>①</num> 投票に関する.</div><div class=\"def\"><num>②</num> 手紙の</div><div class=\"ex\"><i>navis tabellaria</i> (<author>S<small>EN</small></author>)<span class=\"ext\">飛脚船.</span></div><hr><div class=\"hw\">tabellārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 手紙を運ぶ人, 飛脚.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 会計係.</div>\r\n","<div class=\"hw\">taberna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf. </i> trabs]</div><div class=\"def\"><num>①</num> (木造の)小屋.</div><div class=\"def\"><num>②</num> 宿屋, 旅籠<SUB>はたご</SUB></div><div class=\"ex\"><i>Tres Tabernae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">「三軒旅籠」《ローマ市から約50km 南の Appia 街道の宿場》.</span></div><div class=\"def\"><num>③</num> 店;露店, 屋台.</div>\r\n","<div class=\"hw\">tabernula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[taberna]</div><div class=\"def\"><num>①</num> 小屋.</div><div class=\"def\"><num>②</num> 小さな店.</div>\r\n","<div class=\"hw\">tabernāculum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↑<a href=\"entry://taberna\">taberna</a>]</div><div class=\"def\"><num>①</num> テント, 天幕, 幕営<SUB>ばくえい</SUB></div><div class=\"ex\"><i>～ capere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(卜占官が鳥の飛翔を観察するための場所を選んで)天幕を張る.</span></div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(ユダヤ人の)幕屋.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 住居;(魂のすみかとしての)肉体.</div>\r\n","<div class=\"hw\">tabernāria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://tabernārius\">tabernārius<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> <SUP>◇</SUP>(宿屋・商店の)女主人, 女将.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 売春婦.</div><div class=\"def\"><num>③</num> (<i>sc. </i> fabula)低俗な喜劇.</div>\r\n","<div class=\"hw\">tabernārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[taberna]</div><div class=\"def\">低俗な, 下品な.</div><hr><div class=\"hw\">tabernārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">商店主, 商売人.</div>\r\n","<div class=\"hw\">tablīnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://tab(u)līnum\">tabulinum</a>.</div>\r\n","<div class=\"hw\">tabula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 板, 金属板, 石板.</div><div class=\"def\"><num>②</num> (蝋引きの)書字板</div><div class=\"ex\"><i>manum de tabula!</i> (<author>C<small>IC</small></author>)<span class=\"ext\">書字板から手を(離せ), 止め《塾教師の生徒への命令から》.</span></div><div class=\"def\"><num>③</num> (通例 <i>pl</i>)文書;記録;帳簿;遺言書</div><div class=\"ex\"><i>novae tabulae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">借金の帳消し.</span></div><div class=\"def\"><num>④</num> 勘定台, 帳場.</div><div class=\"def\"><num>⑤</num> 競売.</div><div class=\"def\"><num>⑥</num> 掲示[告知]板;(一覧)表.</div><div class=\"def\"><num>⑦</num> (恒久的な布告・記録用の)金属[石]板</div><div class=\"ex\"><i>duodecim tabulae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">十二表法.</span></div><div class=\"def\"><num>⑧</num> 絵, 図;奉納額.</div><div class=\"def\"><num>⑨</num> 遊技盤.</div><div class=\"def\"><num>⑩</num> <SUP>◇</SUP>(衣服の)ひだ, しわ.</div>\r\n","<div class=\"hw\">tabulāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://tabula\">tabula</a>]</div><div class=\"def\">床<SUB>ゆか</SUB>, 床張り.</div>\r\n","<div class=\"hw\">tabulāria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tabula]</div><div class=\"def\"><num>①</num> 記録庫, 文書館.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 記録[文書]保管者の職務.</div>\r\n","<div class=\"hw\">tabulāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tabula]</div><div class=\"def\">木の板の;金属板の.</div>\r\n","<div class=\"hw\">tabulārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tabula]</div><div class=\"def\"><num>①</num> 記録集.</div><div class=\"def\"><num>②</num> 文書館, 記録庫.</div>\r\n","<div class=\"hw\">tabulārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 帳簿係.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 会計官.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>(一種の)公証人.</div>\r\n","<div class=\"hw\">tabulātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[tabula]</div><div class=\"def\">板張り;板材で作った物.</div>\r\n","<div class=\"hw\">tabulātum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tabulātus\">tabulātus</a>]</div><div class=\"def\"><num>①</num> 板張りの床;床板.</div><div class=\"def\"><num>②</num> (家屋などの)階.</div><div class=\"def\"><num>③</num> (樹木の水平に伸びた枝がつくる)層.</div>\r\n","<div class=\"hw\">tabulātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tabula]</div><div class=\"def\">板張りの.</div>\r\n","<div class=\"hw\">tab(u)līnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tabula]</div><div class=\"def\">タブリーヌム《ローマ人の家屋で atrium と peristylum の間にある部屋;一族に関する文書が収蔵され, 絵画や彫像で飾られた》.</div>\r\n","<div class=\"hw\">tabulō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[tabula]</div><div class=\"def\">板を張る.</div>\r\n","<div class=\"hw\">Taburnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">タブルヌス《Samnium の山;オリーブの木が多い;現 Monte Taburno》.</div>\r\n","<div class=\"hw\">tabānus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘昆〙アブ.</div>\r\n","<div class=\"hw\">tacenda</div><div class=\"pos\">-ōrum, <i>n pl</i>(<i>gerundiv</i>)</div><div class=\"ori\">[↓<a href=\"entry://taceō\">taceō</a>]</div><div class=\"def\">口外してはいけないこと, 秘密</div><div class=\"ex\"><i>gravis est culpa ～ loqui</i> (<author>O<small>V</small></author>)<span class=\"ext\">黙すべきことをしゃべるのは重い罪だ.</span></div>\r\n","<div class=\"hw\">taceō</div><div class=\"pos\">-ēre -cuī -citum, <i>intr</i>, <i>tr</i></div><div class=\"def\"><num>①</num> 黙っている, 口を開かない.</div><div class=\"def\"><num>②</num> 話をやめる, 黙る.</div><div class=\"def\"><num>③</num> 静かである[になる].</div><div class=\"def\"><num>④</num> (<i>tr</i>)話さない, ...について口にしない</div><div class=\"ex\"><i>ut alios taceam</i> (<author>O<small>V</small></author>)<span class=\"ext\">他の者たちのことは言わずにおくが(実際は大いに言いたい(逆言法)).</span></div>\r\n","<div class=\"hw\">tachycardia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙頻脈, 頻拍.</div>\r\n","<div class=\"hw\">tachygenesis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘生物〙急速発生.</div>\r\n","<div class=\"hw\">Tacita</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tacitus]</div><div class=\"def\">〘神話〙タキタ《「沈黙の女神」 の意;Lara の異称》.</div>\r\n","<div class=\"hw\">tacitulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[tacitus]</div><div class=\"def\">沈黙している, 無言の.</div>\r\n","<div class=\"hw\">tacitum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tacitus]</div><div class=\"def\"><num>①</num> 沈黙.</div><div class=\"def\"><num>②</num> 秘密.</div>\r\n","<div class=\"hw\">taciturnitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://taciturnus\">taciturnus</a>]</div><div class=\"def\"><num>①</num> 沈黙(を貫くこと);秘密を守ること.</div><div class=\"def\"><num>②</num> 音信[連絡]がないこと.</div>\r\n","<div class=\"hw\">taciturnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://tacitus\">tacitus</a>]</div><div class=\"def\"><num>①</num> 沈黙している, 無言の.</div><div class=\"def\"><num>②</num> 無口の, 寡黙な.</div><div class=\"def\"><num>③</num> 静かな, 音のない.</div>\r\n","<div class=\"hw\">tacitus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[taceo]</div><div class=\"def\"><num>①</num> 黙っている, 無言の;(動物などが)口のきけない.</div><div class=\"def\"><num>②</num> 静かな, 物音ひとつしない.</div><div class=\"def\"><num>③</num> (うちに秘めて)表に出さない</div><div class=\"ex\"><i>tacitum vulnus</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">心の傷.</span></div><div class=\"def\"><num>④</num> 暗黙の</div><div class=\"ex\"><i>adsensiones tacitae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">暗黙の同意.</span></div><div class=\"def\"><num>⑤</num> 秘密の.</div><div class=\"def\"><num>⑥</num> 語られる[議論される]ことのない.</div>\r\n","<div class=\"hw\">Tacitus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">タキトゥス《ローマ人の家名;特に (1) <i>Cornelius ～</i>, ローマの史家(55?‐?120).(2) <i>M. Claudius ～</i>, ローマの皇帝(在位275‐276)》.</div>\r\n","<div class=\"hw\">tacitē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tacitus]</div><div class=\"def\"><num>①</num> 音を立てずに, 静かに.</div><div class=\"def\"><num>②</num> 無言で, 黙って.</div><div class=\"def\"><num>③</num> ひそかに, 内密に;気づかれずに.</div><div class=\"def\"><num>④</num> 暗黙のうちに.</div>\r\n","<div class=\"hw\">tacitō</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"def\">=<a href=\"entry://tacitē\">tacite</a>.</div>\r\n","<div class=\"hw\">tactilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tango]</div><div class=\"def\">触れることができる.</div>\r\n","<div class=\"hw\">tactim</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[tango]</div><div class=\"def\">さわって.</div>\r\n","<div class=\"hw\">tactiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[tango]</div><div class=\"def\">さわる[触れる]こと;触覚.</div>\r\n","<div class=\"hw\">tactor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[tango]</div><div class=\"def\">触れる者.</div>\r\n","<div class=\"hw\">tactus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://tangō\">tango</a>.</div><hr><div class=\"hw\">tactus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> さわる[触れる]こと;触覚.</div><div class=\"def\"><num>②</num> 影響, 作用.</div>\r\n","<div class=\"hw\">Tadius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">タディウス《Augustus 帝時代の画家》.</div>\r\n","<div class=\"hw\">taeda</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 〘植〙マツ(松), 松の木;松林.</div><div class=\"def\"><num>②</num> 松脂<SUB>まつやに</SUB>.</div><div class=\"def\"><num>③</num> 松明<SUB>たいまつ</SUB>.</div><div class=\"def\"><num>④</num> (松明が象徴する)婚礼, 結婚;愛情.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>(犠牲獣の)脂身の小片.</div>\r\n","<div class=\"hw\">taedet</div><div class=\"pos\">-ēre taesum est, <i>tr impers</i></div><div class=\"def\">飽きあきしている, うんざりしている 〈alqm+<i>gen</i>[+<i>inf</i>]〉</div><div class=\"ex\"><i>vos talium civium ～ </i>(<author>C<small>IC</small></author>)<span class=\"ext\">あなたがたはそのような市民たちに辟易しているのだ</span></div><div class=\"ex\"><i>～ jam audire eadem miliens</i> (<author>T<small>ER</small></author>)<span class=\"ext\">同じことを千回も聞くのはもううんざりだ.</span></div>\r\n","<div class=\"hw\">taedeō</div><div class=\"pos\">-ēre -duit, <SUP>◇</SUP><i>intr</i></div><div class=\"def\">いやになる, うんざりする.</div>\r\n","<div class=\"hw\">taedifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[taeda/fero]</div><div class=\"def\">松明<SUB>たいまつ</SUB>を持つ《Ceres 女神の呼称の一つ》.</div>\r\n","<div class=\"hw\">taedium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[taedet]</div><div class=\"def\"><num>①</num> うんざり[飽きあき]していること, 退屈.</div><div class=\"def\"><num>②</num> 不快感, 嫌悪感.</div><div class=\"def\"><num>③</num> 好ましくない品質[状態・物]</div><div class=\"ex\"><i>vetustas oleo ～ adfert</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">古くなると油は傷む.</span></div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 病気.</div>\r\n","<div class=\"hw\">taediō</div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[taedium]</div><div class=\"def\">うんざりしている, 飽きあきしている.</div>\r\n","<div class=\"hw\">taediōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://taedium\">taedium</a>]</div><div class=\"def\"><num>①</num> 退屈な, うんざりさせる.</div><div class=\"def\"><num>②</num> 憂鬱な, 悲しい.</div>\r\n","<div class=\"hw\">taeduit</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://taedeō\">taedeo</a>.</div>\r\n","<div class=\"hw\">Taenara</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"def\">=<a href=\"entry://Taenarum\">Taenarum</a>.</div>\r\n","<div class=\"hw\">Taenaridēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">Taenarum の人(=<a href=\"entry://Hyacinthus\">Hyacinthus</a>).</div>\r\n","<div class=\"hw\">Taenaris</div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">Taenarum の;Sparta の.</div>\r\n","<div class=\"hw\">Taenarius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Taenarum の</div><div class=\"ex\"><i>～ deus</i> (<author>P<small>ROP</small></author>)<span class=\"ext\">=<a href=\"entry://Neptūnus\">Neptunus</a></span></div><div class=\"ex\"><i>Taenaria marita</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Helena\">Helena</a>.</span></div><div class=\"def\"><num>②</num> Laconia(=<a href=\"entry://Sparta\">Sparta</a>)の.</div><div class=\"def\"><num>③</num> 黄泉<SUB>よみ</SUB>の国の入口の, 下界の.</div>\r\n","<div class=\"hw\">Taenarum, -on</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> タエナルム, <SUP>*</SUP>タイナロン《Laconia の岬;Peloponnesus 半島の最南端に位置し, Neptunus の神殿があった;現 Matapan》.</div><div class=\"def\"><num>②</num> 下界, 黄泉の国《その入口が Taenarum 付近にあるといわれたことから》.</div>\r\n","<div class=\"hw\">Taenarus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Taenarum\">Taenarum</a>.</div>\r\n","<div class=\"hw\">taenia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> リボン, 髪ひも.</div><div class=\"def\"><num>②</num> ひも[帯](状のもの).</div><div class=\"def\"><num>③</num> 〘建〙平縁<SUB>ひらぶち</SUB>《ドーリス式円柱でアーキトレーブの一番上の部分》.</div><div class=\"def\"><num>④</num> (ひも状の)寄生虫《条虫など》.</div><div class=\"def\"><num>⑤</num> 岩礁.</div>\r\n","<div class=\"hw\">taeniensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://taenia\">taenia</a>]</div><div class=\"def\">岩礁の上に住んでいる.</div>\r\n","<div class=\"hw\">taeniola</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[taenia]</div><div class=\"def\">細長い一片.</div>\r\n","<div class=\"hw\">taesum est</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://taedet\">taedet</a>.</div>\r\n","<div class=\"hw\">taeter</div><div class=\"pos\">-tra -trum, <i>adj</i></div><div class=\"ori\">[taedet]</div><div class=\"def\"><num>①</num> いやな, 不快な.</div><div class=\"def\"><num>②</num> 忌むべき, 下劣な, けがらわしい.</div>\r\n","<div class=\"hw\">taetritūdō</div><div class=\"pos\">-inis, <i>f</i></div><div class=\"ori\">[taeter]</div><div class=\"def\">忌まわしい状態, 醜悪.</div>\r\n","<div class=\"hw\">taetrum</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i>(<i>neut</i>)</div><div class=\"ori\">[taeter]</div><div class=\"def\">ぞっとするほどに, 忌まわしく.</div>\r\n","<div class=\"hw\">taetrē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://taeter\">taeter</a>]</div><div class=\"def\">忌まわしく;下劣に.</div>\r\n","<div class=\"hw\">taetrō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[taeter]</div><div class=\"def\">けがらわしいものにする, 醜くする.</div>\r\n","<div class=\"hw\">tagax</div><div class=\"pos\">-ācis, <i>adj</i></div><div class=\"ori\">[tago]</div><div class=\"def\">手癖の悪い, 盗癖のある.</div>\r\n","<div class=\"hw\">Tagus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">タグス《Lusitania の川;砂金で有名;現 Tajo》.</div>\r\n","<div class=\"hw\">Tagēs</div><div class=\"pos\">-ētis [-ae], <i>m</i></div><div class=\"def\">〘神話〙タゲース《同胞に卜占<SUB>ぼくせん</SUB>術を教えたとされる Etruria 人》.</div>\r\n","<div class=\"hw\">tagō</div><div class=\"pos\">-ere, <i>tr</i></div><div class=\"def\">《古形》=<a href=\"entry://tangō\">tango</a>.</div>\r\n","<div class=\"hw\">Talas(s)ius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">タラッシウス《婚姻の神》.</div>\r\n","<div class=\"hw\">talas(s)iō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">婚礼時に花嫁にあびせる掛け声.</div>\r\n","<div class=\"hw\">Talaus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙タラウス, <SUP>*</SUP>-オス《Argonautae の一人;Adrastus, Eriphyla の父》.</div>\r\n","<div class=\"hw\">Talaīonidēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">〘伝説〙Talaus の息子(=<a href=\"entry://Adrastus\">Adrastus</a>).</div>\r\n","<div class=\"hw\">Talaīonius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Talaus の血を引く.</div>\r\n","<div class=\"hw\">talcum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘鉱〙タルク, 滑石.</div>\r\n","<div class=\"hw\">talentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">タレント《 (1) ギリシアの衡量単位;地方・年代によって異なるが, Attica 単位では約26.2<i>kg</i>.(2) ギリシアの通貨単位》.</div>\r\n","<div class=\"hw\">talla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">タマネギの皮.</div>\r\n","<div class=\"hw\">talpa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘動〙モグラ.</div>\r\n","<div class=\"hw\">talpīnus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://talpa\">talpa</a>]</div><div class=\"def\">モグラの.</div>\r\n","<div class=\"hw\">talpōna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ブドウの一品種.</div>\r\n","<div class=\"hw\">Talthybius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙タルテュビウス, <SUP>*</SUP>-オス《Agamemnon の伝令使》.</div>\r\n","<div class=\"hw\">tam</div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> この[その]ように, これ[それ]ほどに</div><div class=\"ex\"><i>haec ～ parva civitas</i> (<author>C<small>IC</small></author>)<span class=\"ext\">こんなに小さなこの国.</span></div><div class=\"def\"><num>②</num> </div><div class=\"def\"><num1>⒜</num1> <i>～ ... quam</i> ... ...と同様[同じ程度]に</div><div class=\"ex\"><i>～ esse clemens tyrannus quam rex importunus est</i> (<author>C<small>IC</small></author>)<span class=\"ext\">王が冷酷であるのと同様僭主は慈悲深い.</span></div><div class=\"def\"><num1>⒝</num1> <i>non ～ ... quam</i> ... ...(という)よりはむしろ...</div><div class=\"ex\"><i>non ～ turpe fuit vinci quam contendisse decorum</i> (<author>O<small>V</small></author>)<span class=\"ext\">負けることが恥であるよりはむしろ戦ったことが名誉だった.</span></div><div class=\"def\"><num1>⒞</num1> <i>quam magis</i> ... ～ <i>magis</i> ... ...すればするほど...</div><div class=\"ex\"><i>quam magis adspecto</i>, <i>～ magis est nimbata</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">見れば見るほどつまらない女だ.</span></div><div class=\"def\"><num>③</num> (ut [qui]+<i>subj</i> とともに)</div><div class=\"ex\"><i>non se ～ barbarum esse ut non sciret</i> (<author>C<small>AES</small></author>)<span class=\"ext\">自分は(それを)知らぬほど未開人ではない</span></div><div class=\"ex\"><i>nemo est ～ senex qui se annum non putet posse vivere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あと1年生きられないと考えるほど老いている者はいない.</span></div>\r\n","<div class=\"hw\">tama</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">(手足の)腫<SUB>は</SUB>れ物.</div>\r\n","<div class=\"hw\">tamarix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"def\">〘植〙ギョリュウの木.</div>\r\n","<div class=\"hw\">tamarīcium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">〘植〙ギョリュウ(御柳)の実.</div>\r\n","<div class=\"hw\">tamarīcē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"def\">=<a href=\"entry://tamarix\">tamarix</a>.</div>\r\n","<div class=\"hw\">Tamasos</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">タマソス《Cyprus 島中部の町》.</div>\r\n","<div class=\"hw\">Tamasēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tamasos の.</div>\r\n","<div class=\"hw\">tamdiū, tam diū</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">こんなに長い間;大変長い間.</div>\r\n","<div class=\"hw\">tamen</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">しかし, にもかかわらず;それでも, やはり</div><div class=\"ex\"><i>semper Ajax fortis</i>, <i>fortissimus ～ in furore</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Ajax はいつでも強い, だが怒り狂っているときが最も強い</span></div><div class=\"ex\">(ac [atque], et, sed, at などとともに)<i>difficile factu est</i>, <i>sed conabor ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">実行困難だが, それでも努力してみよう</span></div><div class=\"ex\">(譲歩を表わす句・節を前後に伴って)<i>quamquam abest a culpa</i>, <i>suscipione ～ non caret</i> (<author>C<small>IC</small></author>)<span class=\"ext\">たとえ罰を免れているとはいえ, 依然嫌疑は残っている.</span></div>\r\n","<div class=\"hw\">tamendem</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">それでも, そうだとしても.</div>\r\n","<div class=\"hw\">tamenetsī, tamen etsī</div><div class=\"pos\"><i>conj</i></div><div class=\"def\">=<a href=\"entry://tametsī\">tametsi</a>.</div>\r\n","<div class=\"hw\">Tamesis</div><div class=\"pos\">-is, <i>m</i>, <B>Tamesa</B> -ae, <i>f</i></div><div class=\"def\">タメシス《Britannia 南部の川;現 Thames》.</div>\r\n","<div class=\"hw\">tametsī, tam etsī</div><div class=\"pos\"><i>conj</i></div><div class=\"def\">たとえ...でも;それでもやはり, それにもかかわらず.</div>\r\n","<div class=\"hw\">tamiacus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">国庫(収入)に関する.</div>\r\n","<div class=\"hw\">taminia</div><div class=\"pos\">-ae, <i>adj f</i></div><div class=\"ex\"><i>uva ～</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">tamnus の実.</span></div>\r\n","<div class=\"hw\">tammodo, tam modo</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">今しがた, たった今.</div>\r\n","<div class=\"hw\">tamnus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"def\">〘植〙ヤマノイモ科の蔓草.</div>\r\n","<div class=\"hw\">Tamphiliānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tamphilus の.</div>\r\n","<div class=\"hw\">Tamphilus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">タンピルス《ローマ人の家名;特に (1) <i>Cn. Baebius ～</i>, 法務官(前199), 執政官(前182).(2) <i>M. Baebius ～</i>, (1) の弟;法務官(前192), 執政官(前181)》.</div>\r\n","<div class=\"hw\">tamquam, tanquam</div><div class=\"pos\"><i>adv</i>, <i>conj</i></div><div class=\"def\"><num0>Ⅰ</num0> (<i>adv</i>)</div><div class=\"def\"><num>①</num> (あたかも)...のように, 同じように</div><div class=\"ex\"><i>te ～ oculos amat</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">彼女はあなたを(自分の)目のように愛している</span></div><div class=\"ex\">(sic, ita と呼応して)<i>ex vita ita discedo</i>, <i>～ ex hospitio</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私はあたかも宿をあとにするように人生から去る</span></div><div class=\"ex\">(si+<i>subj</i> とともに)<i>～ si esset consul</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼が執政官でもあるかのように.</span></div><div class=\"def\"><num>②</num> いわば.</div><div class=\"def\"><num>③</num> たとえば.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>conj</i>)〈+<i>subj</i>〉 あたかも...のように</div><div class=\"ex\"><i>～ regina maneret</i> (<author>O<small>V</small></author>)<span class=\"ext\">あたかもまだ女王であるかのように.</span></div>\r\n","<div class=\"hw\">Tamyris</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">=<a href=\"entry://Tomyris\">Tomyris</a>.</div>\r\n","<div class=\"hw\">Tanager</div><div class=\"pos\">-grī, <i>m</i></div><div class=\"def\">タナゲル《Lucania の小川》.</div>\r\n","<div class=\"hw\">Tanagra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">タナグラ《Boeotia の町》.</div>\r\n","<div class=\"hw\">Tanagraeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tanagra の.</div>\r\n","<div class=\"hw\">Tanagricus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Tanagraeus\">Tanagraeus</a>.</div>\r\n","<div class=\"hw\">Tanais</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">タナイス《 (1) Sarmatia の川;現 Don.(2) Tanais (1) 河口の町.(3) Numidia の川》.</div>\r\n","<div class=\"hw\">Tanaquil</div><div class=\"pos\">-īlis, <i>f</i></div><div class=\"def\">タナクゥイル《Tarquinius Priscus の妻;夫を後押ししてローマ第5代の王に即位させた》.</div>\r\n","<div class=\"hw\">Tanaītae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"def\">Tanais (1) 河畔の住民.</div>\r\n","<div class=\"hw\">Tanaīticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tanais (1) の.</div>\r\n","<div class=\"hw\">Tanaītis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"def\">《詩》Tanais (1) のほとりに住む女(=<a href=\"entry://Amazōn\">Amazon</a>).</div>\r\n","<div class=\"hw\">tandem</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tam/-dem]</div><div class=\"def\"><num>①</num> ついに, とうとう, ようやく.</div><div class=\"def\"><num>②</num> (疑問詞とともに)一体全体, 結局, (それ)では</div><div class=\"ex\"><i>quid ～ veremini?</i> (<author>C<small>AES</small></author>)<span class=\"ext\">おまえたちは一体何を恐れるのか</span></div><div class=\"ex\"><i>quousque ～?</i> (<author>C<small>IC</small></author>)<span class=\"ext\">一体全体いつまで.</span></div><div class=\"def\"><num>③</num> つまり, 要するに.</div>\r\n","<div class=\"hw\">Tanfāna, Tamf-</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">タンファーナ《Germania の女神》.</div>\r\n","<div class=\"hw\">tangibilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://tangō\">tangō</a>]</div><div class=\"def\">触れることのできる.</div>\r\n","<div class=\"hw\">tangō</div><div class=\"pos\">-ere tetigī tactum, <i>tr</i></div><div class=\"ori\">[<i>cf. </i> tago, tagax]</div><div class=\"def\"><num>①</num> 触れる, さわる.</div><div class=\"def\"><num>②</num> たたく, 打つ</div><div class=\"ex\"><i>de caelo tactus</i> (<author>C<small>IC</small></author>)<span class=\"ext\">雷に打たれて.</span></div><div class=\"def\"><num>③</num> (食べ物に)手をつける, 味わう.</div><div class=\"def\"><num>④</num> (女性・他人のものなどに)手を出す;(神聖なものなどを)侵す, けがす.</div><div class=\"def\"><num>⑤</num> (水などを)ふりかける;染める</div><div class=\"ex\"><i>corpus aquā tangere</i> (<author>O<small>V</small></author>)<span class=\"ext\">体に水をふりかける.</span></div><div class=\"def\"><num>⑥</num> ...に着手する</div><div class=\"ex\"><i>tetigisse carmina</i> (<author>O<small>V</small></author>)<span class=\"ext\">詩作に手を染めた.</span></div><div class=\"def\"><num>⑦</num> ...からだまし取る 〈alqm re〉.</div><div class=\"def\"><num>⑧</num> (感情などが)...に影響を及ぼす, 動かす.</div><div class=\"def\"><num>⑨</num> ...に(少し)言及する, 触れる.</div><div class=\"def\"><num>⑩</num> 接する, 隣接する.</div><div class=\"def\"><num>⑪</num> 達する, 届く.</div>\r\n","<div class=\"hw\">Tantaleus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tantalus の.</div>\r\n","<div class=\"hw\">Tantalidēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">Tantalus の男系子孫《Pelops, Atreus, Thyestes, Agamemnon, Orestes など》.</div>\r\n","<div class=\"hw\">Tantalis</div><div class=\"pos\">-idis [-idos], <i>f</i></div><div class=\"def\">Tantalus の女系子孫《Niobe, Hermiona など》.</div>\r\n","<div class=\"hw\">Tantalus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙タンタルス, <SUP>*</SUP>-ロス《Juppiter の息子で Pelops と Niobe の父;Lydia の王》.</div>\r\n","<div class=\"hw\">tantillum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tantillus\">tantillus</a>]</div><div class=\"def\">ごくわずかの量[額, 時間(など)].</div>\r\n","<div class=\"hw\">tantillus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[tantus]</div><div class=\"def\">そんなに小さな;ごくわずかの.</div>\r\n","<div class=\"hw\">tantisper</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tantus]</div><div class=\"def\">その間, しばらく, 当面 〈dum;quoad〉.</div>\r\n","<div class=\"hw\">tantopere, tantō opere</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tantus/opus]</div><div class=\"def\">これ[それ]ほどまで大いに[はなはだしく].</div>\r\n","<div class=\"hw\">tantulum<SUP>1</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tantulus]</div><div class=\"def\">それほど[ごく]わずかの量, ささいなこと.</div><hr><div class=\"hw\">tantulum<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"def\">ほんの少し, ごくわずか.</div>\r\n","<div class=\"hw\">tantulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[tantus]</div><div class=\"def\">これ[それ]ほど小さい[わずかな].</div>\r\n","<div class=\"hw\">tantum<SUP>1</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tantus]</div><div class=\"def\"><num>①</num> これ[それ]ほど多くのもの[量] 〈+<i>gen</i>〉</div><div class=\"ex\"><i>～ effatus</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">彼はそれだけ言うと</span></div><div class=\"ex\"><i>～ piscium</i> (<author>C<small>IC</small></author>)<span class=\"ext\">こんなにたくさんの魚</span></div><div class=\"ex\"><i>alterum [ter, quater] ～ auri</i><span class=\"ext\">2[3, 4]倍の金<SUB>きん</SUB></span></div><div class=\"ex\">(quantum と呼応して)<i>～ dedit quantum iste imperavit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼はあの男が命じただけの額を払った</span></div><div class=\"ex\"><i>in ～</i><span class=\"ext\">それほどまで.</span></div><div class=\"def\"><num>②</num> (tanti(価値を表わす <i>gen</i>)で)これ[それ]ほどの値段[価値]で</div><div class=\"ex\"><i>tanti indica</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">売り値を言ってくれ</span></div><div class=\"ex\">(quanti と呼応して)<i>hortos emit tanti quanti Pythius voluit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼は Pythius の言い値で庭を買った</span></div><div class=\"ex\">(+<i>inf</i>)<i>est mihi tanti hujus invidiae tempestatem subire</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私にとってこの嫉妬の嵐を耐える価値は十分ある.</span></div><div class=\"def\"><num>③</num> (tanto で)</div><div class=\"def\"><num1>⒜</num1> それだけの値段で.</div><div class=\"def\"><num1>⒝</num1> それだけ多く 〈+<i>comp</i>〉</div><div class=\"ex\"><i>tanto miserior</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">いっそう気の毒だ</span></div><div class=\"ex\">(quanto と呼応して)<i>tanto major vis, quanto recentior</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">新しければ新しいほど力が大きい</span></div><div class=\"ex\"><i>tanto ante [post]</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ずっと以前に[あとで].</span></div><hr><div class=\"hw\">tantum<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> これ[それ]ほど(多く, 長く, 遠く)</div><div class=\"ex\"><i>～ equitatu valere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">それほど騎兵でまさる.</span></div><div class=\"def\"><num>②</num> ただ, ...だけ</div><div class=\"ex\"><i>non ～ ... sed etiam ...</i><span class=\"ext\">...だけでなく...もまた.</span></div><div class=\"def\"><num>③</num> (～ non で)ほとんど</div><div class=\"ex\"><i>～ non statim a funere</i> (<author>S<small>UET</small></author>)<span class=\"ext\">葬式からほとんど間をおかずに.</span></div><div class=\"def\"><num>④</num> (～ quod で)ようやく, やっと, ちょうど;(～ quod non で)ただ</div><div class=\"ex\"><i>～ quod hominem non nominat</i> (<author>C<small>IC</small></author>)<span class=\"ext\">男を名指ししていないというだけのことだ.</span></div>\r\n","<div class=\"hw\">tantummodo, tantum modo</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">ただ, 単に, ...だけ</div><div class=\"ex\"><i>non ～ ... sed etiam ...</i><span class=\"ext\">...だけでなく...も(また).</span></div>\r\n","<div class=\"hw\">tantundem<SUP>1</SUP>, -tum-<SUP>1</SUP></div><div class=\"pos\">tantīdem, <i>n</i></div><div class=\"ori\">[tantusdem]</div><div class=\"def\"><num>①</num> ちょうど同じだけの量[程度]</div><div class=\"ex\"><i>～ argenti quantum miles debuit</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">兵士が借りていたのと同額の銀貨</span></div><div class=\"ex\"><i>～ est</i> (<author>J<small>UV</small></author>)<span class=\"ext\">(結局は)同じことだ.</span></div><div class=\"def\"><num>②</num> (<i>gen</i> で)ちょうど同じ値段[価値]で</div><div class=\"ex\"><i>tantidem emptam postulat</i> (<author>T<small>ER</small></author>)<span class=\"ext\">彼は(おれが)買った女を元値で売れと言う.</span></div><hr><div class=\"hw\">tantundem<SUP>2</SUP>, -tum-<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"def\">ちょうど同じ程度に.</div>\r\n","<div class=\"hw\">tantus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>cf. </i> tam]</div><div class=\"def\">これ[それ]ほど大きい[多量の, 重要な]</div><div class=\"ex\"><i>tanta multitudo hostium</i> (<author>C<small>AES</small></author>)<span class=\"ext\">これほど多くの敵</span></div><div class=\"ex\">(quantus と呼応して)<i>non sum tanto ingenio quanto Themistocles fuit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私は Themistocles ほどの才能はない</span></div><div class=\"ex\">(ut, qui を伴って)<i>tanta oborta caligo est ut dispicere non posset</i> (<author>S<small>UET</small></author>)<span class=\"ext\">何も見分けられないほどひどい目まいが起きた(=ひどい目まいが起きたので何も見分けられなかった)</span></div><div class=\"ex\"><i>nulla est tanta vis quae non ferro frangi possit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">武器によって破られないほど強固な力はない.</span></div>\r\n","<div class=\"hw\">tantusdem</div><div class=\"pos\">tantadem tantundem [-tum-], <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://tantus\">tantus</a>/-dem]</div><div class=\"def\">ちょうどそれだけの大きさ[量, 程度]の.</div>\r\n","<div class=\"hw\">tantī</div><div class=\"pos\"><i>gen</i></div><div class=\"def\">⇒<a href=\"entry://tantum\">tantum<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">Tanētum, Tannē-</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">タネートゥム《Gallia Cispadana の村》.</div>\r\n","<div class=\"hw\">Taprobanē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">タプロバネー《インド洋の島;現 Ceylon》.</div>\r\n","<div class=\"hw\">Tapȳrī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">タピューリー, <SUP>*</SUP>-ロイ《カスピ海南岸の Hyrcania にいた一部族》.</div>\r\n","<div class=\"hw jl\"><SUP>*</SUP>tapēs</div><div class=\"pos\">-ētis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(<i>sg nom</i> の用例なし)=<a href=\"entry://tapēte\">tapete</a>.</div>\r\n","<div class=\"hw\">tapēte</div><div class=\"pos\">-is, <i>n</i>, <B>tapētia</B> -ium, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 敷物, 絨毯<SUB>じゅうたん</SUB>.</div><div class=\"def\"><num>②</num> 壁掛け, 上<SUB>うわ</SUB>掛け.</div>\r\n","<div class=\"hw\">tapētum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\"><num>①</num> 〘植〙絨毯組織.</div><div class=\"def\"><num>②</num> 〘解〙内面層.</div><div class=\"def\"><num>③</num> 〘解〙(側脳室の)壁板.</div><div class=\"def\"><num>④</num> 〘解・動〙(眼球の)輝板.</div>\r\n","<div class=\"hw\">tapīnōma</div><div class=\"pos\">-atis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">陳腐な表現.</div>\r\n","<div class=\"hw\">tapīnōsis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://tapīnōma\">tapinoma</a>.</div>\r\n","<div class=\"hw\">tarandrus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙トナカイ(馴鹿).</div>\r\n","<div class=\"hw\">Taranis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">タラニス《Galli の雷神;Juppiter と同一視された》.</div>\r\n","<div class=\"hw\">Taranucus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">《碑》=<a href=\"entry://Taranis\">Taranis</a>.</div>\r\n","<div class=\"hw\">taratantara</div><div class=\"def\">tuba の音を表わす擬音語.</div>\r\n","<div class=\"hw\">Tarbellus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tarbelli 族の.</div>\r\n","<div class=\"hw\">Tarbellī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">タルベッリー《Aquitania 南部にいた一部族》.</div>\r\n","<div class=\"hw\">Tarchō(n)</div><div class=\"pos\">-ōnis [-ontis], <i>m</i></div><div class=\"def\">〘伝説〙タルコー(ン)《Etruria 人の長;Turnus に抗して Aeneas に味方した》.</div>\r\n","<div class=\"hw\">tardescō</div><div class=\"pos\">-ere, <i>intr</i></div><div class=\"ori\">[tardus]</div><div class=\"def\">動きが鈍くなる</div><div class=\"ex\"><i>tardescit lingua</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">舌がもつれる.</span></div>\r\n","<div class=\"hw\">tardicors</div><div class=\"pos\">-cordis, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tardus/cor]</div><div class=\"def\">(頭が)鈍い, 鈍感な.</div>\r\n","<div class=\"hw\">tardigradus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tardus/gradior]</div><div class=\"def\">歩みののろい, 足の遅い.</div>\r\n","<div class=\"hw\">tardilinguis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tardus/lingua]</div><div class=\"def\">(ことばの)たどたどしい, 舌の回らぬ.</div>\r\n","<div class=\"hw\">tardiloquus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tardus/loquor]</div><div class=\"def\">ゆっくり話す.</div>\r\n","<div class=\"hw\">tardipēs</div><div class=\"pos\">-pedis, <i>adj</i></div><div class=\"ori\">[tardus/pes]</div><div class=\"def\">歩みののろい, 足を引きずる</div><div class=\"ex\"><i>～ deus</i> (<author>C<small>ATUL</small></author>)<span class=\"ext\">=<a href=\"entry://Volcānus\">Volcanus</a>.</span></div>\r\n","<div class=\"hw\">tarditiēs</div><div class=\"pos\">-ēī, <i>f</i></div><div class=\"def\">=<a href=\"entry://tarditās\">tarditas</a>.</div>\r\n","<div class=\"hw\">tarditās</div><div class=\"pos\">-atis, <i>f</i></div><div class=\"ori\">[tardus]</div><div class=\"def\"><num>①</num> (動きの)鈍いこと, 緩慢.</div><div class=\"def\"><num>②</num> 遅れ, 遅滞.</div><div class=\"def\"><num>③</num> 耳が遠いこと, 難聴.</div><div class=\"def\"><num>④</num> (頭の)鈍さ, 愚鈍.</div>\r\n","<div class=\"hw\">tarditūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[tardus]</div><div class=\"def\">動きが鈍いこと.</div>\r\n","<div class=\"hw\">tardiusculus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[tardus]</div><div class=\"def\">少しのろまの.</div>\r\n","<div class=\"hw\">tardiusculē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://tardiusculus\">tardiusculus</a>]</div><div class=\"def\">少しゆっくりと.</div>\r\n","<div class=\"hw\">tardus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> (動きの)遅い, 鈍い, のろい.</div><div class=\"def\"><num>②</num> (頭の)鈍い, 愚かな.</div><div class=\"def\"><num>③</num> ゆっくりとした, 時間のかかる.</div><div class=\"def\"><num>④</num> 遅れている, 遅い.</div>\r\n","<div class=\"hw\">tardātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tardo]</div><div class=\"def\">のろいこと, 緩慢.</div>\r\n","<div class=\"hw\">tardē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tardus]</div><div class=\"def\">ゆっくりと, のろのろ[ぐずぐず]と;(時間に)遅れて</div><div class=\"ex\"><i>citius tardius</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">遅かれ早かれ, 早晩.</span></div>\r\n","<div class=\"hw\">tardō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[↓<a href=\"entry://tardus\">tardus</a>]</div><div class=\"def\"><num>①</num> 遅らせる;阻む</div><div class=\"ex\"><i>palus Romanos ad insequendum tardabat</i> (<author>C<small>AES</small></author>)<span class=\"ext\">沼地がローマ人の追跡を妨げていた.</span></div><div class=\"def\"><num>②</num> (感情などを)抑える, 弱める.</div><div class=\"def\"><num>③</num> 遅れる, ぐずぐずする.</div>\r\n","<div class=\"hw\">Tarentum<SUP>1</SUP></div><div class=\"pos\">-ī, <i>n</i>, <B>-tus, -tos<SUP>1</SUP></B> -ī, <i>f</i></div><div class=\"def\">タレントゥム, <SUP>*</SUP>タラース《Magna Graecia にあったギリシア人の植民市;現 Taranto》.</div><hr><div class=\"hw\">Tarentum<SUP>2</SUP></div><div class=\"pos\">-ī, <i>n</i>, <B>-tos<SUP>2</SUP></B> -ī, <i>m</i></div><div class=\"def\">タレントゥム《Campus Martius 内の百年祭(ludi saeculares)が催された場所》.</div>\r\n","<div class=\"hw\">Tarentīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tarentum<SUP>1</SUP> の.</div><div class=\"hw2\"><b>Tarentīnī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Tarentum<SUP>1</SUP> の住民.</div>\r\n","<div class=\"hw\">tarmes</div><div class=\"pos\">-itis, <i>m</i></div><div class=\"ori\">[tero]</div><div class=\"def\">〘昆〙キクイムシ.</div>\r\n","<div class=\"hw\">tarpezīta</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">=<a href=\"entry://trapezīta\">trapezita</a>.</div>\r\n","<div class=\"hw\">Tarpēia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">タルペイヤ, <SUP>∥</SUP>-ア《ローマ人の女性名;特に Romulus 王治下のローマ防衛隊長 Sp. Tarpeius の娘;Sabini 族のために裏切って市の城門を開いたという》.</div>\r\n","<div class=\"hw\">Tarpēius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">タルペイユス, <SUP>∥</SUP>-ウス《ローマ人の氏族名》.</div><hr><div class=\"hw\">Tarpēius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tarpeius の(岩の);Tarpeia の</div><div class=\"ex\"><i>saxum ～</i> (<author>T<small>AC</small></author>)<span class=\"ext\">Tarpeius の岩《Capitolinus 丘の崖<SUB>がけ</SUB>;人殺しや国事犯がそこから突き落とされた》.</span></div>\r\n","<div class=\"hw\">Tarquiniensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Tarquinii の.</div><div class=\"hw2\"><b>Tarquiniensēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Tarquinii の住民.</div>\r\n","<div class=\"hw\">Tarquinius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘伝説〙タルクゥイニウス《Etruria 人の家名;特に: (1) <i>～ Priscus</i>, ローマの第5代の王((伝)在位前616‐579).(2) <i>～ Superbus</i>, ローマの最後(第7代)の王((伝)在位前534‐510).(3) <i>L. ～ Collatinus</i>, 最初の二人の執政官の一人(前509)》.</div><hr><div class=\"hw\">Tarquinius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tarquinius の.</div>\r\n","<div class=\"hw\">Tarquiniānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Tarquinius\">Tarquinius<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">Tarquiniī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">タルクゥイニイー《Etruria の町;現 Tarquinia》.</div>\r\n","<div class=\"hw\">Tarquitius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">タルクゥイティウス《占いに関する書物を著わした Etruria 人》.</div>\r\n","<div class=\"hw\">Tarracīna</div><div class=\"pos\">-ae, <i>f</i>, <B>-nae</B> -ārum, <i>f pl</i></div><div class=\"def\">タッラキーナ《Latium の海岸の町;現 Terracina》.</div>\r\n","<div class=\"hw\">Tarracīnensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Tarracina の.</div><div class=\"hw2\"><b>Tarracīnensēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Tarracina の住民.</div>\r\n","<div class=\"hw\">Tarracō(n)</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"def\">タッラコー(ン)《Hispania 東海岸の町;現 Tarragona》.</div>\r\n","<div class=\"hw\">Tarracōnensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Tarraco の.</div>\r\n","<div class=\"hw\">Tarsensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Tarsus の.</div><div class=\"hw2\"><b>Tarsensēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Tarsus の住民.</div>\r\n","<div class=\"hw\">tarsus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘解・動〙</div><div class=\"def\"><num>①</num> 足首;足根(骨).</div><div class=\"def\"><num>②</num> (鳥の)跗蹠<SUB>ふしょ</SUB>骨.</div><div class=\"def\"><num>③</num> (昆虫の)跗節.</div><div class=\"def\"><num>④</num> 瞼板<SUB>けんばん</SUB>.</div>\r\n","<div class=\"hw\">Tarsus, -os</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">タルスス, <SUP>*</SUP>-ソス《Cilicia の町;聖パウロの生地》.</div>\r\n","<div class=\"hw\">tarsālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解・動〙</div><div class=\"def\"><num>①</num> 足根部[骨]の.</div><div class=\"def\"><num>②</num> 瞼板の.</div>\r\n","<div class=\"hw\">Tartara</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"def\">=<a href=\"entry://Tartarus\">Tartarus</a>.</div>\r\n","<div class=\"hw\">Tartareus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[Tartarus]</div><div class=\"def\">冥界の, 地獄の</div><div class=\"ex\"><i>～ custos</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">=<a href=\"entry://Cerberus\">Cerberus</a></span></div><div class=\"ex\"><i>sorores Tartareae</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">=<a href=\"entry://furia\">Furiae</a>.</span></div>\r\n","<div class=\"hw\">tartarum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 酒石.</div><div class=\"def\"><num>②</num> 歯石.</div>\r\n","<div class=\"hw\">Tartarus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">冥界, 地獄.</div>\r\n","<div class=\"hw\">Tartēs(s)iacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tartessus(起源)の.</div>\r\n","<div class=\"hw\">Tartēs(s)ius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tartessus の.</div>\r\n","<div class=\"hw\">Tartēs(s)us, -os</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">タルテーッスス, <SUP>*</SUP>-ソス《Hispania 南部の Baetis 河口の町;時に世界の西端の象徴》.</div>\r\n","<div class=\"hw\">Tarusātēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">タルサーテース《Aquitania の一部族》.</div>\r\n","<div class=\"hw\">Tasgetius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">タスゲティウス《Carnutes 族の首長》.</div>\r\n","<div class=\"hw\">tasis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(声の)調子, 高低.</div>\r\n","<div class=\"hw\">tat</div><div class=\"pos\"><i>int</i></div><div class=\"def\">やあ, ねえ.</div>\r\n","<div class=\"hw\">tata</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">《幼児》</div><div class=\"def\"><num>①</num> おとうちゃん.</div><div class=\"def\"><num>②</num> おじいちゃん.</div>\r\n","<div class=\"hw\">tatae</div><div class=\"pos\"><i>int</i></div><div class=\"def\">おや, まあ.</div>\r\n","<div class=\"hw\">Tatius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">タティウス《<i>T. ～</i>, Sabini 族の王;一時 Romulus とローマを共同統治したという》.</div><hr><div class=\"hw\">Tatius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tatius の.</div>\r\n","<div class=\"hw\">Taulantius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Taulantii 族の.</div>\r\n","<div class=\"hw\">Taulantiī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">タウランティイー《Illyria の一部族》.</div>\r\n","<div class=\"hw\">Taunus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">タウヌス《Germania 西部の山》.</div>\r\n","<div class=\"hw\">taura</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[taurus]</div><div class=\"def\">(不妊の)雌牛.</div>\r\n","<div class=\"hw\">Taurasia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">タウラシア《Samnium の町》.</div>\r\n","<div class=\"hw\">Taurasīnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Taurasia の住民.</div>\r\n","<div class=\"hw\">taurea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[taureus]</div><div class=\"def\"><num>①</num> 牛革の鞭.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> =<a href=\"entry://taura\">taura</a>.</div>\r\n","<div class=\"hw\">taurelephās</div><div class=\"pos\">-antis, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">体の半分が牛で残りが象であるインドの架空の動物.</div>\r\n","<div class=\"hw\">taureus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[taurus]</div><div class=\"def\">雄牛の;牛革の</div><div class=\"ex\"><i>taurea vincla</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">にかわ</span></div><div class=\"ex\"><i>taurea terga</i><span class=\"ext\">牛革 (<author>V<small>ERG</small></author>);太鼓 (<author>O<small>V</small></author>).</span></div>\r\n","<div class=\"hw\">tauricornis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[taurus/cornu]</div><div class=\"def\">雄牛の角<SUB>つの</SUB>をもった.</div>\r\n","<div class=\"hw\">Tauricus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tauri 族の.</div>\r\n","<div class=\"hw\">taurifer</div><div class=\"pos\">-era -erum, <i>adj</i></div><div class=\"ori\">[taurus/fero]</div><div class=\"def\">雄牛を産する[育む].</div>\r\n","<div class=\"hw\">tauriformis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[taurus/forma]</div><div class=\"def\">雄牛の形[姿]をした.</div>\r\n","<div class=\"hw\">taurigenus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[taurus/gigno]</div><div class=\"def\">雄牛(から)の.</div>\r\n","<div class=\"hw\">Tauris</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"def\">タウリス《Illyria 沖の島》.</div>\r\n","<div class=\"hw\">Taurius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">タウリウス《ローマ人の氏族名》.</div><hr><div class=\"hw\">Taurius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Taurius の</div><div class=\"ex\"><i>ludi Taurii</i> (<author>V<small>ARR</small></author>)<span class=\"ext\">地下の神々を祭るために Palatinus 丘の北西にあった Circus Flaminius で催された競技.</span></div>\r\n","<div class=\"hw\">taurobolior</div><div class=\"pos\">-ārī -ātus sum, <SUP>◇</SUP><i>intr dep</i></div><div class=\"ori\">[↓<a href=\"entry://taurobolium\">taurobolium</a>]</div><div class=\"def\">taurobolium の儀式を行なう.</div>\r\n","<div class=\"hw\">taurobolium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">《碑》タウロボリウム, <SUP>*</SUP>-オン《Cybele のために雄牛を犠牲に捧げる儀式》.</div>\r\n","<div class=\"hw\">Tauromenium, -num</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">タウロメニウム《Sicilia 島東岸の町;現 Taormina》.</div>\r\n","<div class=\"hw\">Tauromenītānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tauromenium の.</div><div class=\"hw2\"><b>Tauromenītānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Tauromenium の住民.</div>\r\n","<div class=\"hw\">Tauropolos</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Diana [Artemis] の呼称の一つ.</div>\r\n","<div class=\"hw\">Tauroīs</div><div class=\"pos\">-roentis, <i>m</i></div><div class=\"def\">タウロイース《Gallia Narbonensis の要塞・港町》.</div>\r\n","<div class=\"hw\">taurus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘動〙雄牛.</div><div class=\"def\"><num>②</num> パラリスの牛《Agrigentum の僭主 Phalaris(前6世紀)が作らせた青銅の牛の形をした拷問具》.</div><div class=\"def\"><num>③</num> (T-)〘天・占星〙牡牛座.</div>\r\n","<div class=\"hw\">Taurus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">タウルス, <SUP>*</SUP>-ロス《小アジア南部の山脈》</div><div class=\"ex\"><i>Tauri pylae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Cappadocia と Cilicia の間の隘路<SUB>あいろ</SUB>(「Taurus 山脈の門」 の意).</span></div>\r\n","<div class=\"hw\">taurārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[taurus]</div><div class=\"def\">《碑》闘牛士.</div>\r\n","<div class=\"hw\">Taurī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">タウリー《Chersonesus Taurica(現 Krym)にいた部族》.</div>\r\n","<div class=\"hw\">taurīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[taurus]</div><div class=\"def\"><num>①</num> 雄牛(から)の.</div><div class=\"def\"><num>②</num> 牛革の.</div>\r\n","<div class=\"hw\">Taurīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Taurini 族の.</div>\r\n","<div class=\"hw\">Taurīnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\"><num>①</num> タウリーニー《Gallia Cisalpina にいた Liguria 人の一部族》.</div><div class=\"def\"><num>②</num> <i>Augusta Taurinorum</i> (<author>T<small>AC</small></author>) Augustus 帝により創建された都市(現 Turin).</div>\r\n","<div class=\"hw\">tautologia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘修・論〙同義語反復.</div>\r\n","<div class=\"hw\">taxa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[taxo]</div><div class=\"def\"><num>①</num> 評価(額).</div><div class=\"def\"><num>②</num> 手数料;税.</div>\r\n","<div class=\"hw\">taxeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[taxus]</div><div class=\"def\">イチイ(櫟)の.</div>\r\n","<div class=\"hw\">taxicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://taxeus\">taxeus</a>.</div>\r\n","<div class=\"hw\">taxillus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[talus]</div><div class=\"def\">小さなさいころ.</div>\r\n","<div class=\"hw\">taxim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tango]</div><div class=\"def\">そっと, こっそりと.</div>\r\n","<div class=\"hw\">Taximagulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">タクシマグルス《Cantium(現 Kent)の王》.</div>\r\n","<div class=\"hw\">taxus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"def\">〘植〙イチイ(櫟)(の木).</div>\r\n","<div class=\"hw\">taxātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[taxo]</div><div class=\"def\"><num>①</num> 評価, 査定;評価額.</div><div class=\"def\"><num>②</num> 〘法〙限度額.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 課税.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 非難.</div>\r\n","<div class=\"hw\">taxātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[taxo]</div><div class=\"def\"><num>①</num> ののしる人.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(税などの)評価[査定]者.</div>\r\n","<div class=\"hw\">taxō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[tango]</div><div class=\"def\"><num>①</num> 評価[査定, 判定]する.</div><div class=\"def\"><num>②</num> 非難する;けなす.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 指摘する, 言及する.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 課税する.</div>\r\n","<div class=\"hw\">teba</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">丘, 小山(Sabini 語).</div>\r\n","<div class=\"hw\">techna, techina</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">奸計, 計略.</div>\r\n","<div class=\"hw\">technicus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">技芸[技術]の専門家.</div>\r\n","<div class=\"hw\">technographus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">論稿執筆者.</div>\r\n","<div class=\"hw\">technyphion</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">小さな仕事部屋, 小工房.</div>\r\n","<div class=\"hw\">Tecmēssa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テクメーッサ《Telamon の息子の Ajax の愛妾》.</div>\r\n","<div class=\"hw\">Tecmōn</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テクモーン《Epirus の町》.</div>\r\n","<div class=\"hw\">Tecta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tego]</div><div class=\"def\">(<i>sc. </i> Via)ローマ市内の屋根付き道路;Porta Capena に通じていた.</div>\r\n","<div class=\"hw\">tectiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tego]</div><div class=\"def\">覆うこと.</div>\r\n","<div class=\"hw\">tectonicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">建築(術)の.</div>\r\n","<div class=\"hw\">tector</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[tego]</div><div class=\"def\">左官, 漆喰<SUB>しっくい</SUB>師.</div>\r\n","<div class=\"hw\">Tectosagēs</div><div class=\"pos\">-um, <B>-agī</B> -ōrum, <i>m pl</i></div><div class=\"def\">テクトサゲース《Gallia Narbonensis にいた Volcae 族の一支族》.</div>\r\n","<div class=\"hw\">tectum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tectus]</div><div class=\"def\"><num>①</num> 屋根;天井.</div><div class=\"def\"><num>②</num> 家屋, 住居.</div><div class=\"def\"><num>③</num> 巣, 隠れ家.</div>\r\n","<div class=\"hw\">tectus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[tego]</div><div class=\"def\"><num>①</num> 屋根のある, 屋根付きの</div><div class=\"ex\"><i>Via Tecta</i> (<author>O<small>V</small></author>)<span class=\"ext\">⇒ <a href=\"entry://Tecta\">Tecta</a>.</span></div><div class=\"def\"><num>②</num> おおわれた</div><div class=\"ex\"><i>navis tecta</i> (<author>C<small>AES</small></author>)<span class=\"ext\">甲板を張った(軍)船.</span></div><div class=\"def\"><num>③</num> 隠された, 秘められた.</div><div class=\"def\"><num>④</num> 用心深い, 慎重な.</div>\r\n","<div class=\"hw\">tectē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tectus]</div><div class=\"def\">隠して, ひそかに.</div>\r\n","<div class=\"hw\">tectōriolum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://tectōrium\">tectōrium</a>]</div><div class=\"def\">ちょっとした漆喰仕上げ.</div>\r\n","<div class=\"hw\">tectōrium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tectōrius\">tectōrius</a>]</div><div class=\"def\"><num>①</num> スタッコ, 化粧漆喰.</div><div class=\"def\"><num>②</num> (<i>pl</i>)漆喰仕上げ(の壁, 天井など).</div><div class=\"def\"><num>③</num> (化粧の)上塗り;(うわべだけの)お世辞.</div>\r\n","<div class=\"hw\">tectōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tego]</div><div class=\"def\"><num>①</num> おおい[屋根]となる.</div><div class=\"def\"><num>②</num> 漆喰塗り[仕上げ]の.</div>\r\n","<div class=\"hw\">tectūra</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tego]</div><div class=\"def\"><num>①</num> 漆喰を塗ること.</div><div class=\"def\"><num>②</num> (羊皮紙本の)装丁.</div>\r\n","<div class=\"hw\">Tegea</div><div class=\"pos\">-ae, <B>-geē</B> -ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テゲア(ー)《Arcadia の町》.</div>\r\n","<div class=\"hw\">Tegeaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Tegea の.</div><div class=\"def\"><num>②</num> Arcadia の</div><div class=\"ex\"><i>virgo Tegeaea</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Callistō\">Callisto</a>.</span></div>\r\n","<div class=\"hw\">teges</div><div class=\"pos\">-etis, <i>f</i></div><div class=\"ori\">[tego]</div><div class=\"def\"><num>①</num> おおい.</div><div class=\"def\"><num>②</num> ござ, 敷物, マット.</div>\r\n","<div class=\"hw\">tegetīcula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↑<a href=\"entry://teges\">teges</a>]</div><div class=\"def\"><num>①</num> 小さなおおい.</div><div class=\"def\"><num>②</num> 小さなマット[ござ].</div>\r\n","<div class=\"hw\">Tegeāticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tegea の;Arcadia の</div><div class=\"ex\"><i>ales ～</i> (<author>S<small>TAT</small></author>)<span class=\"ext\">=<a href=\"entry://Mercurius\">Mercurius</a>.</span></div>\r\n","<div class=\"hw\">Tegeātis</div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">Tegea の;Arcadia の.</div>\r\n","<div class=\"hw\">Tegeātēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">Tegea 人.</div>\r\n","<div class=\"hw\">tegiculum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">=<a href=\"entry://tegetīcula\">tegeticula 1</a>.</div>\r\n","<div class=\"hw\">tegile</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[tego]</div><div class=\"def\">(おおいにする)布切れ.</div>\r\n","<div class=\"hw\">tegillum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↑<a href=\"entry://tegile\">tegile</a>]</div><div class=\"def\">(小さな)ござ.</div>\r\n","<div class=\"hw\">tegimen, tegum-, tegm-</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[tego]</div><div class=\"def\"><num>①</num> おおうもの, おおい.</div><div class=\"def\"><num>②</num> 衣服;上着, 外衣.</div><div class=\"def\"><num>③</num> 武具;鎧, 兜.</div><div class=\"def\"><num>④</num> 盾;防御.</div><div class=\"def\"><num>⑤</num> 外皮;毛皮;果皮;殻.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP> 屋根, 住居.</div><div class=\"def\"><num>⑦</num> <SUP>◇</SUP> 口実, 言い訳.</div>\r\n","<div class=\"hw\">tegimentum, tegm-</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tegō\">tegō</a>]</div><div class=\"def\"><num>①</num> おおう[包む, 保護する]もの, おおい.</div><div class=\"def\"><num>②</num> 武具;鎧, 兜.</div><div class=\"def\"><num>③</num> 外皮.</div>\r\n","<div class=\"hw\">tegurium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[tego]</div><div class=\"def\"><num>①</num> 小屋.</div><div class=\"def\"><num>②</num> 小神殿.</div>\r\n","<div class=\"hw\">tegus</div><div class=\"pos\">-oris, <i>n</i></div><div class=\"ori\">[tergus]</div><div class=\"def\">(動物の)背中;背肉.</div>\r\n","<div class=\"hw\">tegō</div><div class=\"pos\">-ere texī tectum, <i>tr</i></div><div class=\"def\"><num>①</num> おおう, 包む.</div><div class=\"def\"><num>②</num> (衣服を)着せる.</div><div class=\"def\"><num>③</num> 屋根をふく.</div><div class=\"def\"><num>④</num> 防御[保護]する, 守る</div><div class=\"ex\"><i>tegere latus alci</i> (<author>H<small>OR</small></author>)<span class=\"ext\">ある人の(無防備な左)側を守る(=敬意を表して左側を歩く).</span></div><div class=\"def\"><num>⑤</num> 隠す, 見えなくする.</div><div class=\"def\"><num>⑥</num> 秘密にする, 秘匿する.</div>\r\n","<div class=\"hw\">Telamō(n)</div><div class=\"pos\">-ōnis [-ōnos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テラモー(ン)《Aeacus の息子で Ajax と Teucer の父;Argonautae の一人》.</div>\r\n","<div class=\"hw\">Telamōniadēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">=<a href=\"entry://Telamōnius\">Telamonius<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">Telamōnius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Telamon の;Telamon の息子の, Ajax の.</div><hr><div class=\"hw\">Telamōnius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘伝説〙Telamon の息子(=<a href=\"entry://ājax\">Ajax</a>).</div>\r\n","<div class=\"hw\">Telchīnes</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙テルキーネス《魔術に長じていたという Rhodos 島の神官一族》.</div>\r\n","<div class=\"hw\">telencephalon</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘解〙終脳, 端脳.</div>\r\n","<div class=\"hw\">Telesia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">テレシア《Samnium の町》.</div>\r\n","<div class=\"hw\">telium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">(サビキン類の)冬胞子堆<SUB>たい</SUB>.</div>\r\n","<div class=\"hw\">telluster</div><div class=\"pos\">-tris -tre, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://tellūs\">tellūs</a>]</div><div class=\"def\">大地の.</div>\r\n","<div class=\"hw\">Tellēna</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"def\">テッレーナ《Latium の町》.</div>\r\n","<div class=\"hw\">tellūs</div><div class=\"pos\">-ūris, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 大地, 地;土地, 地面.</div><div class=\"def\"><num>②</num> (T-)〘神話〙テッルース《ローマの地母神》;母なる大地(=terra mater).</div><div class=\"def\"><num>③</num> 領地, 地方, 国.</div>\r\n","<div class=\"hw\">Telmēssensēs</div><div class=\"pos\">-ium, <SUP>◇</SUP><i>m pl</i></div><div class=\"def\">=<a href=\"entry://Telmēssēs\">Telmesses</a>.</div>\r\n","<div class=\"hw\">Telmēssicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Telmessus の.</div>\r\n","<div class=\"hw\">Telmēssis</div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">Telmessus の.</div>\r\n","<div class=\"hw\">Telmēssius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Telmēssicus\">Telmessicus</a>.</div>\r\n","<div class=\"hw\">Telmēssus, -os</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テルメーッスス, <SUP>*</SUP>-ソス《Lycia の港町》.</div>\r\n","<div class=\"hw\">Telmēssēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Telmessus の住民.</div>\r\n","<div class=\"hw\">telōneum, -nium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">税関.</div>\r\n","<div class=\"hw\">telōnārius, -neā-, -niā-</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://telōneum\">telōneum, -nium</a>]</div><div class=\"def\">関税徴収吏.</div>\r\n","<div class=\"hw\">Temenītis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テメニーティス《 (1)(<i>sc. </i> porta)Tarentum にあった門.(2)(<i>sc. </i> fons)Syracusae にあった泉》.</div>\r\n","<div class=\"hw\">Temenītēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テメニーテース《Apollo の添え名;Syracusae の一地区 Temenos にその聖杯があったことから》.</div>\r\n","<div class=\"hw\">temere</div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> 偶然に, たまたま.</div><div class=\"def\"><num>②</num> わけもなく, でたらめに</div><div class=\"ex\"><i>non ～ est quod corvus cantat</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">カラスが鳴くのは何かわけがあるぞ.</span></div><div class=\"def\"><num>③</num> 無分別に, むこうみずに.</div><div class=\"def\"><num>④</num> </div><div class=\"ex\"><i>non ～</i><span class=\"ext\">容易に, やすやすと.</span></div>\r\n","<div class=\"hw\">temeriter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[temere]</div><div class=\"def\">無思慮[不注意]に.</div>\r\n","<div class=\"hw\">temeritās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://temere\">temere</a>]</div><div class=\"def\"><num>①</num> 偶然.</div><div class=\"def\"><num>②</num> 無分別, 無謀, むこうみず.</div>\r\n","<div class=\"hw\">temeritūdo</div><div class=\"pos\">-inis, <i>f</i></div><div class=\"ori\">[temere]</div><div class=\"def\">無謀, むこうみず.</div>\r\n","<div class=\"hw\">temerārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[temere]</div><div class=\"def\"><num>①</num> 偶然の, 偶発的な.</div><div class=\"def\"><num>②</num> 無分別な, 無謀な, むこうみずな.</div><div class=\"def\"><num>③</num> 浅はかな, 軽はずみな.</div>\r\n","<div class=\"hw\">temerāriē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://temerārius\">temerārius</a>]</div><div class=\"def\">軽率[無思慮]に.</div>\r\n","<div class=\"hw\">temerātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[temero]</div><div class=\"def\"><num>①</num> 偽造, 贋造<SUB>がんぞう</SUB>.</div><div class=\"def\"><num>②</num> 違反, 違背.</div>\r\n","<div class=\"hw\">temerātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[temero]</div><div class=\"def\"><num>①</num> 風俗を乱す者;(婦女子の)陵辱者.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 偽造者.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 背く者.</div>\r\n","<div class=\"hw\">temerō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[temere]</div><div class=\"def\"><num>①</num> (神聖なものを)けがす, 侵す, 踏みにじる.</div><div class=\"def\"><num>②</num> (女性を)はずかしめる, 犯す.</div><div class=\"def\"><num>③</num> よごす, きたなくする.</div>\r\n","<div class=\"hw\">Temesaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Temese の.</div>\r\n","<div class=\"hw\">Temesē</div><div class=\"pos\">-ēs, <B>-a</B> -ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テメセー《Bruttii の町;銅山で有名》.</div>\r\n","<div class=\"hw\">temnibilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[temno]</div><div class=\"def\">軽蔑すべき, 見下げはてた.</div>\r\n","<div class=\"hw\">temnō</div><div class=\"pos\">-ere, <i>tr</i></div><div class=\"def\">軽蔑する, 見くだす(=<a href=\"entry://contemnō\">contemno</a>).</div>\r\n","<div class=\"hw\">temperans</div><div class=\"pos\">-antis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[tempero]</div><div class=\"def\">節度[自制心]のある, 中庸を保つ.</div>\r\n","<div class=\"hw\">temperanter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://temperans\">temperans</a>]</div><div class=\"def\">節度[中庸]を保って, 自制して.</div>\r\n","<div class=\"hw\">temperantia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[temperans]</div><div class=\"def\">節度, 自制, 中庸.</div>\r\n","<div class=\"hw\">temperius</div><div class=\"pos\"><i>adv comp</i></div><div class=\"ori\">[temperi]</div><div class=\"def\"><num>①</num> 早めに, 本来より早く.</div><div class=\"def\"><num>②</num> いっそう時宜<SUB>じぎ</SUB>にかなって.</div>\r\n","<div class=\"hw\">temperiēs</div><div class=\"pos\">-ēī, <i>f</i></div><div class=\"ori\">[tempero]</div><div class=\"def\"><num>①</num> 適切な配合[混合].</div><div class=\"def\"><num>②</num> 気候;(気候の)温暖, 温和.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 季節.</div>\r\n","<div class=\"hw\">temperāculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tempero]</div><div class=\"def\">溶鉱炉.</div>\r\n","<div class=\"hw\">temperāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tempero]</div><div class=\"def\"><num>①</num> (調和のとれた)混合(物).</div><div class=\"def\"><num>②</num> 適度, 節度, 中庸.</div><div class=\"def\"><num>③</num> 調和;妥協.</div><div class=\"def\"><num>④</num> 適温;温暖.</div>\r\n","<div class=\"hw\">temperātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[tempero]</div><div class=\"def\"><num>①</num> (適切な)混合, 配合.</div><div class=\"def\"><num>②</num> (調和のとれた)組織.</div><div class=\"def\"><num>③</num> 組織原理.</div><div class=\"def\"><num>④</num> 抑制, 調節.</div>\r\n","<div class=\"hw\">temperātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[tempero]</div><div class=\"def\"><num>①</num> 調和させる者;節度[中庸]を保つ者.</div><div class=\"def\"><num>②</num> 《詩》(武具を)鍛える者.</div>\r\n","<div class=\"hw\">temperātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[tempero]</div><div class=\"def\"><num>①</num> 適度な, 中程度の.</div><div class=\"def\"><num>②</num> 温暖な, 温和な.</div><div class=\"def\"><num>③</num> 節度[分別]のある, 中庸を得た.</div><hr><div class=\"hw\">temperātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"def\">絶つこと, 禁欲.</div>\r\n","<div class=\"hw\">temperātē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tempero]</div><div class=\"def\"><num>①</num> 適度に.</div><div class=\"def\"><num>②</num> 節度[中庸]を保って, 自制して.</div>\r\n","<div class=\"hw\">temperātīvus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tempero]</div><div class=\"def\">緩和する, 鎮静する.</div>\r\n","<div class=\"hw\">temperātūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tempero]</div><div class=\"def\"><num>①</num> 正しい混合[配合], 調和.</div><div class=\"def\"><num>②</num> 適度;温暖.</div><div class=\"def\"><num>③</num> 制御, 調節.</div>\r\n","<div class=\"hw\">temperī, temporī</div><div class=\"pos\"><i>adv</i>(<i>loc</i>)</div><div class=\"ori\">[tempus<SUP>1</SUP>]</div><div class=\"def\">ちょうどよい時に.</div>\r\n","<div class=\"hw\">temperō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[tempus<SUP>1</SUP>]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> (適切に)混ぜ合わせる, 組み合わせる;調合[配合]する.</div><div class=\"def\"><num>②</num> 調節する;和らげる.</div><div class=\"def\"><num>③</num> 支配する, 規制する.</div><div class=\"def\"><num>④</num> 抑制する;節度を守って扱う.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>(<i>refl</i>)絶つ, 慎む 〈a re〉.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> 節度を守る;抑える 〈+<i>dat</i>〉</div><div class=\"ex\"><i>linguae tempera</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">口を慎め.</span></div><div class=\"def\"><num>②</num> いたわる, 寛恕<SUB>かんじょ</SUB>する</div><div class=\"ex\"><i>etiam superatis hostibus temperavit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼は打ち負かした敵兵どもさえ助命した.</span></div><div class=\"def\"><num>③</num> 自制する, 控える, 慎む 〈(a)re;quin, quominus〉</div><div class=\"ex\"><i>a lacrimis temperare</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">涙を抑える.</span></div>\r\n","<div class=\"hw\">tempestuōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tempestas]</div><div class=\"def\">嵐のような;荒れ狂った;激しい.</div>\r\n","<div class=\"hw\">tempestās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[tempus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> (ひと区切りの)時間, 期間;日, 季節, 時代.</div><div class=\"def\"><num>②</num> 天気, 天候.</div><div class=\"def\"><num>③</num> 悪天候, 嵐.</div><div class=\"def\"><num>④</num> (比喩的に)嵐(の時), 混乱.</div><div class=\"def\"><num>⑤</num> (T-;通例 <i>pl</i>)天候[嵐]の女神.</div>\r\n","<div class=\"hw\">tempestīvitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://tempestīvus\">tempestīvus</a>]</div><div class=\"def\"><num>①</num> ちょうどよい時, 時宜にかなっていること.</div><div class=\"def\"><num>②</num> 時期に合った性質[特徴].</div><div class=\"def\"><num>③</num> 良好な状態, 健康.</div>\r\n","<div class=\"hw\">tempestīvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tempestas]</div><div class=\"def\"><num>①</num> 時勢[時期, 季節]に合った, 時宣<SUB>じぎ</SUB>を得た.</div><div class=\"def\"><num>②</num> 都合のよい, 適当な.</div><div class=\"def\"><num>③</num> 成熟した.</div><div class=\"def\"><num>④</num> 普通より早い</div><div class=\"ex\"><i>convivium tempestivum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">昼日中から開く宴会(=ぜいたくな宴会).</span></div>\r\n","<div class=\"hw\">tempestīvē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tempestivus]</div><div class=\"def\">ちょうどよい時に, 時宜を得て.</div>\r\n","<div class=\"hw\">templum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> (卜占<SUB>ぼくせん</SUB>官が鳥占いのために区切った)天空または地上の一郭<SUB>いっかく</SUB>.</div><div class=\"def\"><num>②</num> 聖域, 神域;神殿.</div><div class=\"def\"><num>③</num> 一帯, 地区, 地域.</div><div class=\"def\"><num>④</num> 〘建〙母屋<SUB>もや</SUB>(桁<SUB>げた</SUB>)《屋根の垂木を受ける桁》.</div>\r\n","<div class=\"hw\">templāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[templum]</div><div class=\"def\">神殿の.</div>\r\n","<div class=\"hw\">templārius</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://templum\">templum</a>]</div><div class=\"def\">テンプル騎士団員.</div>\r\n","<div class=\"hw\">temporomandibulāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙側頭下顎の, 顎関節の.</div>\r\n","<div class=\"hw\">temporāle</div><div class=\"pos\">-is, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://temporālis\">temporālis<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> この世[現世]のもの.</div><div class=\"def\"><num>②</num> 一時的な[はかない]もの.</div>\r\n","<div class=\"hw\">temporālis<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tempus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 一時の, はかない.</div><div class=\"def\"><num>②</num> 現世の, この世の.</div><div class=\"def\"><num>③</num> 〘文〙時制の.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 最近の.</div><hr><div class=\"hw\">temporālis<SUP>2</SUP></div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tempus<SUP>2</SUP>]</div><div class=\"def\">〘解〙こめかみの, 側頭部の.</div>\r\n","<div class=\"hw\">temporālitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[temporalis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 一時性, はかなさ.</div><div class=\"def\"><num>②</num> 環境, 状況.</div><div class=\"def\"><num>③</num> 現在.</div>\r\n","<div class=\"hw\">temporāneum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://temporāneus\">temporāneus</a>]</div><div class=\"def\">早熟の果実.</div>\r\n","<div class=\"hw\">temporāneus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tempus<SUP>1</SUP>]</div><div class=\"def\">ちょうどよい時の, 時宜を得た;好都合な.</div>\r\n","<div class=\"hw\">temporārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tempus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> その場に合わせた;変わりやすい, 気まぐれな.</div><div class=\"def\"><num>②</num> 一時[暫定]的な, ある時期だけの.</div>\r\n","<div class=\"hw\">temporāriē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://temporārius\">temporārius</a>]</div><div class=\"def\">一時的に, しばらくの間.</div>\r\n","<div class=\"hw\">temporātim</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[tempus<SUP>1</SUP>]</div><div class=\"def\">時に応じて.</div>\r\n","<div class=\"hw\">temporī</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://temperī\">temperi</a>.</div>\r\n","<div class=\"hw\">Tempsa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://Temesē\">Temese</a>.</div>\r\n","<div class=\"hw\">Tempsānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tempsa の.</div>\r\n","<div class=\"hw\">temptābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tempto]</div><div class=\"def\">一歩ごとに足元を確かめる.</div>\r\n","<div class=\"hw\">temptāmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[tempto]</div><div class=\"def\"><num>①</num> 試すこと, 試み.</div><div class=\"def\"><num>②</num> 誘惑.</div>\r\n","<div class=\"hw\">temptāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tempto]</div><div class=\"def\"><num>①</num> 試すこと, 試み;努力.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 誘惑.</div>\r\n","<div class=\"hw\">temptātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[tempto]</div><div class=\"def\"><num>①</num> 企て, 試み.</div><div class=\"def\"><num>②</num> 攻撃;(病気の)発作.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 誘惑.</div>\r\n","<div class=\"hw\">temptātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[tempto]</div><div class=\"def\"><num>①</num> (性的)誘惑者.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 害する者.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 悪魔, サタン(Satan).</div>\r\n","<div class=\"hw\">temptātrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://temptātor\">temptātor</a>]</div><div class=\"def\">誘惑者《女性》.</div>\r\n","<div class=\"hw\">temptō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\"><num>①</num> さわる, 触れる.</div><div class=\"def\"><num>②</num> 探る, 調べる</div><div class=\"ex\"><i>temptare venas</i> (<author>Q<small>UINT</small></author>)<span class=\"ext\">脈をとる.</span></div><div class=\"def\"><num>③</num> 試す, 試みる 〈+<i>acc</i>;+<i>inf</i>;ut+<i>subj</i>〉.</div><div class=\"def\"><num>④</num> 働きかける, 動かそうとする</div><div class=\"ex\"><i>judicium pecuniā temptare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">判決を金で買おうとする.</span></div><div class=\"def\"><num>⑤</num> 襲う;攻撃する;苦しめる.</div>\r\n","<div class=\"hw\">tempus<SUP>1</SUP></div><div class=\"pos\">-poris, <i>n</i></div><div class=\"def\"><num>①</num> 時, 時間;頃, 時期;(通例 <i>pl</i>)時代</div><div class=\"ex\"><i>fugit inreparabile ～</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">時は呼び戻す術もなく過ぎて行く.</span></div><div class=\"def\"><num>②</num> 季節</div><div class=\"ex\"><i>～ anni</i> (<author>C<small>IC</small></author>)<span class=\"ext\">季節.</span></div><div class=\"def\"><num>③</num> しかるべき[ふさわしい]時;好機, 機会</div><div class=\"ex\"><i>nunc est discedere ～</i> (<author>P<small>ROP</small></author>)<span class=\"ext\">今こそ別れる時だ.</span></div><div class=\"def\"><num>④</num> 状況, 事情.</div><div class=\"def\"><num>⑤</num> 〘文〙時制, 時.</div><div class=\"def\"><num>⑥</num> 〘詩〙(音節の)長短;〘音〙拍子, 速度.</div><div class=\"def\"><num>⑦</num> (<i>adv</i> として)<i>tempore</i></div><div class=\"def\"><num1>⒜</num1> ちょうどよい時に.</div><div class=\"def\"><num1>⒝</num1> 時とともに, 次第に.</div><div class=\"def\"><num>⑧</num> (前置詞とともに)</div><div class=\"ex\"><i>ad ～</i><span class=\"ext\">(a) 時間[予定]通りに; (b) 状況に応じて; (c) 一時に</span></div><div class=\"ex\"><i>ex tempore</i><span class=\"ext\">(a) すぐに, その場で; (b) = ad ～ (b)</span></div><div class=\"ex\"><i>in tempore</i><span class=\"ext\">ちょうどよい時に, 都合よく</span></div><div class=\"ex\"><i>in ～</i><span class=\"ext\">(a) さしあたって今は, 臨時に; (b) = ad ～ (b)</span></div><div class=\"ex\"><i>per ～</i><span class=\"ext\">= in tempore</span></div><div class=\"ex\"><i>pro tempore</i><span class=\"ext\">= ad ～ (b).</span></div><hr><div class=\"hw\">tempus<SUP>2</SUP></div><div class=\"pos\">-poris, <i>n</i></div><div class=\"def\">こめかみ, 側頭(部).</div>\r\n","<div class=\"hw\">tempusculum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[tempus<SUP>1</SUP>]</div><div class=\"def\">短時間, 瞬時.</div>\r\n","<div class=\"hw\">Tempȳra</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"def\">テンピューラ《Thracia の町》.</div>\r\n","<div class=\"hw\">Tempē</div><div class=\"pos\"><i>indecl n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> テンペー《Thessalia の渓谷;Olympus, Ossa 両山の間にあり Peneus 川が流れていた》.</div><div class=\"def\"><num>②</num> (一般に)美しい渓谷.</div>\r\n","<div class=\"hw\">temō<SUP>2</SUP></div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>m</i></div><div class=\"def\">徴兵免除[回避]税.</div>\r\n","<div class=\"hw\">temōnārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">temo<SUP>2</SUP> に関する.</div>\r\n","<div class=\"hw\">tenax</div><div class=\"pos\">-ācis, <i>adj</i></div><div class=\"ori\">[teneo]</div><div class=\"def\"><num>①</num> しっかりつかむ, まといつく, 粘着力の強い.</div><div class=\"def\"><num>②</num> 手放そうとしない, 物惜しみする, けちな 〈+<i>gen</i>〉.</div><div class=\"def\"><num>③</num> しっかりとした, 確固[断固]たる.</div><div class=\"def\"><num>④</num> ねばり強い, 忠実に守る[従う] 〈+<i>gen</i>〉</div><div class=\"ex\"><i>vir boni exempli ～</i> (<author>S<small>EN</small></author>)<span class=\"ext\">気高い理想に固執する男.</span></div><div class=\"def\"><num>⑤</num> 強情な, 頑固な.</div>\r\n","<div class=\"hw\">Tencterī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">テンクテリー《Rhenus 川流域にいたゲルマン系の一部族》.</div>\r\n","<div class=\"hw\">tendicula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://tendō\">tendō<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> (衣類の)伸張具.</div><div class=\"def\"><num>②</num> わな.</div>\r\n","<div class=\"hw\">Tendēba</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テンデーバ《Caria の町》.</div>\r\n","<div class=\"hw\">tendō<SUP>1</SUP></div><div class=\"pos\">-ere tetendī tentum [tensum], <i>tr</i>, <i>intr</i></div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> 伸ばす, 広げる;(天幕などを)張る.</div><div class=\"def\"><num>②</num> 強く引く, 引っ張る</div><div class=\"ex\"><i>neque semper arcum tendit Apollo</i> (<author>H<small>OR</small></author>)<span class=\"ext\">Apollo も絶えず弓を張っているわけではない.</span></div><div class=\"def\"><num>③</num> ふくらませる.</div><div class=\"def\"><num>④</num> 差し出す, 差しのべる.</div><div class=\"def\"><num>⑤</num> (わななどを)しかける.</div><div class=\"def\"><num>⑥</num> (行方・進路などを)定める, 向ける.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> 伸びる, 向かう, 進む.</div><div class=\"def\"><num>②</num> 目指す, ねらう 〈ad alqd〉.</div><div class=\"def\"><num>③</num> 努力する, 骨折る 〈+<i>inf</i>;ut〉.</div><div class=\"def\"><num>④</num> 固執する, 主張する</div><div class=\"ex\"><i>contra tendere</i> (<author>L<small>IV</small></author>)<span class=\"ext\">反論[反対]する.</span></div><div class=\"def\"><num>⑤</num> 天幕を張る, 野営する.</div><hr><div class=\"hw\">tendō<SUP>2</SUP></div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↑<a href=\"entry://tendō\">tendō<SUP>1</SUP></a>]</div><div class=\"def\">〘解〙腱</div><div class=\"ex\"><i>～ Achillis</i><span class=\"ext\">アキレス腱.</span></div>\r\n","<div class=\"hw\">Tenea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テネア《Corinthus 市外の村落》.</div>\r\n","<div class=\"hw\">tenebrae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\"><num>①</num> 暗闇, 暗黒.</div><div class=\"def\"><num>②</num> 暗夜, 夜.</div><div class=\"def\"><num>③</num> 盲目;(失神・死による)闇.</div><div class=\"def\"><num>④</num> 暗い場所;牢獄;隠れ家;冥界.</div><div class=\"def\"><num>⑤</num> 無知, 蒙昧<SUB>もうまい</SUB>.</div><div class=\"def\"><num>⑥</num> 世に知られない境遇[状態], 窮状.</div><div class=\"def\"><num>⑦</num> <SUP>◇</SUP>〘カト〙テネブレ《復活祭前週の木・金・土曜日の朝課と賛課》.</div>\r\n","<div class=\"hw\">tenebrescō</div><div class=\"pos\">-ere, <SUP>◇</SUP><i>intr inch</i></div><div class=\"ori\">[tenebrae]</div><div class=\"def\">暗くなる, 陰る.</div>\r\n","<div class=\"hw\">tenebricus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tenebrae]</div><div class=\"def\">闇に包まれた, 暗い.</div>\r\n","<div class=\"hw\">tenebricō</div><div class=\"pos\">-āre -āvī, <SUP>◇</SUP><i>intr</i>, <SUP>◇</SUP><i>tr</i></div><div class=\"def\"><num>①</num> =<a href=\"entry://tenebrescō\">tenebresco</a>.</div><div class=\"def\"><num>②</num> 暗くする.</div>\r\n","<div class=\"hw\">tenebricōsitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://tenebricōsus\">tenebricōsus</a>]</div><div class=\"def\">目まい.</div>\r\n","<div class=\"hw\">tenebricōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://tenebricus\">tenebricus</a>]</div><div class=\"def\"><num>①</num> 暗い, 闇の.</div><div class=\"def\"><num>②</num> (行為・過去などが)隠された, 闇に包まれた.</div>\r\n","<div class=\"hw\">tenebriō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[tenebrae]</div><div class=\"def\">光を嫌う者, 不正[悪事]を働く者.</div>\r\n","<div class=\"hw\">tenebrārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://tenebrae\">tenebrae</a>]</div><div class=\"def\">卑賤の, 無名の.</div>\r\n","<div class=\"hw\">tenebrātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tenebro]</div><div class=\"def\">目がくらむこと, 目まい.</div>\r\n","<div class=\"hw\">tenebrō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[tenebrae]</div><div class=\"def\">暗くする.</div>\r\n","<div class=\"hw\">tenebrōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tenebrae]</div><div class=\"def\">暗い;陰気な.</div>\r\n","<div class=\"hw\">tenebrōsē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://tenebrōsus\">tenebrōsus</a>]</div><div class=\"def\">暗く.</div>\r\n","<div class=\"hw\">Tenedius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tenedos の.</div>\r\n","<div class=\"hw\">Tenedos, -us</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テネドス《エーゲ海の Troas 沖の小島;現トルコ領 Bozcaada》.</div>\r\n","<div class=\"hw\">tenellulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"def\">=<a href=\"entry://tenellus\">tenellus</a>.</div>\r\n","<div class=\"hw\">tenellus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[tener]</div><div class=\"def\">きゃしゃな;か弱い.</div>\r\n","<div class=\"hw\">tenens</div><div class=\"pos\">-entis, <SUP>◇</SUP><i>m</i>(<i>prp</i>)</div><div class=\"ori\">[teneo]</div><div class=\"def\">〘史〙封建家臣, 封臣.</div>\r\n","<div class=\"hw\">tener</div><div class=\"pos\">-era -erum, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://teneō\">teneō</a>]</div><div class=\"def\"><num>①</num> 柔らかい.</div><div class=\"def\"><num>②</num> もろい, 弱い;軟弱な.</div><div class=\"def\"><num>③</num> 若い, 幼い.</div><div class=\"def\"><num>④</num> 順応性のある, 柔軟な.</div><div class=\"def\"><num>⑤</num> 繊細な;しなやかな, 優美な.</div>\r\n","<div class=\"hw\">tenerascō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://tener\">tener</a>]</div><div class=\"def\">たるむ, ゆるむ</div><div class=\"ex\"><i>in tenero tenerascere corpore mentem</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">弱い肉体の中では精神もたるむ.</span></div>\r\n","<div class=\"hw\">tenerescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[tener]</div><div class=\"def\">柔らかくなる;ゆるむ, 薄くなる.</div>\r\n","<div class=\"hw\">teneriter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"def\">=<a href=\"entry://tenerē\">tenere</a>.</div>\r\n","<div class=\"hw\">teneritās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[tener]</div><div class=\"def\"><num>①</num> 柔らかさ.</div><div class=\"def\"><num>②</num> もろさ.</div><div class=\"def\"><num>③</num> 若さ;未熟.</div><div class=\"def\"><num>④</num> 優美さ, 上品さ;優しさ.</div>\r\n","<div class=\"hw\">teneritūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"def\"><num>①</num> 柔らかさ, 砕けやすさ.</div><div class=\"def\"><num>②</num> 若い[幼い]こと.</div><div class=\"def\"><num>③</num> 優しさ.</div>\r\n","<div class=\"hw\">tenerē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tener]</div><div class=\"def\"><num>①</num> 柔らかく;なまめかしく.</div><div class=\"def\"><num>②</num> 優美に;弱々しく.</div>\r\n","<div class=\"hw\">tenerōsitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tener]</div><div class=\"def\">幼少, 幼年.</div>\r\n","<div class=\"hw\">teneō</div><div class=\"pos\">-ēre tenuī tentum, <i>tr</i>(<i>intr</i>)</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> しっかり持つ, つかむ, 握る</div><div class=\"ex\"><i>cibum ore tenere</i> (<author>P<small>HAEDR</small></author>)<span class=\"ext\">えさを口にくわえる.</span></div><div class=\"def\"><num>②</num> つかまえる, 支える;抱きしめる.</div><div class=\"def\"><num>③</num> 中に持つ, 含む</div><div class=\"ex\"><i>exspectabant omnes quidnam in tabulis teneretur</i> (<author>C<small>IC</small></author>)<span class=\"ext\">全員その帳簿に一体何が記入されているかと期待して見守った.</span></div><div class=\"def\"><num>④</num> (位置・場所を)占める;(...に)住む;しばしば訪れる.</div><div class=\"def\"><num>⑤</num> 占拠[占領]する;支配する.</div><div class=\"def\"><num>⑥</num> 取り押える, 捕まえる;有罪と決する 〈+<i>gen</i> [<i>abl</i>]〉.</div><div class=\"def\"><num>⑦</num> 引き止める, 留まらせる.</div><div class=\"def\"><num>⑧</num> 抑える, 控える, 慎む;妨げる 〈quin, quominus, ne〉.</div><div class=\"def\"><num>⑨</num> (法律・誓約などが)束縛する, (義務を)負わせる.</div><div class=\"def\"><num>⑩</num> (感情などが人を)とらえる, 襲う</div><div class=\"ex\"><i>magna spes me tenet</i> 〈+<i>acc c. inf</i>〉 (<author>C<small>IC</small></author>)<span class=\"ext\">私は...したいとの大きな希望を持っている.</span></div><div class=\"def\"><num>⑪</num> (地位・官職などを)占める, 勤める.</div><div class=\"def\"><num>⑫</num> 持ち続ける, 保つ, 維持する</div><div class=\"ex\"><i>cursum [iter, viam] tenere</i><span class=\"ext\">進路を守る.</span></div><div class=\"def\"><num>⑬</num> 固執する, (主張などを)通す</div><div class=\"ex\"><i>causam tenere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">訴訟に勝つ.</span></div><div class=\"def\"><num>⑭</num> (ある地点・場所に)着く, 達する;なし遂げる.</div><div class=\"def\"><num>⑮</num> 理解する, 知る.</div><div class=\"def\"><num>⑯</num> 心に留める, 記憶する.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> (場所を)ずっと占拠する.</div><div class=\"def\"><num>②</num> (ある方向へ)進み続ける</div><div class=\"ex\"><i>inter utrumque tene</i> (<author>O<small>V</small></author>)<span class=\"ext\">おまえはずっと両者の間を進むのだ.</span></div><div class=\"def\"><num>③</num> 持続[継続]する</div><div class=\"ex\"><i>imber per noctem totam tenuit</i> (<author>L<small>IV</small></author>)<span class=\"ext\">雨は一晩中降りやまなかった</span></div><div class=\"ex\"><i>tenet fama</i> 〈+<i>acc c. inf</i>〉 (<author>L<small>IV</small></author>)<span class=\"ext\">...と語り伝えられている.</span></div>\r\n","<div class=\"hw\">Tenitae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">〘神話〙運命の女神たち(=<a href=\"entry://Parca\">Parcae</a>).</div>\r\n","<div class=\"hw\">Ten(n)ēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テ(ン)ネース《Cycnus の息子;Tenedos 島に流れつき, その名の由来となった英雄》.</div>\r\n","<div class=\"hw\">tenor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[teneo]</div><div class=\"def\"><num>①</num> 途切れない進行[進み方], 連続した動き</div><div class=\"ex\"><i>hasta servat tenorem</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">槍が一直線に飛ぶ</span></div><div class=\"ex\"><i>uno tenore</i> (<author>C<small>IC</small></author>)<span class=\"ext\">一気に, 中断することなく.</span></div><div class=\"def\"><num>②</num> 持続, 継続.</div><div class=\"def\"><num>③</num> (声の)抑揚, 調子.</div><div class=\"def\"><num>④</num> (法律・文書の)文面, 主旨.</div>\r\n","<div class=\"hw\">tensa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 神像を乗せて競技場へ運ぶ車.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(一般に)荷車.</div>\r\n","<div class=\"hw\">tensibilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tendo<SUP>1</SUP>]</div><div class=\"def\">張ることのできる, 伸長性のある.</div>\r\n","<div class=\"hw\">tensiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[tendo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 強く引っ張ること.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(天幕を)張ること.</div><div class=\"def\"><num>③</num> (筋肉などの)収縮, 緊張.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 勃起.</div>\r\n","<div class=\"hw\">tensor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[tendo<SUP>1</SUP>]</div><div class=\"def\">〘解〙張筋.</div>\r\n","<div class=\"hw\">tensus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[tendo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> ぴんと張った, 張りつめた.</div><div class=\"def\"><num>②</num> (性的に)興奮した, 勃起した.</div>\r\n","<div class=\"hw\">tensūra</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tendo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> (身体の)緊張.</div><div class=\"def\"><num>②</num> (天幕を)張ること.</div><div class=\"def\"><num>③</num> 勃起.</div>\r\n","<div class=\"hw\">tentiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[tendo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> =<a href=\"entry://tensiō\">tensio 1</a>.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 延長.</div>\r\n","<div class=\"hw\">tentus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://tendō\">tendo<SUP>1</SUP></a>, <a href=\"entry://teneō\">teneo</a>.</div><hr><div class=\"hw\">tentus<SUP>2</SUP></div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[teneo]</div><div class=\"def\">止<SUB>と</SUB>めること.</div>\r\n","<div class=\"hw\">Tentyra</div><div class=\"pos\">-ōrum, <i>n pl</i>, <B>-ris</B> -idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テンテュラ《上エジプトの町》.</div>\r\n","<div class=\"hw\">Tentyrītae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"def\">Tentyra の住民.</div>\r\n","<div class=\"hw\">Tentyrīticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tentyra の.</div>\r\n","<div class=\"hw\">tentā-</div><div class=\"def\">⇒tempta-.</div>\r\n","<div class=\"hw\">tentīgō</div><div class=\"pos\">-ginis, <i>f</i></div><div class=\"ori\">[tendo<SUP>1</SUP>]</div><div class=\"def\">過度の性的興奮, 持続勃起.</div>\r\n","<div class=\"hw\">tentō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"def\">=<a href=\"entry://temptō\">tempto</a>.</div>\r\n","<div class=\"hw\">tentōriolum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://tentōrium\">tentōrium</a>]</div><div class=\"def\">小さなテント.</div>\r\n","<div class=\"hw\">tentōrium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tendo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> テント, 天幕.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙</div><div class=\"ex\"><i>～ cerebelli</i><span class=\"ext\">小脳天幕.</span></div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘昆〙幕状骨.</div>\r\n","<div class=\"hw\">tentōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://tentōrium\">tentōrium</a>]</div><div class=\"def\">天幕用の.</div>\r\n","<div class=\"hw\">tenuescō</div><div class=\"pos\">-ere, <SUP>◇</SUP><i>intr inch</i></div><div class=\"def\">(月が)欠け始める.</div>\r\n","<div class=\"hw\">tenuiculus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://tenuis\">tenuis</a>]</div><div class=\"def\">いくぶん粗末[質素]な.</div>\r\n","<div class=\"hw\">tenuis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\"><num>①</num> 細い;やせた;狭い</div><div class=\"ex\"><i>subtemen tenue</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">細い糸.</span></div><div class=\"def\"><num>②</num> 薄い</div><div class=\"ex\"><i>murus</i> ～ (<author>C<small>IC</small></author>)<span class=\"ext\">薄い壁.</span></div><div class=\"def\"><num>③</num> (気体・液体など)希薄な;澄んだ.</div><div class=\"def\"><num>④</num> (影・幽霊など)ぼんやり見える, ぼやけた.</div><div class=\"def\"><num>⑤</num> 弱い, 力のない;かすかな.</div><div class=\"def\"><num>⑥</num> 小さい;細かい</div><div class=\"ex\"><i>～ formica</i> (<author>J<small>UV</small></author>)<span class=\"ext\">小さなアリ.</span></div><div class=\"def\"><num>⑦</num> 繊細な;微妙な</div><div class=\"ex\"><i>tenues Athenae</i> (<author>M<small>ART</small></author>)<span class=\"ext\">洗練された都市 Athenae.</span></div><div class=\"def\"><num>⑧</num> 少ない, 乏しい;貧しい;下賤な.</div><div class=\"def\"><num>⑨</num> 取るに足らない, つまらない.</div><div class=\"def\"><num>⑩</num> (文章など)飾らない, 簡素[簡潔]な.</div>\r\n","<div class=\"hw\">tenuiter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tenuis]</div><div class=\"def\"><num>①</num> 薄く;細かく.</div><div class=\"def\"><num>②</num> 少なく, 乏しく.</div><div class=\"def\"><num>③</num> 力なく, 弱々しく.</div><div class=\"def\"><num>④</num> 繊細に, 精細に.</div><div class=\"def\"><num>⑤</num> 飾らず, 簡素に.</div>\r\n","<div class=\"hw\">tenuitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://tenuis\">tenuis</a>]</div><div class=\"def\"><num>①</num> 細いこと;やせていること.</div><div class=\"def\"><num>②</num> 薄いこと, 希薄.</div><div class=\"def\"><num>③</num> 欠乏, 貧困;質素.</div><div class=\"def\"><num>④</num> 洗練されていること;微妙なこと.</div><div class=\"def\"><num>⑤</num> 文飾のないこと, 簡素.</div>\r\n","<div class=\"hw\">tenus<SUP>1</SUP></div><div class=\"pos\">-noris, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> わな.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(伸ばした)なわ.</div><hr><div class=\"hw\">tenus<SUP>2</SUP></div><div class=\"pos\"><i>prep</i></div><div class=\"def\">(後置される)</div><div class=\"ori\">[<i>cf. </i> teneo, tendo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> ...に(至る)まで, ...を限度として</div><div class=\"ex\">〈+<i>gen</i>(通例 <i>pl</i>)〉 <i>lumborum ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">腰まで</span></div><div class=\"ex\"><i>Cumarum ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Cumae まで</span></div><div class=\"ex\">〈+<i>abl</i>(通例 <i>sg</i>)〉 <i>lateri capulo ～ abdidit ensem</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">脇腹に剣を柄<SUB>つか</SUB>も通れと突き刺した</span></div><div class=\"ex\"><i>Cantabrico ～ bello</i> (<author>S<small>UET</small></author>)<span class=\"ext\">Cantabria の戦まで.</span></div><div class=\"def\"><num>②</num> ...に可能な限りで 〈+<i>abl</i>〉</div><div class=\"ex\"><i>titulo ～</i> (<author>S<small>UET</small></author>)<span class=\"ext\">(...の)肩書きで</span></div><div class=\"ex\"><i>verbo ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ことばの上だけで(=純理論的に).</span></div>\r\n","<div class=\"hw\">tenuābilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tenuo]</div><div class=\"def\">薄める, 希釈用の.</div>\r\n","<div class=\"hw\">tenuārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tenuis]</div><div class=\"def\">《碑》薄地[薄手]の.</div>\r\n","<div class=\"hw\">tenuātim</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[tenuo]</div><div class=\"def\">薄く.</div>\r\n","<div class=\"hw\">tenuātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tenuo]</div><div class=\"def\">やせ衰えること, 衰弱.</div>\r\n","<div class=\"hw\">tenuō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[tenuis]</div><div class=\"def\"><num>①</num> 薄くする;細くする.</div><div class=\"def\"><num>②</num> やつれ[やせ衰え]させる;弱める.</div><div class=\"def\"><num>③</num> (糸を)紡ぎ出す;(詩を)作る.</div>\r\n","<div class=\"hw\">tenācia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tenax]</div><div class=\"def\"><num>①</num> (馬が)御しがたいこと, 強情.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 貪欲.</div>\r\n","<div class=\"hw\">tenāciter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tenax]</div><div class=\"def\"><num>①</num> ぎゅっとつかんで.</div><div class=\"def\"><num>②</num> 頑固に, 執拗に.</div>\r\n","<div class=\"hw\">tenācitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[tenax]</div><div class=\"def\">しっかりつかむこと;堅持, 固守;強情.</div>\r\n","<div class=\"hw\">tenāculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[teneo]</div><div class=\"def\">つかむ道具.</div>\r\n","<div class=\"hw\">tenōn</div><div class=\"pos\">-ontis, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://tendō\">tendo<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">tepefacere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://tepefaciō\">tepefacio</a>.</div>\r\n","<div class=\"hw\">tepefaciō</div><div class=\"pos\">-ere -fēcī -factum, <i>tr</i></div><div class=\"ori\">[tepeo/facio]</div><div class=\"def\">温[暖]める, 熱する.</div>\r\n","<div class=\"hw\">tepefactus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://tepefaciō\">tepefacio</a>.</div>\r\n","<div class=\"hw\">tepefactō</div><div class=\"pos\">-āre, <i>tr freq</i></div><div class=\"ori\">[↑<a href=\"entry://tepefaciō\">tepefaciō</a>]</div><div class=\"def\">温[暖]める(のを常とする).</div>\r\n","<div class=\"hw\">tepefēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tepefaciō\">tepefacio</a>.</div>\r\n","<div class=\"hw\">tepescō</div><div class=\"pos\">-ere -puī, <i>intr</i>, <i>tr inch</i></div><div class=\"ori\">[↑<a href=\"entry://tepeō\">tepeō</a>]</div><div class=\"def\"><num>①</num> 温[暖]まる, 温[暖]かくなる.</div><div class=\"def\"><num>②</num> ぬるくなる, 冷める.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 冷やす.</div>\r\n","<div class=\"hw\">tepeō</div><div class=\"pos\">-ēre -puī, <i>intr</i></div><div class=\"def\"><num>①</num> 温[暖]かい;ぬるい.</div><div class=\"def\"><num>②</num> 恋心を抱いて熱くなっている.</div><div class=\"def\"><num>③</num> たいして興味がない, 熱がない.</div>\r\n","<div class=\"hw\">tepidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tepeo]</div><div class=\"def\"><num>①</num> 温[暖]かい;温暖な.</div><div class=\"def\"><num>②</num> 生ぬるい.</div><div class=\"def\"><num>③</num> 熱意のない, 冷淡な.</div>\r\n","<div class=\"hw\">tepidārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tepidārius\">tepidārius</a>]</div><div class=\"def\">(caldarium より低い温度の)温浴室.</div>\r\n","<div class=\"hw\">tepidārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tepidus]</div><div class=\"def\">温浴(室)用の.</div>\r\n","<div class=\"hw\">tepidē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tepidus]</div><div class=\"def\"><num>①</num> 温かく.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 不熱心に, 気持を入れず.</div>\r\n","<div class=\"hw\">tepidō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://tepidus\">tepidus</a>]</div><div class=\"def\">温[暖]める.</div>\r\n","<div class=\"hw\">tepor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[tepeo]</div><div class=\"def\"><num>①</num> 温[暖]かさ.</div><div class=\"def\"><num>②</num> 生ぬるいこと.</div><div class=\"def\"><num>③</num> (文章の)生気のなさ.</div>\r\n","<div class=\"hw\">Tepulus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><i>aqua Tepula</i> (<author>P<small>LIN</small></author>) テプラ水道《ローマ市南東にある Albanus mons からローマ市へ至る水道;前125年頃建造》.</div>\r\n","<div class=\"hw\">tepuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tepeō\">tepeo</a>, <a href=\"entry://tepescō\">tepesco</a>.</div>\r\n","<div class=\"hw\">tepōrus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tepor]</div><div class=\"def\">暖かい, 温暖な.</div>\r\n","<div class=\"hw\">tepōrātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://tepor\">tepor</a>]</div><div class=\"def\">熱せられた.</div>\r\n","<div class=\"hw\">ter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tres]</div><div class=\"def\"><num>①</num> 3度, 3回</div><div class=\"ex\"><i>～ centum milia</i> (<author>H<small>OR</small></author>)<span class=\"ext\">30万.</span></div><div class=\"def\"><num>②</num> (強調)非常に</div><div class=\"ex\"><i>stulte bis ～que</i> (<author>C<small>IC</small></author>)<span class=\"ext\">二重三重に(=はなはだしく)愚かに</span></div><div class=\"ex\"><i>o ～que quaterque beati</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">ああ, 3倍も4倍も(=非常に)恵まれた人々よ.</span></div>\r\n","<div class=\"hw\">teratologia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘生物〙奇形学.</div>\r\n","<div class=\"hw\">teratōma</div><div class=\"pos\">-atis, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘医〙奇形腫.</div>\r\n","<div class=\"hw\">tercentum</div><div class=\"pos\"><i>indecl num card</i></div><div class=\"def\">300(の)(=<a href=\"entry://trecentī\">trecenti</a>).</div>\r\n","<div class=\"hw\">terdeciens, -ēs</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">13回[倍].</div>\r\n","<div class=\"hw\">terebinthinus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テレビンノキの, トクノウコウの</div><div class=\"ex\"><i>resina terebinthina</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">テレビン樹脂.</span></div>\r\n","<div class=\"hw\">terebinthus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙テレビンノキ, トクノウコウ.</div>\r\n","<div class=\"hw\">terebra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tero]</div><div class=\"def\"><num>①</num> 穴あけ道具, 錐<SUB>きり</SUB>.</div><div class=\"def\"><num>②</num> 〘医〙(外科用の)トレパン, 管錐.</div><div class=\"def\"><num>③</num> 〘軍〙(壁に穴をあける)攻城器械.</div>\r\n","<div class=\"hw\">terebrum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[terebra]</div><div class=\"def\">穴あけ道具, 錐.</div>\r\n","<div class=\"hw\">terebrātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[terebro]</div><div class=\"def\"><num>①</num> 穴をあけること, 穿孔<SUB>せんこう</SUB>.</div><div class=\"def\"><num>②</num> (あけられた)穴.</div>\r\n","<div class=\"hw\">terebrātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">=<a href=\"entry://terebrātiō\">terebratio 1</a>.</div>\r\n","<div class=\"hw\">terebrō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[terebra]</div><div class=\"def\"><num>①</num> 穴をあける, 突き刺す.</div><div class=\"def\"><num>②</num> (人を)うまく言いくるめる.</div>\r\n","<div class=\"hw\">Terentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">テレンティア《Cicero の妻》.</div>\r\n","<div class=\"hw\">Terentilius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">テレンティリウス《ローマ人の氏族名;特に <i>C. ～ Harsa</i>, 護民官(前462)》.</div>\r\n","<div class=\"hw\">Terentius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">テレンティウス《ローマ人の氏族名;特に (1) <i>P. ～ Afer</i>, 喜劇詩人(前190?‐159).(2) <i>C. ～ Varro</i> ⇒ <a href=\"entry://Varrō\">Varro</a>.(3) <i>M. ～ Varro</i> ⇒ <a href=\"entry://Varrō\">Varro</a>》.</div><hr><div class=\"hw\">Terentius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Terentius の.</div>\r\n","<div class=\"hw\">Terentiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Terentius (1)  (2) の.</div>\r\n","<div class=\"hw\">Terentum</div><div class=\"pos\">-ī, <i>n</i>, <B>-tus</B> -ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Tarentum\">Tarentum<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">teres</div><div class=\"pos\">-retis, <i>adj</i></div><div class=\"ori\">[tero]</div><div class=\"def\"><num>①</num> 磨かれた, すべすべした.</div><div class=\"def\"><num>②</num> 丸みを帯びた;すらりとした.</div><div class=\"def\"><num>③</num> きつく撚<SUB>よ</SUB>った, しっかり編んだ.</div><div class=\"def\"><num>④</num> (話し方・文章が)なめらかな, 洗練された;(耳が)鋭敏な.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘解〙円の.</div>\r\n","<div class=\"hw\">tergeminus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://trigeminus\">trigeminus</a>.</div>\r\n","<div class=\"hw\">Tergeste</div><div class=\"pos\">-is, <i>n</i>, <B>-tum</B> -ī, <i>n</i></div><div class=\"def\">テルゲステ《Histria 半島の沿岸の町;現 Trieste》.</div>\r\n","<div class=\"hw\">Tergestīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tergeste の.</div><div class=\"hw2\"><b>Tergestīnī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Tergeste の住民.</div>\r\n","<div class=\"hw\">tergeō</div><div class=\"pos\">-ēre tersī tersum, <i>tr</i></div><div class=\"def\"><num>①</num> こすってきれいにする, 磨く.</div><div class=\"def\"><num>②</num> ふく, ぬぐう;清掃する</div><div class=\"ex\"><i>manu lacrimantia tersit lumina</i> (<author>O<small>V</small></author>)<span class=\"ext\">手で涙のやどる目をぬぐった.</span></div><div class=\"def\"><num>③</num> (感覚を)刺激する.</div><div class=\"def\"><num>④</num> 改善する;償う.</div>\r\n","<div class=\"hw\">tergilla</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tergum]</div><div class=\"def\">(料理に使う)豚の皮.</div>\r\n","<div class=\"hw\">tergiversanter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tergiversor]</div><div class=\"def\">しぶしぶ, いやいや(ながら).</div>\r\n","<div class=\"hw\">tergiversor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[tergum/verso]</div><div class=\"def\">しりごみする, 言い逃れをする.</div>\r\n","<div class=\"hw\">tergiversātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[tergiversor]</div><div class=\"def\">しりごみ[躊躇<SUB>ちゅうちょ</SUB>]すること;(責任・義務などの)回避.</div>\r\n","<div class=\"hw\">tergiversātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[tergiversor]</div><div class=\"def\">しりごみする[ためらう]人.</div>\r\n","<div class=\"hw\">tergiversātōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://tergiversor\">tergiversor</a>]</div><div class=\"def\">言いつくろいの, 逃げ口上の.</div>\r\n","<div class=\"hw\">tergorō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[tergus]</div><div class=\"def\">おおう, 塗りたくる.</div>\r\n","<div class=\"hw\">tergum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 背, 背中</div><div class=\"ex\"><i>tergo ac capite punire</i> (<author>L<small>IV</small></author>)<span class=\"ext\">鞭で打たれ斬首される</span></div><div class=\"ex\"><i>terga vertere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">敗走する</span></div><div class=\"ex\"><i>a tergo</i><span class=\"ext\">背後から, 後ろで.</span></div><div class=\"def\"><num>②</num> 裏, 反対側</div><div class=\"ex\"><i>ad terga collis</i> (<author>L<small>IV</small></author>)<span class=\"ext\">丘の向こう側へ.</span></div><div class=\"def\"><num>③</num> (動物の)背(肉), 胴体</div><div class=\"ex\"><i>centum terga suum</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">百頭の豚.</span></div><div class=\"def\"><num>④</num> (動物の)皮;皮革製品《袋・楯・拳闘用籠手<SUB>こて</SUB>・タンバリンなど》.</div><div class=\"def\"><num>⑤</num> (土地・海などの広い)表面.</div><div class=\"def\"><num>⑥</num> (畑の)畝<SUB>うね</SUB>.</div>\r\n","<div class=\"hw\">tergus</div><div class=\"pos\">-oris, <i>n</i></div><div class=\"ori\">[<i>cf. </i> tegus]</div><div class=\"def\"><num>①</num> 背, 背中.</div><div class=\"def\"><num>②</num> (動物の)背(肉), 胴体.</div><div class=\"def\"><num>③</num> (動物の)皮, 皮革;(<i>pl</i>)盾.</div>\r\n","<div class=\"hw\">tergīnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tergum]</div><div class=\"def\">革のむち[ひも].</div>\r\n","<div class=\"hw\">tergō</div><div class=\"pos\">-ere -rsī -rsum, <i>tr</i></div><div class=\"def\">=<a href=\"entry://tergeō\">tergeo</a>.</div>\r\n","<div class=\"hw\">terjugus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ter/jugum]</div><div class=\"def\">三つの, 3倍の.</div>\r\n","<div class=\"hw\">termen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"def\"><num>①</num> 境界標, 境界石.</div><div class=\"def\"><num>②</num> 《碑》期限.</div>\r\n","<div class=\"hw\">termentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tero/mentum]</div><div class=\"def\">(足の)まめ.</div>\r\n","<div class=\"hw\">termes</div><div class=\"pos\">-mitis, <i>m</i></div><div class=\"def\">(木の)枝.</div>\r\n","<div class=\"hw\">Termes</div><div class=\"pos\"><i>indecl n</i></div><div class=\"def\">テルメス《Hispania Tarraconensis の町》.</div>\r\n","<div class=\"hw\">Termestīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Termes の.</div><div class=\"hw2\"><b>Termestīnī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Termes の住民.</div>\r\n","<div class=\"hw\">terminus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 境界標, 境界石.</div><div class=\"def\"><num>②</num> 地の果て, さいはての地;(<i>pl</i>)国境地方.</div><div class=\"def\"><num>③</num> 境界, 限界.</div><div class=\"def\"><num>④</num> 終わり, 結末.</div><div class=\"def\"><num>⑤</num> (T-)〘神話〙テルミヌス《ローマの境界(標)の神》</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP> 判決, 裁定.</div><div class=\"def\"><num>⑦</num> <SUP>◇</SUP>〘論〙名辞.</div><div class=\"def\"><num>⑧</num> <SUP>◇</SUP> 郡, 郷.</div>\r\n","<div class=\"hw\">terminābilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[termino]</div><div class=\"def\">制限することのできる, 限られた.</div>\r\n","<div class=\"hw\">Terminālia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"def\">Terminus の祭典(2月23日).</div>\r\n","<div class=\"hw\">terminālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[terminus]</div><div class=\"def\"><num>①</num> 境界の.</div><div class=\"def\"><num>②</num> 終わりを告げる.</div>\r\n","<div class=\"hw\">terminātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[termino]</div><div class=\"def\"><num>①</num> 境界を定めること;測量, 測定.</div><div class=\"def\"><num>②</num> 境界;境界地.</div><div class=\"def\"><num>③</num> 限界, 範囲.</div><div class=\"def\"><num>④</num> 結末;〘修〙結句.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘文〙語尾.</div>\r\n","<div class=\"hw\">terminātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[termino]</div><div class=\"def\">限界を設ける者.</div>\r\n","<div class=\"hw\">terminātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://terminō\">termino</a>.</div><hr><div class=\"hw\">terminātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 境界を定めること.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 境界.</div>\r\n","<div class=\"hw\">terminātē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[termino]</div><div class=\"def\">決着ずみとして.</div>\r\n","<div class=\"hw\">terminō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://terminus\">terminus</a>]</div><div class=\"def\"><num>①</num> 境界を定める, 区切る 〈alqd a re〉.</div><div class=\"def\"><num>②</num> 制限する, 限定する.</div><div class=\"def\"><num>③</num> 定義する</div><div class=\"ex\"><i>bona voluptate, mala dolore terminare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">善を快楽によって, 悪を苦痛によって定義する.</span></div><div class=\"def\"><num>④</num> 終わらせる, 結末をつける.</div><div class=\"def\"><num>⑤</num> (問題・紛争を)解決する, 決着させる.</div>\r\n","<div class=\"hw\">Termēssensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">Termessus の住民.</div>\r\n","<div class=\"hw\">Termēssus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テルメーッスス, <SUP>*</SUP>-ソス《Pisidia の町》.</div>\r\n","<div class=\"hw\">termō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>cf. </i> termen, terminus]</div><div class=\"def\">(競走路の)ゴール標識.</div>\r\n","<div class=\"hw\">ternitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://ternī\">ternī</a>]</div><div class=\"def\">三つ組(=<a href=\"entry://trīnitās\">trinitas</a>).</div>\r\n","<div class=\"hw\">ternus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">terni の <i>sg</i>(稀用).</div>\r\n","<div class=\"hw\">ternārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://ternī\">ternī</a>]</div><div class=\"def\">三つから成る, 三つ一組の.</div>\r\n","<div class=\"hw\">ternī</div><div class=\"pos\">-ae -a, <i>adj pl</i></div><div class=\"ori\">[ter]</div><div class=\"def\"><num>①</num> 三つずつの;三つ一組の.</div><div class=\"def\"><num>②</num> 《詩》三つの, 三人の(=<a href=\"entry://trēs\">tres</a>).</div>\r\n","<div class=\"hw\">Terpsichorē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙テルプシコレー《Musa たちの一人;舞踏・合唱をつかさどる》.</div>\r\n","<div class=\"hw\">terra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 陸, 陸地</div><div class=\"ex\"><i>terrā marique</i> (<author>C<small>IC</small></author>)<span class=\"ext\">陸と海とで.</span></div><div class=\"def\"><num>②</num> 地面, 大地</div><div class=\"ex\"><i>terrae motus</i> (<author>C<small>IC</small></author>)<span class=\"ext\">地震.</span></div><div class=\"def\"><num>③</num> 土, 土壌</div><div class=\"ex\"><i>terrae filius</i> (<author>C<small>IC</small></author>)<span class=\"ext\">素姓も知れない男.</span></div><div class=\"def\"><num>④</num> 土地, 国土</div><div class=\"ex\"><i>～ Italia</i> (<author>L<small>IV</small></author>)<span class=\"ext\">=<a href=\"entry://Italia\">Italia</a>.</span></div><div class=\"def\"><num>⑤</num> (天に対する)地, 地上.</div><div class=\"def\"><num>⑥</num> 世界</div><div class=\"ex\"><i>orbis terrarum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">全世界.</span></div><div class=\"def\"><num>⑦</num> 地球</div><div class=\"ex\"><i>globus terrarum</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">地球</span></div><div class=\"def\"><num>⑧</num> (T-)〘神話〙大地の女神.</div>\r\n","<div class=\"hw\">Terracīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://Tarracīna\">Tarracina</a>.</div>\r\n","<div class=\"hw\">terrester</div><div class=\"pos\">-tris -tre, <i>adj</i></div><div class=\"def\">=<a href=\"entry://terrestris\">terrestris</a>.</div>\r\n","<div class=\"hw\">terrestris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[terra]</div><div class=\"def\"><num>①</num> 陸(上)の.</div><div class=\"def\"><num>②</num> 地面の</div><div class=\"ex\"><i>cibus</i> ～ (<author>V<small>ITR</small></author>)<span class=\"ext\">大地からもたらされる食物.</span></div><div class=\"def\"><num>③</num> 地上の;地球の.</div>\r\n","<div class=\"hw\">terreus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[terra]</div><div class=\"def\">土の, 土でできた</div><div class=\"ex\"><i>virorum terrea progenies</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">人間の土の[から生じた]種族.</span></div>\r\n","<div class=\"hw\">terreō</div><div class=\"pos\">-ēre terruī territum, <i>tr</i></div><div class=\"def\"><num>①</num> こわがらせる, おびえさせる, 威圧する.</div><div class=\"def\"><num>②</num> おどして思いとどまらせる 〈alqm a re;quominus, ne;+<i>inf</i>〉.</div>\r\n","<div class=\"hw\">terribilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[terreo]</div><div class=\"def\"><num>①</num> 恐ろしい, 恐るべき 〈alci〉.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 畏敬<SUB>いけい</SUB>すべき, 尊敬に値する.</div>\r\n","<div class=\"hw\">terribiliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[terribilis]</div><div class=\"def\">恐ろしく.</div>\r\n","<div class=\"hw\">terribilitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://terribilis\">terribilis</a>]</div><div class=\"def\">恐ろしさ.</div>\r\n","<div class=\"hw\">terricola</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[terra/colo<SUP>2</SUP>]</div><div class=\"def\">地上に住む者.</div>\r\n","<div class=\"hw\">terricrepus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[terror/crepo]</div><div class=\"def\">恐ろしげに鳴り響く.</div>\r\n","<div class=\"hw\">terricula</div><div class=\"pos\">-ae, <i>f</i>, <B>-lum</B> -ī, <i>n</i></div><div class=\"ori\">[terreo]</div><div class=\"def\">こわがらせる[おどす]もの;化け物.</div>\r\n","<div class=\"hw\">terriculāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://terricula\">terricula</a>]</div><div class=\"def\">幽霊, お化け.</div>\r\n","<div class=\"hw\">terrificus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[terreo/facio]</div><div class=\"def\">こわがらせる, 恐ろしい.</div>\r\n","<div class=\"hw\">terrificō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://terrificus\">terrificus</a>]</div><div class=\"def\">こわがらせる, おびえさせる.</div>\r\n","<div class=\"hw\">terrigena</div><div class=\"pos\">-ae, <i>m</i>, <i>f</i></div><div class=\"ori\">[terra/gigno]</div><div class=\"def\">大地から生まれた者.</div>\r\n","<div class=\"hw\">terrigenus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[terra/gigno]</div><div class=\"def\">大地から生まれた.</div>\r\n","<div class=\"hw\">terriloquus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[terreo/loquor]</div><div class=\"def\">恐怖を起こさせる.</div>\r\n","<div class=\"hw\">terripavium, -pudium, -puvium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[terra/pavio]</div><div class=\"def\">tripudium (3) の語源と考えられた語.</div>\r\n","<div class=\"hw\">terrisonus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[terreo/sono]</div><div class=\"def\">恐ろしげに響く.</div>\r\n","<div class=\"hw\">territiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[terreo]</div><div class=\"def\">おびえさせること, 威圧.</div>\r\n","<div class=\"hw\">territus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://terreō\">terreo</a>.</div>\r\n","<div class=\"hw\">territō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[terreo]</div><div class=\"def\">おびえさせる, おどす.</div>\r\n","<div class=\"hw\">territōrium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[terra]</div><div class=\"def\">(町などの)領有地.</div>\r\n","<div class=\"hw\">territōriālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://territōrium\">territōrium</a>]</div><div class=\"def\">領地[領土]の.</div>\r\n","<div class=\"hw\">terror</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[terreo]</div><div class=\"def\"><num>①</num> 恐れ, 恐怖 〈alcis〉.</div><div class=\"def\"><num>②</num> 恐怖をひき起こすもの;恐ろしい人[物, 事件].</div>\r\n","<div class=\"hw\">terrula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[terra]</div><div class=\"def\">わずかな地所.</div>\r\n","<div class=\"hw\">terrulenta</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>n pl</i></div><div class=\"ori\">[terrulentus]</div><div class=\"def\">大地の産物, 農作物.</div>\r\n","<div class=\"hw\">terrulentus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[terra]</div><div class=\"def\">地上の, 現世の.</div>\r\n","<div class=\"hw\">terrulentē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://terrulentus\">terrulentus</a>]</div><div class=\"def\">世俗的に.</div>\r\n","<div class=\"hw\">terruncius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[ter/uncia]</div><div class=\"def\">(<i>sc. </i> nummus)</div><div class=\"def\"><num>①</num> 3 unciae の目方の銅貨(=<img class=\"font\" src=\"img/B161.png\"> as).</div><div class=\"def\"><num>②</num> わずかな金額, はした金.</div><div class=\"def\"><num>③</num> (遺産総額の)4分の1.</div>\r\n","<div class=\"hw\">terrāneola</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[terra]</div><div class=\"def\">〘鳥〙ヒバリ.</div>\r\n","<div class=\"hw\">terrārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[terra]</div><div class=\"def\">《碑》(通路として利用される)土手.</div>\r\n","<div class=\"hw\">terrārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[terra]</div><div class=\"def\"><num>①</num> 田舎で気ままに暮らしている.</div><div class=\"def\"><num>②</num> 地上の.</div>\r\n","<div class=\"hw\">terrēnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://terrēnus\">terrēnus</a>]</div><div class=\"def\">土地;土, 土壌</div><div class=\"ex\"><i>herbidum ～</i> (<author>L<small>IV</small></author>)<span class=\"ext\">草の繁った土地.</span></div>\r\n","<div class=\"hw\">terrēnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[terra]</div><div class=\"def\"><num>①</num> 陸の, 陸地の.</div><div class=\"def\"><num>②</num> 大地の, 地面の</div><div class=\"ex\"><i>numina terrena</i> (<author>O<small>V</small></author>)<span class=\"ext\">地下の神々.</span></div><div class=\"def\"><num>③</num> 土の, 土でできた.</div><div class=\"def\"><num>④</num> 世界の;地球の.</div>\r\n","<div class=\"hw\">terrōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[terra]</div><div class=\"def\">土の多い, 土質の.</div>\r\n","<div class=\"hw\">tersus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[tergeo]</div><div class=\"def\"><num>①</num> きちんとした, こぎれいな.</div><div class=\"def\"><num>②</num> 晴天の.</div><div class=\"def\"><num>③</num> (文体・趣味が)洗練された, 品のある.</div>\r\n","<div class=\"hw\">tersī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tergeō\">tergeo</a>.</div>\r\n","<div class=\"hw\">tertia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tertius]</div><div class=\"def\"><num>①</num> (<i>sc. </i> pars)3分の1</div><div class=\"ex\"><i>duae tertiae partes</i> (<author>C<small>OL</small></author>)<span class=\"ext\">3分の2.</span></div><div class=\"def\"><num>②</num> (<i>sc. </i> hora)第3時.</div><div class=\"def\"><num>③</num> (<i>pl</i>)(<i>sc. </i> partes)劇の第三役.</div>\r\n","<div class=\"hw\">Tertia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">テルティア《ローマ人(女性)の個人名》.</div>\r\n","<div class=\"hw\">tertiadecimānī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[tertiusdecimus]</div><div class=\"def\">(<i>sc. </i> milites)第13軍団の兵士たち.</div>\r\n","<div class=\"hw\">tertium</div><div class=\"pos\"><i>adv</i>(<i>neut</i>)</div><div class=\"ori\">[↓<a href=\"entry://tertius\">tertius</a>]</div><div class=\"def\"><num>①</num> 3度目に.</div><div class=\"def\"><num>②</num> 3番目に.</div>\r\n","<div class=\"hw\">tertius</div><div class=\"pos\">-a -um, <i>num ord</i></div><div class=\"ori\">[ter]</div><div class=\"def\"><num>①</num> 第3の, 3番目の</div><div class=\"ex\"><i>tertia regna</i> (<author>O<small>V</small></author>)<span class=\"ext\">下界, 冥府.</span></div><div class=\"def\"><num>②</num> </div><div class=\"ex\"><i>tertia pars</i> (<author>C<small>IC</small></author>)<span class=\"ext\">3分の1.</span></div>\r\n","<div class=\"hw\">Tertius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://tertius\">tertius</a>]</div><div class=\"def\">テルティウス《ローマ人の個人名》.</div>\r\n","<div class=\"hw\">tertiusdecimus, tertius decimus</div><div class=\"pos\">-adecima -umdecimum, <i>num ord</i></div><div class=\"def\">第13の, 13番目の.</div>\r\n","<div class=\"hw\">tertiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tertius]</div><div class=\"def\">3日目ごと[隔日]に起こる</div><div class=\"ex\"><i>tertianae febres</i> (<author>C<small>IC</small></author>)<span class=\"ext\">三日熱.</span></div>\r\n","<div class=\"hw\">tertiānī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://tertiānus\">tertiānus</a>]</div><div class=\"def\">(<i>sc. </i> milites)第3軍団の兵士たち.</div>\r\n","<div class=\"hw\">tertiārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tertius]</div><div class=\"def\">3分の1(のある物)を含む.</div><hr><div class=\"hw\">tertiārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 3分の1.</div><div class=\"def\"><num>②</num> (前の試合で殺された者の代わりをする)控えの剣闘士.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘カト〙(修道会員で俗籍にある)第三会員.</div>\r\n","<div class=\"hw\">tertiō</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[tertius]</div><div class=\"def\"><num>①</num> 3度目に.</div><div class=\"def\"><num>②</num> 3番目に.</div>\r\n","<div class=\"hw\">Tertulliānus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">テルトゥッリアーヌス《<i>Q. Septimius Florens ～</i>, Carthago 生まれのキリスト教神学者(160?‐?220)》.</div>\r\n","<div class=\"hw\">teruncius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://terruncius\">terruncius</a>.</div>\r\n","<div class=\"hw\">tervenēficus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">極悪人.</div>\r\n","<div class=\"hw\">terēdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙フナクイ(船食)虫.</div>\r\n","<div class=\"hw\">Terīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">テリーナ《Bruttii 西海岸の町》.</div>\r\n","<div class=\"hw\">Terīnaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Terina の.</div>\r\n","<div class=\"hw\">terō</div><div class=\"pos\">-ere trīvī trītum, <i>tr</i></div><div class=\"def\"><num>①</num> こする.</div><div class=\"def\"><num>②</num> こすって磨く[研ぐ].</div><div class=\"def\"><num>③</num> 脱穀する.</div><div class=\"def\"><num>④</num> すりつぶす, つき砕く.</div><div class=\"def\"><num>⑤</num> すり減らす</div><div class=\"ex\"><i>tempus adamanta terit</i> (<author>O<small>V</small></author>)<span class=\"ext\">時は金剛石をもすりへらす.</span></div><div class=\"def\"><num>⑥</num> 踏みつける, しばしば通る.</div><div class=\"def\"><num>⑦</num> (時を)使い果たす, むだに費やす 〈(in)re〉.</div><div class=\"def\"><num>⑧</num> 疲れさせる, 消耗させる 〈alqm in re〉.</div><div class=\"def\"><num>⑨</num> (使い過ぎてことばを)陳腐なものにする.</div>\r\n","<div class=\"hw\">tesqua, tesca</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"def\">(<i>sc. </i> loca)荒れ地, 荒蕪<SUB>こうぶ</SUB>地.</div>\r\n","<div class=\"hw\">tessella</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[tessera]</div><div class=\"def\"><num>①</num> (石畳・モザイクなどに使う)小さな立方形の石.</div><div class=\"def\"><num>②</num> さいころ.</div>\r\n","<div class=\"hw\">tessellārius</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↑<a href=\"entry://tessella\">tessella</a>]</div><div class=\"def\">モザイク職人.</div>\r\n","<div class=\"hw\">tessellātim</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://tessellātus\">tessellātus</a>]</div><div class=\"def\">(料理で)賽<SUB>さい</SUB>の目に.</div>\r\n","<div class=\"hw\">tessellātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tessella]</div><div class=\"def\">切りばめ細工の.</div>\r\n","<div class=\"hw\">tessera</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> モザイクの石片.</div><div class=\"def\"><num>②</num> さいころ.</div><div class=\"def\"><num>③</num> 四角形の小片</div><div class=\"def\"><num1>⒜</num1> (軍隊における)合言葉・命令などを記した小板.</div><div class=\"def\"><num1>⒝</num1> </div><div class=\"ex\"><i>～ hospitalis</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">(友人間で分かち持ち, 後に相手を確認するための)割符.</span></div><div class=\"def\"><num1>⒞</num1> </div><div class=\"ex\"><i>～ frumentaria</i> (<author>S<small>UET</small></author>)<span class=\"ext\">穀物の配給切符.</span></div>\r\n","<div class=\"hw\">tesserula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[tessera]</div><div class=\"def\"><num>①</num> モザイクの石片.</div><div class=\"def\"><num>②</num> 小さなさいころ.</div><div class=\"def\"><num>③</num> 穀物の配給切符.</div><div class=\"def\"><num>④</num> 投票札.</div>\r\n","<div class=\"hw\">tesserārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://tessera\">tessera</a>]</div><div class=\"def\">さいころ遊びの.</div><hr><div class=\"hw\">tesserārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> <SUP>◇</SUP> さいころ遊びをする人.</div><div class=\"def\"><num>②</num> (軍隊における)合いことば伝達係の兵.</div>\r\n","<div class=\"hw\">tesserātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tessera]</div><div class=\"def\">(さいころ状の骨を)くっつけた.</div>\r\n","<div class=\"hw\">testa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf. </i> testu, testum]</div><div class=\"def\"><num>①</num> 煉瓦, 瓦.</div><div class=\"def\"><num>②</num> 土製の容器《壺, 瓶など》</div><div class=\"ex\"><i>～ ardens</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">ランプ.</span></div><div class=\"def\"><num>③</num> (陶器の)破片.</div><div class=\"def\"><num>④</num> (甲殻類などの)殻;貝.</div><div class=\"def\"><num>⑤</num> </div><div class=\"ex\"><i>～ lubrica</i> (<author>O<small>V</small></author>)<span class=\"ext\">張りつめた氷.</span></div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP>〘植〙種皮.</div>\r\n","<div class=\"hw\">testeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[testa]</div><div class=\"def\">陶製の, 粘土(製)の.</div>\r\n","<div class=\"hw\">testiculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[testis<SUP>2</SUP>]</div><div class=\"def\">〘解〙睾丸, 精巣.</div>\r\n","<div class=\"hw\">testiculāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://testiculus\">testiculus</a>]</div><div class=\"def\">〘解〙睾丸の, 精巣の.</div>\r\n","<div class=\"hw\">testificor</div><div class=\"pos\">-ārī -ātus sum, <i>tr dep</i></div><div class=\"ori\">[testis<SUP>1</SUP>/facio]</div><div class=\"def\"><num>①</num> 証言する 〈alqd;+<i>acc c. inf</i>;+間接疑問〉.</div><div class=\"def\"><num>②</num> 立証する;明らかにする</div><div class=\"ex\"><i>testificandi amoris mei causā</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私の(あなたへの)好意を示すために.</span></div><div class=\"def\"><num>③</num> 証人として呼ぶ.</div>\r\n","<div class=\"hw\">testificātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[testificor]</div><div class=\"def\"><num>①</num> 証言.</div><div class=\"def\"><num>②</num> 証明, 立証.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 戒律, 掟.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 殉教, 受難.</div>\r\n","<div class=\"hw\">testificātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[↓<a href=\"entry://testificor\">testificor</a>]</div><div class=\"def\">明らかにされた, よく知られた.</div>\r\n","<div class=\"hw\">testimōnium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[testor]</div><div class=\"def\"><num>①</num> 証言.</div><div class=\"def\"><num>②</num> 証明, 立証.</div><div class=\"def\"><num>③</num> 証拠.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 戒律, 掟.</div>\r\n","<div class=\"hw\">testimōniāles</div><div class=\"pos\">-ium, <SUP>◇</SUP><i>f pl</i></div><div class=\"ori\">[↓<a href=\"entry://testimōniālis\">testimōniālis</a>]</div><div class=\"def\">(<i>sc. </i> litterae)証明書.</div>\r\n","<div class=\"hw\">testimōniālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://testimōnium\">testimōnium</a>]</div><div class=\"def\">証拠の, 証明になる.</div>\r\n","<div class=\"hw\">testis<SUP>1</SUP></div><div class=\"pos\">-is, <i>m</i>(<i>f</i>)</div><div class=\"def\"><num>①</num> 証人;立会人.</div><div class=\"def\"><num>②</num> 証拠.</div><div class=\"def\"><num>③</num> 目撃者.</div><hr><div class=\"hw\">testis<SUP>2</SUP></div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">〘解・動〙睾丸, 精巣.</div>\r\n","<div class=\"hw\">testor</div><div class=\"pos\">-ārī -ātus sum, <i>tr</i>, <i>intr dep</i></div><div class=\"ori\">[testis<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 証人として呼ぶ.</div><div class=\"def\"><num>②</num> 証言する;宣言する.</div><div class=\"def\"><num>③</num> 立証[証明]する;明らかにする.</div><div class=\"def\"><num>④</num> 遺言する, 遺言状を作成する 〈de re〉.</div>\r\n","<div class=\"hw\">testula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[testa]</div><div class=\"def\">(特に, Athenae で陶片追放に使われた)陶片, 陶器の破片.</div>\r\n","<div class=\"hw\">testābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[testor]</div><div class=\"def\">証言する権利を有する.</div>\r\n","<div class=\"hw\">testāceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[testa]</div><div class=\"def\"><num>①</num> 煉瓦[瓦]で作った.</div><div class=\"def\"><num>②</num> 煉瓦色の.</div><div class=\"def\"><num>③</num> 殻でおおわれた, 殻をもつ.</div>\r\n","<div class=\"hw\">testāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[testor]</div><div class=\"def\"><num>①</num> 遺言(書).</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘聖〙(神と人との)契約;(契約の)文書</div><div class=\"ex\"><i>vetus ～</i> (<author>V<small>ULG</small></author>)<span class=\"ext\">旧約聖書</span></div><div class=\"ex\"><i>novum ～</i> (<author>H<small>IER</small></author>)<span class=\"ext\">新約聖書.</span></div>\r\n","<div class=\"hw\">testāmentārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[testamentum]</div><div class=\"def\">遺言の[に関する];遺言で指定された.</div><hr><div class=\"hw\">testāmentārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> <SUP>◇</SUP>(雇われた)遺言状作成者.</div><div class=\"def\"><num>②</num> 遺言状偽造者.</div>\r\n","<div class=\"hw\">testātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[testa]</div><div class=\"def\">粉々に.</div>\r\n","<div class=\"hw\">testātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[testor]</div><div class=\"def\"><num>①</num> 証言すること, 証人となること.</div><div class=\"def\"><num>②</num> 〘法〙宣誓証言.</div>\r\n","<div class=\"hw\">testātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[testor]</div><div class=\"def\"><num>①</num> <SUP>◇</SUP> 証人.</div><div class=\"def\"><num>②</num> 遺言者.</div>\r\n","<div class=\"hw\">testātrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://testātor\">testātor</a>]</div><div class=\"def\">(女性の)遺言者.</div>\r\n","<div class=\"hw\">testātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[testor]</div><div class=\"def\"><num>①</num> 立証された, 明白な.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 有効な遺言状を残した.</div>\r\n","<div class=\"hw\">testātō</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[testatus]</div><div class=\"def\"><num>①</num> 証人の前で, 証人立会で.</div><div class=\"def\"><num>②</num> (証言によって)よく知られているように.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 遺言状を作成してのちに.</div>\r\n","<div class=\"hw\">testū</div><div class=\"pos\"><i>indecl n</i>, <B>testum</B> -ī, <i>n</i></div><div class=\"ori\">[<i>cf. </i> testa]</div><div class=\"def\"><num>①</num> 陶製の容器《鍋・鉢など》.</div><div class=\"def\"><num>②</num> 調理用の陶製[金属製]の蓋<SUB>ふた</SUB>.</div>\r\n","<div class=\"hw\">testūdineus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://testūdō\">testūdō</a>]</div><div class=\"def\"><num>①</num> カメのような(足の遅い).</div><div class=\"def\"><num>②</num> カメの甲で作られた[おおわれた].</div>\r\n","<div class=\"hw\">testūdinātus, -neātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[testudo]</div><div class=\"def\">(天井・屋根が)円筒形[アーチ状]の.</div>\r\n","<div class=\"hw\">testūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[testu, testa]</div><div class=\"def\"><num>①</num> 〘動〙カメ(亀).</div><div class=\"def\"><num>②</num> カメの甲, 亀甲.</div><div class=\"def\"><num>③</num> (lyra や cithara などの)撥弦<SUB>はつげん</SUB>楽器《その反響板が亀甲でも作られた》.</div><div class=\"def\"><num>④</num> 亀甲[丸]天井[屋根].</div><div class=\"def\"><num>⑤</num> 〘軍〙亀甲状隊形《攻城の際, 数人の兵士がかたまって盾を亀甲状に連ねて突進した》.</div><div class=\"def\"><num>⑥</num> 〘軍〙亀甲車《攻城の際に使用された屋根つきの装甲車》.</div>\r\n","<div class=\"hw\">teta</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘鳥〙ハト(鳩)の一種.</div>\r\n","<div class=\"hw\">tetanicus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">強直痙攣の患者.</div>\r\n","<div class=\"hw\">tetanus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘生理〙筋肉の強直痙攣.</div><div class=\"def\"><num>②</num> 〘病〙破傷風.</div>\r\n","<div class=\"hw\">tetartēmoria</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘音〙4分の1音.</div>\r\n","<div class=\"hw\">tetartēmorion</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘天・占星〙黄道帯の4分の1(=3宮).</div>\r\n","<div class=\"hw\">tetendī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tendō\">tendo<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">tetigī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tangō\">tango</a>.</div>\r\n","<div class=\"hw\">tetrachmum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(ギリシアの)4ドラクマ銀貨.</div>\r\n","<div class=\"hw\">tetrachordon, -um</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tetrachordos\">tetrachordos</a>]</div><div class=\"def\"><num>①</num> 〘音〙四音音階.</div><div class=\"def\"><num>②</num> 四弦琴.</div><div class=\"def\"><num>③</num> </div><div class=\"ex\"><i>～ anni</i> (<author>V<small>ARR</small></author>)<span class=\"ext\">四季.</span></div>\r\n","<div class=\"hw\">tetrachordos</div><div class=\"pos\">-os -on, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘音〙四音音階の.</div><div class=\"def\"><num>②</num> 4弦から成る.</div>\r\n","<div class=\"hw\">tetracōlon</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tetracōlos\">tetracōlos</a>]</div><div class=\"def\">〘文・修〙4個の並列節から成る文.</div>\r\n","<div class=\"hw\">tetracōlos</div><div class=\"pos\">-os -on, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘詩・修〙4行から成る.</div>\r\n","<div class=\"hw\">tetradium, -dēum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">4個[人]一組.</div>\r\n","<div class=\"hw\">tetradrachmum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://tetrachmum\">tetrachmum</a>.</div>\r\n","<div class=\"hw\">tetradōros</div><div class=\"pos\">-os -on, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">4手幅尺の.</div>\r\n","<div class=\"hw\">tetraetēris</div><div class=\"pos\">-idis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">4年間.</div>\r\n","<div class=\"hw\">tetragnathius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙毒グモの一種.</div>\r\n","<div class=\"hw\">tetragrammatos</div><div class=\"pos\">-os -on, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">4文字から成る.</div>\r\n","<div class=\"hw\">tetragōnicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://tetragōnālis\">tetragonalis</a>.</div>\r\n","<div class=\"hw\">tetragōnium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://tetragōnum\">tetragonum</a>.</div>\r\n","<div class=\"hw\">tetragōnum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">四角形, 正方形.</div>\r\n","<div class=\"hw\">tetragōnus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 四角[正方]形の.</div><div class=\"def\"><num>②</num> 〘占星〙</div><div class=\"ex\"><i>～ aspectus</i> (<author>A<small>US</small></author>)<span class=\"ext\">惑星間の角度が90度になる星相.</span></div>\r\n","<div class=\"hw\">tetragōnālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tetragonum]</div><div class=\"def\">四角(形)の.</div>\r\n","<div class=\"hw\">tetralix</div><div class=\"pos\">-icis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙アザミの類.</div>\r\n","<div class=\"hw\">tetrametrus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘詩〙四歩格の.</div>\r\n","<div class=\"hw\">tetrans</div><div class=\"pos\">-antis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 4分の1.</div><div class=\"def\"><num>②</num> 四分円.</div><div class=\"def\"><num>③</num> 2本の直径の交点, 円の中心;2本の線の交点.</div>\r\n","<div class=\"hw\">tetrapharmacum, -on</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 四つの成分から成る膏薬.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 4皿の料理が出る食事.</div>\r\n","<div class=\"hw\">tetraplasius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">4倍の.</div>\r\n","<div class=\"hw\">tetraplō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">4倍にする.</div>\r\n","<div class=\"hw\">tetraptōton</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘文〙四つの格だけを有する語.</div>\r\n","<div class=\"hw\">tetraptōtos</div><div class=\"pos\">-os -on, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘文〙四つの格だけを有する.</div>\r\n","<div class=\"hw\">Tetrapūs</div><div class=\"pos\">-podis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">「四足獣(料理)」《Apicius に帰せられる <i>de Re Coquinaria</i> 「料理大全」 の第8巻の題名》.</div>\r\n","<div class=\"hw\">tetrarcha</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"def\">=<a href=\"entry://tetrarchēs\">tetrarches</a>.</div>\r\n","<div class=\"hw\">tetrarchia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">四分領太守[小君主]の領地.</div>\r\n","<div class=\"hw\">tetrarchēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">四分領太守;(属州の)小王, 小君主.</div>\r\n","<div class=\"hw\">tetras</div><div class=\"pos\">-adis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (数の)4.</div><div class=\"def\"><num>②</num> 4個一組.</div>\r\n","<div class=\"hw\">tetrastichon</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘詩〙四行詩.</div>\r\n","<div class=\"hw\">tetrastichos</div><div class=\"pos\">-os -on, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 四行詩の.</div><div class=\"def\"><num>②</num> 4柱列の.</div>\r\n","<div class=\"hw\">tetrastȳlon, -um</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tetrastȳlus\">tetrastȳlus</a>]</div><div class=\"def\">《碑》四柱式建築物.</div>\r\n","<div class=\"hw\">tetrastȳlus</div><div class=\"pos\">-a -um, <B> -stȳlos</B> -os -on, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘建〙4本の柱のある, 四柱式の.</div>\r\n","<div class=\"hw\">tetrasyllabus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">4音節の.</div>\r\n","<div class=\"hw\">tetrasēmus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">4音節の.</div>\r\n","<div class=\"hw\">tetrax</div><div class=\"pos\">-acis, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://tetraō\">tetrao</a>.</div>\r\n","<div class=\"hw\">tetraō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘鳥〙ライチョウの類.</div>\r\n","<div class=\"hw\">Tetrica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">テトリカ《Sabini 族の領土にある岩山》.</div>\r\n","<div class=\"hw\">tetricitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://tetricus\">tetricus</a>]</div><div class=\"def\">いかめしさ, 厳格.</div>\r\n","<div class=\"hw\">tetricus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> いかめしい, 厳格な;不機嫌な, 無愛想な</div><div class=\"ex\"><i>tetricae deae</i> (<author>M<small>ART</small></author>)<span class=\"ext\">=<a href=\"entry://Parca\">Parcae</a>.</span></div><div class=\"def\"><num>②</num> (山などが)険しい, 切り立った.</div>\r\n","<div class=\"hw\">tetrinniō</div><div class=\"pos\">-īre, <SUP>◇</SUP><i>intr</i></div><div class=\"def\">=<a href=\"entry://tetrissitō\">tetrissito</a>.</div>\r\n","<div class=\"hw\">tetrissitō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"def\">(アヒルなどが)ガーガー鳴く.</div>\r\n","<div class=\"hw\">tettīgomētra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">セミの幼虫.</div>\r\n","<div class=\"hw\">tettīgonium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">小型のセミ.</div>\r\n","<div class=\"hw\">tetulī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">《古形》=<a href=\"entry://tulī\">tuli</a>(⇒ <a href=\"entry://ferō\">fero</a>).</div>\r\n","<div class=\"hw\">Teucer, -crus<SUP>1</SUP></div><div class=\"pos\">-crī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テウケル, <SUP>*</SUP>テウクロス《 (1) Salamis の王 Telamon の息子で Ajax の異母兄弟.(2) Scamander 河神の息子で Dardanus の義父;Troja 王家の祖》.</div>\r\n","<div class=\"hw\">teuchītis</div><div class=\"pos\">-idis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙(芳香性の)イグサの類.</div>\r\n","<div class=\"hw\">Teucria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">Teucri の国(=<a href=\"entry://Trōja\">Troja</a>).</div>\r\n","<div class=\"hw\">teucria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘植〙=<a href=\"entry://chamaedrys\">chamaedrys</a>.</div>\r\n","<div class=\"hw\">teucrion, -um</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙</div><div class=\"def\"><num>①</num> ニガクサの一種.</div><div class=\"def\"><num>②</num> シダの一種.</div>\r\n","<div class=\"hw\">Teucris</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"def\">Troja の女.</div>\r\n","<div class=\"hw\">Teucrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Teucer の;Teucer が創建した.</div>\r\n","<div class=\"hw\">Teucrus<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Teucer\">Teucer</a>.</div><hr><div class=\"hw\">Teucrus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Teucer の子孫の;Troja の.</div>\r\n","<div class=\"hw\">Teucrī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\"><num>①</num> Teucer の子孫(=<a href=\"entry://Trōja\">Troja</a> 人).</div><div class=\"def\"><num>②</num> ローマ人.</div>\r\n","<div class=\"hw\">Teumēsius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Teumesos の;《詩》Thebae の, Boeotia の.</div>\r\n","<div class=\"hw\">Teumēsos</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テウメーソス《Boeotia の Thebae 付近の丘》.</div>\r\n","<div class=\"hw\">teuthalis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙=<a href=\"entry://polygonus\">polygonus</a>.</div>\r\n","<div class=\"hw\">Teuthrantius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Teuthras(の子孫)の</div><div class=\"ex\"><i>Teuthrantia turba</i> (<author>O<small>V</small></author>)<span class=\"ext\">Thespius の50人の娘たち.</span></div>\r\n","<div class=\"hw\">Teuthrantēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Teuthras の;《詩》Mysia の.</div>\r\n","<div class=\"hw\">teuthrion</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ニガクサ属の植物.</div>\r\n","<div class=\"hw\">Teuthrās</div><div class=\"pos\">-antis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テウトラース《Mysia の王;Thespius の父》.</div>\r\n","<div class=\"hw\">Teutoburgiensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\"><i>～ saltus</i> (<author>T<small>AC</small></author>) 「トイトブルクの森」《紀元9年, ゲルマン人連合軍がここでローマ軍を撃滅した;この古戦場は現在の Teutoburger Wald ではなく, Osnabrück 北方の地》.</div>\r\n","<div class=\"hw\">Teutoburgium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">テウトブルギウム《Pannonia の町;現 Teutoburg》.</div>\r\n","<div class=\"hw\">Teutomatus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">テウトマトゥス《Aquitania の Nitiobriges 族の王》.</div>\r\n","<div class=\"hw\">Teutonicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Teutoni 族の;《詩》ゲルマン人の.</div>\r\n","<div class=\"hw\">Teutonēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Teutonī\">Teutoni</a>.</div>\r\n","<div class=\"hw\">Teutonī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">テウトニー《ゲルマン人の一部族》.</div>\r\n","<div class=\"hw\">textile</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://textilis\">textilis</a>]</div><div class=\"def\">(<i>sc. </i> opus)織物</div><div class=\"ex\"><i>pictura in textili</i> (<author>C<small>IC</small></author>)<span class=\"ext\">綴れ織.</span></div>\r\n","<div class=\"hw\">textilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[texo]</div><div class=\"def\">織られた;編まれた.</div>\r\n","<div class=\"hw\">textor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[texo]</div><div class=\"def\">機織り.</div>\r\n","<div class=\"hw\">textrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[textor]</div><div class=\"def\">機織り《女性》.</div>\r\n","<div class=\"hw\">textrīcula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[textrix]</div><div class=\"def\">機織り娘.</div>\r\n","<div class=\"hw\">textrīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[textor]</div><div class=\"def\"><num>①</num> (<i>sc. </i> officina)機<SUB>はた</SUB>織り場.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 織物;(クモの)巣.</div>\r\n","<div class=\"hw\">textrīnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[textor]</div><div class=\"def\"><num>①</num> 機織り場.</div><div class=\"def\"><num>②</num> 機織りの技術.</div><div class=\"def\"><num>③</num> 造船所.</div>\r\n","<div class=\"hw\">textrīnus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[textor]</div><div class=\"def\">機織りの.</div>\r\n","<div class=\"hw\">textum</div><div class=\"pos\">-ī, <i>n</i>(<i>pp</i>)</div><div class=\"ori\">[texo]</div><div class=\"def\"><num>①</num> 布地;衣装.</div><div class=\"def\"><num>②</num> 骨組, 構造, 組織.</div><div class=\"def\"><num>③</num> (文章の)肌理<SUB>きめ</SUB>, 文体.</div>\r\n","<div class=\"hw\">textus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://texō\">texo</a>.</div><hr><div class=\"hw\">textus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 織物;編物;織り[編み]方.</div><div class=\"def\"><num>②</num> 結合, 構造, 組織.</div>\r\n","<div class=\"hw\">textōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[texo]</div><div class=\"def\"><num>①</num> 織る[編む]ことの.</div><div class=\"def\"><num>②</num> もつれた, 込み入った.</div>\r\n","<div class=\"hw\">textūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[texo]</div><div class=\"def\"><num>①</num> 機織り(の技術).</div><div class=\"def\"><num>②</num> 結合, 構造, 組織.</div>\r\n","<div class=\"hw\">texuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://texō\">texo</a>.</div>\r\n","<div class=\"hw\">texī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tegō\">tego</a>.</div>\r\n","<div class=\"hw\">texō</div><div class=\"pos\">-ere -xuī -xtum, <i>tr</i></div><div class=\"def\"><num>①</num> 織る.</div><div class=\"def\"><num>②</num> 編む, 編み合わせる.</div><div class=\"def\"><num>③</num> 組み合わせて作る;建造する.</div><div class=\"def\"><num>④</num> (文章を)つづる.</div>\r\n","<div class=\"hw\">Teānensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">Teanum Apulum の住民.</div>\r\n","<div class=\"hw\">Teānum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">テアーヌム《 (1) Apulia の町;<i>～ Apulum</i> ともいう;現 San Paolo di Civitate.(2) Campania の町;<i>～ Sidicinum</i> ともいう;現 Teano》.</div>\r\n","<div class=\"hw\">Teānī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Teānensēs\">Teanenses</a>.</div>\r\n","<div class=\"hw\">Teāte</div><div class=\"pos\">-is, <i>n</i></div><div class=\"def\">テアーテ《イタリア中部のアドリア海側にいた Marrucini 族の町;現 Chieti》.</div>\r\n","<div class=\"hw\">Teātēs</div><div class=\"pos\">-us, <i>m pl</i></div><div class=\"def\">テアーテース《Apulia の一部族》.</div>\r\n","<div class=\"hw\">Teātīnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Teate の住民.</div>\r\n","<div class=\"hw\">Teōs, -us</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テオース《Ionia の町;抒情詩人 Anacreon の生地》.</div>\r\n","<div class=\"hw\">Thabēna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">タベーナ《Numidia の海沿いの町》.</div>\r\n","<div class=\"hw\">Thabēnensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">Thabena の住民.</div>\r\n","<div class=\"hw\">Thala</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">タラ《Numidia の町》.</div>\r\n","<div class=\"hw\">thalamencephalon</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘解〙視床脳.</div>\r\n","<div class=\"hw\">thalamus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 部屋;寝室.</div><div class=\"def\"><num>②</num> 新婚[夫婦]の床.</div><div class=\"def\"><num>③</num> 婚姻, 結婚.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘解〙視床.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘植〙花床.</div>\r\n","<div class=\"hw\">thalamēgus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">船室のある遊覧船.</div>\r\n","<div class=\"hw\">thalasseros</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">《碑》眼薬の一種.</div>\r\n","<div class=\"hw\">thalassicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">海の.</div>\r\n","<div class=\"hw\">thalassinus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">海の色の.</div>\r\n","<div class=\"hw\">Thalas(s)ius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Talas(s)ius\">Talassius</a>.</div>\r\n","<div class=\"hw\">thalas(s)iō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">=<a href=\"entry://talas(s)iō\">talassio</a>.</div>\r\n","<div class=\"hw\">thalassomeli</div><div class=\"pos\"><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">海水と蜂蜜を混ぜた飲み物.</div>\r\n","<div class=\"hw\">thalassometra</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">海の測量士(=maris mensor).</div>\r\n","<div class=\"hw\">thallophyta</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>n pl</i></div><div class=\"def\">〘植〙葉状植物.</div>\r\n","<div class=\"hw\">thallus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 若枝, 小枝.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘植〙葉状体.</div>\r\n","<div class=\"hw\">Thalēs</div><div class=\"pos\">-ētis [-is], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">タレース《Ionia の Miletus 生まれの哲学者(前640?‐?546);ギリシア七賢人の一人;万物の根源は水と唱えた》.</div>\r\n","<div class=\"hw\">Thalīa, Thalēa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙タリーア, <SUP>*</SUP>タレイア《 (1) Musae の一人;喜劇をつかさどる.(2) 美の三女神(Gratiae)の一人.(3) 海のニンフたち(Nereides)の一人》.</div>\r\n","<div class=\"hw\">thamnus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙低木の一種.</div>\r\n","<div class=\"hw\">Thamyris<SUP>1</SUP></div><div class=\"pos\">-idis, <i>m</i></div><div class=\"def\">=<a href=\"entry://Thamyrās\">Thamyras</a>.</div><hr><div class=\"hw\">Thamyris<SUP>2</SUP></div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">=<a href=\"entry://Tomyris\">Tomyris</a>.</div>\r\n","<div class=\"hw\">Thamyrās</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙タミュラース《Thracia の詩人;Musae と技を競って盲目に(あるいは口をきけなく)されたという》.</div>\r\n","<div class=\"hw\">Thapsacus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">タプサクス, <SUP>*</SUP>-コス《Syria の Euphrates 川沿いの町》.</div>\r\n","<div class=\"hw\">thapsia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ウイキョウに似たセリ科オオウイキョウ属の植物.</div>\r\n","<div class=\"hw\">Thapsitānī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Thapsus の住民.</div>\r\n","<div class=\"hw\">thapsos</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ハグマノキ《黄色の染料が採れる》.</div>\r\n","<div class=\"hw\">Thapsus, -os</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">タプスス, <SUP>*</SUP>-ソス《 (1) Sicilia 島の町.(2) Africa 沿岸の町;ここで Caesar が Pompeius 派の残党に大勝した(前46)》.</div>\r\n","<div class=\"hw\">Thasius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thasos の.</div>\r\n","<div class=\"hw\">Thasos, -us</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">タソス《Thracia 海岸沖, エーゲ海最北の島》.</div>\r\n","<div class=\"hw\">Thaumaciē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">タウマキエー, <SUP>*</SUP>-アー《Magnesia の町》.</div>\r\n","<div class=\"hw\">Thaumacī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">タウマキー, <SUP>*</SUP>-コイ《Thessalia の町》.</div>\r\n","<div class=\"hw\">Thaumantias</div><div class=\"pos\">-adis, <i>f</i></div><div class=\"def\">=<a href=\"entry://Thaumantis\">Thaumantis</a>.</div>\r\n","<div class=\"hw\">Thaumantis</div><div class=\"pos\">-idis [-idos], <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://Thaumās\">Thaumās</a>]</div><div class=\"def\">〘神話〙Thaumas の娘(=<a href=\"entry://īris\">Iris</a>).</div>\r\n","<div class=\"hw\">Thaumantēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thaumas の</div><div class=\"ex\"><i>Thaumantea virgo</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://īris\">Iris</a>.</span></div>\r\n","<div class=\"hw\">Thaumās</div><div class=\"pos\">-antis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙タウマース《 (1) Iris の父.(2) Centaurus 族の一人》.</div>\r\n","<div class=\"hw\">thelodīves</div><div class=\"pos\">-vitis, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">金持ぶる.</div>\r\n","<div class=\"hw\">thelohumilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">謙遜ぶる.</div>\r\n","<div class=\"hw\">thelosapiens</div><div class=\"pos\">-entis, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">賢者ぶる.</div>\r\n","<div class=\"hw\">thema</div><div class=\"pos\">-atis, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (二手に分かれて争う, 弁論術の稽古用の)事件, 状況, 論題.</div><div class=\"def\"><num>②</num> 〘占星〙(誕生時の)天体の位置, 星相.</div>\r\n","<div class=\"hw\">Themis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙テミス《天空神 Uranus と 大地女神 Gaea の娘で法律・秩序・正義の女神》.</div>\r\n","<div class=\"hw\">Themiscȳra</div><div class=\"pos\">-ae, <i>f</i>, <B>-rium</B> -ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テミスキューラ, -キューリウム《Cappadocia の町;Amazon 族の国の首都》.</div>\r\n","<div class=\"hw\">Themista</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テミスタ《Lampsacus の Epicurus 学派哲学者》.</div>\r\n","<div class=\"hw\">Themistoclēs</div><div class=\"pos\">-is [-ī], <i>m</i></div><div class=\"def\">テミストクレース《Athenae の政治家・将軍(前527?‐?462);Salamis の海戦で Xerxes の率いる Persia 艦隊を撃破(前480)》.</div>\r\n","<div class=\"hw\">Themistoclēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Themistocles の.</div>\r\n","<div class=\"hw\">Themisōn</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テミソーン《Syria の医師;Asclepiades の弟子》.</div>\r\n","<div class=\"hw\">thenar</div><div class=\"pos\">-aris, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘解〙母指球.</div>\r\n","<div class=\"hw\">thensaurus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://thēsaurus\">thesaurus</a>.</div>\r\n","<div class=\"hw\">theocratia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">神の支配.</div>\r\n","<div class=\"hw\">Theocritus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テオクリトゥス, <SUP>*</SUP>-トス《Syracusae 生まれの詩人(前300?‐?260);牧歌の創始者とされる》.</div>\r\n","<div class=\"hw\">Theodectēs</div><div class=\"pos\">-is [-ī], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テオデクテース《Cilicia 出身の弁論家(前375?‐?334);ずば抜けた記憶力で有名》.</div>\r\n","<div class=\"hw\">Theodōrus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テオドーロス《 (1) Byzantium 出身のギリシアのソフィスト(前5世紀後半).(2) Cyrene 出身のソフィストで無神論者;Socrates と同時代.(3) Palaestina の町 Gadara 出身の修辞学者(前1世紀後半);Tiberius 帝の師》.</div>\r\n","<div class=\"hw\">Theognis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テオグニス《Megara 出身の詩人(前6世紀)》.</div>\r\n","<div class=\"hw\">Theogonia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">「神々の誕生」(別名 「神統記」)《Hesiodus 作の叙事詩》.</div>\r\n","<div class=\"hw\">theologia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">神学.</div>\r\n","<div class=\"hw\">theologicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://theologia\">theologia</a>]</div><div class=\"def\">神学の.</div>\r\n","<div class=\"hw\">theologus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 神話について論述する人.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 神性を論ずる人;神学者.</div>\r\n","<div class=\"hw\">Theophanēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テオパネース《Mytilene 出身の歴史家;Pompeius の友人》.</div>\r\n","<div class=\"hw\">Theophrastus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テオプラストゥス, <SUP>*</SUP>-トス, <SUP>∥</SUP>テオフラストス《Lesbos 島の Eressus 出身の哲学者(前372?‐?287);Aristoteles の弟子で後継者》.</div>\r\n","<div class=\"hw\">theopnoē</div><div class=\"pos\">-ēs, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙マンネンロウ(=<a href=\"entry://rosmarīnum\">rosmarinum</a>).</div>\r\n","<div class=\"hw\">Theopompus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">テオポンプス, <SUP>*</SUP>-ポス《Chios 島生まれのギリシア史家・弁論家(前4世紀);Isocrates の弟子》.</div>\r\n","<div class=\"hw\">Theopompēus, -īus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Theopompus の.</div>\r\n","<div class=\"hw\">Theorāctus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テオラークトゥス, <SUP>*</SUP>-レークトス《「神が憑<SUB>つ</SUB>いた[気がふれた]人」 の意;Syracusae の Theomnastus のあだ名》.</div>\r\n","<div class=\"hw\">theostasis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">《碑》神像の台座.</div>\r\n","<div class=\"hw\">theotocos</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">神の母《聖母 Maria の尊称》.</div>\r\n","<div class=\"hw\">therapeutica</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘医〙治療学, 療法.</div>\r\n","<div class=\"hw\">theraphim</div><div class=\"pos\"><i>indecl</i><SUP>◇</SUP><i>pl</i></div><div class=\"ori\">[<i>Heb. </i>]</div><div class=\"def\">(古代ヘブライ人の)家神像.</div>\r\n","<div class=\"hw\">Therapnae</div><div class=\"pos\">-ārum, <i>f pl</i>, <B>-ē</B> -ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テラプナエ, <SUP>*</SUP>-ナイ《 (1) Sparta に近い小さな町;Helena と Dioscoroe の生地.(2) =<a href=\"entry://Sparta\">Sparta</a>》.</div>\r\n","<div class=\"hw\">Therapnaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Therapnae の.</div><div class=\"def\"><num>②</num> Sparta の, Laconia の.</div>\r\n","<div class=\"hw\">therapīa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">治療, 療法.</div>\r\n","<div class=\"hw\">theristrum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> アラブ女性の軽い夏着.</div><div class=\"def\"><num>②</num> 装い.</div>\r\n","<div class=\"hw\">thermae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(<i>sc. </i> aquae)温浴場;公共大浴場.</div>\r\n","<div class=\"hw\">Thermae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テルマエ, <SUP>*</SUP>-マイ《Sicilia 島北岸, Himera の西隣りの町;現 Termini Imerese》.</div>\r\n","<div class=\"hw\">Thermaeus, -maicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Therme の</div><div class=\"ex\"><i>～ sinus</i> (<author>T<small>AC</small></author>)<span class=\"ext\">テルメー湾.</span></div>\r\n","<div class=\"hw\">thermanticus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">体を熱くさせる[ほてらせる].</div>\r\n","<div class=\"hw\">therminus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(油が)ハウチワマメから作られた.</div>\r\n","<div class=\"hw\">Thermitānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thermae の.</div><div class=\"hw2\"><b>Thermitānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Thermae の住民.</div>\r\n","<div class=\"hw\">thermoplēgia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙日射病.</div>\r\n","<div class=\"hw\">Thermopylae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テルモピュラエ, <SUP>*</SUP>-ライ《Thessalia から Locris に通ずる海辺の峡路;Sparta の王 Leonidas の率いる千人余のギリシア兵がペルシアの大軍を迎えて戦い全滅した場所(前480)》.</div>\r\n","<div class=\"hw\">thermopōlium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">温めた酒を飲ませる店.</div>\r\n","<div class=\"hw\">thermopōtō</div><div class=\"pos\">-āre -āvī, <i>tr</i></div><div class=\"ori\">[<i>Gk</i>▷θερμ<img class=\"font\" src=\"img/A152.png\"><img class=\"font\" src=\"img/A153.png\">◁/poto]</div><div class=\"def\">温めた酒を出す.</div>\r\n","<div class=\"hw\">thermoreceptor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘生理〙温度受容器.</div>\r\n","<div class=\"hw\">thermospodium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">熱い灰, 残り火.</div>\r\n","<div class=\"hw\">thermotaxis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘生物〙走熱性, 温度走性.</div>\r\n","<div class=\"hw\">thermulae</div><div class=\"pos\">-ārum, <i>f pl dim</i></div><div class=\"ori\">[thermae]</div><div class=\"def\">(小さい)温浴場.</div>\r\n","<div class=\"hw\">thermārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[thermae]</div><div class=\"def\">《碑》温浴場の管理人.</div>\r\n","<div class=\"hw\">Thermē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テルメー《Macedonia の町;後に建設される Thessalonica のすぐ南に位置した》.</div>\r\n","<div class=\"hw\">Thermōdontiacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Thermōdontēus\">Thermodonteus</a>.</div>\r\n","<div class=\"hw\">Thermōdontēus, -ius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thermodon 川の;《詩》Amazon 族の.</div>\r\n","<div class=\"hw\">Thermōdōn</div><div class=\"pos\">-ontis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テルモードーン《Pontus の川;その付近に Amazon 族が住んでいたという》.</div>\r\n","<div class=\"hw\">Thersītēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テルシーテース《Troja に進攻したギリシア軍の中で最も醜悪で横柄な兵士》.</div>\r\n","<div class=\"hw\">thesis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘修〙(一般的・抽象的)問題, 題目.</div><div class=\"def\"><num>②</num> 〘詩〙(詩脚の)抑音[弱音]部.</div><div class=\"def\"><num>③</num> 《碑》満願成就の際の礼金の寄託.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>(命題の)提示.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP> 読点;句読点.</div>\r\n","<div class=\"hw\">Thesmophoria</div><div class=\"pos\">-iōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">立法者としての Demeter を称<SUB>たた</SUB>えるギリシアの祭.</div>\r\n","<div class=\"hw\">Thespiacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thespiae の.</div>\r\n","<div class=\"hw\">Thespiades<SUP>2</SUP></div><div class=\"pos\">-um, <i>f pl</i></div><div class=\"def\"><num>①</num> Thespius の娘たち.</div><div class=\"def\"><num>②</num> (Thespiae で祭られた)Musa たち.</div>\r\n","<div class=\"hw\">Thespiadēs<SUP>1</SUP></div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">Thespius の子孫《特に Thespius の50人の娘たちと Hercules の間にできた息子たちの一人》.</div>\r\n","<div class=\"hw\">Thespiae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テスピアエ, <SUP>*</SUP>-アイ《Boeotia の町;Helicon 山の東麓》.</div>\r\n","<div class=\"hw\">Thespiensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">Thespiae の住民.</div>\r\n","<div class=\"hw\">Thespis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テスピス《ギリシア悲劇の創始者(前6世紀)》.</div>\r\n","<div class=\"hw\">Thespius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thespiae の.</div><div class=\"hw2\"><b>Thespiī</b></div><div class=\"pos2\">-ōrum, <SUP>◇</SUP><i>m pl</i></div><div class=\"def2\">Thespiae の住民.</div><hr><div class=\"hw\">Thespius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テスピウス, <SUP>*</SUP>-オス《Thespiae の創建者;50人の娘を Hercules と結婚させてそれぞれに息子を得させたという》.</div>\r\n","<div class=\"hw\">Thesprōtia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テスプローティア《Thesproti 族のいた Epirus の一地方》.</div>\r\n","<div class=\"hw\">Thesprōtis</div><div class=\"pos\">-idis, <SUP>◇</SUP><i>adj f</i></div><div class=\"def\">Thesproti 族の.</div>\r\n","<div class=\"hw\">Thesprōtius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thesproti 族(の領土)の.</div>\r\n","<div class=\"hw\">Thesprōtī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テスプローティー, <SUP>*</SUP>-トイ《Epirus の南西部にいた一部族》.</div>\r\n","<div class=\"hw\">Thessalia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テッサリア(ー)《ギリシア北東部の一地方》.</div>\r\n","<div class=\"hw\">Thessalicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thessalia の.</div>\r\n","<div class=\"hw\">Thessalis<SUP>1</SUP></div><div class=\"pos\">-idis [-idos], <i>adj f</i></div><div class=\"def\">Thessalia の.</div><hr><div class=\"hw\">Thessalis<SUP>2</SUP></div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://Thessalis\">Thessalis<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> Thessalia の女.</div><div class=\"def\"><num>②</num> 魔女.</div>\r\n","<div class=\"hw\">Thessalius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Thessalicus\">Thessalicus</a>.</div>\r\n","<div class=\"hw\">Thessalonīca</div><div class=\"pos\">-ae, <B>-ē</B> -ēs, <i>f</i></div><div class=\"def\">テッサロニーカ, <SUP>*</SUP>-ケー《Macedonia の町;テルメー湾(sinus Thermaicus)に臨む;現 Thessaloniki》.</div>\r\n","<div class=\"hw\">Thessalonīcensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">Thessalonica の住民.</div>\r\n","<div class=\"hw\">Thessalus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thessalia の.</div><hr><div class=\"hw\">Thessalus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">Thessalia 人.</div>\r\n","<div class=\"hw\">Thestiadēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">〘伝説〙Thestius の子孫(=息子 Plexippus, Toxeus;孫 Meleager).</div>\r\n","<div class=\"hw\">Thestias</div><div class=\"pos\">-adis, <i>f</i></div><div class=\"def\">〘伝説〙Thestius の娘(=<a href=\"entry://Althaea\">Althaea</a>).</div>\r\n","<div class=\"hw\">Thestius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テスティウス, <SUP>*</SUP>-オス《Aetolia の王;Plexippus, Leda, Althaea らの父》.</div>\r\n","<div class=\"hw\">Thestoridēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">Thestor の息子(=<a href=\"entry://Calchās\">Calchas</a>).</div>\r\n","<div class=\"hw\">Thestōr</div><div class=\"pos\">-oris, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テストール《予言者 Calchas の父》.</div>\r\n","<div class=\"hw\">theticus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">理論的な, 一般論の.</div>\r\n","<div class=\"hw\">Thetidium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テティディウム, <SUP>*</SUP>-オン《Thessalia の町》.</div>\r\n","<div class=\"hw\">Thetidēius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">(Achilles について)Thetis から生まれた.</div>\r\n","<div class=\"hw\">Thetis</div><div class=\"pos\">-idis [-idos], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘神話〙テティス《海のニンフ Nereides の一人;Peleus の妻で Achilles の母》.</div><div class=\"def\"><num>②</num> 《詩》海.</div>\r\n","<div class=\"hw\">theurgia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(魂の浄化のための)魔術, 神的秘術.</div>\r\n","<div class=\"hw\">theurgicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">魔法の, 神的秘術の.</div>\r\n","<div class=\"hw\">theurgus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">魔法[神的秘術]を行なう人.</div>\r\n","<div class=\"hw\">theātricus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">劇場の;演劇の.</div>\r\n","<div class=\"hw\">theātridion</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://theātrum\">theātrum</a>]</div><div class=\"def\">小劇場.</div>\r\n","<div class=\"hw\">theātrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 劇場, 舞台;円形劇場[闘技場].</div><div class=\"def\"><num>②</num> 観衆, 聴衆;会衆.</div><div class=\"def\"><num>③</num> (活動などの)場, 舞台.</div>\r\n","<div class=\"hw\">theātrālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[theatrum]</div><div class=\"def\"><num>①</num> 劇場の;演劇の</div><div class=\"ex\"><i>theatrales operae</i> (<author>T<small>AC</small></author>)<span class=\"ext\">(雇われて)拍手喝采する連中.</span></div><div class=\"def\"><num>②</num> 芝居がかった, 作り事めいた.</div>\r\n","<div class=\"hw\">Theōn</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テオーン《Samos 島出身の画家(前4世紀後半)》.</div>\r\n","<div class=\"hw\">Theōnīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">(毒舌家として知られた)Theon の;人を中傷する.</div>\r\n","<div class=\"hw\">theōria</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">思弁;考究.</div>\r\n","<div class=\"hw\">theōricus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">思弁的な, 観想的な.</div>\r\n","<div class=\"hw\">theōrēma</div><div class=\"pos\">-atis, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 論題, 問題.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘論・数〙定理.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 意見, 見解.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 見ること, 観察.</div>\r\n","<div class=\"hw\">theōrēmatium</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↑<a href=\"entry://theōrēma\">theōrēma</a>]</div><div class=\"def\">問題.</div>\r\n","<div class=\"hw\">theōrētica</div><div class=\"pos\">-ae, <B>-ē</B> -ēs, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">思弁哲学.</div>\r\n","<div class=\"hw\">theōrēticus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">思弁的な.</div>\r\n","<div class=\"hw\">thiasus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Bacchus の信者たちの乱舞;お供の一団.</div><div class=\"def\"><num>②</num> 《碑》(特に Bacchus 祭祀の)神官団.</div>\r\n","<div class=\"hw\">thiasō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[↓<a href=\"entry://thiasus\">thiasus</a>]</div><div class=\"def\">Bacchus の熱狂的信者たちを先導する.</div>\r\n","<div class=\"hw\">thigmotaxis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘生物〙走触性, 接触走性.</div>\r\n","<div class=\"hw\">Thirmida</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ティルミダ《Numidia の町》.</div>\r\n","<div class=\"hw\">Thisbaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thisbe (2) の.</div>\r\n","<div class=\"hw\">Thisbē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティスベー《 (1) 〘伝説〙Babylon の美少女;Pyramus の恋人.(2) Boeotia の町;ハト(鳩)で有名》.</div>\r\n","<div class=\"hw\">thlasiās</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">睾丸をつぶして去勢された男子.</div>\r\n","<div class=\"hw\">thlaspi</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ナズナ, ペンペングサ.</div>\r\n","<div class=\"hw\">thlibiās</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">睾丸を抜いて去勢された男子.</div>\r\n","<div class=\"hw\">Thoantias</div><div class=\"pos\">-adis, <i>f</i></div><div class=\"def\">Thoas (2) の娘(=<a href=\"entry://Hypsipylē\">Hypsipyle</a>).</div>\r\n","<div class=\"hw\">Thoantēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thoas (1) の;《詩》Tauri 族の.</div>\r\n","<div class=\"hw\">tholus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(丸屋根付きの)円形建造物.</div>\r\n","<div class=\"hw\">Thorius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トリウス《ローマ人の氏族名;特に <i>Sp. ～ Balbus</i>, 護民官(前111?)》.</div>\r\n","<div class=\"hw\">Thoās</div><div class=\"pos\">-antis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙トアース《 (1) Tauri 族の王;彼のもとへ女神 Diana が Iphigenia を運んだ.(2) Lemnos 島の王;島中の男が皆殺しにされたとき, 彼だけが娘の Hypsipyle に救われた》.</div>\r\n","<div class=\"hw\">Thraecidica, Thrēc-</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://Thraecidicus\">Thraecidicus, Thrēc-</a>]</div><div class=\"def\">(<i>sc. </i> arma)Thraex の武器.</div>\r\n","<div class=\"hw\">Thraecidicus, Thrēc-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thraex の.</div>\r\n","<div class=\"hw\">Thraeissa, Thraessa, Thrēissa, Thrēssa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">Thracia の女.</div>\r\n","<div class=\"hw\">Thraex<SUP>1, 2</SUP></div><div class=\"def\">⇒<a href=\"entry://Thrax\">Thrax<SUP>1</SUP></a>, <a href=\"entry://Thrax\">Thrax<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">Thrasybūlus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トラシュブールス, <SUP>*</SUP>-ロス《Athenae の政治家(前445?‐?389);祖国を三十人僭主から解放した》.</div>\r\n","<div class=\"hw\">Thrax<SUP>1</SUP></div><div class=\"pos\">-ācis, <B>Thraex<SUP>1</SUP></B> -aecis, <B>Threx<SUP>1</SUP></B> -ēcis, <i>adj</i></div><div class=\"def\">Thracia の.</div><hr><div class=\"hw\">Thrax<SUP>2</SUP></div><div class=\"pos\">-ācis, <B>Thraex<SUP>2</SUP></B> -aecis, <B>Threx<SUP>2</SUP></B> -ēcis, <i>m</i></div><div class=\"def\"><num>①</num> Thracia 人.</div><div class=\"def\"><num>②</num> (Thracia 人のように, 小型の楯と短剣で武装した)剣闘士.</div>\r\n","<div class=\"hw\">Threx<SUP>1, 2</SUP></div><div class=\"def\">⇒<a href=\"entry://Thrax\">Thrax<SUP>1</SUP></a>, <a href=\"entry://Thrax\">Thrax<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">thrissa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘魚〙ニシンダマシ.</div>\r\n","<div class=\"hw\">thrombus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙血栓.</div>\r\n","<div class=\"hw\">thrombōsis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙血栓症.</div>\r\n","<div class=\"hw\">Thronium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トロニウム, <SUP>*</SUP>-オン《Locri Opuntii 人の町》.</div>\r\n","<div class=\"hw\">thronus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 王座, 玉座.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘神学〙(<i>pl</i>)座天使《九天使中の第3位》.</div>\r\n","<div class=\"hw\">Thrāca</div><div class=\"pos\">-ae, <B>Thrācē</B> -ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://Thrācia\">Thracia</a>.</div>\r\n","<div class=\"hw\">Thrācia, Thraecia, Thrēcia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トラーキア《Macedonia の東の広大な地方》.</div>\r\n","<div class=\"hw\">Thrācicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《碑》=<a href=\"entry://Thrācius\">Thracius</a>.</div>\r\n","<div class=\"hw\">Thrācius, Thraecius, Thrēcius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thracia の.</div>\r\n","<div class=\"hw\">Thrācus, Thraecus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Thrācius\">Thracius</a>.</div>\r\n","<div class=\"hw\">Thrēicius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《詩》=<a href=\"entry://Thrācius\">Thracius</a>.</div>\r\n","<div class=\"hw\">thrēnicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">哀歌の, 挽歌の.</div>\r\n","<div class=\"hw\">thrēnus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">哀歌, 挽歌.</div>\r\n","<div class=\"hw\">thrīpes</div><div class=\"pos\">-pum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 木を食う害虫.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> くだらぬ物.</div>\r\n","<div class=\"hw\">thunnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://thynnus\">thynnus</a>.</div>\r\n","<div class=\"hw\">Thuys</div><div class=\"pos\">(<i>dat</i> Thuyni, <i>acc</i> Thuynem, Thuyn), <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トゥユス, <SUP>*</SUP>テュース《Paphlagonia の王侯(前4世紀)》.</div>\r\n","<div class=\"hw\">thya</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙マオウヒバ属の木.</div>\r\n","<div class=\"hw\">Thyamis</div><div class=\"pos\">-idis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テュアミス《Epirus 中部の川》.</div>\r\n","<div class=\"hw\">Thyatīra</div><div class=\"pos\">-ae, <i>f</i>, <B>-a</B> -ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テュアティーラ, <SUP>*</SUP>-テイラ《Lydia の町》.</div>\r\n","<div class=\"hw\">Thybris</div><div class=\"pos\">-idos, <i>adj f</i></div><div class=\"def\">《詩》=<a href=\"entry://Tiberīnis\">Tiberinis</a>.</div>\r\n","<div class=\"hw\">Thyestiadēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">Thyestes の子孫(=<a href=\"entry://Aegisthus\">Aegisthus</a>).</div>\r\n","<div class=\"hw\">Thyestēs</div><div class=\"pos\">-ae [-is], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テュエステース《Pelops の息子;兄弟の Atreus に自分の息子の肉を供された;Aegisthus の父》.</div>\r\n","<div class=\"hw\">Thyestēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thyestes の.</div>\r\n","<div class=\"hw\">thyinus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">thya の.</div>\r\n","<div class=\"hw\">thyius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">thya で作られた.</div>\r\n","<div class=\"hw\">thymbra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙セリ科の植物.</div>\r\n","<div class=\"hw\">Thymbra</div><div class=\"pos\">-ae, <B>-ē</B> -ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テュンブラ, <SUP>*</SUP>-ブレー《Troas の町;Apollo の神殿があった》.</div>\r\n","<div class=\"hw\">thymbraeum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ハッカの一種(=<a href=\"entry://sisymbrium\">sisymbrium</a>)《シソ科》.</div>\r\n","<div class=\"hw\">thymbraeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">《碑》シソ科の香料植物の.</div>\r\n","<div class=\"hw\">Thymbraeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">(特に Apollo の添え名として)Thymbra の.</div>\r\n","<div class=\"hw\">thymelaea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ジンチョウゲ属の低木.</div>\r\n","<div class=\"hw\">thymelica</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://thymelicus\">thymelicus<SUP>1</SUP></a>]</div><div class=\"def\">女優.</div>\r\n","<div class=\"hw\">thymelicus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">コロス(合唱歌舞団)の.</div><hr><div class=\"hw\">thymelicus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> コロス(合唱歌舞団)の一員.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 俳優, 役者.</div>\r\n","<div class=\"hw\">thymelē</div><div class=\"pos\">-ēs, <B>-a</B> -ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">劇場, 芝居《原義は Athenae の劇場の orchestra 中央にあった祭壇状に高くなった場所》.</div>\r\n","<div class=\"hw\">thyminus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[thymum]</div><div class=\"def\">〘植〙タチジャコウソウの.</div>\r\n","<div class=\"hw\">thymium, -on</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">いぼ状の潰瘍<SUB>かいよう</SUB>.</div>\r\n","<div class=\"hw\">thymolum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘化〙チモール《タチジャコウソウ油の主成分》.</div>\r\n","<div class=\"hw\">thymum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙(シソ科)タチジャコウソウ.</div>\r\n","<div class=\"hw\">thymus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> イボの一種.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙胸腺.</div>\r\n","<div class=\"hw\">thynnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙マグロ(鮪).</div>\r\n","<div class=\"hw\">thynnārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://thynnus\">thynnus</a>]</div><div class=\"def\">マグロ(鮪)の.</div>\r\n","<div class=\"hw\">thyon</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://thya\">thya</a>.</div>\r\n","<div class=\"hw\">thyraeus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">門番《Apollo の添え名の一つ》.</div>\r\n","<div class=\"hw\">Thyrea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テュレア《Argolis と Laconia の境をなす一地区》.</div>\r\n","<div class=\"hw\">thyreoglossus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙甲状舌の.</div>\r\n","<div class=\"hw\">thyreoīdea</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘解〙甲状腺.</div>\r\n","<div class=\"hw\">thyreoīditis</div><div class=\"pos\">-idis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙甲状腺炎.</div>\r\n","<div class=\"hw\">Thyreātis</div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">《詩》Thyrea の.</div>\r\n","<div class=\"hw\">Thyrreum, -ium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テュッレウム, <SUP>*</SUP>-レイオン《Acarnania 北部の町》.</div>\r\n","<div class=\"hw\">Thyrriensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">Thyrreum の住民.</div>\r\n","<div class=\"hw\">thyrsiculus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m dim</i></div><div class=\"ori\">[thyrsus]</div><div class=\"def\">(小さな)茎, 軸.</div>\r\n","<div class=\"hw\">thyrsicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">飲み騒ぐ.</div>\r\n","<div class=\"hw\">thyrsiger</div><div class=\"pos\">-gera -gerum, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://thyrsus\">thyrsus</a>/gero]</div><div class=\"def\">Bacchus の杖を携えている.</div>\r\n","<div class=\"hw\">thyrsus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 茎, 軸.</div><div class=\"def\"><num>②</num> Bacchus の杖《キヅタやブドウのつるで巻いた杖に松かさをのせたもの》.</div>\r\n","<div class=\"hw\">thyrōma</div><div class=\"pos\">-atis, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">扉, 入口.</div>\r\n","<div class=\"hw\">Thyēnē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙テュエーネー《Hyades の一人》.</div>\r\n","<div class=\"hw\">Thyōneus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">Thyone (1) の息子(=<a href=\"entry://Bacchus\">Bacchus</a>).</div>\r\n","<div class=\"hw\">Thyōnē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙テュオーネー《 (1)(一説で)Bacchus の母.(2) Hyades の一人》.</div>\r\n","<div class=\"hw\">Thȳias ▶(詩では2音節)◀, Thȳas</div><div class=\"pos\">-adis [-ados] <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(酒神 Bacchus の祭りに参加して)乱飲乱舞している女.</div>\r\n","<div class=\"hw\">thȳmiāma</div><div class=\"pos\">-atis, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">薫香, 香<SUB>こう</SUB>.</div>\r\n","<div class=\"hw\">thȳmiāmatizō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[thymiama]</div><div class=\"def\">香をたく.</div>\r\n","<div class=\"hw\">thȳmiāmatērium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↑<a href=\"entry://thȳmiāma\">thȳmiāma</a>]</div><div class=\"def\">香炉.</div>\r\n","<div class=\"hw\">thȳmiāmātus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[thymiama]</div><div class=\"def\">香をしみ込ませた.</div>\r\n","<div class=\"hw\">thȳmiātērium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://thȳmiāmatērium\">thymiamaterium</a>.</div>\r\n","<div class=\"hw\">Thȳnia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">Thyni 族の国《Thracia の黒海沿岸地方》;《詩》=<a href=\"entry://Bīthȳnia\">Bithynia</a>.</div>\r\n","<div class=\"hw\">Thȳniacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thynia の.</div>\r\n","<div class=\"hw\">Thȳnias</div><div class=\"pos\">-adis, <i>adj f</i></div><div class=\"def\">《詩》Bithynia の.</div>\r\n","<div class=\"hw\">Thȳnicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《詩》Bithynia の.</div>\r\n","<div class=\"hw\">Thȳnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Thȳnicus\">Thynicus</a>.</div>\r\n","<div class=\"hw\">Thȳnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テューニー, <SUP>*</SUP>-ノイ《Thracia の黒海沿岸地方にいた一部族;Bithynia へ移住した》.</div>\r\n","<div class=\"hw\">Thāis</div><div class=\"pos\">-idis [-idos], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ターイス《Athenae の遊女(前4世紀);Alexander 大王に愛され, のちにエジプトの Ptolemaeus 1世の愛妾となった》.</div>\r\n","<div class=\"hw\">Thēbae</div><div class=\"pos\">-ārum, <i>f pl</i>, <B>Thēbē<SUP>1</SUP></B> -ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テーバエ, <SUP>*</SUP>-バイ《 (1) Boeotia の主都;Cadmus が創建したという.(2) 上<SUB>かみ</SUB>エジプトの首都;現 Luxor.(3) Mysia の町;Eetion 王の支配地》.</div>\r\n","<div class=\"hw\">Thēbais<SUP>1</SUP></div><div class=\"pos\">-idis [-dos], <i>adj f</i></div><div class=\"def\">Thebae (1)  (3) の.</div><hr><div class=\"hw\">Thēbais<SUP>2</SUP></div><div class=\"pos\">-idis [-idos], <i>f</i></div><div class=\"def\"><num>①</num> Thebae (1) の女.</div><div class=\"def\"><num>②</num> 「テーバイス」 「テーバイ物語」《Oedipus 王の二人の遺子の王位争いに取材した Statius 作の叙事詩》.</div><div class=\"def\"><num>③</num> Thebae (2) 周辺の地域.</div>\r\n","<div class=\"hw\">Thēbāna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[Thebanus]</div><div class=\"def\">〘神話〙Thebae (3) の女(=<a href=\"entry://ēetiōn\">Eetion</a> の娘 <a href=\"entry://Andromacha\">Andromacha</a>).</div>\r\n","<div class=\"hw\">Thēbānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thebae (1)  (2)  (3) の.</div>\r\n","<div class=\"hw\">Thēbānī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Thebae (1) の住民.</div>\r\n","<div class=\"hw\">Thēbē<SUP>1</SUP></div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"def\">=<a href=\"entry://Thēbae\">Thebae</a>.</div><hr><div class=\"hw\">Thēbē<SUP>2</SUP></div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"def\">テーベー《 (1) Pherae の僭主 Alexander の妻.(2) Asopus 河神に愛されたニンフ》.</div>\r\n","<div class=\"hw\">thēca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 箱, 容器, ケース.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙膜</div><div class=\"ex\"><i>～ folliculi</i><span class=\"ext\">卵胞膜.</span></div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘動〙甲.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘植〙半葯;(苔類の)子嚢<SUB>しのう</SUB>.</div>\r\n","<div class=\"hw\">thēcātus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://thēca\">thēca</a>]</div><div class=\"def\">箱[袋]に入った.</div>\r\n","<div class=\"hw\">thēlycardios</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">心臓の色をした宝石.</div>\r\n","<div class=\"hw\">thēlygonon</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙トウダイグサ科ヤマアイ属の多年草《妊娠を促す効能があるとされた》.</div>\r\n","<div class=\"hw\">thēlyphonon</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙トリカブト(=<a href=\"entry://aconītum\">aconitum</a>).</div>\r\n","<div class=\"hw\">thēlypteris</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙シダの一種.</div>\r\n","<div class=\"hw\">Thēra</div><div class=\"pos\">-ae, <B>-ē</B> -ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テーラ(ー)《エーゲ海上, Creta 島北方の島;現 Thira または Santorini》.</div>\r\n","<div class=\"hw\">Thēraeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thera 島の.</div><div class=\"hw2\"><b>Thēraeī</b></div><div class=\"pos2\">-ōn, <i>m pl</i></div><div class=\"def2\">Thera 島の住民.</div>\r\n","<div class=\"hw\">thēriaca</div><div class=\"pos\">-ae, <B>-ē</B> -ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(毒)ヘビによる咬傷<SUB>こうしょう</SUB>の解毒剤.</div>\r\n","<div class=\"hw\">Thēriclēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テーリクレース《Corinthus の陶工(前5世紀)》.</div>\r\n","<div class=\"hw\">Thēriclēus, -īus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thericles の.</div>\r\n","<div class=\"hw\">thēriōma</div><div class=\"pos\">-atis, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙悪性潰瘍<SUB>かいよう</SUB>.</div>\r\n","<div class=\"hw\">Thērodamantēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">(人肉をライオンの餌<SUB>えさ</SUB>にやっていたという Scythia の王)Therodamas の.</div>\r\n","<div class=\"hw\">Thēromedōn</div><div class=\"pos\">-ontis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テーロメドーン《残酷な王の名;Therodamas と同一人物か》.</div>\r\n","<div class=\"hw\">thērotrophīum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">野獣飼育場.</div>\r\n","<div class=\"hw\">Thērāmenēs</div><div class=\"pos\">-is [-ī], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テーラーメネース《Athenae の三十人僭主の一人;急進派の Critias に処刑された(前403)》.</div>\r\n","<div class=\"hw\">thēsaurensis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>m</i></div><div class=\"def\">=<a href=\"entry://thēsaurārius\">thesaurarius<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">thēsaurizātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[thesaurizo]</div><div class=\"def\">蓄財, 財宝蓄積.</div>\r\n","<div class=\"hw\">thēsaurizātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://thēsaurizō\">thēsaurizō</a>]</div><div class=\"def\">財をたくわえる人, 蓄財家.</div>\r\n","<div class=\"hw\">thēsaurizō</div><div class=\"pos\">-āre, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://thēsaurus\">thēsaurus</a>]</div><div class=\"def\">財宝を集める, 蓄財する.</div>\r\n","<div class=\"hw\">thēsaurus</div><div class=\"pos\">-ī, <i>m</i>, <B>-um</B> -ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 宝物, 財宝;大切な[いとしい]人.</div><div class=\"def\"><num>②</num> (情報・知識などの)宝庫, 豊かなたくわえ.</div><div class=\"def\"><num>③</num> 倉庫, 貯蔵所;宝物室, 宝蔵</div><div class=\"ex\"><i>～ rerum omnium memoria</i> (<author>C<small>IC</small></author>)<span class=\"ext\">万物の宝蔵である記憶.</span></div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘法〙埋蔵物《所有者不明の発掘物》.</div>\r\n","<div class=\"hw\">thēsaurārium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://thēsaurārius\">thēsaurārius<SUP>1</SUP></a>]</div><div class=\"def\">宝物.</div>\r\n","<div class=\"hw\">thēsaurārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[thesaurus]</div><div class=\"def\">宝物の</div><div class=\"ex\"><i>fur ～</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">宝物泥棒.</span></div><hr><div class=\"hw\">thēsaurārius<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">宝物管理人.</div>\r\n","<div class=\"hw\">Thēseus<SUP>1</SUP></div><div class=\"pos\">-eī [-eos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テーセウス《Athenae の王;Aegeus と Aethra の息子で Phaedra の夫;若くして Minotaurus を退治した》.</div>\r\n","<div class=\"hw\">Thēsēius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Theseus の</div><div class=\"ex\"><i>～ heros</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Hippolytus\">Hippolytus</a>.</span></div>\r\n","<div class=\"hw\">Thēsēus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Theseus の.</div><div class=\"def\"><num>②</num> 《詩》(Theseus の王国である)Attica の.</div>\r\n","<div class=\"hw\">Thēsīdēs</div><div class=\"pos\">-ae, <i>m</i>, <B>Thēsīdae</B> -ārum, <i>m pl</i></div><div class=\"def\"><num>①</num> Theseus の子孫(=息子 Hippolytus).</div><div class=\"def\"><num>②</num> (<i>pl</i>)Athenae 人たち.</div>\r\n","<div class=\"hw\">thēta</div><div class=\"pos\"><i>indecl n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ギリシア語アルファベットの第8字(▷Θ, θ◁).</div>\r\n","<div class=\"hw\">Thīa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙ティーア, <SUP>*</SUP>テイア《Hyperion の妻で Sol の母》.</div>\r\n","<div class=\"hw\">thīus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">伯父, 叔父.</div>\r\n","<div class=\"hw\">thōmix</div><div class=\"pos\">-icis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">縄, ロープ.</div>\r\n","<div class=\"hw\">thōrax</div><div class=\"pos\">-ācis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘解・動〙胸, 胸廓.</div><div class=\"def\"><num>②</num> 胸甲, 胸当て.</div><div class=\"def\"><num>③</num> 胴着.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 胸像.</div>\r\n","<div class=\"hw\">thōrāca</div><div class=\"pos\">-ae, <B>-ē</B> -ēs, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[thorax]</div><div class=\"def\">胸像.</div>\r\n","<div class=\"hw\">thōrācium</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[thorax]</div><div class=\"def\">(小さな)胸甲, 胴着.</div>\r\n","<div class=\"hw\">thōrācoacrōmiālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙胸肩峰の.</div>\r\n","<div class=\"hw\">thōrācodorsālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙胸背の.</div>\r\n","<div class=\"hw\">thōrācālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[thorax]</div><div class=\"def\">〘解・動〙胸の, 胸廓の.</div>\r\n","<div class=\"hw\">thōrācātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[thorax]</div><div class=\"def\">胸甲を着けた.</div>\r\n","<div class=\"hw\">thōs</div><div class=\"pos\">-ōos [-ōis], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙ジャッカル《オオカミ(狼)の一種》.</div>\r\n","<div class=\"hw\">Thōth</div><div class=\"pos\"><i>indecl m</i></div><div class=\"def\">トート《エジプトの神;ローマ神話の Mercurius と同一視された》.</div>\r\n","<div class=\"hw\">Thūcȳdidēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トゥーキューディデース, <SUP>∥</SUP>ツキディデス《ギリシアの史家(前460?‐?400);ペロポネソス戦争(bellum Peloponnesiacum)史を著わした》.</div>\r\n","<div class=\"hw\">Thūcȳdidīus, -ēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thucydides の.</div><div class=\"hw2\"><b>Thūcȳdidīī</b>, <b>-ēī</b></div><div class=\"pos2\"> -ōrum, <i>m pl</i></div><div class=\"def2\">Thucydides の模倣者たち.</div>\r\n","<div class=\"hw\">Thūlē, Thȳlē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トゥーレー《極北の島;現在の Iceland とも Shetland 諸島ともいわれる》.</div>\r\n","<div class=\"hw\">thūr-</div><div class=\"def\">⇒tur-.</div>\r\n","<div class=\"hw\">Thūriī</div><div class=\"pos\">-ōrum, <i>m pl</i>, <B>Thūrium</B> -ī, <i>n</i>, <B>Thūriae</B> -ārum, <i>f pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トゥーリイー《Magna Graecia のギリシア人の植民市;破壊された Sybaris の跡地に建設された(前443)》.</div>\r\n","<div class=\"hw\">Thūrīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Thurii の.</div><div class=\"hw2\"><b>Thūrīnī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Thurii の住民.</div>\r\n","<div class=\"hw\">thūs</div><div class=\"pos\">thūris, <i>n</i></div><div class=\"def\">=<a href=\"entry://tūs\">tus</a>.</div>\r\n","<div class=\"hw\">Ti.</div><div class=\"def\">《略》=<a href=\"entry://Tiberius\">Tiberius</a>.</div>\r\n","<div class=\"hw\">Tibarānī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ティバラーニー《Cilicia にいた一部族》.</div>\r\n","<div class=\"hw\">Tiberiolus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"def\">(いとしい)Tiberius 帝.</div>\r\n","<div class=\"hw\">Tiberis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">ティベリス《 (1) イタリア中部の川;現 Tevere.(2)  (1) の河神》.</div>\r\n","<div class=\"hw\">Tiberius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ティベリウス《ローマの個人名(略形 Ti.);特に <i>～ Claudius Nero Caesar</i>, 第2代皇帝(前42‐後37;在位後14‐37)》.</div>\r\n","<div class=\"hw\">Tiberiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tiberius 帝の.</div>\r\n","<div class=\"hw\">Tiberēius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《詩》=<a href=\"entry://Tiberēus\">Tibereus</a>.</div>\r\n","<div class=\"hw\">Tiberēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tiberius 帝の.</div>\r\n","<div class=\"hw\">Tiberīnis</div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">《詩》=<a href=\"entry://Tiberīnus\">Tiberinus<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">Tiberīnus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tiberis 川の.</div><hr><div class=\"hw\">Tiberīnus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[Tiberis]</div><div class=\"def\">ティベリーヌス《 (1) 〘伝説〙Alba Longa の王;彼がおぼれて死んだ Albula 川がのちに Tiberis の名を得たという.(2) =<a href=\"entry://Tiberis\">Tiberis</a>.(3) <SUP>◇</SUP>ローマ皇帝 M. Aurelius Antoninus Heliogabalus(在位218‐22)の死後のあだ名;その死体が Tiberis 川に投げ込まれたことから》.</div>\r\n","<div class=\"hw\">tib<img class=\"font\" src=\"img/A130.png\"></div><div class=\"pos\"><i>pron pers</i>(<i>dat</i>)</div><div class=\"def\">⇒<a href=\"entry://tū\">tu</a>.</div>\r\n","<div class=\"hw\">Tibullus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ティブッルス《<i>Albius ～</i>, ローマの elegia 詩人で Horatius や Ovidius の友人(前48?‐19)》.</div>\r\n","<div class=\"hw\">tibulus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"def\">マツ(松)の一種.</div>\r\n","<div class=\"hw\">tieldō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">Hispania 産の馬.</div>\r\n","<div class=\"hw\">Tigellius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ティゲッリウス《 (1) <i>～ Sardus</i>, Sardinia 島出身;Caesar, Octavianus の取巻きの一人;歌が上手だった.(2) ～ <i>Hermogenes</i>, Horatius に諷刺された歌手で三文詩人》.</div>\r\n","<div class=\"hw\">Tigellīnus, Tigil-</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ティゲッリーヌス《Nero の寵臣(69年没)》.</div>\r\n","<div class=\"hw\">tigillum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[tignum]</div><div class=\"def\">(小さな)梁<SUB>はり</SUB>.</div>\r\n","<div class=\"hw\">tignulum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://tignum\">tignum</a>]</div><div class=\"def\">(小さな)梁<SUB>はり</SUB>.</div>\r\n","<div class=\"hw\">tignum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 建築材料;材木.</div><div class=\"def\"><num>②</num> 梁<SUB>はり</SUB>, 桁<SUB>けた</SUB>.</div>\r\n","<div class=\"hw\">tignārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tignum]</div><div class=\"def\">梁<SUB>はり</SUB>の</div><div class=\"ex\"><i>faber ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">大工.</span></div>\r\n","<div class=\"hw\">tigrifer</div><div class=\"pos\">-fera -ferum, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tigris/fero]</div><div class=\"def\">虎を生む.</div>\r\n","<div class=\"hw\">tigris</div><div class=\"pos\">-idis [-is], <i>m</i>(<i>f</i>)</div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘動〙トラ(虎).</div><div class=\"def\"><num>②</num> 虎の皮.</div>\r\n","<div class=\"hw\">Tigris</div><div class=\"pos\">-is [-idis], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティグリス《Euphrates 川と合流してペルシア湾に注ぐ大河》.</div>\r\n","<div class=\"hw\">Tigrānocerta</div><div class=\"pos\">-ae, <i>f</i>, <B>-a</B> -ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティグラーノケルタ《Tigranes II によって建設された Armenia の首都》.</div>\r\n","<div class=\"hw\">Tigrānēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティグラーネース《Armenia の数人の王の名;特に (1) ～ <i>II</i>, Mithridates VI の娘婿で同盟者;「王中の王」 と称された(?前56没).(2)  (1) の孫(在位前20‐?6)》.</div>\r\n","<div class=\"hw\">tigrīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://tigris\">tigris</a>]</div><div class=\"def\">虎のような模様のある.</div>\r\n","<div class=\"hw\">Tigurīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><i>pagus ～</i> ティグリーヌス郷<SUB>ごう</SUB>《Helvetia の一地区》.</div>\r\n","<div class=\"hw\">Tigurīnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">pagus Tigurinus の住民.</div>\r\n","<div class=\"hw\">tilia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘植〙</div><div class=\"def\"><num>①</num> シナノキ;シナノキ材.</div><div class=\"def\"><num>②</num> シナノキの内皮.</div>\r\n","<div class=\"hw\">tiliāceus, -ius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://tilia\">tilia</a>]</div><div class=\"def\">シナノキの.</div>\r\n","<div class=\"hw\">tiliāgineus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tilia]</div><div class=\"def\">シナノキ材で作られた.</div>\r\n","<div class=\"hw\">tiliāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://tiliāceus\">tiliaceus</a>.</div>\r\n","<div class=\"hw\">timefactus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[timeo/facio]</div><div class=\"def\">おびえた, 恐れをなした.</div>\r\n","<div class=\"hw\">timendus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>gerundiv</i>)</div><div class=\"ori\">[timeo]</div><div class=\"def\">恐るべき, 恐ろしい.</div>\r\n","<div class=\"hw\">timens</div><div class=\"pos\">-ntis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[↓<a href=\"entry://timeō\">timeō</a>]</div><div class=\"def\">(...を)恐れている 〈+<i>gen</i>〉.</div>\r\n","<div class=\"hw\">timescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://timeō\">timeō</a>]</div><div class=\"def\">恐れる, おびえる.</div>\r\n","<div class=\"hw\">timeō</div><div class=\"pos\">-ēre -muī, <i>intr</i>, <i>tr</i></div><div class=\"def\">恐れる, 心配する, 気づかう 〈+<i>acc</i>;ne, ne non, ut;+<i>inf</i>;a re;+間接疑問〉</div><div class=\"ex\"><i>neque timent ne aversi ab hoste circumveniantur</i> (<author>C<small>AES</small></author>)<span class=\"ext\">自分たちの後尾が敵に包囲されるのではないかと恐れることもない</span></div><div class=\"ex\"><i>timeo ut sustineas</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私はどうしてあなたが耐えられようかと気がかりだ(=耐えられないのではないかと心配だ).</span></div>\r\n","<div class=\"hw\">timiditās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[timidus]</div><div class=\"def\">臆病, びくびくすること.</div>\r\n","<div class=\"hw\">timidulē</div><div class=\"pos\"><i>adv dim</i></div><div class=\"ori\">[↓<a href=\"entry://timidus\">timidus</a>]</div><div class=\"def\">びくびくして.</div>\r\n","<div class=\"hw\">timidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[timeo]</div><div class=\"def\">臆病な;びくびくしている, 恐れている 〈ad alqd;in re;+<i>gen</i>;+<i>inf</i>〉.</div>\r\n","<div class=\"hw\">timidē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[timidus]</div><div class=\"def\"><num>①</num> 恐れて, びくびくして.</div><div class=\"def\"><num>②</num> 躊躇して, 慎重に.</div>\r\n","<div class=\"hw\">timor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[timeo]</div><div class=\"def\"><num>①</num> 恐怖, 心配, 懸念 〈+<i>gen</i>;+<i>inf</i>;ne;+<i>acc c.inf</i>〉</div><div class=\"ex\">(+<i>obj gen</i>)<i>mortis timores</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">死への恐怖</span></div><div class=\"ex\">(+<i>subj gen</i>)<i>～ omnium</i> (<author>C<small>IC</small></author>)<span class=\"ext\">万人の抱く恐怖.</span></div><div class=\"def\"><num>②</num> 恐怖の対象, 不安の種.</div>\r\n","<div class=\"hw\">timorātus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://timor\">timor</a>]</div><div class=\"def\">神を恐れる, 敬神の, 敬虔な.</div>\r\n","<div class=\"hw\">Timāvus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ティマーウゥス《Histria の川;現 Timavo》.</div>\r\n","<div class=\"hw\">Timōlus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Tmōlus\">Tmolus</a>.</div>\r\n","<div class=\"hw\">timōs</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"def\">《古形》=<a href=\"entry://timor\">timor</a>.</div>\r\n","<div class=\"hw\">tinca</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘魚〙コイ(鯉)の一種.</div>\r\n","<div class=\"hw\">tincta</div><div class=\"pos\">-ōrum, <i>n pl</i>(<i>pp</i>)</div><div class=\"ori\">[tingo]</div><div class=\"def\">染められた物.</div>\r\n","<div class=\"hw\">tinctilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tingo]</div><div class=\"def\">染められた, 浸された.</div>\r\n","<div class=\"hw\">tinctiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tingo]</div><div class=\"def\"><num>①</num> つける[浸す]こと.</div><div class=\"def\"><num>②</num> 洗礼.</div>\r\n","<div class=\"hw\">tinctor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[tingo]</div><div class=\"def\">《碑》染め物師.</div>\r\n","<div class=\"hw\">tinctus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://tingō\">tingo</a>.</div><hr><div class=\"hw\">tinctus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">浸すこと.</div>\r\n","<div class=\"hw\">tinctōrium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tinctōrius\">tinctōrius</a>]</div><div class=\"def\"><num>①</num> 染色作業場, 染め物屋.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 洗礼盤.</div>\r\n","<div class=\"hw\">tinctōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tingo]</div><div class=\"def\">染色にかかわる;血に飢えた.</div>\r\n","<div class=\"hw\">tinctūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tingo]</div><div class=\"def\"><num>①</num> 染めること, 着色, 染色.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘薬〙チンキ(剤)</div><div class=\"ex\"><i>～ amara</i><span class=\"ext\">苦味チンキ</span></div><div class=\"ex\"><i>～ opii</i><span class=\"ext\">アヘン(阿片)チンキ</span></div><div class=\"ex\"><i>～ valerianae</i><span class=\"ext\">カノコソウチンキ.</span></div>\r\n","<div class=\"hw\">tinea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 幼虫, ウジ;(衣類・本などを食いあらす)害虫.</div><div class=\"def\"><num>②</num> ガ(蛾).</div><div class=\"def\"><num>③</num> 回虫.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> シラミ.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP> 疥癬<SUB>かいせん</SUB>.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP> 錆<SUB>さび</SUB>.</div>\r\n","<div class=\"hw\">Tingitānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><i>provincia Tingitana</i> (<author>P<small>LIN</small></author>) 北アフリカの属州の一つ《Claudius 帝が Mauritania を東部の Caesariensis と西部の Tingitana の2属州に分割したときの後者;ほぼ現在の Morocco に当たる》.</div>\r\n","<div class=\"hw\">tingō, tinguō</div><div class=\"pos\">-ere tinxī tinctum, <i>tr</i></div><div class=\"def\"><num>①</num> 湿らす, ぬらす, (ある物に)浸す 〈alqd re〉.</div><div class=\"def\"><num>②</num> 染める, 染色[着色]する.</div><div class=\"def\"><num>③</num> 血でよごす, 血ぬらす 〈alqd re〉.</div><div class=\"def\"><num>④</num> 影響を与える, 染み込ませる</div><div class=\"ex\"><i>orator tinctus litteris</i> (<author>C<small>IC</small></author>)<span class=\"ext\">文学の素養のある弁論家.</span></div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP> 洗礼を授ける.</div>\r\n","<div class=\"hw\">tinia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://tinea\">tinea</a>.</div>\r\n","<div class=\"hw\">tinnipō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"def\">(フクロウが)ポーポーと鳴く.</div>\r\n","<div class=\"hw\">tinniō, tīniō</div><div class=\"pos\">-īre -īvī -ītum, <i>intr</i></div><div class=\"def\"><num>①</num> (鈴・鐘などが)カンカン[チリンチリン]と鳴る;(耳が)鳴る.</div><div class=\"def\"><num>②</num> お金(硬貨)をチャリンといわせる, お金を数える[支払う].</div><div class=\"def\"><num>③</num> 甲高い声[金切り声]をあげる.</div>\r\n","<div class=\"hw\">tinnulus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tinnio]</div><div class=\"def\">(シンバル・弦楽器・人の声などが)鳴り響く, 甲高い.</div>\r\n","<div class=\"hw\">tinnunculus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘鳥〙チョウゲンボウ《ハヤブサの一種》.</div>\r\n","<div class=\"hw\">tinnīmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tinniō\">tinniō, tīniō</a>]</div><div class=\"def\">耳鳴り.</div>\r\n","<div class=\"hw\">tinnītus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[tinnio]</div><div class=\"def\"><num>①</num> (剣・兜・青銅製のシンバルなどが立てる)甲高い音.</div><div class=\"def\"><num>②</num> 耳鳴り.</div><div class=\"def\"><num>③</num> (雄弁家の)響きのよい語り口.</div>\r\n","<div class=\"hw\">tintinnum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i>, <B>-us</B> -ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">小さな鈴.</div>\r\n","<div class=\"hw\">tintin(n)ābulum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tintin(n)ō\">tintin(n)ō</a>]</div><div class=\"def\">(小さな)鐘, 鈴, ベル.</div>\r\n","<div class=\"hw\">tintin(n)ō</div><div class=\"pos\">-āre, <B>tintin(n)iō</B> -īre, <i>intr</i></div><div class=\"def\">=<a href=\"entry://tinniō\">tinnio</a>.</div>\r\n","<div class=\"hw\">tinxī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tingō\">tingo</a>.</div>\r\n","<div class=\"hw\">tiphyon</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙スイセン(水仙)の一種.</div>\r\n","<div class=\"hw\">tiphē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙一粒系コムギの一種.</div>\r\n","<div class=\"hw\">tippūla, tīpulla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘昆〙ミズムシ科の昆虫.</div>\r\n","<div class=\"hw\">tis</div><div class=\"pos\"><i>gen</i></div><div class=\"def\">《古形》=<a href=\"entry://tū\">tui</a>(⇒ <a href=\"entry://tū\">tu</a>).</div>\r\n","<div class=\"hw\">tisana, ▶etc◀</div><div class=\"def\">⇒<a href=\"entry://ptisana\">ptisana</a>, etc.</div>\r\n","<div class=\"hw\">Tissaphernēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティッサペルネース《ペルシア王 Dareus II と Artaxerxes II 時代の Sardes の太守;狡猾な策略家》.</div>\r\n","<div class=\"hw\">Tissensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">Tisse の住民.</div>\r\n","<div class=\"hw\">Tissē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティッセー《Aetna 山麓の小さな町》.</div>\r\n","<div class=\"hw\">tithymal(l)is</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙トウダイグサの一種.</div>\r\n","<div class=\"hw\">tithymal(l)us</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トウダイグサ属の植物.</div>\r\n","<div class=\"hw\">Titiensēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Titiēs\">Tities</a>.</div>\r\n","<div class=\"hw\">Titin(n)ius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ティティ(ン)ニウス《ローマの喜劇詩人;Terentius と同時代》.</div>\r\n","<div class=\"hw\">Titius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ティティウス《ローマ人の氏族名;特に <i>Sex. ～</i>, 護民官(前99年)》.</div>\r\n","<div class=\"hw\">Titiālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">《碑》Titus 帝の祭祀に関する.</div>\r\n","<div class=\"hw\">Titiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Titius の.</div>\r\n","<div class=\"hw\">Titiēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">ティティエース《ローマの血縁的3部族(tribus)の一つ》.</div>\r\n","<div class=\"hw\">titiō<SUP>1</SUP></div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">燃えている木, たいまつ.</div><hr><div class=\"hw\">titiō<SUP>2</SUP></div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"def\">(スズメが)チュンチュンさえずる.</div>\r\n","<div class=\"hw\">titubanter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[titubo]</div><div class=\"def\">(語り口が)たどたどしく, もたもたして.</div>\r\n","<div class=\"hw\">titubantia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[titubo]</div><div class=\"ex\"><i>linguae [oris] ～</i> (<author>S<small>UET</small></author>)<span class=\"ext\">どもること.</span></div>\r\n","<div class=\"hw\">titubātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://titubō\">titubō</a>]</div><div class=\"def\"><num>①</num> (足取りが)ふらつくこと.</div><div class=\"def\"><num>②</num> 躊躇, ためらい.</div>\r\n","<div class=\"hw\">titubō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"def\"><num>①</num> (酔って足取りが)ふらつく, よろめく.</div><div class=\"def\"><num>②</num> (物が)ぐらつく, 揺れる.</div><div class=\"def\"><num>③</num> (体力などが)弱まる, 衰える.</div><div class=\"def\"><num>④</num> 狼狽<SUB>ろうばい</SUB>する, うろたえる.</div><div class=\"def\"><num>⑤</num> (ことばが)つかえる, 口ごもる.</div>\r\n","<div class=\"hw\">titulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 銘(刻)文, 碑文.</div><div class=\"def\"><num>②</num> 墓碑銘.</div><div class=\"def\"><num>③</num> (売り物・貸し家などを告知する)(貼り)札, 掲示(板)</div><div class=\"ex\"><i>mittere sub titulum</i> (<author>O<small>V</small></author>)<span class=\"ext\">売り[貸し]に出す.</span></div><div class=\"def\"><num>④</num> 書名, 標題, 見出し.</div><div class=\"def\"><num>⑤</num> 称号, 官職名, 肩書き.</div><div class=\"def\"><num>⑥</num> 名誉, 栄誉.</div><div class=\"def\"><num>⑦</num> 口実, 名目.</div><div class=\"def\"><num>⑧</num> <SUP>◇</SUP> 権利, 資格.</div>\r\n","<div class=\"hw\">titulāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[titulus]</div><div class=\"def\">称号の, 名義上の</div><div class=\"ex\"><i>～ episcopus</i><span class=\"ext\">〘カト〙名義司教.</span></div>\r\n","<div class=\"hw\">titulō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://titulus\">titulus</a>]</div><div class=\"def\"><num>①</num> 《碑》...に銘を刻む.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> ...に名称[称号]を与える, 名づける.</div>\r\n","<div class=\"hw\">titus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘鳥〙ヤマバト(山鳩).</div>\r\n","<div class=\"hw\">Titus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> ティトゥス《ローマ人の個人名(略形 T.);特に (1) <i>～ Tatius</i>, Sabini 族の王;のちローマを Romulus と共同統治した.(2) <i>～ Flavius Vespasianus</i>, ローマ皇帝(在位79‐81)》.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘聖〙<SUP>∥</SUP>テトス《使徒パウロ(Paulus)の友人》.</div>\r\n","<div class=\"hw\">Tityos, -us</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙ティテュオス《Juppiter の息子;Latona をはずかしめようとしたため冥界でハゲタカに肝臓を喰われ続ける罰を受けた》.</div>\r\n","<div class=\"hw\">Titūrius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ティトゥーリウス《Gallia 戦争における Caesar の副官(legatus)の一人》.</div>\r\n","<div class=\"hw\">Titūriānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Titurius の.</div>\r\n","<div class=\"hw\">tiāra</div><div class=\"pos\">-ae, <i>f</i>, <B>tiārās</B> -ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (ペルシア人の)頭飾り, 冠.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘カト〙(ローマ教皇の)三重宝冠, 教皇冠.</div>\r\n","<div class=\"hw\">tiārātus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">tiara をかぶった.</div>\r\n","<div class=\"hw\">Tlēpolemos</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙トレーポレモス《Hercules の息子;Troja 攻めの Rhodos 軍の指揮官》.</div>\r\n","<div class=\"hw\">Tmarius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">Tmarus の.</div>\r\n","<div class=\"hw\">Tmarus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トマルス, <SUP>*</SUP>-ロス《Epirus の山》.</div>\r\n","<div class=\"hw\">Tmōlius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tmolus 山の.</div><hr><div class=\"hw\">Tmōlius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://Tmōlius\">Tmōlius<SUP>1</SUP></a>]</div><div class=\"def\">Tmolus 産のぶどう酒.</div>\r\n","<div class=\"hw\">Tmōlus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トモールス, <SUP>*</SUP>-ロス《 (1) Lydia の山;Pactolus 川がこの山に発する.(2) Tmolus 山近辺の町》.</div>\r\n","<div class=\"hw\">Tmōlītae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"def\">Tmolus の住民.</div>\r\n","<div class=\"hw\">Tmōlītēs<SUP>1</SUP></div><div class=\"pos\">-is, <i>adj m</i></div><div class=\"def\">Tmolus 山の.</div><hr><div class=\"hw\">Tmōlītēs<SUP>2</SUP></div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">Tmolus 産のぶどう酒.</div>\r\n","<div class=\"hw\">tocologia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘医〙産科学.</div>\r\n","<div class=\"hw\">tocul(l)iō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">高利貸し.</div>\r\n","<div class=\"hw\">todillus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://todī\">todī</a>]</div><div class=\"def\">小鳥のような.</div>\r\n","<div class=\"hw\">todī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">小鳥.</div>\r\n","<div class=\"hw\">toga</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tego]</div><div class=\"def\"><num>①</num> (一般に)衣服, おおい.</div><div class=\"def\"><num>②</num> トガ《ローマ市民が平時に着用した寛衣》</div><div class=\"ex\"><i>～ virilis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">成年男子用の無地のトガ</span></div><div class=\"ex\"><i>～ praetexta</i> (<author>C<small>IC</small></author>)<span class=\"ext\">高級公職者および未成年者用の紫の縁付きトガ</span></div><div class=\"ex\"><i>～ picta</i> (<author>L<small>IV</small></author>)<span class=\"ext\">凱旋将軍用の刺繍を施したトガ</span></div><div class=\"ex\"><i>～ candida</i> (<author>L<small>IV</small></author>)<span class=\"ext\">官職立候補者用の白無垢<SUB>しろむく</SUB>のトガ</span></div><div class=\"ex\"><i>cedant arma togae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">武器(=武)はトガ(=文)に譲るべし.</span></div><div class=\"def\"><num>③</num> 平時.</div><div class=\"def\"><num>④</num> ローマ市民であること.</div><div class=\"def\"><num>⑤</num> 売春婦《女性の外衣 stola の着用が許されず, トガをまとっていた》.</div>\r\n","<div class=\"hw\">togula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[toga]</div><div class=\"def\">(軽蔑的に)トガ.</div>\r\n","<div class=\"hw\">togāta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[togatus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> (<i>sc. </i> fabula)(toga をまとう一般のローマ人の生活に取材した)国民喜劇(<i>cf. </i> palliata).</div><div class=\"def\"><num>②</num> (<i>sc. </i> ancilla)売春婦.</div>\r\n","<div class=\"hw\">togātulus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://togātus\">togātus<SUP>1</SUP></a>]</div><div class=\"def\">(あわれな)庇護民.</div>\r\n","<div class=\"hw\">togātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[toga]</div><div class=\"def\"><num>①</num> (ローマ市民として)トガを着た</div><div class=\"ex\"><i>gens togata</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">トガを着た国民(=ローマ人).</span></div><div class=\"def\"><num>②</num> 文民の, 平時の生活[活動]をしている.</div><div class=\"def\"><num>③</num> <i>Gallia togata</i> (<author>P<small>LIN</small></author>) =<a href=\"entry://Gallia\">Gallia Cisalpina</a>《北イタリアの Padus 川と Alpes 山脈の間の Gallia 地方ではローマ風の暮らしが普通であった》.</div><hr><div class=\"hw\">togātus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> ローマ市民.</div><div class=\"def\"><num>②</num> 文民, 文官.</div><div class=\"def\"><num>③</num> 庇護民.</div>\r\n","<div class=\"hw\">togātārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[togatus<SUP>1</SUP>]</div><div class=\"def\">国民喜劇の俳優[役者].</div>\r\n","<div class=\"hw\">Tolbiacum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">トルビアクム《Gallia Belgica の町;現 Zülpich》.</div>\r\n","<div class=\"hw\">tolerans</div><div class=\"pos\">-antis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[tolero]</div><div class=\"def\">我慢する, 忍耐強い 〈alcis rei〉.</div>\r\n","<div class=\"hw\">toleranter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://tolerans\">tolerans</a>]</div><div class=\"def\"><num>①</num> 我慢して, 忍耐強く.</div><div class=\"def\"><num>②</num> 耐えられる程度に, まずまず.</div>\r\n","<div class=\"hw\">tolerantia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tolerans]</div><div class=\"def\">忍耐, 辛抱, 我慢.</div>\r\n","<div class=\"hw\">toleror</div><div class=\"pos\">-ārī, <SUP>◇</SUP><i>tr dep</i></div><div class=\"def\">=<a href=\"entry://tolerō\">tolero</a>.</div>\r\n","<div class=\"hw\">tolerābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tolero]</div><div class=\"def\"><num>①</num> 耐えられる, 我慢できる</div><div class=\"ex\"><i>～ condicio</i> (<author>C<small>IC</small></author>)<span class=\"ext\">耐えられる程度の境遇.</span></div><div class=\"def\"><num>②</num> 寛容な, 忍耐強い.</div>\r\n","<div class=\"hw\">tolerābiliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://tolerābilis\">tolerābilis</a>]</div><div class=\"def\"><num>①</num> 耐えられる程度に, ほどほどに.</div><div class=\"def\"><num>②</num> 我慢強く.</div>\r\n","<div class=\"hw\">tolerātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[tolero]</div><div class=\"def\">耐える方法.</div>\r\n","<div class=\"hw\">tolerātus</div><div class=\"pos\">-ūs, <i><SUP>◇</SUP>m</i></div><div class=\"ori\">[↓<a href=\"entry://tolerō\">tolerō</a>]</div><div class=\"def\">忍耐[辛抱]すること.</div>\r\n","<div class=\"hw\">tolerō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[<i>cf. </i> tollo]</div><div class=\"def\"><num>①</num> (重さを)支える, 持ちこたえる.</div><div class=\"def\"><num>②</num> (義務・責任を)負う, になう.</div><div class=\"def\"><num>③</num> 食料を与える, 暮らしを支える, 養う.</div><div class=\"def\"><num>④</num> 耐える, 我慢する 〈+<i>acc c. inf</i>;+<i>inf</i>〉.</div><div class=\"def\"><num>⑤</num> ...に立ち向かう, ...と戦う.</div>\r\n","<div class=\"hw\">Tolistobogiī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Tolostobogiī\">Tolostobogii</a>.</div>\r\n","<div class=\"hw\">tollēnō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>cf. </i> tollo]</div><div class=\"def\">てこの働きを利用した装置</div><div class=\"def\"><num1>⒜</num1> (井戸の)はねつるべを動かす仕掛け.</div><div class=\"def\"><num1>⒝</num1> (岩石・金属などを吊り上げて落とす)攻城[船]器械.</div>\r\n","<div class=\"hw\">tollō</div><div class=\"pos\">-ere sustulī sublātum, <i>tr</i></div><div class=\"def\"><num>①</num> 上げる, 持ち上げる</div><div class=\"ex\"><i>oculos tollere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">目を上げる, 見上げる</span></div><div class=\"ex\"><i>sortes tollere</i> (<author>T<small>ER</small></author>)<span class=\"ext\">くじを引く</span></div><div class=\"ex\"><i>ancoras tollere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">錨を上げる, 出帆する.</span></div><div class=\"def\"><num>②</num> (子どもを認知・養育するために)拾い上げる;(子を)もうける.</div><div class=\"def\"><num>③</num> (<i>refl</i>;<i>pass</i>)上がる, 登る.</div><div class=\"def\"><num>④</num> (叫び声などを)上げる.</div><div class=\"def\"><num>⑤</num> (天・大空まで)高める, 称揚する.</div><div class=\"def\"><num>⑥</num> (船・乗物などに)乗せる, 積み込む.</div><div class=\"def\"><num>⑦</num> 起こす, 立てる</div><div class=\"ex\"><i>fluctūs tollere</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">波を逆立てる.</span></div><div class=\"def\"><num>⑧</num> (意気・気分などを)高揚させる, 鼓舞する.</div><div class=\"def\"><num>⑨</num> 取り去る, 運び去る.</div><div class=\"def\"><num>⑩</num> 盗む.</div><div class=\"def\"><num>⑪</num> 取り除く, 除去する, 削除する</div><div class=\"ex\"><i>alqm tollere de medio</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人を人目につかないところへ片付ける(=殺す).</span></div><div class=\"def\"><num>⑫</num> (ある地位から)追い出す.</div><div class=\"def\"><num>⑬</num> (ある状態・習慣・制度などを)終わらせる, 廃止する.</div><div class=\"def\"><num>⑭</num> <SUP>◇</SUP> 耐え忍ぶ, 辛抱する.</div>\r\n","<div class=\"hw\">Tolostobogiī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">トロストボギイー《Galatia の一部族》.</div>\r\n","<div class=\"hw\">Tolumnius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トルムニウス《 (1) 〘伝説〙Rutuli 族の占い師.(2) <i>Lars ～</i>, Veii の王》.</div>\r\n","<div class=\"hw\">Tolēnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トレーヌス《Latium の川;現 Turano》.</div>\r\n","<div class=\"hw\">Tolētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">トレートゥム《Hispania Tarraconensis の町;現 Toledo》.</div>\r\n","<div class=\"hw\">Tolētānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Toletum の.</div><div class=\"hw2\"><b>Tolētānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Toletum の住民.</div>\r\n","<div class=\"hw\">Tolōsa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">トローサ《Gallia Narbonensis の町;現 Toulouse》.</div>\r\n","<div class=\"hw\">Tolōsensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Tolōsānus\">Tolosanus</a>.</div>\r\n","<div class=\"hw\">Tolōsānus, Toloss-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tolosa の.</div><div class=\"hw2\"><b>Tolōsānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Tolosa の住民.</div>\r\n","<div class=\"hw\">Tolōsās</div><div class=\"pos\">-ātis, <i>adj</i></div><div class=\"def\">Tolosa の.</div><div class=\"hw2\"><b>Tolōsātēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Tolosa の住民.</div>\r\n","<div class=\"hw\">tolūtilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tolutim]</div><div class=\"def\">速歩の.</div>\r\n","<div class=\"hw\">tolūtiloquentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://tolūtim\">tolūtim</a>/loquor]</div><div class=\"def\">多弁, 饒舌<SUB>じょうぜつ</SUB>, おしゃべり.</div>\r\n","<div class=\"hw\">tolūtim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tollo]</div><div class=\"def\">だく足で, 速歩で.</div>\r\n","<div class=\"hw\">tolūtārius</div><div class=\"pos\">-a -um, <B>-tāris</B> -is -e, <i>adj</i></div><div class=\"ori\">[tolutim]</div><div class=\"def\">速歩の, 速足の</div><div class=\"ex\"><i>～ equus</i> (<author>S<small>EN</small></author>)<span class=\"ext\">速歩の馬.</span></div>\r\n","<div class=\"hw\">tomus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> パピルスの一片.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(書物の)巻.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>(一冊の)書物.</div>\r\n","<div class=\"hw\">Tomyris, T(h)amyris</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トミュリス《Scythia の Massagetae 族の女王;かつて自分に求婚した大 Cyrus の率いるペルシア軍を撃破した;このとき Cyrus も戦死したという》.</div>\r\n","<div class=\"hw\">tomācina</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://tomāculum\">tomaculum</a>.</div>\r\n","<div class=\"hw\">tomāculum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[<i>Gk</i>▷τομ<img class=\"font\" src=\"img/A14A.png\">◁]</div><div class=\"def\">ソーセージの一種.</div>\r\n","<div class=\"hw\">tomāculārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://tomāculum\">tomāculum</a>]</div><div class=\"def\">ソーセージ商人.</div>\r\n","<div class=\"hw\">tomē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘詩〙行中休止(=<a href=\"entry://caesūra\">caesura</a>);行中休止によって分かたれた詩行の一部.</div>\r\n","<div class=\"hw\">Tomī</div><div class=\"pos\">-ōrum, <i>m pl</i>, <B>Tomis</B> -is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トミー <SUP>*</SUP>トモイ《黒海に面する Moesia の町;Ovidius の流謫<SUB>るたく</SUB>地;現 Constantza》.</div>\r\n","<div class=\"hw\">Tomītae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"def\">Tomi の住民.</div>\r\n","<div class=\"hw\">Tomītānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tomi の.</div>\r\n","<div class=\"hw\">Tonans</div><div class=\"pos\">-ntis, <i>m</i>(<i>prp</i>)</div><div class=\"ori\">[tono]</div><div class=\"def\">雷鳴をとどろかす者《Juppiter の添え名》.</div>\r\n","<div class=\"hw\">tonanter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[tono]</div><div class=\"def\">雷鳴をとどろかして.</div>\r\n","<div class=\"hw\">tondeō</div><div class=\"pos\">-ēre totondī tonsum, <i>tr</i></div><div class=\"def\"><num>①</num> (髪を)切る, (ひげを)剃<SUB>そ</SUB>る.</div><div class=\"def\"><num>②</num> (木を)剪定する, 枝打ちする.</div><div class=\"def\"><num>③</num> 刈る, 刈り取る;摘み取る.</div><div class=\"def\"><num>④</num> (草を)食<SUB>は</SUB>む.</div><div class=\"def\"><num>⑤</num> むさぼる;(人を)丸裸[無一文]にする.</div>\r\n","<div class=\"hw\">tonescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[tono]</div><div class=\"def\">雷鳴がとどろき始める.</div>\r\n","<div class=\"hw\">tongeō</div><div class=\"pos\">-ēre, <i>tr</i></div><div class=\"def\">知っている.</div>\r\n","<div class=\"hw\">tongitiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://tongeō\">tongeō</a>]</div><div class=\"def\">知っていること, 知識.</div>\r\n","<div class=\"hw\">tonicum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘薬〙強壮剤.</div>\r\n","<div class=\"hw\">tonitrus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[tono]</div><div class=\"def\"><num>①</num> 雷鳴.</div><div class=\"def\"><num>②</num> 雷鳴のように大きな[とどろく]音.</div>\r\n","<div class=\"hw\">tonitruum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://tonitrus\">tonitrus</a>.</div>\r\n","<div class=\"hw\">tonitruālis, -trāl-</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tonitrus]</div><div class=\"def\">雷鳴がとどろく[をとどろかす].</div>\r\n","<div class=\"hw\">tonitruō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[↓<a href=\"entry://tonitrus\">tonitrus</a>]</div><div class=\"def\">(神が)雷鳴をとどろかす.</div>\r\n","<div class=\"hw\">tonitrātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[tonitrus]</div><div class=\"def\">《碑》雷鳴をとどろかす者《Juppiter の添え名》.</div>\r\n","<div class=\"hw\">tonor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">《古形》=<a href=\"entry://tenor\">tenor 3</a>.</div>\r\n","<div class=\"hw\">tonsa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">櫂<SUB>かい</SUB>.</div>\r\n","<div class=\"hw\">tonsilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tondeo]</div><div class=\"def\"><num>①</num> (織物の)毛足をつんだ[短く切った].</div><div class=\"def\"><num>②</num> 剪定された, 刈り込まれた.</div><div class=\"def\"><num>③</num> 刈り[切り]取って作った.</div>\r\n","<div class=\"hw\">tonsilla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tonsa]</div><div class=\"def\">係留杭<SUB>くい</SUB>.</div>\r\n","<div class=\"hw\">tonsillae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">〘解〙扁桃(腺).</div>\r\n","<div class=\"hw\">tonsillītis</div><div class=\"pos\">-tidis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙扁桃(腺)炎.</div>\r\n","<div class=\"hw\">tonsitō</div><div class=\"pos\">-āre, <i>tr freq</i></div><div class=\"ori\">[tondeo]</div><div class=\"def\">(羊の)毛を刈る.</div>\r\n","<div class=\"hw\">tonsiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tondeo]</div><div class=\"def\">(羊の)毛を刈ること, 剪毛;草刈り.</div>\r\n","<div class=\"hw\">tonsor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[tondeo]</div><div class=\"def\"><num>①</num> 理髪師.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(羊の)毛を刈る人.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 剪定する人.</div>\r\n","<div class=\"hw\">tonstrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[tonsor]</div><div class=\"def\">理髪師《女性》.</div>\r\n","<div class=\"hw\">tonstrīcula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[tonstrix]</div><div class=\"def\">(愛らしい)女性の理髪師.</div>\r\n","<div class=\"hw\">tonstrīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tondeo]</div><div class=\"def\">床屋, 理髪店.</div>\r\n","<div class=\"hw\">tonstrīnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tondeo]</div><div class=\"def\">理髪業.</div>\r\n","<div class=\"hw\">tonsus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://tondeō\">tondeo</a>.</div><hr><div class=\"hw\">tonsus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">理髪;髪形.</div>\r\n","<div class=\"hw\">tonsōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tondeo]</div><div class=\"def\">理髪(師)の.</div>\r\n","<div class=\"hw\">tonsūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tondeo]</div><div class=\"def\"><num>①</num> (羊の)毛を刈ること, 剪毛.</div><div class=\"def\"><num>②</num> (髪を)切ること, 散髪.</div><div class=\"def\"><num>③</num> (草木を)刈る[切る]こと, 剪定.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘カト〙剃髪(式), トンスラ.</div>\r\n","<div class=\"hw\">tonsūrō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[↑<a href=\"entry://tonsūra\">tonsūra</a>]</div><div class=\"def\">剃髪する 〈alqm〉.</div>\r\n","<div class=\"hw\">tonus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 張り, 緊張.</div><div class=\"def\"><num>②</num> 音, 響き;音調.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘音〙音階;和声, 諧調.</div><div class=\"def\"><num>④</num> (音節の)抑揚, アクセント.</div><div class=\"def\"><num>⑤</num> (色の)明暗, 色調.</div><div class=\"def\"><num>⑥</num> 雷鳴.</div>\r\n","<div class=\"hw\">tonuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tonō\">tono</a>.</div>\r\n","<div class=\"hw\">tonātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tono]</div><div class=\"def\">雷鳴(のとどろき).</div>\r\n","<div class=\"hw\">tonō</div><div class=\"pos\">-āre -nuī, <i>intr</i>, <i>tr</i></div><div class=\"def\"><num>①</num> (時に <i>impers</i>)雷が鳴る, 雷鳴がとどろく.</div><div class=\"def\"><num>②</num> とどろく, 鳴り響く;とどろかせる, 鳴り響かせる.</div>\r\n","<div class=\"hw\">tonōticus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">強壮にする.</div>\r\n","<div class=\"hw\">toparchia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(ヘレニズム時代の)地方行政区.</div>\r\n","<div class=\"hw\">toparchēs, -a</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">toparchia の長.</div>\r\n","<div class=\"hw\">topazus, -os</div><div class=\"pos\">-ī, <i>f</i>, <B>-zion</B> -ī, <SUP>◇</SUP><i>n</i>, <B>-zius</B> -ī, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘鉱〙貴橄欖<SUB>きかんらん</SUB>石.</div>\r\n","<div class=\"hw\">topia</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(<i>sc. </i> opera)</div><div class=\"def\"><num>①</num> 風景画.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> ぜいたくな庭園.</div>\r\n","<div class=\"hw\">Topica</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[topicus]</div><div class=\"def\">トピカ《 (1) Aristoteles の著作 「論拠集」.(2) それにならった Cicero の著作》.</div>\r\n","<div class=\"hw\">topicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 場所の[に関する].</div><div class=\"def\"><num>②</num> 〘医〙局所の, 部位的な.</div><div class=\"def\"><num>③</num> 常套的論題の.</div>\r\n","<div class=\"hw\">topicē</div><div class=\"pos\">-ēs, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">常套的論題を用いる技術.</div>\r\n","<div class=\"hw\">topiāria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[topiarius<SUP>1</SUP>]</div><div class=\"def\">造園[築庭]術.</div>\r\n","<div class=\"hw\">topiārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://topiārius\">topiārius<SUP>1</SUP></a>]</div><div class=\"def\">(<i>sc</i>. opus)装飾庭園.</div>\r\n","<div class=\"hw\">topiārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[topia]</div><div class=\"def\">造園の, 築庭の.</div><hr><div class=\"hw\">topiārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">造園師, 庭師.</div>\r\n","<div class=\"hw\">topographia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">地誌, 風土記.</div>\r\n","<div class=\"hw\">topper</div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> すぐに, 直ちに.</div><div class=\"def\"><num>②</num> おそらく, ひょっとすると.</div>\r\n","<div class=\"hw\">toral</div><div class=\"pos\">-ālis, <i>n</i></div><div class=\"ori\">[torus]</div><div class=\"def\">長椅子[寝台]の掛け布.</div>\r\n","<div class=\"hw\">torcular</div><div class=\"pos\">-āris, <i>n</i></div><div class=\"ori\">[torqueo]</div><div class=\"def\">(ブドウ・オリーブの)圧搾器[室].</div>\r\n","<div class=\"hw\">torculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://torculus\">torculus</a>]</div><div class=\"def\">(ブドウ・オリーブの)圧搾器.</div>\r\n","<div class=\"hw\">torculus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[torqueo]</div><div class=\"def\">(ブドウ・オリーブの)圧搾器の.</div>\r\n","<div class=\"hw\">torculārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://torculārius\">torculārius<SUP>1</SUP></a>]</div><div class=\"def\">=<a href=\"entry://torcular\">torcular</a>.</div>\r\n","<div class=\"hw\">torculārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[torcular]</div><div class=\"def\">(ブドウ・オリーブの)圧搾(用)の.</div><hr><div class=\"hw\">torculārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">圧搾室で作業する人.</div>\r\n","<div class=\"hw\">tordȳlon</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙セリ科の植物の一種.</div>\r\n","<div class=\"hw\">toreuma</div><div class=\"pos\">-atis, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">浮彫り細工を施した物品.</div>\r\n","<div class=\"hw\">toreuticē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(<i>sc. </i> ars)浮彫り細工.</div>\r\n","<div class=\"hw\">toreutēs, -a</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">浮彫り細工師.</div>\r\n","<div class=\"hw\">tormentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[torqueo]</div><div class=\"def\"><num>①</num> (髪の毛・線維などを綯<SUB>な</SUB>った)縄, 綱.</div><div class=\"def\"><num>②</num> 巻揚げ機.</div><div class=\"def\"><num>③</num> 射出機, 投石機, 弩<SUB>いしゆみ</SUB>.</div><div class=\"def\"><num>④</num> (射出機によって発射された)矢玉, 飛び道具.</div><div class=\"def\"><num>⑤</num> 拷問台[具];拷問.</div><div class=\"def\"><num>⑥</num> 苦痛, 苦悩.</div><div class=\"def\"><num>⑦</num> <SUP>◇</SUP>(編んだ)下<SUB>さ</SUB>げ髪.</div>\r\n","<div class=\"hw\">tormentuōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://tormentum\">tormentum</a>]</div><div class=\"def\">激しい痛みのある;責めさいなむ.</div>\r\n","<div class=\"hw\">tormina</div><div class=\"pos\">-um, <i>n pl</i></div><div class=\"ori\">[torqueo]</div><div class=\"def\">〘病〙(激しい)腹痛, 疝痛<SUB>せんつう</SUB></div><div class=\"ex\"><i>urinae ～</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">排尿痛, 有痛性排尿困難.</span></div>\r\n","<div class=\"hw\">torminālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://tormina\">tormina</a>]</div><div class=\"def\">疝痛に効く.</div>\r\n","<div class=\"hw\">torminōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tormina]</div><div class=\"def\">疝痛病みの[になりやすい].</div>\r\n","<div class=\"hw\">tornus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ろくろ</div><div class=\"ex\"><i>angusto versūs includere torno</i> (<author>P<small>ROP</small></author>)<span class=\"ext\">狭いろくろの上に詩を閉じ込める(=短詩を作る).</span></div>\r\n","<div class=\"hw\">tornātilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[torno]</div><div class=\"def\"><num>①</num> ろくろ細工の.</div><div class=\"def\"><num>②</num> みごとに丸く仕上げられた.</div>\r\n","<div class=\"hw\">tornātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[torno]</div><div class=\"def\">ろくろ細工師.</div>\r\n","<div class=\"hw\">tornātūra</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://tornō\">tornō</a>]</div><div class=\"def\">ろくろ細工.</div>\r\n","<div class=\"hw\">tornō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://tornus\">tornus</a>]</div><div class=\"def\"><num>①</num> (ろくろで)丸く[滑らかに]する.</div><div class=\"def\"><num>②</num> (詩を)いじり回す.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>(あごひげを)ひねる.</div>\r\n","<div class=\"hw\">torpefacere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://torpefaciō\">torpefacio</a>.</div>\r\n","<div class=\"hw\">torpefaciō</div><div class=\"pos\">-cere -fēcī, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[torpeo/facio]</div><div class=\"def\">=<a href=\"entry://torpōrō\">torporo</a>.</div>\r\n","<div class=\"hw\">torpefēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://torpefaciō\">torpefacio</a>.</div>\r\n","<div class=\"hw\">torpescō</div><div class=\"pos\">-ere -puī, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://torpeō\">torpeō</a>]</div><div class=\"def\"><num>①</num> 麻痺する, 無感覚になる.</div><div class=\"def\"><num>②</num> 動けなくなる, すくむ.</div><div class=\"def\"><num>③</num> 鈍る, 怠惰になる.</div>\r\n","<div class=\"hw\">torpeō</div><div class=\"pos\">-ēre -puī, <i>intr</i></div><div class=\"def\"><num>①</num> 麻痺している, 無感覚である.</div><div class=\"def\"><num>②</num> 動けないでいる, すくんでいる.</div><div class=\"def\"><num>③</num> 鈍い, 緩慢[不活発]である.</div>\r\n","<div class=\"hw\">torpidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[torpeo]</div><div class=\"def\">動けなくなった;呆然としている.</div>\r\n","<div class=\"hw\">torpor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[torpeo]</div><div class=\"def\"><num>①</num> 麻痺, 無感覚.</div><div class=\"def\"><num>②</num> 無気力, 怠惰.</div><div class=\"def\"><num>③</num> 動かないこと, 不活発.</div>\r\n","<div class=\"hw\">torpuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://torpeō\">torpeo</a>, <a href=\"entry://torpescō\">torpesco</a>.</div>\r\n","<div class=\"hw\">torpēdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[torpeo]</div><div class=\"def\"><num>①</num> 無気力, 怠惰;無感覚.</div><div class=\"def\"><num>②</num> 〘魚〙シビレエイ.</div>\r\n","<div class=\"hw\">torpōrō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↑<a href=\"entry://torpor\">torpor</a>]</div><div class=\"def\">麻痺させる, 無感覚にする.</div>\r\n","<div class=\"hw\">torqueō</div><div class=\"pos\">-ēre torsī tortum, <i>tr</i></div><div class=\"def\"><num>①</num> ねじる, ひねる</div><div class=\"ex\"><i>stamina pollice torquere</i> (<author>O<small>V</small></author>)<span class=\"ext\">糸を親指でねじる(=紡ぐ).</span></div><div class=\"def\"><num>②</num> 曲げる, 向ける</div><div class=\"ex\"><i>omnia ad suae causae commodum torquere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">すべてを自分の利益になるようにねじ曲げる.</span></div><div class=\"def\"><num>③</num> 巻く, 巻きつける.</div><div class=\"def\"><num>④</num> 回す, 回転させる.</div><div class=\"def\"><num>⑤</num> 投げる, 射る, 発射する.</div><div class=\"def\"><num>⑥</num> 拷問にかける;責める, さいなむ, 苦しめる.</div><div class=\"def\"><num>⑦</num> 吟味する</div><div class=\"ex\"><i>alqm mero torquere</i> (<author>H<small>OR</small></author>)<span class=\"ext\">ある人を酒で試す(=酒を飲ませて人物を見とどける).</span></div>\r\n","<div class=\"hw\">torquātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[torques]</div><div class=\"def\"><num>①</num> 首飾りを着けた</div><div class=\"ex\"><i>Allecto torquata colubris</i> (<author>O<small>V</small></author>)<span class=\"ext\">蛇を(首飾りのように)巻きつけた Allecto</span></div><div class=\"ex\"><i>palumbus ～</i> (<author>M<small>ART</small></author>)<span class=\"ext\">モリバト.</span></div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(兵士が)銀の首章を授けられた.</div>\r\n","<div class=\"hw\">Torquātus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トルクゥアートゥス《Manlia 氏族に属する家名;T. Manlius が討ち取った Gallia 人から奪った首飾りにちなむ;⇒ <a href=\"entry://Manlius\">Manlius (2)</a> 》.</div>\r\n","<div class=\"hw\">torquēs, torquis</div><div class=\"pos\">-is, <i>m</i>(<i>f</i>)</div><div class=\"ori\">[↑<a href=\"entry://torqueō\">torqueō</a>]</div><div class=\"def\"><num>①</num> 首飾り;(戦功のあった兵士に授与される)首章.</div><div class=\"def\"><num>②</num> (牛の)首輪.</div><div class=\"def\"><num>③</num> 花輪, 花冠.</div>\r\n","<div class=\"hw\">torrefacere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://torrefaciō\">torrefacio</a>.</div>\r\n","<div class=\"hw\">torrefaciō</div><div class=\"pos\">-cere -fēcī -factum, <i>tr</i></div><div class=\"ori\">[torreo/facio]</div><div class=\"def\">(日光にあてて)乾燥させる.</div>\r\n","<div class=\"hw\">torrens<SUP>1</SUP></div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[torreo]</div><div class=\"def\"><num>①</num> 灼熱している, (焼けるように)熱い.</div><div class=\"def\"><num>②</num> 激しく流れる, 急流の.</div><hr><div class=\"hw\">torrens<SUP>2</SUP></div><div class=\"pos\">-entis, <i>m</i></div><div class=\"def\">(激しい)流れ, 急流, 奔流.</div>\r\n","<div class=\"hw\">torrenter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[torrens<SUP>1</SUP>]</div><div class=\"def\">激しく, 急流をなして.</div>\r\n","<div class=\"hw\">torrescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://torreō\">torreō</a>]</div><div class=\"def\"><num>①</num> あぶら[焦がさ]れる.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 乾く.</div>\r\n","<div class=\"hw\">torreō</div><div class=\"pos\">-ēre torruī tostum, <i>tr</i></div><div class=\"def\"><num>①</num> 乾かす;干上がらせる.</div><div class=\"def\"><num>②</num> あぶる, 焦がす, 焼く.</div><div class=\"def\"><num>③</num> (恋が心[胸・身]を)燃え上がらせる.</div><div class=\"def\"><num>④</num> (寒さで)凍えさす.</div>\r\n","<div class=\"hw\">torridus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[torreo]</div><div class=\"def\"><num>①</num> 乾いた;干上がった;ひからびた.</div><div class=\"def\"><num>②</num> 焦げた, 焼かれた.</div><div class=\"def\"><num>③</num> 凍えた;(寒さが)肌を刺すような.</div>\r\n","<div class=\"hw\">torridō</div><div class=\"pos\">-āre -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://torridus\">torridus</a>]</div><div class=\"def\">焼く, あぶる, 乾燥させる.</div>\r\n","<div class=\"hw\">torris</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[torreo]</div><div class=\"def\">燃えている木;燃えさし.</div>\r\n","<div class=\"hw\">torror</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[torreo]</div><div class=\"def\">日光にさらすこと, 日光を浴びること.</div>\r\n","<div class=\"hw\">torrus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://torris\">torris</a>.</div>\r\n","<div class=\"hw\">torsiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[torqueo]</div><div class=\"def\">捻転;腹痛, 疝痛<SUB>せんつう</SUB>.</div>\r\n","<div class=\"hw\">torsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://torqueō\">torqueo</a>.</div>\r\n","<div class=\"hw\">torta</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tortus<SUP>1</SUP>]</div><div class=\"def\">(丸い)パン.</div>\r\n","<div class=\"hw\">torticollis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙斜頸.</div>\r\n","<div class=\"hw\">torticordius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tortus<SUP>1</SUP>/cor]</div><div class=\"def\">ねじけた心の.</div>\r\n","<div class=\"hw\">tortilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[torqueo]</div><div class=\"def\">ねじれた;(渦状に)巻いた.</div>\r\n","<div class=\"hw\">tortiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[torqueo]</div><div class=\"def\"><num>①</num> ねじる[ひねる]こと.</div><div class=\"def\"><num>②</num> 耐えがたい苦痛, 疝痛<SUB>せんつう</SUB>.</div>\r\n","<div class=\"hw\">tortor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[torqueo]</div><div class=\"def\"><num>①</num> 拷問する人[係];(T-)拷問する者《Apollo の添え名》.</div><div class=\"def\"><num>②</num> (投石器の革ひもを)振り回す者.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>(弩砲の綱を)よじる者.</div>\r\n","<div class=\"hw\">tortula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[torta]</div><div class=\"def\">(小さな)パン, 菓子.</div>\r\n","<div class=\"hw\">tortum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[tortus<SUP>1</SUP>]</div><div class=\"def\">(拷問用の)縄.</div>\r\n","<div class=\"hw\">tortus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[torqueo]</div><div class=\"def\"><num>①</num> ねじれた, 曲がった, 曲がりくねった</div><div class=\"ex\"><i>torta quercus</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">オークの冠</span></div><div class=\"ex\"><i>torta via</i> (<author>P<small>ROP</small></author>)<span class=\"ext\">迷路(=<a href=\"entry://labyrinthus\">labyrinthus</a>).</span></div><div class=\"def\"><num>②</num> 渦巻いた;巻き毛の.</div><div class=\"def\"><num>③</num> 入り組んだ.</div><hr><div class=\"hw\">tortus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> (ヘビが)のたくる[のたうち回る]こと;とぐろ.</div><div class=\"def\"><num>②</num> (投石器の革ひもを)振り回すこと.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>(ラッパの)湾曲部.</div>\r\n","<div class=\"hw\">tortuōsitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://tortuōsus\">tortuōsus</a>]</div><div class=\"def\"><num>①</num> (ラクダの背が)曲がっている様子[外観].</div><div class=\"def\"><num>②</num> 言いのがれ, 逃げ口上.</div>\r\n","<div class=\"hw\">tortuōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tortus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 曲がった, 曲がりくねった, ねじれた.</div><div class=\"def\"><num>②</num> 回りくどい;込み入った, 複雑な.</div><div class=\"def\"><num>③</num> </div><div class=\"ex\"><i>tortuosior urina</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">(有痛)排尿困難.</span></div>\r\n","<div class=\"hw\">tortuōsē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[tortuosus]</div><div class=\"def\">(曲がり)くねって.</div>\r\n","<div class=\"hw\">tortē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tortus<SUP>1</SUP>]</div><div class=\"def\">曲がって, ねじれて.</div>\r\n","<div class=\"hw\">tortīvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[torqueo]</div><div class=\"ex\"><i>mustum tortivum</i> (<author>C<small>ATO</small></author>)<span class=\"ext\">二番しぼりのブドウ液.</span></div>\r\n","<div class=\"hw\">tortō</div><div class=\"pos\">-āre, <i>tr freq</i></div><div class=\"ori\">[torqueo]</div><div class=\"def\"><num>①</num> 拷問にかける.</div><div class=\"def\"><num>②</num> (くねくねと)曲げる, よじる.</div>\r\n","<div class=\"hw\">tortūra</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[torqueo]</div><div class=\"def\"><num>①</num> 撚り合わせる[巻きつける]こと.</div><div class=\"def\"><num>②</num> 腹痛, 疝痛.</div>\r\n","<div class=\"hw\">torulus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://torus\">torus</a>]</div><div class=\"def\"><num>①</num> ひも.</div><div class=\"def\"><num>②</num> 編んだ髪, 束髪.</div><div class=\"def\"><num>③</num> (盛り上がった)筋肉.</div><div class=\"def\"><num>④</num> 〘植〙辺材, 白太<SUB>しらた</SUB>(=<a href=\"entry://alburnum\">alburnum</a>).</div>\r\n","<div class=\"hw\">torus</div><div class=\"pos\">-ī, <i>m</i>, <B>-um</B> -ī, <i>n</i></div><div class=\"def\"><num>①</num> (縄・綱の)組み継ぎ;結び目;ゆわえ付けること.</div><div class=\"def\"><num>②</num> (盛り上がった)筋肉;(牛などの)太い頸.</div><div class=\"def\"><num>③</num> (木の)こぶ.</div><div class=\"def\"><num>④</num> (地面の)高くなった場所.</div><div class=\"def\"><num>⑤</num> (枝葉でつくった冠に添える)花(束).</div><div class=\"def\"><num>⑥</num> 敷物, 褥<SUB>しとね</SUB>.</div><div class=\"def\"><num>⑦</num> 寝椅子, 寝台.</div><div class=\"def\"><num>⑧</num> 新床<SUB>にいどこ</SUB>;結婚;情事.</div><div class=\"def\"><num>⑨</num> 棺架.</div><div class=\"def\"><num>⑩</num> 〘建〙トルス《柱基上の横に出っ張った繰形<SUB>くりがた</SUB>》.</div><div class=\"def\"><num>⑪</num> (破城槌<SUB>づち</SUB>の槌を滑らせる)円筒.</div>\r\n","<div class=\"hw\">torva</div><div class=\"pos\"><i>adv</i>(<i>n pl</i>)</div><div class=\"def\">=<a href=\"entry://torvum\">torvum</a>.</div>\r\n","<div class=\"hw\">torvidus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[torvus]</div><div class=\"def\">荒々しい, 激しい.</div>\r\n","<div class=\"hw\">torviter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[torvus]</div><div class=\"def\">荒々しく, 残忍に.</div>\r\n","<div class=\"hw\">torvitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[torvus]</div><div class=\"def\">(容貌・性格が)狂暴な[陰険な, きびしい]こと.</div>\r\n","<div class=\"hw\">torvum</div><div class=\"pos\"><i>adv</i>(<i>neut</i>)</div><div class=\"ori\">[↓<a href=\"entry://torvus\">torvus</a>]</div><div class=\"def\">きびしく, 激しく.</div>\r\n","<div class=\"hw\">torvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 狂暴な, 残忍な, 陰険な, 恐ろしい</div><div class=\"ex\"><i>～ senex</i> (<author>P<small>ROP</small></author>)<span class=\"ext\">陰鬱な(目つきの)老人(=<a href=\"entry://Charōn\">Charon</a>).</span></div><div class=\"def\"><num>②</num> (味が)苦い, 渋い.</div>\r\n","<div class=\"hw\">Torōnaeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Torone の</div><div class=\"ex\"><i>sinus ～</i> (<author>T<small>AC</small></author>)<span class=\"ext\">トローネー湾.</span></div><div class=\"hw2\"><b>Torōnaeī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Torone の住民.</div>\r\n","<div class=\"hw\">Torōnāicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Torōnaeus\">Toronaeus</a></div><div class=\"ex\"><i>mare Toronaicum</i> (<author>L<small>IV</small></author>)<span class=\"ext\">=<a href=\"entry://Torōnaeus\">sinus Toronaeus</a>.</span></div>\r\n","<div class=\"hw\">Torōnē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トローネー《Chalcidice の南に突き出た三つの半島のうち, 中央の Sithonia 半島西岸の町》.</div>\r\n","<div class=\"hw\">torōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[torus]</div><div class=\"def\"><num>①</num> 筋肉が盛りあがった, たくましい.</div><div class=\"def\"><num>②</num> 多肉質の.</div><div class=\"def\"><num>③</num> 節<SUB>ふし</SUB>くれ立った, 節の多い.</div>\r\n","<div class=\"hw\">tostus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://torreō\">torreo</a>.</div>\r\n","<div class=\"hw\">tostārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[torreo]</div><div class=\"def\">焼くのに適した.</div>\r\n","<div class=\"hw\">tostō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr freq</i></div><div class=\"ori\">[torreo]</div><div class=\"def\"><num>①</num> あぶる, 焼く.</div><div class=\"def\"><num>②</num> 乾かす, 乾燥させる.</div>\r\n","<div class=\"hw\">tot</div><div class=\"pos\"><i>indecl adj</i></div><div class=\"def\">〈+<i>pl</i>〉 これ[それ, あれ]だけの数の;これ[それ, あれ]ほどたくさんの</div><div class=\"ex\"><i>quot homines, ～ sententiae</i> (<author>T<small>ER</small></author>)<span class=\"ext\">(それだけ)多くの人がいれば, (それだけ)多くの考え(がある), 十人十色</span></div><div class=\"ex\"><i>～ tantaeque classes</i> (<author>C<small>AES</small></author>)<span class=\"ext\">あれほどたくさんの艦船.</span></div>\r\n","<div class=\"hw\">totidem</div><div class=\"pos\"><i>indecl adj</i></div><div class=\"ori\">[tot/idem]</div><div class=\"def\">〈+<i>pl</i>〉(...と)同数の;同じくらいの数の</div><div class=\"ex\"><i>quot fratres</i>, <i>～ periēre sorores</i> (<author>O<small>V</small></author>)<span class=\"ext\">兄弟と同じ数だけの姉妹が失われた</span></div><div class=\"ex\"><i>epistula quam ～ fere verbis interpretatus sum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私がほとんど逐語訳した書簡.</span></div>\r\n","<div class=\"hw\">totiens, totiēs</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tot]</div><div class=\"def\">(...と)同じ回数だけ, 同じ頻度で;(これ[それ, あれ]ほど)頻繁に, しばしば</div><div class=\"ex\"><i>quotienscumque dico</i>, <i>～ mihi videor in judicium venire</i> (<author>C<small>IC</small></author>)<span class=\"ext\">弁論に立つたびに, 私自身が裁判にかけられるように感じる</span></div><div class=\"ex\"><i>～ne sententiam mutas</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あなたはそれほど頻繁に意見を変えるのですか.</span></div>\r\n","<div class=\"hw\">totjugis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tot/jugum]</div><div class=\"def\">そんなに多く(のもの)を一まとめにした, 多岐にわたる.</div>\r\n","<div class=\"hw\">totjugī</div><div class=\"pos\">-ae -a, <i>adj pl</i></div><div class=\"ori\">[tot/jugum]</div><div class=\"def\">(まとめて)それほど多くの.</div>\r\n","<div class=\"hw\">totondī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tondeō\">tondeo</a>.</div>\r\n","<div class=\"hw\">toxicum, -on</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">毒, 毒物.</div>\r\n","<div class=\"hw\">toxicō</div><div class=\"pos\">-āre -ātus, <SUP>◇</SUP><i>tr</i></div><div class=\"def\">毒を塗る.</div>\r\n","<div class=\"hw\">toxotis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ヨモギ.</div>\r\n","<div class=\"hw\">Tr.</div><div class=\"def\">《略》=<a href=\"entry://tribūnus\">tribunus</a>;<a href=\"entry://tribūnicius\">tribunicius</a>.</div>\r\n","<div class=\"hw\">trabea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[trabs]</div><div class=\"def\"><num>①</num> 式服, 礼服《紫の縞<SUB>しま</SUB>の入った白いマント;王・騎士・卜占官が着用した》.</div><div class=\"def\"><num>②</num> 騎士階級.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 執政官職.</div>\r\n","<div class=\"hw\">Trabea</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">トラベア《ローマの喜劇詩人;Caecilius と同時代の人》.</div>\r\n","<div class=\"hw\">trabeālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">trabea の.</div>\r\n","<div class=\"hw\">trabeāta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://trabeātus\">trabeātus</a>]</div><div class=\"def\">(<i>sc. </i> fabula)トラベアータ《ローマ喜劇の一種;騎士身分のローマ人を主題としたらしい》.</div>\r\n","<div class=\"hw\">trabeātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">trabea を着た.</div>\r\n","<div class=\"hw\">trabica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">(<i>sc. </i> navis)</div><div class=\"ori\">[↓<a href=\"entry://trabs\">trabs</a>]</div><div class=\"def\">小舟の一種.</div>\r\n","<div class=\"hw\">trabs</div><div class=\"pos\">-bis, <i>f</i></div><div class=\"def\"><num>①</num> 梁<SUB>はり</SUB>, 桁<SUB>けた</SUB>;材木.</div><div class=\"def\"><num>②</num> 木, 樹木;幹.</div><div class=\"def\"><num>③</num> 棍棒;槍;破城槌.</div><div class=\"def\"><num>④</num> 松明<SUB>たいまつ</SUB>.</div><div class=\"def\"><num>⑤</num> 船.</div><div class=\"def\"><num>⑥</num> 屋根.</div><div class=\"def\"><num>⑦</num> 食卓.</div><div class=\"def\"><num>⑧</num> 流星, ほうき星.</div><div class=\"def\"><num>⑨</num> 男根.</div>\r\n","<div class=\"hw\">trabālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[trabs]</div><div class=\"def\"><num>①</num> 梁<SUB>はり</SUB>の</div><div class=\"ex\"><i>clavus ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">大釘.</span></div><div class=\"def\"><num>②</num> (幹のように)太い, 大きな.</div>\r\n","<div class=\"hw\">trabēcula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[trabs]</div><div class=\"def\"><num>①</num> 小さな梁<SUB>はり</SUB>.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解・動〙柱, 小柱.</div>\r\n","<div class=\"hw\">trabēs</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">《古形》=<a href=\"entry://trabs\">trabs</a>.</div>\r\n","<div class=\"hw\">Trachālus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トラカールス《Quintilianus と同時代の弁論家》.</div>\r\n","<div class=\"hw\">tracta<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[traho]</div><div class=\"def\">(長く伸ばした)パン, 焼き菓子.</div><hr><div class=\"hw\">tracta<SUP>2</SUP></div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[tractus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> =<a href=\"entry://tracta\">tracta<SUP>1</SUP></a>.</div><div class=\"def\"><num>②</num> (糸に紡ぐために取り分けた)羊毛の房.</div>\r\n","<div class=\"hw\">tractim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[traho]</div><div class=\"def\"><num>①</num> 長く伸びて[伸ばして].</div><div class=\"def\"><num>②</num> なでるように.</div><div class=\"def\"><num>③</num> ゆっくり.</div>\r\n","<div class=\"hw\">tractiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[traho]</div><div class=\"def\">〘文〙(副詞の)派生語.</div>\r\n","<div class=\"hw\">tractus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[traho]</div><div class=\"def\">(弁説が)なめらかな, よどみなく続く.</div><hr><div class=\"hw\">tractus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 引く[引っ張る]こと.</div><div class=\"def\"><num>②</num> (ものの動いた)跡;道筋, 通り道</div><div class=\"ex\"><i>longo per aera tractu</i> (<author>O<small>V</small></author>)<span class=\"ext\">空中に長い尾を引いて.</span></div><div class=\"def\"><num>③</num> 広がり, 距離;位置.</div><div class=\"def\"><num>④</num> 区域, 地域, 地方.</div><div class=\"def\"><num>⑤</num> (時間の)流れ, 長さ, 期間.</div><div class=\"def\"><num>⑥</num> 引き延ばす[長引かせる]こと, 延長.</div><div class=\"def\"><num>⑦</num> 展開, 進行.</div><div class=\"def\"><num>⑧</num> <SUP>◇</SUP>〘解〙道, 路, 索</div><div class=\"ex\"><i>～ iliotibialis</i><span class=\"ext\">腸脛索[腸脛靱帯]</span></div><div class=\"ex\"><i>～ olfactorius</i><span class=\"ext\">嗅索</span></div><div class=\"ex\"><i>～ solitarius</i><span class=\"ext\">孤束.</span></div><div class=\"def\"><num>⑨</num> <SUP>◇</SUP>(神性の)拡張.</div><div class=\"def\"><num>⑩</num> <SUP>◇</SUP>〘カト〙(ミサの)詠誦<SUB>えいしょう</SUB>.</div>\r\n","<div class=\"hw\">tractuōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[traho]</div><div class=\"def\">ねばねばする, ねばり気のある,, 粘性の.</div>\r\n","<div class=\"hw\">tractābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tracto]</div><div class=\"def\"><num>①</num> 触れることができる.</div><div class=\"def\"><num>②</num> 扱いやすい, 御しやすい</div><div class=\"ex\"><i>non tractabile caelum</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">(航海には)適さない天候.</span></div><div class=\"def\"><num>③</num> 素直[従順]な;穏和な.</div>\r\n","<div class=\"hw\">tractābiliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tractabilis]</div><div class=\"def\">容易に.</div>\r\n","<div class=\"hw\">tractābilitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://tractābilis\">tractābilis</a>]</div><div class=\"def\">扱いやすさ.</div>\r\n","<div class=\"hw\">tractātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[tracto]</div><div class=\"def\"><num>①</num> (取り)扱うこと;(取り)扱い方.</div><div class=\"def\"><num>②</num> 処遇</div><div class=\"ex\"><i>mala ～</i> (<author>Q<small>UINT</small></author>)<span class=\"ext\">虐待.</span></div><div class=\"def\"><num>③</num> 考察, 論ずること;論じ方.</div>\r\n","<div class=\"hw\">tractātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[tracto]</div><div class=\"def\"><num>①</num> マッサージ奴隷.</div><div class=\"def\"><num>②</num> 《碑》(帝政期の)会計官.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 論ずる人;注解者.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 説教する人.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP> 助言者, 顧問.</div>\r\n","<div class=\"hw\">tractātrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://tractātor\">tractātor</a>]</div><div class=\"def\">マッサージ奴隷《女性》.</div>\r\n","<div class=\"hw\">tractātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://tractō\">tracto</a>.</div><hr><div class=\"hw\">tractātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 手でいじる[触れる]こと.</div><div class=\"def\"><num>②</num> (取り)扱うこと;(取り)扱い方.</div><div class=\"def\"><num>③</num> 考察, 論ずること;論じ方.</div><div class=\"def\"><num>④</num> 論考, 論文.</div><div class=\"def\"><num>⑤</num> 遂行, 履行.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP> 討議, 審議.</div><div class=\"def\"><num>⑦</num> <SUP>◇</SUP> 熟慮;見解.</div><div class=\"def\"><num>⑧</num> <SUP>◇</SUP> 検査.</div><div class=\"def\"><num>⑨</num> <SUP>◇</SUP> 管理, 運営.</div><div class=\"def\"><num>⑩</num> <SUP>◇</SUP> 説教.</div><div class=\"def\"><num>⑪</num> <SUP>◇</SUP>〘キ教〙公会議, 教会会議.</div>\r\n","<div class=\"hw\">Tractīcius</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[traho]</div><div class=\"def\">「引きずられた者」《ローマ皇帝 Elagabalus(別名 Heliogabalus;正式名 M. Aurelius Antoninus(在位218‐22))の死後のあだ名;その死体が市中を引きずり回されたことから》.</div>\r\n","<div class=\"hw\">tractō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>(<i>intr</i>)<i>freq</i></div><div class=\"ori\">[traho]</div><div class=\"def\"><num>①</num> 引きずる;引きずり込む.</div><div class=\"def\"><num>②</num> (手で)取り扱う, 操作する</div><div class=\"ex\"><i>fila lyrae tractare</i> (<author>O<small>V</small></author>)<span class=\"ext\">竪琴(の弦)を弾ずる</span></div><div class=\"ex\"><i>gubernacula rei publicae tractare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">国家の舵を取る.</span></div><div class=\"def\"><num>③</num> なでる, 触れる;(傷の)手当てをする.</div><div class=\"def\"><num>④</num> (人を)遇する, 扱う.</div><div class=\"def\"><num>⑤</num> 対処する, 処理する.</div><div class=\"def\"><num>⑥</num> 用いる, 利用する.</div><div class=\"def\"><num>⑦</num> 行なう, 実行する.</div><div class=\"def\"><num>⑧</num> (人生を)送る, 生きる.</div><div class=\"def\"><num>⑨</num> (役を)演じる.</div><div class=\"def\"><num>⑩</num> (<i>refl</i>)ふるまう, 行動する.</div><div class=\"def\"><num>⑪</num> (人(の心)に)働きかける, 影響を与える.</div><div class=\"def\"><num>⑫</num> (<i>intr</i>)交渉する, 協議[討議]する</div><div class=\"ex\"><i>de condicionibus tractare</i> (<author>N<small>EP</small></author>)<span class=\"ext\">(降服の)条件について談判する.</span></div><div class=\"def\"><num>⑬</num> 考察する, 研究する.</div><div class=\"def\"><num>⑭</num> (題材などを)取り上げる, 扱う.</div><div class=\"def\"><num>⑮</num> <SUP>◇</SUP>(聖書の字句を)解釈する.</div>\r\n","<div class=\"hw\">tractōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[traho]</div><div class=\"def\">引っ張る, 引っ張り上げる.</div>\r\n","<div class=\"hw\">tractūra</div><div class=\"pos\">-se, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[traho]</div><div class=\"def\">引く[引っ張る]こと.</div>\r\n","<div class=\"hw\">tragacantha</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙トラガカントゴムノキ.</div>\r\n","<div class=\"hw\">tragacanthum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">トラガカントゴム.</div>\r\n","<div class=\"hw\">tragelaphos</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙野生ヤギの一種.</div>\r\n","<div class=\"hw\">tragicus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 悲劇の.</div><div class=\"def\"><num>②</num> 悲劇のような[にふさわしい];荘重な, 悲壮な.</div><div class=\"def\"><num>③</num> 悲劇的な;恐ろしい.</div><hr><div class=\"hw\">tragicus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 悲劇役者.</div><div class=\"def\"><num>②</num> 悲劇詩人[作者].</div>\r\n","<div class=\"hw\">tragicē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tragicus<SUP>1</SUP>]</div><div class=\"def\">悲劇のように, 悲劇にふさわしく.</div>\r\n","<div class=\"hw\">tragicōmoedia</div><div class=\"ori\">[↓<a href=\"entry://tragicus\">tragicus<SUP>1</SUP></a>/comoedia]</div><div class=\"def\">悲喜劇.</div>\r\n","<div class=\"hw\">tragoedia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 悲劇;文芸としての悲劇作品.</div><div class=\"def\"><num>②</num> 芝居がかった演説, 大げさな表現.</div><div class=\"def\"><num>③</num> 大騒ぎ.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 痛ましいできごと.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP> 悪事, 悪行.</div>\r\n","<div class=\"hw\">tragoediographus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">悲劇作者.</div>\r\n","<div class=\"hw\">tragoedus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">悲劇役者.</div>\r\n","<div class=\"hw\">tragum<SUP>1</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">粥<SUB>かゆ</SUB>の一種.</div>\r\n","<div class=\"hw\">tragus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 腋臭<SUB>わきが</SUB>, 強い体臭.</div><div class=\"def\"><num>②</num> 〘魚〙=<a href=\"entry://maena\">maena</a>《産卵期の雄について言う》.</div><div class=\"def\"><num>③</num> 〘解〙耳毛<SUB>じもう</SUB>;耳珠<SUB>じじゅ</SUB>.</div>\r\n","<div class=\"hw\">tragēmata</div><div class=\"pos\">-tum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">デザート用のドライフルーツ(=ナツメヤシの実・デーツ).</div>\r\n","<div class=\"hw\">traha, trahea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[traho]</div><div class=\"def\">(牛に引かせる脱穀用の)そり.</div>\r\n","<div class=\"hw\">trahax</div><div class=\"pos\">-ācis, <i>adj</i></div><div class=\"ori\">[traho]</div><div class=\"def\">何でも引ったくるのが好きな, 強欲な.</div>\r\n","<div class=\"hw\">trahitōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://trahō\">trahō</a>]</div><div class=\"def\">(心を)引きつける, 魅惑する.</div>\r\n","<div class=\"hw\">trahō</div><div class=\"pos\">-ere traxī tractum, <i>tr</i>(<i>intr</i>)</div><div class=\"def\"><num>①</num> 引く, 引っ張る, 引きずる</div><div class=\"ex\"><i>caudā traxit in antra boves</i> (<author>P<small>ROP</small></author>)<span class=\"ext\">(Hercules は)尻尾をつかんで牛を洞穴へ引き入れた</span></div><div class=\"ex\"><i>trahit Hectorem ad currum religatum Achilles</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Achilles は Hector(の死体)を戦車に縛りつけて引きずり回す.</span></div><div class=\"def\"><num>②</num> (兵士・従者などの一隊[団]を)引き連れ(て来)る.</div><div class=\"def\"><num>③</num> 引き寄せる;引き倒す.</div><div class=\"def\"><num>④</num> 引き抜く[離す].</div><div class=\"def\"><num>⑤</num> 長く引き出す, 紡ぐ</div><div class=\"ex\"><i>data pensa trahens</i> (<author>O<small>V</small></author>)<span class=\"ext\">日課の糸紡ぎをしながら.</span></div><div class=\"def\"><num>⑥</num> (水を)汲む, 汲み出す.</div><div class=\"def\"><num>⑦</num> 飲む;吸収する;吸い込む</div><div class=\"ex\"><i>spiritum [animum] trahere</i> (<author>S<small>EN</small> [P<small>LIN</small>]</author>)<span class=\"ext\">呼吸する, 息をする.</span></div><div class=\"def\"><num>⑧</num> 引き締める, 縮める</div><div class=\"ex\"><i>vultum trahere</i> (<author>O<small>V</small></author>)<span class=\"ext\">顔をしかめる</span></div><div class=\"ex\"><i>vela trahere</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">帆をたたむ.</span></div><div class=\"def\"><num>⑨</num> 奪う, 略奪する.</div><div class=\"def\"><num>⑩</num> (関心などを)引きつける;魅了する.</div><div class=\"def\"><num>⑪</num> 引き込む, 巻き込む.</div><div class=\"def\"><num>⑫</num> ひき起こす, 招来する.</div><div class=\"def\"><num>⑬</num> (結論を)引き出す, 導く.</div><div class=\"def\"><num>⑭</num> 取り入れる;獲得する.</div><div class=\"def\"><num>⑮</num> (色・熱・様相などを)帯びる, 呈する.</div><div class=\"def\"><num>⑯</num> 取り除く, 排除する.</div><div class=\"def\"><num>⑰</num> 長引かせる, 引き延ばす;(<i>intr</i>)長引く.</div><div class=\"def\"><num>⑱</num> (時を)過ごす, 費やす.</div><div class=\"def\"><num>⑲</num> 帰する, 結びつける;解釈する</div><div class=\"ex\"><i>crimen in se trahere</i> (<author>O<small>V</small></author>)<span class=\"ext\">(他人の)罪を自分にかぶせる</span></div><div class=\"ex\"><i>cuncta in deterius trahere</i> (<author>T<small>AC</small></author>)<span class=\"ext\">すべてを悪い方にとる.</span></div><div class=\"def\"><num>⑳</num> 利用[適用]する</div><div class=\"ex\"><i>spinas in pisce traxit in exemplum</i> (<author>O<small>V</small></author>)<span class=\"ext\">彼は魚の骨を(のこぎりを発明する)手本にした.</span></div><div class=\"def\"><num>㉑</num> 変える.</div><div class=\"def\"><num>㉒</num> 熟考[熟慮]する.</div>\r\n","<div class=\"hw\">Tralles<SUP>2</SUP></div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トラッレス《Illyria の一部族》.</div>\r\n","<div class=\"hw\">Trallis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">=<a href=\"entry://Trallēs\">Tralles<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">Tralliānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tralles<SUP>1</SUP> の.</div><div class=\"hw2\"><b>Tralliānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Tralles<SUP>1</SUP> の住民.</div>\r\n","<div class=\"hw\">Trallēs<SUP>1</SUP></div><div class=\"pos\">-ium, <i>f pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トラッレース, <SUP>*</SUP>-レイス《Lydia の Maeander 川近くの町》.</div>\r\n","<div class=\"hw\">tranquillitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[tranquillus]</div><div class=\"def\"><num>①</num> 海[風]が穏やかなこと;好天.</div><div class=\"def\"><num>②</num> (航行を妨げる)凪<SUB>なぎ</SUB>, 無風.</div><div class=\"def\"><num>③</num> 平静, 平安.</div>\r\n","<div class=\"hw\">tranquillum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tranquillus\">tranquillus</a>]</div><div class=\"def\"><num>①</num> 穏やかな海;好天.</div><div class=\"def\"><num>②</num> 平穏, 落ちつき.</div>\r\n","<div class=\"hw\">tranquillus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> (海・天候などが)穏やかな.</div><div class=\"def\"><num>②</num> 平静な, 落ちついた.</div><div class=\"def\"><num>③</num> 静かな, 平穏な.</div>\r\n","<div class=\"hw\">tranquillē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tranquillus]</div><div class=\"def\">静かに, 穏やかに.</div>\r\n","<div class=\"hw\">tranquillō<SUP>1</SUP></div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"def\">=<a href=\"entry://tranquillē\">tranquille</a>.</div><hr><div class=\"hw\">tranquillō<SUP>2</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[tranquillus]</div><div class=\"def\">静める, 落ちつかせる.</div>\r\n","<div class=\"hw\">trans</div><div class=\"pos\"><i>prep</i>, <i>adv</i></div><div class=\"ori\">[<i>cf. </i> tero]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>prep</i>)〈+<i>acc</i>〉 ...を越えて, ...を通って向こうに</div><div class=\"ex\"><i>qui ～ mare currunt</i> (<author>H<small>OR</small></author>)<span class=\"ext\">海のかなたへと駆け出す人々</span></div><div class=\"ex\"><i>qui ～ Rhenum incolunt</i> (<author>C<small>AES</small></author>)<span class=\"ext\">Rhenus 川の向こう側に住む人々.</span></div><div class=\"def\"><num0>Ⅱ</num0> (<i>adv</i>)向こう[反対]側に.</div>\r\n","<div class=\"hw\">trans-</div><div class=\"pos\"><i>pref</i></div><div class=\"ori\">[↑<a href=\"entry://trans\">trans</a>]</div><div class=\"def\">意味は <a href=\"entry://trans\">trans</a> を参照(有声子音の前ではしばしば trā-).</div>\r\n","<div class=\"hw\">transabeō</div><div class=\"pos\">-īre -iī -itum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[↑<a href=\"entry://trans-\">trans-</a>/abeo]</div><div class=\"def\">越えて[通って, 向こうへ]行く</div><div class=\"ex\"><i>ensis transabiit costas</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">剣があばら骨を刺し貫いた.</span></div>\r\n","<div class=\"hw\">transabitus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transabeō\">transabeo</a>.</div>\r\n","<div class=\"hw\">transabiī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transabeō\">transabeo</a>.</div>\r\n","<div class=\"hw\">transabīre</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://transabeō\">transabeo</a>.</div>\r\n","<div class=\"hw\">transactiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[transigo]</div><div class=\"def\"><num>①</num> 和解, 示談.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 契約, 取引.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 完成[終了]すること.</div>\r\n","<div class=\"hw\">transactor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[transigo]</div><div class=\"def\">代理人, 代行者.</div>\r\n","<div class=\"hw\">transactus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transigō\">transigo</a>.</div>\r\n","<div class=\"hw\">transadactus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transadigō\">transadigo</a>.</div>\r\n","<div class=\"hw\">transadigō</div><div class=\"pos\">-ere -adēgī -adactum, <i>tr</i></div><div class=\"ori\">[trans-/adigo]</div><div class=\"def\">刺し通す, 突き刺す.</div>\r\n","<div class=\"hw\">transadēgī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transadigō\">transadigo</a>.</div>\r\n","<div class=\"hw\">Transalpibus</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">Alpes の向こうから.</div>\r\n","<div class=\"hw\">Transalpicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://Transalpīnus\">Transalpinus</a>.</div>\r\n","<div class=\"hw\">Transalpīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Alpes の向こう側の.</div><div class=\"hw2\"><b>Transalpīnī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Alpes の向こう側の住民.</div>\r\n","<div class=\"hw\">transbibō</div><div class=\"pos\">-ere, <SUP>◇</SUP><i>tr</i></div><div class=\"def\">飲み尽くす, 飲みほす.</div>\r\n","<div class=\"hw\">transbītō</div><div class=\"pos\">-ere, <i>intr</i></div><div class=\"def\">こちらに来る.</div>\r\n","<div class=\"hw\">transcendentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[transcendo]</div><div class=\"def\">議論の筋道を他へ移すこと.</div>\r\n","<div class=\"hw\">transcendentālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[transcendo]</div><div class=\"def\">〘哲〙超越的な.</div>\r\n","<div class=\"hw\">transcendī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transcendō\">transcendo</a>.</div>\r\n","<div class=\"hw\">transcendō</div><div class=\"pos\">-ere -endī -ensum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[trans-/scando]</div><div class=\"def\"><num>①</num> 登り越える, 向こう側へ行く, 渡る.</div><div class=\"def\"><num>②</num> (境界・規則などを)踏み越える, 違反する</div><div class=\"ex\"><i>transcendere fines juris</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">法の限度を越える.</span></div><div class=\"def\"><num>③</num> 超える, 上回る.</div><div class=\"def\"><num>④</num> 抜かす, 省く, 飛ばす.</div><div class=\"def\"><num>⑤</num> (<i>intr</i>)(話題が)移る, 移行する.</div>\r\n","<div class=\"hw\">transcensiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://transcendō\">transcendō</a>]</div><div class=\"def\"><num>①</num> 踏み越えること;違反.</div><div class=\"def\"><num>②</num> (ユダヤ教の)過越しの祝い.</div><div class=\"def\"><num>③</num> 〘修〙転置法(=<a href=\"entry://hyperbaton\">hyperbaton</a>).</div>\r\n","<div class=\"hw\">transcensus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transcendō\">transcendo</a>.</div><hr><div class=\"hw\">transcensus<SUP>2</SUP></div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"def\"><num>①</num> 登ること.</div><div class=\"def\"><num>②</num> (川の)渡り場, 渡し.</div><div class=\"def\"><num>③</num> 移り変わり, 変化.</div><div class=\"def\"><num>④</num> 〘修〙転位, 転置.</div>\r\n","<div class=\"hw\">transcripsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transcrībō\">transcribo</a>.</div>\r\n","<div class=\"hw\">transcriptiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[transcribo]</div><div class=\"def\"><num>①</num> <SUP>◇</SUP> 書写, 転記.</div><div class=\"def\"><num>②</num> (所有権・負債などの)移転, 移動.</div>\r\n","<div class=\"hw\">transcriptus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transcrībō\">transcribo</a>.</div>\r\n","<div class=\"hw\">transcrībō</div><div class=\"pos\">-ere -scripsī -scriptum, <i>tr</i></div><div class=\"ori\">[trans-/scribo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 書き写す, 転記する;(絵画を)模写する.</div><div class=\"def\"><num>②</num> 偽造する.</div><div class=\"def\"><num>③</num> 移す, 移し替える</div><div class=\"ex\"><i>alci spatium vitae transcribere</i> (<author>O<small>V</small></author>)<span class=\"ext\">ある人に寿命を移し替える.</span></div><div class=\"def\"><num>④</num> 移籍[移管]する;登録する</div><div class=\"ex\"><i>transcribere matres urbi</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">母親たちを町(の住民名簿)に載せる.</span></div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP> 刻み込む.</div>\r\n","<div class=\"hw\">transcucurrī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">=<a href=\"entry://transcurrī\">transcurri</a>(⇒ <a href=\"entry://transcurrō\">transcurro</a>).</div>\r\n","<div class=\"hw\">transcurrī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transcurrō\">transcurro</a>.</div>\r\n","<div class=\"hw\">transcurrō</div><div class=\"pos\">-ere -currī [-cucurrī] -cursum, <i>intr</i>, <i>tr</i></div><div class=\"def\"><num>①</num> 向こう(側)へ走る[駆けて行く].</div><div class=\"def\"><num>②</num> 急いで通過する[越える]</div><div class=\"ex\"><i>caelum transcurrit nimbus</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">黒雲が天空を漂い渡る.</span></div><div class=\"def\"><num>③</num> 素早く変わる[移る].</div><div class=\"def\"><num>④</num> (時が)(早く)過ぎ去る;(一定の期間を)過ごす, 終える.</div><div class=\"def\"><num>⑤</num> 手短かに論じる;ざっと読む.</div>\r\n","<div class=\"hw\">transcursiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://transcurrō\">transcurrō</a>]</div><div class=\"def\"><num>①</num> すばやく通り過ぎること.</div><div class=\"def\"><num>②</num> 手短かに論ずること.</div><div class=\"def\"><num>③</num> (時の)経過.</div>\r\n","<div class=\"hw\">transcursus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transcurrō\">transcurro</a>.</div><hr><div class=\"hw\">transcursus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> すばやく通り過ぎる[走り抜ける]こと.</div><div class=\"def\"><num>②</num> 手短かに論ずること, 簡単な言及.</div>\r\n","<div class=\"hw\">transcursōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[transcurro]</div><div class=\"def\">ぞんざいな, 皮相の.</div>\r\n","<div class=\"hw\">transcīdī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transcīdō\">transcido</a>.</div>\r\n","<div class=\"hw\">transcīdō</div><div class=\"pos\">-ere -cīdī, <i>tr</i></div><div class=\"ori\">[trans-/caedo]</div><div class=\"def\"><num>①</num> めった打ちにする.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 貫く, 貫通する.</div>\r\n","<div class=\"hw\">Transdānubiānus, -viānus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">Danubius 川対岸の.</div><div class=\"hw2\"><b>Transdānubiānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">《碑》Danubius 川対岸に住む人々.</div>\r\n","<div class=\"hw\">transenna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 捕鳥網;罠<SUB>わな</SUB>.</div><div class=\"def\"><num>②</num> 格子(窓).</div>\r\n","<div class=\"hw\">transeō</div><div class=\"pos\">-īre -iī [-īvī] -itum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[trans-/eo<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> (ある場所から他へ)行く, 渡る</div><div class=\"ex\"><i>plebs in Sacrum Montem ex Aventino transit</i> (<author>L<small>IV</small></author>)<span class=\"ext\">平民は Aventinus の丘から聖山へ移動する</span></div><div class=\"ex\"><i>mare hieme transire</i> (<author>C<small>IC</small></author>)<span class=\"ext\">冬に渡航する.</span></div><div class=\"def\"><num>②</num> 通り過ぎる, 通過する.</div><div class=\"def\"><num>③</num> 追いつく, 追い越す.</div><div class=\"def\"><num>④</num> (権利・状態などが)移る, 転ずる</div><div class=\"ex\"><i>terror ad hostes transit</i> (<author>L<small>IV</small></author>)<span class=\"ext\">(今度は)敵が恐怖に陥る番だ.</span></div><div class=\"def\"><num>⑤</num> 寝返る, 乗り換える</div><div class=\"ex\"><i>ad Pompeium transierunt</i> (<author>C<small>AES</small></author>)<span class=\"ext\">彼らは Pompeius のもとへ脱走した.</span></div><div class=\"def\"><num>⑥</num> 変わる, 変化する;変容する.</div><div class=\"def\"><num>⑦</num> ...よりまさる, しのぐ.</div><div class=\"def\"><num>⑧</num> (基準・限度などを)越える</div><div class=\"ex\"><i>verecundiae fines transire</i> (<author>C<small>IC</small></author>)<span class=\"ext\">慎しみの一線を踏み越える.</span></div><div class=\"def\"><num>⑨</num> 無視する, 省く;簡単に論じる.</div><div class=\"def\"><num>⑩</num> 消え去る, なくなる.</div><div class=\"def\"><num>⑪</num> (時が)過ぎ(去)る;(時を)過ごす.</div>\r\n","<div class=\"hw\">transferre</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://transferō\">transfero</a>.</div>\r\n","<div class=\"hw\">transferō, trāferō</div><div class=\"pos\">-ferre -tulī -lātum, <i>tr</i></div><div class=\"def\"><num>①</num> (ある場所から他へ)運ぶ, 移送する.</div><div class=\"def\"><num>②</num> 場所を変える, 動かす, 移す;移植する</div><div class=\"ex\"><i>in Celtiberiam bellum transferre</i> (<author>C<small>AES</small></author>)<span class=\"ext\">Celtiberia へ戦場を移す</span></div><div class=\"ex\">(2個の <i>acc</i> と)<i>concilium Lutetiam Parisiorum transfert</i> (<author>C<small>AES</small></author>)<span class=\"ext\">彼は会議の場を Parisii 族の町 Lutetia に変更する.</span></div><div class=\"def\"><num>③</num> (所有権・支配権などを)移譲する;(責任などを)転嫁する;(役割などを)移し替える.</div><div class=\"def\"><num>④</num> (別の用途に)転用する, 充てる.</div><div class=\"def\"><num>⑤</num> (新しい局面に)注意[関心]を振り向けさせる</div><div class=\"ex\"><i>ut se ad aliud studium transferat admonebo</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私は彼が他の(分野の)研究に専念するよう忠告するだろう.</span></div><div class=\"def\"><num>⑥</num> 書き写す, 転写する.</div><div class=\"def\"><num>⑦</num> 翻訳する.</div><div class=\"def\"><num>⑧</num> 比喩的に用いる.</div><div class=\"def\"><num>⑨</num> 延期する, 先送りする.</div><div class=\"def\"><num>⑩</num> 変える, 変容させる.</div><div class=\"def\"><num>⑪</num> <SUP>◇</SUP>(<i>pass</i>)死ぬ.</div>\r\n","<div class=\"hw\">transfictiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[transfingo]</div><div class=\"def\"><num>①</num> 偽造, 捏造<SUB>ねつぞう</SUB>.</div><div class=\"def\"><num>②</num> 〘文〙語形変異(=<a href=\"entry://metaplasmus\">metaplasmus</a>).</div>\r\n","<div class=\"hw\">transfigūrābilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[transfiguro]</div><div class=\"def\">変容することのできる.</div>\r\n","<div class=\"hw\">transfigūrātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[transfiguro]</div><div class=\"def\"><num>①</num> 変容.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(キリストの)変容.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘カト〙変容の祝日(8月6日).</div>\r\n","<div class=\"hw\">transfigūrātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://transfigūrō\">transfigūrō</a>]</div><div class=\"def\">変容させる人</div><div class=\"ex\"><i>sui ～</i> (<author>T<small>ERT</small></author>)<span class=\"ext\">偽善者.</span></div>\r\n","<div class=\"hw\">transfigūrō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\"><num>①</num> 姿形[性状]を変える, 変容させる.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(<i>refl</i>)ふりをする, 装う 〈in+<i>acc</i>〉.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> たとえて[あてはめて]話す.</div>\r\n","<div class=\"hw\">transfingō</div><div class=\"pos\">-ere, <SUP>◇</SUP><i>tr</i></div><div class=\"def\">(<i>refl</i>)ふりをする, 装う.</div>\r\n","<div class=\"hw\">transfixiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[transfigo]</div><div class=\"def\">(釘を)打ち込むこと.</div>\r\n","<div class=\"hw\">transfixus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transfīgō\">transfigo</a>.</div>\r\n","<div class=\"hw\">transfixī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transfīgō\">transfigo</a>.</div>\r\n","<div class=\"hw\">transfluvium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">渡河.</div>\r\n","<div class=\"hw\">transfluviālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">川の向こうに住んでいる.</div>\r\n","<div class=\"hw\">transfluviō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"def\">川を渡る, 渡河する.</div>\r\n","<div class=\"hw\">transfluxī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transfluō\">transfluo</a>.</div>\r\n","<div class=\"hw\">transfluō</div><div class=\"pos\">-ere -fluxī, <i>intr</i></div><div class=\"def\"><num>①</num> 横切って[越えて]流れる;貫流する.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(時が)流れる, 経過する.</div>\r\n","<div class=\"hw\">transfodere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://transfodiō\">transfodio</a>.</div>\r\n","<div class=\"hw\">transfodiō</div><div class=\"pos\">-dere -fōdī -fossum, <i>tr</i></div><div class=\"def\"><num>①</num> 反対側まで掘り抜く.</div><div class=\"def\"><num>②</num> 突き[刺し]通す.</div>\r\n","<div class=\"hw\">transformis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://transformō\">transformō</a>]</div><div class=\"def\">変身することのできる.</div>\r\n","<div class=\"hw\">transformātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[transformo]</div><div class=\"def\">変形, 変貌<SUB>へんぼう</SUB>;(キリストの)変容, 変身.</div>\r\n","<div class=\"hw\">transformō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\">変身[変容]させる, 変える.</div>\r\n","<div class=\"hw\">transforātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[transforo]</div><div class=\"def\">穴があいていること</div><div class=\"ex\"><i>transforationis partes</i> (<author>C<small>AEL</small> A<small>UR</small></author>)<span class=\"ext\">(人体の)開口部位(=目, 鼻, 耳, 肛門).</span></div>\r\n","<div class=\"hw\">transforō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\">貫く, 刺し[突き]通す.</div>\r\n","<div class=\"hw\">transfossus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transfodiō\">transfodio</a>.</div>\r\n","<div class=\"hw\">transfretānus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">海の向こうからの.</div>\r\n","<div class=\"hw\">transfretātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://transfretō\">transfretō</a>]</div><div class=\"def\">海峡を渡ること.</div>\r\n","<div class=\"hw\">transfretō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[trans-/fretum]</div><div class=\"def\"><num>①</num> 海を渡る, 渡航する.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 渡す, 渡らせる.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>(時を)過ごす.</div>\r\n","<div class=\"hw\">transfuga</div><div class=\"pos\">-ae, <i>m</i>(<i>f</i>)</div><div class=\"ori\">[transfugio]</div><div class=\"def\"><num>①</num> 敵に寝返る者, 裏切り者;逃亡者.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 背教[棄教]者.</div>\r\n","<div class=\"hw\">transfugere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://transfugiō\">transfugio</a>.</div>\r\n","<div class=\"hw\">transfugitus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transfugiō\">transfugio</a>.</div>\r\n","<div class=\"hw\">transfugium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[transfugio]</div><div class=\"def\">脱走;寝返り.</div>\r\n","<div class=\"hw\">transfugiō</div><div class=\"pos\">-gere -fūgī -fugitum, <i>intr</i>, <i>tr</i></div><div class=\"def\"><num>①</num> 寝返る, 裏切る.</div><div class=\"def\"><num>②</num> 逃れる 〈+<i>acc</i>〉.</div>\r\n","<div class=\"hw\">transfunctōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[transfungor]</div><div class=\"def\">おざなりの, ぞんざいな.</div>\r\n","<div class=\"hw\">transfundō</div><div class=\"pos\">-ere -fūdī -fūsum, <i>tr</i></div><div class=\"def\"><num>①</num> (別の容器へ)注ぎ移す, 移し替える.</div><div class=\"def\"><num>②</num> (気持などを)移す.</div><div class=\"def\"><num>③</num> (<i>pass</i>)注ぐ, 流れ込む.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 翻訳する.</div>\r\n","<div class=\"hw\">transfungor</div><div class=\"pos\">-gī, <i>intr dep</i></div><div class=\"def\">《碑》休みなく...を楽しむ 〈+<i>abl</i>〉.</div>\r\n","<div class=\"hw\">transfungī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://transfungor\">transfungor</a>.</div>\r\n","<div class=\"hw\">transfīgō</div><div class=\"pos\">-ere -fixī -fixum, <i>tr</i></div><div class=\"def\">突き通す, 貫く.</div>\r\n","<div class=\"hw\">transfōdī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transfodiō\">transfodio</a>.</div>\r\n","<div class=\"hw\">transfūdī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transfundō\">transfundo</a>.</div>\r\n","<div class=\"hw\">transfūgī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transfugiō\">transfugio</a>.</div>\r\n","<div class=\"hw\">transfūmō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"def\">煙となって[のように]吐き出される.</div>\r\n","<div class=\"hw\">transfūsiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[transfundo]</div><div class=\"def\"><num>①</num> (別の容器への)注ぎ移し, 移し替え.</div><div class=\"def\"><num>②</num> 混交, 混血.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘法〙(負債の)転移.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>(光が世界のすみずみにまで)行きわたること.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘医〙輸血.</div>\r\n","<div class=\"hw\">transfūsus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transfundō\">transfundo</a>.</div>\r\n","<div class=\"hw\">transgerō</div><div class=\"pos\">-ere, <i>tr</i></div><div class=\"def\">運び移す, 移動させる.</div>\r\n","<div class=\"hw\">transgredior</div><div class=\"pos\">-dī -gressus sum, <i>tr</i>, <i>intr dep</i></div><div class=\"ori\">[trans-/gradior]</div><div class=\"def\"><num>①</num> ...の側<SUB>がわ</SUB>へと(歩いて)行く, 越える, 渡る 〈+<i>acc</i>;in [ad]+<i>acc</i>〉</div><div class=\"ex\"><i>amnem Araxem ponte transgredi</i> (<author>T<small>AC</small></author>)<span class=\"ext\">Araxes 川に橋をかけて渡る</span></div><div class=\"ex\"><i>Galli in Italiam transgressi</i> (<author>L<small>IV</small></author>)<span class=\"ext\">(Alpes 山脈を越えて)Italia に入ってきた Gallia 人たち.</span></div><div class=\"def\"><num>②</num> (別の党派などへ)移る, 乗り換える, つく 〈in [ad]+<i>acc</i>〉.</div><div class=\"def\"><num>③</num> 変わる, 変化する.</div><div class=\"def\"><num>④</num> (新しい題目に)移行する.</div><div class=\"def\"><num>⑤</num> (限度などを)踏み越える.</div><div class=\"def\"><num>⑥</num> まさる, しのぐ.</div><div class=\"def\"><num>⑦</num> (話題を)簡単に扱う, とばす.</div><div class=\"def\"><num>⑧</num> <SUP>◇</SUP> 罪を犯す.</div>\r\n","<div class=\"hw\">transgredī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://transgredior\">transgredior</a>.</div>\r\n","<div class=\"hw\">transgressiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://transgredior\">transgredior</a>]</div><div class=\"def\"><num>①</num> 越える[渡る]こと.</div><div class=\"def\"><num>②</num> (別の話題へ)移ること.</div><div class=\"def\"><num>③</num> 〘修〙転置(法)(=<a href=\"entry://hyperbaton\">hyperbaton</a>).</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>(法を)犯すこと.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>(神への)罪.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP> 背教.</div><div class=\"def\"><num>⑦</num> <SUP>◇</SUP> 苦難.</div>\r\n","<div class=\"hw\">transgressor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[transgredior]</div><div class=\"def\">(神の法の)違反者, 罪人<SUB>つみびと</SUB>.</div>\r\n","<div class=\"hw\">transgressus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transgredior\">transgredior</a>.</div><hr><div class=\"hw\">transgressus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">渡ること, 渡河.</div>\r\n","<div class=\"hw\">transiciō</div><div class=\"pos\">-cere, <i>tr</i></div><div class=\"def\">=<a href=\"entry://transjiciō\">transjicio</a>(⇒ <a href=\"entry://trājiciō\">trajicio</a>).</div>\r\n","<div class=\"hw\">transigō</div><div class=\"pos\">-ere -ēgī -actum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[trans-/ago]</div><div class=\"def\"><num>①</num> (武器を)突き刺す;(武器で)刺し貫く.</div><div class=\"def\"><num>②</num> (最後まで)やり遂げる, 終わらせる.</div><div class=\"def\"><num>③</num> (交渉などを)まとめる, (紛争などを)解決する;(<i>intr</i>)まとまる, 片づく 〈cum alqo;de alqo;cum re〉</div><div class=\"ex\"><i>me absente omnia cum illis transigi malo</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私がいない間にすべてが彼らとの交渉で決着してほしいものだ</span></div><div class=\"ex\">(impers pass)<i>cum spe votoque uxoris semel transigitur</i> (<author>T<small>AC</small></author>)<span class=\"ext\">(未婚女性が)妻となる望みと誓いはただ一度しか許されない(=一度で相手が決められてしまう).</span></div><div class=\"def\"><num>④</num> 〘法〙互譲によって示談にする, 妥協する.</div><div class=\"def\"><num>⑤</num> (時を)過ごす.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP> 支える, 維持する.</div><div class=\"def\"><num>⑦</num> <SUP>◇</SUP> 処分する, 売却する.</div>\r\n","<div class=\"hw\">transiliō, transsiliō</div><div class=\"pos\">-īre -uī [-īvī, -iī], <i>tr</i>, <i>intr</i></div><div class=\"ori\">[trans-/salio<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 跳び越える, 跳び移る 〈+<i>acc</i>;in+<i>acc</i>〉.</div><div class=\"def\"><num>②</num> 無視する, とばす.</div><div class=\"def\"><num>③</num> (限界などを)越える</div><div class=\"ex\"><i>transilire munera Liberi</i> (<author>H<small>OR</small></author>)<span class=\"ext\">Liber(=<a href=\"entry://Bacchus\">Bacchus</a>)の贈り物(=ぶどう酒)の程を過ごす(=乱飲する).</span></div>\r\n","<div class=\"hw\">transiluī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transiliō\">transilio</a>.</div>\r\n","<div class=\"hw\">transilīvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">=<a href=\"entry://transiluī\">transilui</a>(⇒ <a href=\"entry://transiliō\">transilio</a>).</div>\r\n","<div class=\"hw\">transitiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[transeo]</div><div class=\"def\"><num>①</num> 通り過ぎること;移動.</div><div class=\"def\"><num>②</num> 通路.</div><div class=\"def\"><num>③</num> (敵方に)寝返ること, 裏切り.</div><div class=\"def\"><num>④</num> (階級を)移ること, 転籍.</div><div class=\"def\"><num>⑤</num> 話頭を転ずること.</div><div class=\"def\"><num>⑥</num> 感染, 伝染.</div><div class=\"def\"><num>⑦</num> 〘文〙(格変化に伴う)語形の変化.</div><div class=\"def\"><num>⑧</num> <SUP>◇</SUP>〘文〙関係.</div><div class=\"def\"><num>⑨</num> <SUP>◇</SUP> 死.</div>\r\n","<div class=\"hw\">transitor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[transeo]</div><div class=\"def\">通りがかりの人, 通り過ぎる人.</div>\r\n","<div class=\"hw\">transitus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transeō\">transeo</a>.</div><hr><div class=\"hw\">transitus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 渡る[越える]こと, 横断.</div><div class=\"def\"><num>②</num> 通り過ぎること, 通過</div><div class=\"ex\"><i>in transitu</i> (<author>T<small>AC</small></author>)<span class=\"ext\">途中で.</span></div><div class=\"def\"><num>③</num> 通り道, 通路</div><div class=\"ex\"><i>～ spiritūs</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">気管.</span></div><div class=\"def\"><num>④</num> 寝返り, 裏切り.</div><div class=\"def\"><num>⑤</num> 移り変わり, 変化;転換</div><div class=\"ex\"><i>～ rerum</i> (<author>T<small>AC</small></author>)<span class=\"ext\">改変.</span></div><div class=\"def\"><num>⑥</num> 話頭を転ずること.</div><div class=\"def\"><num>⑦</num> 〘文〙語形変化, 活用.</div><div class=\"def\"><num>⑧</num> <SUP>◇</SUP> 出発.</div><div class=\"def\"><num>⑨</num> <SUP>◇</SUP> 死.</div>\r\n","<div class=\"hw\">transitīvus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[transeo]</div><div class=\"def\">〘文〙他動詞の.</div>\r\n","<div class=\"hw\">transitīvē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://transitīvus\">transitīvus</a>]</div><div class=\"def\">〘文〙他動詞的に[として].</div>\r\n","<div class=\"hw\">transitōrium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://transitōrius\">transitōrius</a>]</div><div class=\"def\">《碑》通路, 通り道.</div>\r\n","<div class=\"hw\">transitōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[transeo]</div><div class=\"def\"><num>①</num> 通路の[となる].</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> はかない, 束<SUB>つか</SUB>の間の.</div>\r\n","<div class=\"hw\">transitōriē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[transitorius]</div><div class=\"def\">ついでに;ざっと.</div>\r\n","<div class=\"hw\">transiī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transeō\">transeo</a>.</div>\r\n","<div class=\"hw\">transjiciō</div><div class=\"pos\">-cere, <i>tr</i></div><div class=\"def\">=<a href=\"entry://trājiciō\">trajicio</a>.</div>\r\n","<div class=\"hw\">transjugō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"def\">(牛・馬などを)別の軛<SUB>くびき</SUB>にかける.</div>\r\n","<div class=\"hw\">transjungō</div><div class=\"pos\">-ere, <SUP>◇</SUP><i>tr</i></div><div class=\"def\">軛にかける2頭のラバの左右を入れ替える.</div>\r\n","<div class=\"hw\">translapsus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://translābor\">translabor</a>.</div>\r\n","<div class=\"hw\">translegō<SUP>2</SUP></div><div class=\"pos\">-ere, <i>tr</i></div><div class=\"def\">(人に)読んで聞かせる.</div>\r\n","<div class=\"hw\">transloquor, trāl-</div><div class=\"pos\">-quī, <i>tr dep</i></div><div class=\"def\">一部始終を語る, すっかり話す.</div>\r\n","<div class=\"hw\">transloquī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://transloquor\">transloquor</a>.</div>\r\n","<div class=\"hw\">translābor</div><div class=\"pos\">-bī -lapsus sum, <SUP>◇</SUP><i>tr dep</i></div><div class=\"def\">...の上を(すべるように)飛び過ぎる.</div>\r\n","<div class=\"hw\">translābī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://translābor\">translabor</a>.</div>\r\n","<div class=\"hw\">translātiō, trāl-</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[transfero]</div><div class=\"def\"><num>①</num> 運ぶこと, 移送.</div><div class=\"def\"><num>②</num> 移すこと, 移動.</div><div class=\"def\"><num>③</num> 移植, 接ぎ木.</div><div class=\"def\"><num>④</num> 移管, 移譲.</div><div class=\"def\"><num>⑤</num> (罪・責任の)転嫁.</div><div class=\"def\"><num>⑥</num> (語の)転用;転義, 比喩(的用法).</div><div class=\"def\"><num>⑦</num> <SUP>◇</SUP>〘文〙音位[字位]転換(=<a href=\"entry://metathesis\">metathesis</a>).</div><div class=\"def\"><num>⑧</num> 翻訳.</div><div class=\"def\"><num>⑨</num> <SUP>◇</SUP>(魂の)転生, 輪廻.</div><div class=\"def\"><num>⑩</num> <SUP>◇</SUP> 死.</div>\r\n","<div class=\"hw\">translātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[transfero]</div><div class=\"def\"><num>①</num> 譲渡する人.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 翻訳者.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 転写する人.</div>\r\n","<div class=\"hw\">translātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transferō\">transfero</a>.</div><hr><div class=\"hw\">translātus<SUP>2</SUP>, trāl-</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> (ある物を誇示する)行列, 行進.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 運搬.</div>\r\n","<div class=\"hw\">translātīcius, trāl-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[translatus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 伝統的な, 慣例の.</div><div class=\"def\"><num>②</num> 普通の, ふだんの.</div><div class=\"def\"><num>③</num> (ことばが)転じた, 転義した.</div>\r\n","<div class=\"hw\">translātīciē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://translātīcius\">translātīcius, trāl-</a>]</div><div class=\"def\">ぞんざいに, なげやりに.</div>\r\n","<div class=\"hw\">translātīva</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[translativus]</div><div class=\"def\">〘修〙換喩的転義(=<a href=\"entry://metalepsis\">metalepsis</a>).</div>\r\n","<div class=\"hw\">translātīvus, trāl-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[transfero]</div><div class=\"def\"><num>①</num> (異議申し立てに伴う)訴訟手続き・弁論などの変更に関する.</div><div class=\"def\"><num>②</num> 通常の, 慣例の.</div>\r\n","<div class=\"hw\">translātīvē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://translātīvus\">translātīvus, trāl-</a>]</div><div class=\"def\">〘修〙転義的に, 比喩的に.</div>\r\n","<div class=\"hw\">translēgō<SUP>1</SUP></div><div class=\"pos\">-āre -āvī, <SUP>◇</SUP><i>tr</i></div><div class=\"def\">遺言で譲る, 遺贈する.</div>\r\n","<div class=\"hw\">translūceō, trāl-</div><div class=\"pos\">-ēre, <i>intr</i></div><div class=\"def\"><num>①</num> (映像が)反射する.</div><div class=\"def\"><num>②</num> (水・薄衣などを通して)光って[輝いて]見える.</div><div class=\"def\"><num>③</num> 透けて見える, 透明である.</div>\r\n","<div class=\"hw\">translūcidus, trāl-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">澄んだ, 透き通った, 透明な.</div>\r\n","<div class=\"hw\">translūcānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[trans-/lucus]</div><div class=\"def\">《碑》森の向こう側にある.</div>\r\n","<div class=\"hw\">transmarīnus, trām-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[trans-/mare]</div><div class=\"def\"><num>①</num> 海を渡って来る, 舶来の</div><div class=\"ex\"><i>politissima doctrina transmarina</i> (<author>C<small>IC</small></author>)<span class=\"ext\">きわめて洗練された海外(=ギリシア)からの文化.</span></div><div class=\"def\"><num>②</num> 海外(で)の, 海外にある.</div>\r\n","<div class=\"hw\">transmeābilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[transmeo]</div><div class=\"def\">通過[横断]することのできる.</div>\r\n","<div class=\"hw\">transmeātōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://transmeō\">transmeō, trām-</a>]</div><div class=\"def\">通過[横断]に関する.</div>\r\n","<div class=\"hw\">transmeō, trām-</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"def\">通過する, 横断する.</div>\r\n","<div class=\"hw\">transmigrātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://transmigrō\">transmigrō, trām-</a>]</div><div class=\"def\"><num>①</num> 移住;亡命;虜囚.</div><div class=\"def\"><num>②</num> (霊魂の)転生.</div>\r\n","<div class=\"hw\">transmigrō, trām-</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"def\"><num>①</num> 移住する;居所を変えて住む.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 移住させる.</div>\r\n","<div class=\"hw\">transmineō</div><div class=\"pos\">-ēre, <i>intr</i></div><div class=\"def\">反対側へ突き出る.</div>\r\n","<div class=\"hw\">transmissiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[transmitto]</div><div class=\"def\"><num>①</num> 渡航.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(税の)支払い.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>(罪・責任の)転嫁.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>(遺産の)相続.</div>\r\n","<div class=\"hw\">transmissor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[transmitto]</div><div class=\"def\">(罪を)運び去ってくれる者(=贖罪<SUB>しょくざい</SUB>のヤギ).</div>\r\n","<div class=\"hw\">transmissus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transmittō\">transmitto</a>.</div><hr><div class=\"hw\">transmissus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 渡航, 横断.</div><div class=\"def\"><num>②</num> 遺贈, 相続.</div>\r\n","<div class=\"hw\">transmittō, trām-</div><div class=\"pos\">-ere -mīsī -missum, <i>tr</i>, <i>intr</i></div><div class=\"def\"><num>①</num> 向こう側へ送る[行かせる], 横断[渡航]させる, 通過させる</div><div class=\"ex\"><i>magnam classem in Siciliam transmittere</i> (<author>L<small>IV</small></author>)<span class=\"ext\">大艦隊を Sicilia 島へ派遣する</span></div><div class=\"ex\"><i>ponte transmisso</i> (<author>S<small>UET</small></author>)<span class=\"ext\">橋をかけて.</span></div><div class=\"def\"><num>②</num> 渡る, 横断する, 通過する</div><div class=\"ex\"><i>equites adnantes equis transmisere</i> (<author>T<small>AC</small></author>)<span class=\"ext\">騎兵たちは馬にすがって泳いで(川を)渡った.</span></div><div class=\"def\"><num>③</num> (水・光・風などを)通す, 通らせる.</div><div class=\"def\"><num>④</num> (別の党派へ)移る, 鞍替えする.</div><div class=\"def\"><num>⑤</num> 手渡す;譲渡[贈与]する</div><div class=\"ex\"><i>poma intacta ore servis transmisit</i> (<author>T<small>AC</small></author>)<span class=\"ext\">(毒殺を恐れた彼女は)リンゴに口をつけず奴隷たちに手渡した.</span></div><div class=\"def\"><num>⑥</num> 託す, ゆだねる</div><div class=\"ex\"><i>huic hoc tantum bellum transmittere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼にこの大戦争を託す.</span></div><div class=\"def\"><num>⑦</num> (手をつけずに)放置する, 無視する</div><div class=\"ex\"><i>eam sententiam silentio, deinde oblivio transmisere</i> (<author>T<small>AC</small></author>)<span class=\"ext\">世間はその意見を(始めは)黙って聞き流し, やがては忘れた.</span></div><div class=\"def\"><num>⑧</num> (時を)過ごす, 費やす.</div><div class=\"def\"><num>⑨</num> 体験[経験]する;耐える.</div>\r\n","<div class=\"hw\">transmontānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[trans-/mons]</div><div class=\"def\">山の向こうにある[住む].</div>\r\n","<div class=\"hw\">transmoveō</div><div class=\"pos\">-ēre -mōvī -mōtum, <i>tr</i>, <i>intr</i></div><div class=\"def\"><num>①</num> (一地点から他へ)移動させる.</div><div class=\"def\"><num>②</num> (...の)せいにする</div><div class=\"ex\"><i>gloriam verbis in se transmovere</i> (<author>T<small>ER</small></author>)<span class=\"ext\">栄光をことば巧みにわがものとする.</span></div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 離れる, 遠ざかる.</div>\r\n","<div class=\"hw\">transmīsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transmittō\">transmitto</a>.</div>\r\n","<div class=\"hw\">transmōtus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transmoveō\">transmoveo</a>.</div>\r\n","<div class=\"hw\">transmūtātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://transmūtō\">transmūtō</a>]</div><div class=\"def\"><num>①</num> 字位[語順]転置.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 変化, 変形.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘修〙換喩.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>(霊魂の)転生.</div>\r\n","<div class=\"hw\">transmūtō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\">置き換える, 移し変える.</div>\r\n","<div class=\"hw\">transnatō, trān-</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"def\">向こう岸まで泳ぐ, 泳いで渡る.</div>\r\n","<div class=\"hw\">transnumerō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"def\">全部数える, 数え終える.</div>\r\n","<div class=\"hw\">transnāvigō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"def\"><num>①</num> 向こう岸まで航海する, 船で横断する.</div><div class=\"def\"><num>②</num> 船で通り過ぎる.</div>\r\n","<div class=\"hw\">transnō, trān-</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"def\"><num>①</num> 向こう岸まで泳ぐ, 泳いで渡る</div><div class=\"ex\"><i>in Tiberim desiluit et incolumis ad suos transnavit</i> (<author>L<small>IV</small></author>)<span class=\"ext\">彼は Tiberis 川に飛び込むと, 無事, 味方のいるところまで泳ぎ切った.</span></div><div class=\"def\"><num>②</num> (船で)渡る.</div><div class=\"def\"><num>③</num> 飛んで行く, 通過する 〈+<i>acc</i>;per+<i>acc</i>〉</div><div class=\"ex\"><i>Strymoniae grues aethera transnant</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">Strymon のツルが大空を飛んで行く.</span></div><div class=\"def\"><num>④</num> 一面に広がる, 行き渡る.</div>\r\n","<div class=\"hw\">transnōminō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\">...を...と改称する 〈+2個の <i>acc</i>〉.</div>\r\n","<div class=\"hw\">transnūbō</div><div class=\"pos\">-ere, <SUP>◇</SUP><i>intr</i></div><div class=\"def\">(女性が)夫を捨てて別の男性と結ばれる.</div>\r\n","<div class=\"hw\">transpadānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[trans/Padus]</div><div class=\"def\">Padus 川の向こう[北]側にある.</div>\r\n","<div class=\"hw\">transpectus, transs-</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[transpicio]</div><div class=\"def\">(開口部を通しての)眺め, 光景.</div>\r\n","<div class=\"hw\">transpicere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://transpiciō\">transpicio</a>.</div>\r\n","<div class=\"hw\">transpiciō, transs-</div><div class=\"pos\">-cere, <i>tr</i></div><div class=\"ori\">[trans-/specio]</div><div class=\"def\">(開口部の)向こう側を見る, 見通す.</div>\r\n","<div class=\"hw\">transplantō</div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"def\">移植する.</div>\r\n","<div class=\"hw\">transportātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://transportō\">transportō</a>]</div><div class=\"def\">移住させること.</div>\r\n","<div class=\"hw\">transportō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\"><num>①</num> (通例, 水路で)運ぶ, 渡す</div><div class=\"ex\"><i>duas legiones transportare</i> (<author>C<small>AES</small></author>)<span class=\"ext\">2個軍団を(アフリカへ)派遣する</span></div><div class=\"ex\">(2個の <i>acc</i> と)<i>milites navibus flumen transportat</i> (<author>C<small>AES</small></author>)<span class=\"ext\">彼は兵士たちを船橋で渡河させる.</span></div><div class=\"def\"><num>②</num> (強制的に)移送する, 移住させる.</div>\r\n","<div class=\"hw\">transpositus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transpōnō\">transpono</a>.</div>\r\n","<div class=\"hw\">transposuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transpōnō\">transpono</a>.</div>\r\n","<div class=\"hw\">transpōnō</div><div class=\"pos\">-ere -posuī -positum, <i>tr</i></div><div class=\"def\">位置を移す, 移動させる.</div>\r\n","<div class=\"hw\">transrhēnānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[trans/Rhenus]</div><div class=\"def\">Rhenus 川の向こう[東]側の.</div>\r\n","<div class=\"hw\">transs-</div><div class=\"def\">⇒<a href=\"entry://trans-\">trans-</a>.</div>\r\n","<div class=\"hw\">transtiberīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[trans/Tiberis]</div><div class=\"def\">Tiberis 川の向こう側にある[住んでいる].</div>\r\n","<div class=\"hw\">transtineō</div><div class=\"pos\">-ēre, <i>intr</i></div><div class=\"ori\">[trans-/teneo]</div><div class=\"def\">(横切って)通じている.</div>\r\n","<div class=\"hw\">transtrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 漕ぎ手席.</div><div class=\"def\"><num>②</num> 〘建〙大梁<SUB>おおはり</SUB>.</div>\r\n","<div class=\"hw\">transtulī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transferō\">transfero</a>.</div>\r\n","<div class=\"hw\">transubstantiātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[trans/substantia]</div><div class=\"def\">〘カト〙実体変化《ミサにおいて聖体のパンとぶどう酒がキリストの肉と血に変えられること》.</div>\r\n","<div class=\"hw\">transultō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[trans-/salto]</div><div class=\"def\">跳び移る.</div>\r\n","<div class=\"hw\">transumptiō, transs-</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://transūmō\">transūmō</a>]</div><div class=\"def\">(ギリシア語 ▷μετ<img class=\"font\" src=\"img/A146.png\">ληψι<img class=\"font\" src=\"img/A153.png\">◁ のラテン訳)⇒ <a href=\"entry://metalepsis\">metalepsis</a>.</div>\r\n","<div class=\"hw\">transumptīva</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://transumptiō\">transumptio</a>.</div>\r\n","<div class=\"hw\">transuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transuō\">transuo</a>.</div>\r\n","<div class=\"hw\">transuō</div><div class=\"pos\">-ere -suī -sūtum, <i>tr</i></div><div class=\"ori\">[trans-/suo]</div><div class=\"def\"><num>①</num> (治療のために針が体の一部を)刺し貫く.</div><div class=\"def\"><num>②</num> (とがった物が)突き刺す.</div><div class=\"def\"><num>③</num> (端から端まで)縫う.</div>\r\n","<div class=\"hw\">transvadō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"def\"><num>①</num> (浅瀬を)渡る.</div><div class=\"def\"><num>②</num> (無事に)通過する.</div>\r\n","<div class=\"hw\">transvectiō, trāv-</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[transveho]</div><div class=\"def\"><num>①</num> 渡河.</div><div class=\"def\"><num>②</num> 運搬, 輸送.</div><div class=\"def\"><num>③</num> (censor による騎士観閲時の)騎馬行進.</div>\r\n","<div class=\"hw\">transvectus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transvehō\">transveho</a>.</div>\r\n","<div class=\"hw\">transvectō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr freq</i></div><div class=\"ori\">[transveho]</div><div class=\"def\">運ぶ, 輸送する.</div>\r\n","<div class=\"hw\">transvectūrārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[transveho]</div><div class=\"def\">《碑》駄獣による荷物運送業者.</div>\r\n","<div class=\"hw\">transvehō, trāv-</div><div class=\"pos\">-ere -vexī -vectum, <i>tr</i></div><div class=\"def\"><num>①</num> 向こう側へ運ぶ, 渡す.</div><div class=\"def\"><num>②</num> (<i>pass</i>)渡る, 渡航する;(馬などに)乗って行く[進む].</div><div class=\"def\"><num>③</num> (<i>pass</i>)(物が)通り過ぎる, 横切る;(時が)過ぎ去る.</div><div class=\"def\"><num>④</num> (凱旋行進で)運んで通る.</div><div class=\"def\"><num>⑤</num> (<i>pass</i>)騎馬行進する(<i>cf. </i> transvectio 3).</div>\r\n","<div class=\"hw\">transvena</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[transvenio]</div><div class=\"def\">移住者, 外来者.</div>\r\n","<div class=\"hw\">transvendō</div><div class=\"pos\">-ere, <i>tr</i></div><div class=\"def\">《碑》売却する.</div>\r\n","<div class=\"hw\">transveniō</div><div class=\"pos\">-īre, <SUP>◇</SUP><i>intr</i></div><div class=\"def\">よそから来る.</div>\r\n","<div class=\"hw\">transverberātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://transverberō\">transverberō</a>]</div><div class=\"def\">刺し通す[貫く]こと.</div>\r\n","<div class=\"hw\">transverberō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\">刺し貫く, 突き刺す.</div>\r\n","<div class=\"hw\">transversa</div><div class=\"pos\"><i>adv</i>(<i>n pl acc</i>)</div><div class=\"def\">=<a href=\"entry://transversē\">transverse</a></div><div class=\"ex\"><i>～ tueri</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">横目で見る.</span></div>\r\n","<div class=\"hw\">transversim</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"def\">=<a href=\"entry://transversē\">transverse</a>.</div>\r\n","<div class=\"hw\">transversum<SUP>1</SUP>, trāv-</div><div class=\"pos\"><i>adv</i>(<i>n sg acc</i>)</div><div class=\"def\">=<a href=\"entry://transversē\">transverse</a>.</div><hr><div class=\"hw\">transversum<SUP>2</SUP>, trāv-</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://transversus\">transversus, trāv-</a>]</div><div class=\"def\">斜め, はす, 横(方向)</div><div class=\"ex\"><i>ex [de] transverso</i> (<author>C<small>IC</small></author>)<span class=\"ext\">横[脇]から;思いがけず, 不意に</span></div><div class=\"ex\"><i>in</i> ～ (<author>L<small>IV</small></author>)<span class=\"ext\">横[水平]に</span></div><div class=\"ex\"><i>per</i> ～ (<author>P<small>LIN</small></author>)<span class=\"ext\">横切って.</span></div>\r\n","<div class=\"hw\">transversus, trāv-</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[transverto]</div><div class=\"def\"><num>①</num> 斜めの, 交差する, 横断する</div><div class=\"ex\">～, <i>non proversus cedit, quasi cancer solet</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">あいつは真っすぐじゃなく, カニみたいに横歩きしている</span></div><div class=\"ex\"><i>transversa proelia</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">側面攻撃.</span></div><div class=\"def\"><num>②</num> </div><div class=\"ex\"><i>digitus ～</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">指の幅だけの長さ</span></div><div class=\"ex\"><i>unguis ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">爪の幅だけの長さ《いずれも長さの最小単位》.</span></div><div class=\"def\"><num>③</num> (正しい道・本筋を)踏みはずした, (わき道に)それた.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘解〙横の.</div>\r\n","<div class=\"hw\">transversālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[transversus]</div><div class=\"def\">〘解〙横の.</div>\r\n","<div class=\"hw\">transversāria, trāv-</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://transversārius\">transversārius, trāv-</a>]</div><div class=\"def\">横木, 横材.</div>\r\n","<div class=\"hw\">transversārius, trāv-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[transversus]</div><div class=\"def\">横に渡された, 横断する.</div>\r\n","<div class=\"hw\">transversē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[transversus]</div><div class=\"def\">斜めに, はすに, 横に, 横切って.</div>\r\n","<div class=\"hw\">transversō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"def\"><num>①</num> こね回す.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 渡る, 越える.</div>\r\n","<div class=\"hw\">transvertī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transvertō\">transverto</a>.</div>\r\n","<div class=\"hw\">transvertō, trāv-</div><div class=\"pos\">-ere -vertī -versum, <i>tr</i></div><div class=\"def\"><num>①</num> 変えて...にする.</div><div class=\"def\"><num>②</num> (<i>pass</i>)横切る.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 避ける, そらす.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 翻訳する.</div>\r\n","<div class=\"hw\">transvexī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transvehō\">transveho</a>.</div>\r\n","<div class=\"hw\">transvolitō</div><div class=\"pos\">-āre, <i>tr freq</i></div><div class=\"ori\">[↓<a href=\"entry://transvolō\">transvolō</a>]</div><div class=\"def\">突き抜けて飛ぶ.</div>\r\n","<div class=\"hw\">transvolō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"def\"><num>①</num> 横切って飛ぶ;飛んで越える.</div><div class=\"def\"><num>②</num> すばやく(通り)過ぎる, 突っ切る.</div><div class=\"def\"><num>③</num> 無視する;注意を引かない.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>(時が)早く過ぎ去る.</div>\r\n","<div class=\"hw\">transvorsum, trāv-</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://transversum\">transversum<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">transvorātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://transvorō\">transvorō</a>]</div><div class=\"def\"><num>①</num> 飲み下すこと, 嚥下<SUB>えんげ</SUB>.</div><div class=\"def\"><num>②</num> 喉<SUB>のど</SUB>;食道.</div>\r\n","<div class=\"hw\">transvorō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\"><num>①</num> <SUP>◇</SUP> 飲み下す, むさぼり食う.</div><div class=\"def\"><num>②</num> (財産を)蕩尽<SUB>とうじん</SUB>する, 使い果たす.</div>\r\n","<div class=\"hw\">transvāricō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"def\">大股<SUB>おおまた</SUB>で歩く.</div>\r\n","<div class=\"hw\">transēgī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://transigō\">transigo</a>.</div>\r\n","<div class=\"hw\">transīre</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://transeō\">transeo</a>.</div>\r\n","<div class=\"hw\">transūmō</div><div class=\"pos\">-ere, <i>tr</i></div><div class=\"ori\">[trans-/sumo]</div><div class=\"def\">取る, 受け取る.</div>\r\n","<div class=\"hw\">transūtus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://transuō\">transuo</a>.</div>\r\n","<div class=\"hw\">trapezium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘幾〙台形, 梯形<SUB>ていけい</SUB>.</div><div class=\"def\"><num>②</num> 境界標石.</div><div class=\"def\"><num>③</num> 〘解〙(手首の)大菱形骨.</div>\r\n","<div class=\"hw\">trapezius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://trapezium\">trapezium</a>]</div><div class=\"def\">〘解〙僧帽の.</div>\r\n","<div class=\"hw\">trapezophorum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テーブル[卓]の脚部《凝った装飾が施してある》.</div>\r\n","<div class=\"hw\">trapezīta</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">両替屋, 金貸し.</div>\r\n","<div class=\"hw\">Trapezūs</div><div class=\"pos\">-ūntis [-ūntos], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トラペズース《Pontus の町;現トルコ Trabzon》.</div>\r\n","<div class=\"hw\">trapizēum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘幾〙台形.</div>\r\n","<div class=\"hw\">trapētus</div><div class=\"pos\">-ī, <i>m</i>, <B>-um</B> -ī, <i>n</i>, <B>-es</B> -um, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">オリーブの搾油器.</div>\r\n","<div class=\"hw\">Trasimēnicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://Trasumēnus\">Trasumenus<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">Trasumēnus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Trasumenus 湖の(語形は<a href=\"entry://Trasumēnus\">Trasumenus</a>参照).</div><hr><div class=\"hw\">Trasumēnus<SUP>2</SUP>, -mennus, Trasym-, Trasim-</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トラスメーヌス《Etruria の湖;現 Trasimeno;そのほとりで Hannibal がローマ軍に大勝した(前217)》.</div>\r\n","<div class=\"hw\">traulizī</div><div class=\"pos\"><i>intr</i> 3 <i>sg pr</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(人が)舌足らずに話す《ギリシア語の音訳》.</div>\r\n","<div class=\"hw\">trauma</div><div class=\"pos\">-atis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙創傷;心的外傷.</div>\r\n","<div class=\"hw\">traumaticum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://traumaticus\">traumaticus</a>]</div><div class=\"def\">傷薬.</div>\r\n","<div class=\"hw\">traumaticus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">傷に効く.</div>\r\n","<div class=\"hw\">traxī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://trahō\">traho</a>.</div>\r\n","<div class=\"hw\">trebax</div><div class=\"pos\">-ācis, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">世故<SUB>せこ</SUB>にたけた, 狡猾な.</div>\r\n","<div class=\"hw\">Trebellius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トレベッリウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Trebelliānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Trebellius の.</div>\r\n","<div class=\"hw\">Trebia<SUP>1</SUP></div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">トレビア《Padus 川の支流;現 Trebbia;その合流点付近で Hannibal がローマ軍を破った(前218)》.</div><hr><div class=\"hw\">Trebia<SUP>2</SUP></div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">トレビア《Umbria の町》.</div>\r\n","<div class=\"hw\">Trebium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">トレビウム《Latium の町》.</div>\r\n","<div class=\"hw\">Trebiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Trebia<SUP>2</SUP> の.</div><div class=\"hw2\"><b>Trebiānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Trebia<SUP>2</SUP> の住民.</div>\r\n","<div class=\"hw\">Trebiātēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Trebiānus\">Trebiani</a>.</div>\r\n","<div class=\"hw\">trebāciter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[trebax]</div><div class=\"def\">ずる賢く, 狡猾に.</div>\r\n","<div class=\"hw\">Trebātius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トレバーティウス《<i>C. ～ Testa</i>, ローマの法律家;Cicero の友人》.</div>\r\n","<div class=\"hw\">Trebōnius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トレボーニウス《ローマ人の氏族名;特に <i>Gaius ～</i>, Gallia における Caesar の副官(legatus);後に Caesar 暗殺に加担した(前44)》.</div>\r\n","<div class=\"hw\">trecentiens, -tiēs</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://trecentī\">trecentī</a>]</div><div class=\"def\">300回[度・倍].</div>\r\n","<div class=\"hw\">trecentēnārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://trecentēnī\">trecentēnī</a>]</div><div class=\"def\">300回[度・倍]の.</div>\r\n","<div class=\"hw\">trecentēnī</div><div class=\"pos\">-ae -a, <i>num distrib</i></div><div class=\"ori\">[trecenti]</div><div class=\"def\">300ずつの.</div>\r\n","<div class=\"hw\">trecentēsimus</div><div class=\"pos\">-a -um, <i>num ord</i></div><div class=\"ori\">[↓<a href=\"entry://trecentī\">trecentī</a>]</div><div class=\"def\">300番目の.</div>\r\n","<div class=\"hw\">trecentī</div><div class=\"pos\">-ae -a, <i>num card</i></div><div class=\"ori\">[tres/centum]</div><div class=\"def\"><num>①</num> 300(の).</div><div class=\"def\"><num>②</num> 無数の, おびただしい数の.</div>\r\n","<div class=\"hw\">trechedipnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(伴食者が身に着ける)軽衣(あるいはスリッパ).</div>\r\n","<div class=\"hw\">trecēnārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[treceni]</div><div class=\"def\">300の;《碑》300, 000 sestertia の支給を受ける.</div><hr><div class=\"hw\">trecēnārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">《碑》近衛兵団(cohortes praetoriae)に配置された300人の斥候(speculatores)を指揮する百人隊長(centurio).</div>\r\n","<div class=\"hw\">trecēnī</div><div class=\"pos\">-ae -a, <i>num distrib</i></div><div class=\"ori\">[tres/centum]</div><div class=\"def\"><num>①</num> 300ずつの.</div><div class=\"def\"><num>②</num> 300(の)(=<a href=\"entry://trecentī\">trecenti</a>).</div>\r\n","<div class=\"hw\">tredecim</div><div class=\"pos\"><i>indecl num card</i></div><div class=\"ori\">[tres/decem]</div><div class=\"def\">13(の).</div>\r\n","<div class=\"hw\">tredeciēs</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://tredecim\">tredecim</a>]</div><div class=\"def\">13回[度・倍](=<a href=\"entry://terdeciens\">terdeciens</a>).</div>\r\n","<div class=\"hw\">treis</div><div class=\"pos\"><i>num card</i></div><div class=\"def\">《古形》=<a href=\"entry://trēs\">tres</a>.</div>\r\n","<div class=\"hw\">tremebundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tremo]</div><div class=\"def\">震える, 震えている;揺れる, 揺れている.</div>\r\n","<div class=\"hw\">tremefacere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://tremefaciō\">tremefacio</a>.</div>\r\n","<div class=\"hw\">tremefaciō</div><div class=\"pos\">-cere -fēcī -factum, <i>tr</i></div><div class=\"ori\">[tremo/facio]</div><div class=\"def\"><num>①</num> 震動させる, 揺らす.</div><div class=\"def\"><num>②</num> (恐怖などで)震えさせる.</div>\r\n","<div class=\"hw\">tremefactus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://tremefaciō\">tremefacio</a>.</div>\r\n","<div class=\"hw\">tremefēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tremefaciō\">tremefacio</a>.</div>\r\n","<div class=\"hw\">tremendus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>gerundiv</i>)</div><div class=\"ori\">[tremo]</div><div class=\"def\">恐ろしい;畏怖すべき.</div>\r\n","<div class=\"hw\">trementer</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[tremo]</div><div class=\"def\">震えて, 戦慄<SUB>せんりつ</SUB>して.</div>\r\n","<div class=\"hw\">tremescō</div><div class=\"pos\">-ere, <i>intr</i>, <i>tr inch</i></div><div class=\"ori\">[tremo]</div><div class=\"def\"><num>①</num> 震える, 揺れる.</div><div class=\"def\"><num>②</num> ...を恐れて震える, ...におののく 〈+<i>acc</i>;+<i>acc c.inf</i>〉.</div>\r\n","<div class=\"hw\">tremibundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://tremebundus\">tremebundus</a>.</div>\r\n","<div class=\"hw\">tremidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tremo]</div><div class=\"def\">震えている.</div>\r\n","<div class=\"hw\">tremiscō</div><div class=\"pos\">-ere, <i>intr</i>, <i>tr</i></div><div class=\"def\">=<a href=\"entry://tremescō\">tremesco</a>.</div>\r\n","<div class=\"hw\">tremor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://tremō\">tremō</a>]</div><div class=\"def\"><num>①</num> (体が)震えること, 身震い, おののき.</div><div class=\"def\"><num>②</num> 恐怖(の原因).</div><div class=\"def\"><num>③</num> 揺れ;地震</div><div class=\"ex\"><i>～ ignium</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">炎のゆらぎ.</span></div>\r\n","<div class=\"hw\">tremulus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tremo]</div><div class=\"def\"><num>①</num> 震える, 震えている, 揺れる, 揺れている</div><div class=\"ex\"><i>tremula canna</i> (<author>O<small>V</small></author>)<span class=\"ext\">風にそよぐアシ(葦).</span></div><div class=\"def\"><num>②</num> 震えさせる, おののかせる.</div><hr><div class=\"hw\">tremulus<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘植〙ヤマナラシ.</div>\r\n","<div class=\"hw\">tremulē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://tremulus\">tremulus<SUP>1</SUP></a>]</div><div class=\"def\">震えて, 震えながら.</div>\r\n","<div class=\"hw\">tremuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tremō\">tremo</a>.</div>\r\n","<div class=\"hw\">tremō</div><div class=\"pos\">-ere -uī, <i>intr</i>, <i>tr</i></div><div class=\"def\"><num>①</num> 震動する, 震える, 揺れる.</div><div class=\"def\"><num>②</num> ...に震える, おののく 〈+<i>acc</i>〉.</div>\r\n","<div class=\"hw\">trepidanter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[trepido]</div><div class=\"def\">震えながら, びくびくして.</div>\r\n","<div class=\"hw\">trepidulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://trepidus\">trepidus</a>]</div><div class=\"def\">おののいている.</div>\r\n","<div class=\"hw\">trepidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 恐れて[心配して]いる, おののいている</div><div class=\"ex\">(原因の <i>gen</i> と)<i>～ admirationis et metūs</i> (<author>T<small>AC</small></author>)<span class=\"ext\">驚きと恐怖におののく.</span></div><div class=\"def\"><num>②</num> あわただしい, 落ちつかない.</div><div class=\"def\"><num>③</num> 揺れる, 震える</div><div class=\"ex\"><i>trepidum aenum</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">ぶくぶく泡立っている銅鍋.</span></div><div class=\"def\"><num>④</num> (物事が)不安な, 恐ろしい, 危険な</div><div class=\"ex\"><i>in re trepida</i>=<i>in rebus trepidis</i> (<author>L<small>IV</small></author>)<span class=\"ext\">危急の事態に, 重大な局面で</span></div><div class=\"ex\"><i>incerta et trepida vita</i> (<author>T<small>AC</small></author>)<span class=\"ext\">不確かで不安な人生.</span></div>\r\n","<div class=\"hw\">trepidātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[trepido]</div><div class=\"def\"><num>①</num> 震え, おののき;動揺, 狼狽</div><div class=\"ex\"><i>ferrum pectori per trepidationem admovens</i> (<author>T<small>AC</small></author>)<span class=\"ext\">震えながら剣を胸に近づけると.</span></div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 躊躇, ためらい.</div>\r\n","<div class=\"hw\">trepidē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[trepidus]</div><div class=\"def\"><num>①</num> 狼狽[動揺, 混乱]して.</div><div class=\"def\"><num>②</num> せかせかと.</div>\r\n","<div class=\"hw\">trepidō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>(<i>tr</i>)</div><div class=\"ori\">[trepidus]</div><div class=\"def\"><num>①</num> 狼狽<SUB>ろうばい</SUB>する, あわてふためく</div><div class=\"ex\">(impers pass)<i>totis trepidatur castris</i> (<author>C<small>AES</small></author>)<span class=\"ext\">全陣営がパニック状態だ.</span></div><div class=\"def\"><num>②</num> せわしなく動く;急いで...する 〈+<i>inf</i>〉.</div><div class=\"def\"><num>③</num> 震動する, 震える, 揺れる</div><div class=\"ex\"><i>pennā trepidante</i> (<author>O<small>V</small></author>)<span class=\"ext\">震える翼で(=翼を震わせて)</span></div><div class=\"ex\"><i>trepidantia bello corda</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">戦<SUB>いくさ</SUB>にはやる胸.</span></div><div class=\"def\"><num>④</num> 心配[不安]である;(<i>tr</i>)恐れる.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP> 躊躇する, ためらう.</div>\r\n","<div class=\"hw\">trepondō</div><div class=\"pos\"><i>indecl n</i></div><div class=\"ori\">[↓<a href=\"entry://trēs\">trēs</a>/pondo<SUP>2</SUP>]</div><div class=\"def\">(重さ)3ポンド.</div>\r\n","<div class=\"hw\">tressis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://trēs\">trēs</a>/as]</div><div class=\"def\">3 asses, 三文《金額》.</div>\r\n","<div class=\"hw\">treuga</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>G</i>]</div><div class=\"def\">休戦</div><div class=\"ex\"><i>～ Dei</i><span class=\"ext\">神の休戦《中世にローマ・カトリック教会が首唱した》.</span></div>\r\n","<div class=\"hw\">tri-</div><div class=\"pos\"><i>pref</i></div><div class=\"ori\">[tres]</div><div class=\"def\">「三つの...から成る」 の意.</div>\r\n","<div class=\"hw\">triambī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">(芝居における)三人の役者の会話.</div>\r\n","<div class=\"hw\">triangulum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://triangulus\">triangulus</a>]</div><div class=\"def\">三角(形).</div>\r\n","<div class=\"hw\">triangulus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tri-/angulus]</div><div class=\"def\">三角形の.</div>\r\n","<div class=\"hw\">triangulāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[triangulus]</div><div class=\"def\">三角形の.</div>\r\n","<div class=\"hw\">triangulātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[triangulus]</div><div class=\"def\">三角形にすること.</div>\r\n","<div class=\"hw\">trias</div><div class=\"pos\">-adis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 3(=<a href=\"entry://trēs\">tres</a>).</div><div class=\"def\"><num>②</num> 〘神学〙(聖)三位一体.</div>\r\n","<div class=\"hw\">Triballia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">《碑》Triballi 族の国.</div>\r\n","<div class=\"hw\">Triballī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トリバッリー《下(=東)Moesia にいた Thracia 人の一部族》.</div>\r\n","<div class=\"hw\">tribas</div><div class=\"pos\">-adis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">同性愛の女性.</div>\r\n","<div class=\"hw\">Tribocī</div><div class=\"pos\">-ōrum, <B>-cēs</B> -um, <i>m pl</i></div><div class=\"def\">トリボキー《Rhenus 河畔(現 Alsace 地方)にいた Germania の一部族》.</div>\r\n","<div class=\"hw\">tribolus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://tribulus\">tribulus</a>.</div>\r\n","<div class=\"hw\">tribrachys</div><div class=\"pos\">-yos, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘詩〙三短格, 短短短格(<img class=\"font\" src=\"img/A13C.png\"><img class=\"font\" src=\"img/A13C.png\"><img class=\"font\" src=\"img/A13C.png\">).</div>\r\n","<div class=\"hw\">tribulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 〘植〙(いずれも実にトゲがある)</div><div class=\"def\"><num1>⒜</num1> ハマビシ(浜菱)《海岸に多い》.</div><div class=\"def\"><num1>⒝</num1> ヒシ《水生》.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 鉄菱<SUB>てつびし</SUB>《地上にまいて敵の騎兵の進撃を防いだ》.</div>\r\n","<div class=\"hw\">tribulōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tribulus]</div><div class=\"def\"><num>①</num> とげの多い.</div><div class=\"def\"><num>②</num> 困難な, つらい, 危険な.</div>\r\n","<div class=\"hw\">tribus</div><div class=\"pos\">-ūs, <i>f</i></div><div class=\"ori\">[tres]</div><div class=\"def\"><num>①</num> ローマ最初期の Ramnes, Tities, Luceres の血縁的3部族の一つ.</div><div class=\"def\"><num>②</num> 第6代の王 Servius Tullius が制定したという地縁的部族の一つ《ローマ市域の4部族 tribus urbanae と周辺部の16(この数は時とともに増え, 最終的には31)部族 tribus rusticae があり, 行政区域として機能した》</div><div class=\"ex\"><i>tribu movere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">部族からはずす[除名する]</span></div><div class=\"ex\"><i>tribum ferre</i> (<author>C<small>IC</small></author>)<span class=\"ext\">部族の票[支持]を獲得する.</span></div><div class=\"def\"><num>③</num> (<i>pl</i>)大衆, 庶民.</div>\r\n","<div class=\"hw\">tribuārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tribus]</div><div class=\"def\">部族(tribus 2)の[に関する].</div>\r\n","<div class=\"hw\">tribuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tribuō\">tribuo</a>.</div>\r\n","<div class=\"hw\">tribuō</div><div class=\"pos\">-ere -buī -būtum, <i>tr</i>(<i>intr</i>)</div><div class=\"ori\">[↓<a href=\"entry://tribus\">tribus</a>]</div><div class=\"def\"><num>①</num> 分ける, 区分する</div><div class=\"ex\"><i>rem universam tribuere in partes</i> (<author>C<small>IC</small></author>)<span class=\"ext\">全体を部分に分ける.</span></div><div class=\"def\"><num>②</num> 配分する, 割り当てる;(時間を)割く.</div><div class=\"def\"><num>③</num> 与える, 授ける</div><div class=\"ex\"><i>paribus beneficiis parem voluntatem tribuere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">受けた恩恵に釣り合うだけの好意を返す.</span></div><div class=\"def\"><num>④</num> ...に帰する, ...のせいにする.</div><div class=\"def\"><num>⑤</num> 認める</div><div class=\"ex\"><i>principiis rerum colores tribuere</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">元素に色(があること)を認める.</span></div><div class=\"def\"><num>⑥</num> 重んじる, 敬意を表する 〈+<i>dat</i>〉</div><div class=\"ex\"><i>honori abeuntis amici tribuere</i> (<author>T<small>AC</small></author>)<span class=\"ext\">その場を去ろうとしている友人の名誉に配慮する</span></div><div class=\"ex\">(tantum, plurimum などと)<i>patri ejus uni plurimum tribui</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私は彼の父一人だけに最も敬意を払ってきた.</span></div>\r\n","<div class=\"hw\">tribūlis<SUP>1</SUP></div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[tribus]</div><div class=\"def\"><num>①</num> 同じ部族(tribus 2)の人.</div><div class=\"def\"><num>②</num> 貧乏人.</div><hr><div class=\"hw\">tribūlis<SUP>2</SUP></div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tribus]</div><div class=\"def\">部族の.</div>\r\n","<div class=\"hw\">tribūnal</div><div class=\"pos\">-ālis, <i>n</i></div><div class=\"ori\">[tribunus]</div><div class=\"def\"><num>①</num> (法廷などの)高官席, 高壇.</div><div class=\"def\"><num>②</num> (戦陣での将軍の)指揮壇[台].</div><div class=\"def\"><num>③</num> (劇場における法務官(praetor)の)特別席.</div><div class=\"def\"><num>④</num> 玉座.</div><div class=\"def\"><num>⑤</num> (物故高位者の)記念塚.</div><div class=\"def\"><num>⑥</num> (神殿の)壇;(家屋の)土台.</div><div class=\"def\"><num>⑦</num> 高み, 頂点.</div><div class=\"def\"><num>⑧</num> <SUP>◇</SUP> 説教壇, 朗読台.</div><div class=\"def\"><num>⑨</num> <SUP>◇</SUP> 合唱[聖歌]隊.</div>\r\n","<div class=\"hw\">tribūnicius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tribunus]</div><div class=\"def\">護民官[軍団司令官]の.</div><hr><div class=\"hw\">tribūnicius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">前護民官.</div>\r\n","<div class=\"hw\">tribūnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[tribus]</div><div class=\"def\"><num>①</num> ローマ最初期の3部族(tribus 1)の各々が兵員を出して編制された軍隊の司令官</div><div class=\"ex\"><i>～ celerum</i> (<author>L<small>IV</small></author>)<span class=\"ext\">(王制期の)親衛隊長.</span></div><div class=\"def\"><num>②</num> </div><div class=\"ex\"><i>～ militum consulari potestate</i> (<author>L<small>IV</small></author>)<span class=\"ext\">執政官格軍司令官《前444‐367年の間, 2名の執政官に代えてほぼ毎年選出された3名(のちに6名)の高官》.</span></div><div class=\"def\"><num>③</num> </div><div class=\"ex\"><i>～ militum [militaris]</i> (<author>C<small>AES</small></author>)<span class=\"ext\">軍団司令官《各軍団に6名配置され, 2か月交代で指揮した》.</span></div><div class=\"def\"><num>④</num> </div><div class=\"ex\"><i>～ plebis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">護民官《貴族の横暴から平民を護るために毎年平民自身によって選出された10名の高官》.</span></div><div class=\"def\"><num>⑤</num> </div><div class=\"ex\"><i>～ aerarius</i> (<author>C<small>IC</small></author>)<span class=\"ext\">主計官《古くは戦時税徴収と軍隊への給料支払いを担当;前1世紀には準騎士階級として陪審員団に選ばれた》.</span></div>\r\n","<div class=\"hw\">tribūnāle</div><div class=\"pos\">-is, <i>n</i></div><div class=\"def\">=<a href=\"entry://tribūnal\">tribunal</a>.</div>\r\n","<div class=\"hw\">tribūnātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[tribunus]</div><div class=\"def\">護民官[軍団司令官]の地位[職].</div>\r\n","<div class=\"hw\">tribūtim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tribus]</div><div class=\"def\">部族(tribus 2)ごとに[によって].</div>\r\n","<div class=\"hw\">tribūtiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[tribuo]</div><div class=\"def\"><num>①</num> 分配, 配分.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 貢納, 納税.</div>\r\n","<div class=\"hw\">tribūtor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[tribuo]</div><div class=\"def\"><num>①</num> 与える者.</div><div class=\"def\"><num>②</num> 分配者.</div>\r\n","<div class=\"hw\">tribūtum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tribūtus\">tribūtus<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 租税, 貢ぎ物</div><div class=\"ex\"><i>～ imponere</i> (<author>C<small>AES</small></author>)=<i>～ exigere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">課税する</span></div><div class=\"ex\"><i>～ pendere</i> (<author>C<small>AES</small></author>)=<i>～ conferre</i> (<author>C<small>IC</small></author>)<span class=\"ext\">納税する.</span></div><div class=\"def\"><num>②</num> (当然視される)贈り物.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 債権者に支払われるべき金額.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP></div><div class=\"ex\"><i>～ sanguinis</i> (<author>T<small>ERT</small></author>)<span class=\"ext\">月経.</span></div>\r\n","<div class=\"hw\">tribūtus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://tribuō\">tribuo</a>.</div><hr><div class=\"hw\">tribūtus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 租税.</div><div class=\"def\"><num>②</num> 《碑》割当て, 配分.</div><hr><div class=\"hw\">tribūtus<SUP>3</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tribus]</div><div class=\"def\">部族(tribus 2)による</div><div class=\"ex\"><i>comitia tributa</i> (<author>C<small>IC</small></author>)<span class=\"ext\">トリブス民会《部族ごとに投票した》.</span></div>\r\n","<div class=\"hw\">tribūtārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tributum]</div><div class=\"def\">租税[貢ぎ物]の[を納める義務のある].</div>\r\n","<div class=\"hw\">tribūtōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tribuo]</div><div class=\"def\">〘法〙配分に関する.</div>\r\n","<div class=\"hw\">tricamerātus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tri-/camera]</div><div class=\"def\">3室から成る;3階建ての.</div>\r\n","<div class=\"hw\">Tricastīnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">トリカスティーニー《Gallia Narbonensis の Rhodanus(現 Rhône)川沿い(の現 Tricastin 地方)にいた一部族》.</div>\r\n","<div class=\"hw\">Tricca</div><div class=\"pos\">-ae, <B>-ē</B> -ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トリッカ, <SUP>*</SUP>トリッケー《Thessalia 西部の Peneus 川沿いの町》.</div>\r\n","<div class=\"hw\">tricent-</div><div class=\"def\">⇒trecent-.</div>\r\n","<div class=\"hw\">triceps</div><div class=\"pos\">-cipitis, <i>adj</i></div><div class=\"ori\">[tres/caput]</div><div class=\"def\"><num>①</num> 頭が三つある, 三頭の.</div><div class=\"def\"><num>②</num> 三様[種]の.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘解〙(筋肉が)三頭の.</div>\r\n","<div class=\"hw\">trichiasis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙さか(さ)まつげ.</div>\r\n","<div class=\"hw\">trichila, triclia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">四阿<SUB>あずまや</SUB>, 亭<SUB>てい</SUB><SUB>ちん</SUB>.</div>\r\n","<div class=\"hw\">trichinus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">わずかな, 乏しい.</div>\r\n","<div class=\"hw\">trichiās</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘魚〙イワシ.</div>\r\n","<div class=\"hw\">trichomanes</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙チャセンシダ《ウラボシ科の常緑のシダ》.</div>\r\n","<div class=\"hw\">trichordis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tri-/chorda]</div><div class=\"def\">3弦の.</div>\r\n","<div class=\"hw\">trichītis</div><div class=\"pos\">-tidis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">明礬<SUB>みょうばん</SUB>の一種.</div>\r\n","<div class=\"hw\">trichōrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://trichōrus\">trichōrus</a>]</div><div class=\"def\">三つに仕切られた家屋[建物].</div>\r\n","<div class=\"hw\">trichōrus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">三つに分かれた.</div>\r\n","<div class=\"hw\">trichōsis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙</div><div class=\"def\"><num>①</num> 異所発毛症.</div><div class=\"def\"><num>②</num> =<a href=\"entry://trichiasis\">trichiasis</a>.</div>\r\n","<div class=\"hw\">Tricipitīnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トリキピティーヌス《Lucretia 氏族に属する家名》.</div>\r\n","<div class=\"hw\">tricoccum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙ヒマワリなどの日向性植物の一種.</div>\r\n","<div class=\"hw\">tricolor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tri-/color]</div><div class=\"def\">三色の.</div>\r\n","<div class=\"hw\">Tricoriī</div><div class=\"pos\">-iōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トリコリイー, <SUP>*</SUP>-コリオイ《Gallia Narbonensis の Alpes 山脈にいた一部族》.</div>\r\n","<div class=\"hw\">tricorniger</div><div class=\"pos\">-gera -gerum, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">三つの角<SUB>つの</SUB>のある《ギリシア文字 ▷Ψ◁ を指して言う》.</div>\r\n","<div class=\"hw\">tricornis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tri-/cornu]</div><div class=\"def\">三つの角<SUB>つの</SUB>をもつ, 三本角の.</div>\r\n","<div class=\"hw\">tricorpor</div><div class=\"pos\">-oris, <i>adj</i></div><div class=\"ori\">[tri-/corpus]</div><div class=\"def\">三つの身体をもつ.</div>\r\n","<div class=\"hw\">tricubitus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">3 cubita(の長さ)の.</div>\r\n","<div class=\"hw\">tricuspidālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://tricuspis\">tricuspis</a>]</div><div class=\"def\">〘解〙三尖(弁)の.</div>\r\n","<div class=\"hw\">tricuspis</div><div class=\"pos\">-idis, <i>adj</i></div><div class=\"ori\">[tri-/cuspis]</div><div class=\"def\">三叉の, 三つの先端のある</div><div class=\"ex\"><i>～ telum</i> (<author>O<small>V</small></author>)<span class=\"ext\">(Neptunus の持つ)三叉の槍.</span></div>\r\n","<div class=\"hw\">tricōlos</div><div class=\"pos\">-os -on, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">三つの節から成る.</div>\r\n","<div class=\"hw\">tricōlum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘修〙三つの節から成る文.</div>\r\n","<div class=\"hw\">tridacna</div><div class=\"pos\">-nōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">カキ(牡蠣)の一種《食べるのに三口を要することから》.</div>\r\n","<div class=\"hw\">tridens<SUP>1</SUP></div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"ori\">[tri-/dens]</div><div class=\"def\">(船嘴<SUB>せんし</SUB>が)三叉の.</div><hr><div class=\"hw\">tridens<SUP>2</SUP></div><div class=\"pos\">-entis, <i>m</i></div><div class=\"def\"><num>①</num> (漁獲用の)三叉のやす.</div><div class=\"def\"><num>②</num> (投網剣闘士(retiarius)の持つ)三叉の槍.</div><div class=\"def\"><num>③</num> (Neptunus の標章としての)三叉の槍.</div>\r\n","<div class=\"hw\">tridentifer</div><div class=\"pos\">-era -erum, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://tridens\">tridens<SUP>2</SUP></a>/fero]</div><div class=\"def\">三叉の槍を持っている《Neptunus の添え名》.</div>\r\n","<div class=\"hw\">tridentiger</div><div class=\"pos\">-era -erum, <i>adj</i></div><div class=\"ori\">[tridens/gero]</div><div class=\"def\">=<a href=\"entry://tridentifer\">tridentifer</a>.</div>\r\n","<div class=\"hw\">triennia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://triennis\">triennis</a>]</div><div class=\"def\">3年ごとに Thebae で行なわれた Bacchus の祭(=trieterica sacra).</div>\r\n","<div class=\"hw\">triennis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tri-/annus]</div><div class=\"def\">3年目の;<SUP>◇</SUP>3歳の.</div>\r\n","<div class=\"hw\">triennium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://triennis\">triennis</a>]</div><div class=\"def\">3年間;3年.</div>\r\n","<div class=\"hw\">triennālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tri-/annus]</div><div class=\"def\">3年間の, 3年続く.</div>\r\n","<div class=\"hw\">triens</div><div class=\"pos\">-entis, <i>m</i></div><div class=\"ori\">[tres]</div><div class=\"def\"><num>①</num> 3分の1.</div><div class=\"def\"><num>②</num> (通貨・重量単位としての)<img class=\"font\" src=\"img/B152.png\"> as.</div><div class=\"def\"><num>③</num> <img class=\"font\" src=\"img/B152.png\"> sextarius 入る酒杯.</div><div class=\"def\"><num>④</num> <img class=\"font\" src=\"img/B152.png\"> pes(約10cm)の梁<SUB>はり</SUB>.</div>\r\n","<div class=\"hw\">triental</div><div class=\"pos\">-ālis, <SUP>◇</SUP><i>n</i></div><div class=\"def\">=<a href=\"entry://triens\">triens 3</a>.</div>\r\n","<div class=\"hw\">trientābulum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://triens\">triens</a>]</div><div class=\"def\">国に金を貸した人にその3分の1の返済分として与えられた公有地.</div>\r\n","<div class=\"hw\">trientālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[triens]</div><div class=\"def\">(長さ)<img class=\"font\" src=\"img/B152.png\"> pes の.</div>\r\n","<div class=\"hw\">trientārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[triens]</div><div class=\"def\">(利子が)月 <img class=\"font\" src=\"img/B152.png\">%(=年4%)の.</div>\r\n","<div class=\"hw\">trietērica</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://trietēricus\">trietēricus</a>]</div><div class=\"def\">=<a href=\"entry://triennia\">triennia</a>.</div>\r\n","<div class=\"hw\">trietēricus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">3年ごとの</div><div class=\"ex\"><i>sacra trieterica</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://triennia\">triennia</a>.</span></div>\r\n","<div class=\"hw\">trietēris</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 3年間.</div><div class=\"def\"><num>②</num> 3年ごとの祝祭(特に Bacchus の).</div>\r\n","<div class=\"hw\">trifaucis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tri-/fauces]</div><div class=\"def\">三つの喉<SUB>のど</SUB>をもつ[からの]</div><div class=\"ex\"><i>latratus ～</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">三つの喉から出る(Cerberus の)ほえる声.</span></div>\r\n","<div class=\"hw\">trifax</div><div class=\"pos\">-ācis, <i>f</i></div><div class=\"def\">(弩<SUB>いしゆみ</SUB>で射出される)長い飛び道具の一種.</div>\r\n","<div class=\"hw\">trifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[tri-/fero]</div><div class=\"def\">(年に)3回実を結ぶ.</div>\r\n","<div class=\"hw\">trifidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tri-/findo]</div><div class=\"def\">三つに分かれた, 三叉の</div><div class=\"ex\"><i>trifida flamma</i> (<author>O<small>V</small></author>)<span class=\"ext\">稲妻.</span></div>\r\n","<div class=\"hw\">trifissilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://tricorniger\">tricorniger</a>.</div>\r\n","<div class=\"hw\">trifolium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tri-/folium]</div><div class=\"def\">〘植〙クローバー《マメ科シャジクソウ属の草本の総称》.</div>\r\n","<div class=\"hw\">triformis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tri-/forma]</div><div class=\"def\">三つの姿[形]をもつ;三つの部分から成る.</div>\r\n","<div class=\"hw\">triformiter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[triformis]</div><div class=\"def\">三つの形を成して.</div>\r\n","<div class=\"hw\">triformitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://triformis\">triformis</a>]</div><div class=\"def\">三つの姿[形]をもつこと;三つの部分から成ること.</div>\r\n","<div class=\"hw\">trifurcifer</div><div class=\"pos\">-erī, <i>m</i></div><div class=\"ori\">[tri-/furcifer]</div><div class=\"def\">大悪党.</div>\r\n","<div class=\"hw\">trifurcus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tri-/furca]</div><div class=\"def\">三つの先端をもつ, 三叉の.</div>\r\n","<div class=\"hw\">trifāriam</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[trifarius]</div><div class=\"def\"><num>①</num> 三つに(分けて).</div><div class=\"def\"><num>②</num> 三方から[で].</div><div class=\"def\"><num>③</num> 三様に.</div>\r\n","<div class=\"hw\">trifārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tri-;<i>cf</i>. bifarius]</div><div class=\"def\">三種の, 三様の.</div>\r\n","<div class=\"hw\">trifāriē</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://trifāriam\">trifariam</a>.</div>\r\n","<div class=\"hw\">trifīlis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tri-/filum]</div><div class=\"def\">(頭に)毛が3本しかない.</div>\r\n","<div class=\"hw\">trifīnium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tri-/finis]</div><div class=\"def\">三つの境界が会する地点.</div>\r\n","<div class=\"hw\">trifūr</div><div class=\"pos\">-ris, <i>m</i></div><div class=\"ori\">[tri-/fur]</div><div class=\"def\">大泥棒.</div>\r\n","<div class=\"hw\">trigamia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">三重婚, 一夫三妻.</div>\r\n","<div class=\"hw\">trigamus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">三重婚している[三人の妻を持つ]男.</div>\r\n","<div class=\"hw\">trigeminus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tri-/geminus]</div><div class=\"def\"><num>①</num> 三つ子の</div><div class=\"ex\"><i>fratres trigemini</i> (<author>L<small>IV</small></author>)<span class=\"ext\">ローマの Horatii 三兄弟と Alba Longa の Curiatii 三兄弟《いずれも三つ子と伝えられる》.</span></div><div class=\"def\"><num>②</num> 三つ一組の</div><div class=\"ex\"><i>trigemina via</i> (<author>S<small>EN</small></author>)<span class=\"ext\">三叉路.</span></div><div class=\"def\"><num>③</num> 3重[倍・度]の</div><div class=\"ex\"><i>trigemini honores</i> (<author>H<small>OR</small></author>)<span class=\"ext\">造営官(aedilis), 法務官(praetor), 執政官(consul)の三高官職.</span></div><div class=\"def\"><num>④</num> <i>porta Trigemina</i> (<author>P<small>LAUT</small></author>) トリゲミナ門《ローマ市の Aventinus 丘北麓の門;上部がアーチ形をした三つの出入口があった》.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘解〙三叉の.</div>\r\n","<div class=\"hw\">trigeminō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[tri-/gemino]</div><div class=\"def\">3倍にする.</div>\r\n","<div class=\"hw\">trigemmis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tri-/gemma]</div><div class=\"def\">三つの芽のある.</div>\r\n","<div class=\"hw\">triglyphus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘建〙トリグリュフォス《ドーリス式建築のフリーズのうち, 3本の縦溝が刻まれた矩形部分》.</div>\r\n","<div class=\"hw\">trigon</div><div class=\"pos\">-ōnis [-ōnos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">三人でする球戯;それに用いる球.</div>\r\n","<div class=\"hw\">trigōnicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">三角形の.</div>\r\n","<div class=\"hw\">trigōnium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[trigonum]</div><div class=\"def\">三角形.</div>\r\n","<div class=\"hw\">trigōnius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://trigōnus\">trigonus</a>.</div>\r\n","<div class=\"hw\">trigōnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://trigōnus\">trigōnus</a>]</div><div class=\"def\"><num>①</num> 三角(形).</div><div class=\"def\"><num>②</num> =<a href=\"entry://trigon\">trigon</a>.</div>\r\n","<div class=\"hw\">trigōnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">三角(形)の.</div>\r\n","<div class=\"hw\">trigōnālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://trigon\">trigon</a>]</div><div class=\"ex\"><i>pila ～</i> (<author>M<small>ART</small></author>)<span class=\"ext\">trigon 用の球.</span></div>\r\n","<div class=\"hw\">trihōrium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[tri-/hora]</div><div class=\"def\">3時間.</div>\r\n","<div class=\"hw\">trijugis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tri-/jugum]</div><div class=\"def\">3頭立ての.</div>\r\n","<div class=\"hw\">trilaterus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tri-/latus<SUP>2</SUP>]</div><div class=\"def\">三辺から成る.</div>\r\n","<div class=\"hw\">trilinguis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tri-/lingua]</div><div class=\"def\"><num>①</num> 三つの舌をもつ.</div><div class=\"def\"><num>②</num> 3言語を話す.</div>\r\n","<div class=\"hw\">trilix</div><div class=\"pos\">-īcis, <i>adj</i></div><div class=\"ori\">[tri-/licium]</div><div class=\"def\">3本の糸で織られた, 3段重ねた.</div>\r\n","<div class=\"hw\">trilongus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tri-/longus]</div><div class=\"def\">〘詩〙三つの長音節から成る.</div>\r\n","<div class=\"hw\">trilībris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tri-/libra]</div><div class=\"def\">(重量)3 librae の.</div>\r\n","<div class=\"hw\">trimanus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">手の3本ある.</div>\r\n","<div class=\"hw\">trime(n)stris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tri-/mensis]</div><div class=\"def\"><num>①</num> (作物が)3か月で成熟する.</div><div class=\"def\"><num>②</num> (生後)3か月の.</div><div class=\"def\"><num>③</num> 3か月間続く;3か月の間(だけ)の.</div>\r\n","<div class=\"hw\">trimeter</div><div class=\"pos\">-trī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">=<a href=\"entry://trimetrus\">trimetrus<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">trimetrus, -os</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘詩〙三複詩脚の, 六歩格の.</div><hr><div class=\"hw\">trimetrus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘詩〙三複詩脚の詩行.</div>\r\n","<div class=\"hw\">trimodia</div><div class=\"pos\">-ae, <i>f</i>, <B>-modium</B> -ī, <i>n</i></div><div class=\"def\">3 modii 入る容器.</div>\r\n","<div class=\"hw\">trineptis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[tri-/neptis]</div><div class=\"def\">曾孫の曾孫, 仍孫<SUB>じょうそん</SUB>《女》.</div>\r\n","<div class=\"hw\">trinepōs</div><div class=\"pos\">-ōtis, <i>m</i></div><div class=\"ori\">[tri-/nepos]</div><div class=\"def\">曾孫の曾孫, 仍孫<SUB>じょうそん</SUB>《男》.</div>\r\n","<div class=\"hw\">Trinobantēs</div><div class=\"pos\">-ium [-um], <i>m pl</i></div><div class=\"def\">トリノバンテース《Britannia 東部(現 Essex と Suffolk 南部)にいた一部族》.</div>\r\n","<div class=\"hw\">trinoctium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tri-/nox]</div><div class=\"def\">三夜(連続).</div>\r\n","<div class=\"hw\">trinoctiālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://trinoctium\">trinoctium</a>]</div><div class=\"def\">三夜(連続)の.</div>\r\n","<div class=\"hw\">trinummus</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> ある高額(一説では低額)貨幣の通称.</div><div class=\"def\"><num>②</num> (T-)「三千両」(または 「三文銭」)《Plautus 作の喜劇の題名》.</div>\r\n","<div class=\"hw\">trinundinus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tri-/nundinae]</div><div class=\"def\">3度目の市の日の</div><div class=\"ex\"><i>trinundino die</i> (<author>M<small>ACR</small></author>)<span class=\"ext\">24日目に.</span></div>\r\n","<div class=\"hw\">trinōdis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tri-/nodus]</div><div class=\"def\"><num>①</num> 三つの節<SUB>ふし</SUB>[瘤<SUB>こぶ</SUB>]のある.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>3音節から成る.</div>\r\n","<div class=\"hw\">trinōminis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tri-/nomen]</div><div class=\"def\">三つの名をもつ.</div>\r\n","<div class=\"hw\">trinōmius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://trinōminis\">trinominis</a>.</div>\r\n","<div class=\"hw\">Triopās</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙トリオパース《Thessalia の王;Erysichthon の父》.</div>\r\n","<div class=\"hw\">Triopēis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"def\">〘伝説〙Erysichthon の娘で Triopas の孫(=変身の能力をもつ Mestra).</div>\r\n","<div class=\"hw\">Triopēius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘伝説〙Triopas の息子(=<a href=\"entry://Erysichthōn\">Erysichthon</a>).</div>\r\n","<div class=\"hw\">triparcus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tri-/parcus]</div><div class=\"def\">ひどくけちな.</div>\r\n","<div class=\"hw\">tripart-</div><div class=\"def\">⇒tripert-.</div>\r\n","<div class=\"hw\">tripeccia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf. </i> tripes<SUP>1</SUP>]</div><div class=\"def\">(Gallia 地方の方言で)三脚腰掛け.</div>\r\n","<div class=\"hw\">tripectorus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tri-/pectus]</div><div class=\"def\">三つの胸の.</div>\r\n","<div class=\"hw\">tripedālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tri-/pes]</div><div class=\"def\">(長さ)3 pedes の.</div>\r\n","<div class=\"hw\">tripedāneus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://tripedālis\">tripedalis</a>.</div>\r\n","<div class=\"hw\">tripertiō</div><div class=\"pos\">-īre -īvī, <SUP>◇</SUP><i>tr</i></div><div class=\"def\">三つに分ける.</div>\r\n","<div class=\"hw\">tripertītiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[tripertitus]</div><div class=\"def\">三つに分けること, 三分割.</div>\r\n","<div class=\"hw\">tripertītus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tri-/partior]</div><div class=\"def\">三つの部分に分かれた, 三つの部分から成る.</div>\r\n","<div class=\"hw\">tripertītō</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[↓<a href=\"entry://tripertītus\">tripertītus</a>]</div><div class=\"def\">三つに(分けて).</div>\r\n","<div class=\"hw\">Triphȳlia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トリピューリア(ー)《Elis 南部の沿岸地方》.</div>\r\n","<div class=\"hw\">triplasius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">3倍の;(比が)3対1の.</div>\r\n","<div class=\"hw\">triplex<SUP>1</SUP></div><div class=\"pos\">-plicis, <i>adj</i></div><div class=\"ori\">[tri-/plico]</div><div class=\"def\"><num>①</num> 3重の, 3倍の</div><div class=\"ex\"><i>～ acies</i> (<author>C<small>AES</small></author>)<span class=\"ext\">3重の戦列.</span></div><div class=\"def\"><num>②</num> 三つの部分から成る</div><div class=\"ex\"><i>～ mundus</i> (<author>O<small>V</small></author>)<span class=\"ext\">(陸・海・天の)3領域から成る世界.</span></div><div class=\"def\"><num>③</num> 三つの(=<a href=\"entry://trēs\">tres</a>)</div><div class=\"ex\"><i>poenarum deae triplices</i> (<author>O<small>V</small></author>)<span class=\"ext\">復讐の三女神(=<a href=\"entry://furia\">Furiae</a>).</span></div><hr><div class=\"hw\">triplex<SUP>2</SUP></div><div class=\"pos\">-plicis, <i>n</i></div><div class=\"def\">3倍.</div>\r\n","<div class=\"hw\">tripliciter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[triplex<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 三通りに, 三様に.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 激しく.</div>\r\n","<div class=\"hw\">triplicitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[triplico]</div><div class=\"def\">三重[様]の性質.</div>\r\n","<div class=\"hw\">triplicābilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[triplico]</div><div class=\"def\">三つの部分から成る.</div>\r\n","<div class=\"hw\">triplicārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[triplico]</div><div class=\"def\">《碑》3倍の給与を受ける兵士.</div>\r\n","<div class=\"hw\">triplicātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[triplico]</div><div class=\"def\"><num>①</num> <SUP>◇</SUP> 3倍にすること.</div><div class=\"def\"><num>②</num> 〘法〙(被告の再々抗弁に対する)原告の第3回目の訴答.</div>\r\n","<div class=\"hw\">triplicēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">(<i>sc. </i> codicilli)</div><div class=\"ori\">[triplex<SUP>1</SUP>]</div><div class=\"def\">3枚つづりの書字板.</div>\r\n","<div class=\"hw\">triplicō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[triplex<SUP>1</SUP>]</div><div class=\"def\">3倍にする.</div>\r\n","<div class=\"hw\">triplus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">3倍の.</div>\r\n","<div class=\"hw\">tripoda</div><div class=\"pos\">-dae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">(Pythia<SUP>1</SUP> の)鼎<SUB>かなえ</SUB>.</div>\r\n","<div class=\"hw\">tripodum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(馬の)速歩.</div>\r\n","<div class=\"hw\">tripodō<SUP>1</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"def\">《碑》=<a href=\"entry://tripudiō\">tripudio</a>.</div><hr><div class=\"hw\">tripodō<SUP>2</SUP></div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[↓<a href=\"entry://tripodum\">tripodum</a>]</div><div class=\"def\">(馬が)速歩で駆ける.</div>\r\n","<div class=\"hw\">Tripolis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トリポリス《 (1) Laconia の一地域.(2) Thessalia 北部の一地域.(3) Pontus の港町と同名の川.(4) Phoenicia の港町;Tyrus, Sidon, Aradus の三市によって建設された;現 Lebanon の Tarabulus(Tripoli).(5) <SUP>◇</SUP>Africa の Oea, Leptis などの町を含む一地域》.</div>\r\n","<div class=\"hw\">Tripolitānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tripolis (2)  (5) の.</div>\r\n","<div class=\"hw\">tripontium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[tri-/pons]</div><div class=\"def\">三つの橋のある場所.</div>\r\n","<div class=\"hw\">triportentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tri-/portentum]</div><div class=\"def\">きわめて異常な前兆.</div>\r\n","<div class=\"hw\">Triptolemus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙トリプトレムス, <SUP>*</SUP>-モス《Celeus の息子;Eleusin の王;女神 Ceres に穀物栽培を教えられ, その業を世に広めた》</div><div class=\"ex\"><i>Triptolemo dare fruges</i> (<author>O<small>V</small></author>)<span class=\"ext\">Triptolemus に穀物を与える(=釈迦<SUB>しゃか</SUB>に説法).</span></div>\r\n","<div class=\"hw\">tripudium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tri-/pes]</div><div class=\"def\"><num>①</num> (Mars の神官団 Salii が儀式の中で踊った)三拍子の踊り.</div><div class=\"def\"><num>②</num> (Salii 以外の儀式的または娯楽的な)踊り.</div><div class=\"def\"><num>③</num> (卜占における)吉兆《聖なるニワトリがついばむ餌の一部が音を立ててくちばしから地面に落ちたとき》.</div>\r\n","<div class=\"hw\">tripudiō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[↓<a href=\"entry://tripudium\">tripudium</a>]</div><div class=\"def\"><num>①</num> (儀式の中で)三拍子で踊る.</div><div class=\"def\"><num>②</num> (一般に)踊る, 跳ねる;欣喜雀躍する.</div>\r\n","<div class=\"hw\">tripēs<SUP>1</SUP></div><div class=\"pos\">-pedis, <i>adj</i></div><div class=\"ori\">[tri-/pes]</div><div class=\"def\">3本足の, 三脚の.</div><hr><div class=\"hw\">tripēs<SUP>2</SUP></div><div class=\"pos\">-pedis, <i>m</i></div><div class=\"def\"><num>①</num> 三脚台, 三脚腰掛け.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 鼎<SUB>かなえ</SUB>.</div>\r\n","<div class=\"hw\">tripūs</div><div class=\"pos\">-podis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 鼎<SUB>かなえ</SUB>, 三脚, 三脚の鍋[供物台].</div><div class=\"def\"><num>②</num> (Delphi の Apollo の巫女が座る)三脚の座.</div><div class=\"def\"><num>③</num> (Delphi の, または一般に)神託, 託宣.</div>\r\n","<div class=\"hw\">triquetrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://triquetrus\">triquetrus</a>]</div><div class=\"def\">〘占星〙三分, トライン《黄道十二宮図で惑星間の角度が120度をなしている状態》.</div>\r\n","<div class=\"hw\">triquetrus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 三角(形)の.</div><div class=\"def\"><num>②</num> Sicilia 島の《島の全体的な形状から》.</div>\r\n","<div class=\"hw\">trirēmis<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tri-/remus]</div><div class=\"def\">三段櫂の.</div><hr><div class=\"hw\">trirēmis<SUP>2</SUP></div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">三段櫂船.</div>\r\n","<div class=\"hw\">trisagium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘教会〙三聖唱</div><div class=\"def\"><num1>⒜</num1> サンクトゥス《sanctus, sanctus, sanctus で始まるカトリック教会などの聖歌》.</div><div class=\"def\"><num1>⒝</num1> トリサギオン《正教会の典礼文;sanctus Deus, sanctus fortis, sanctus immortalis を唱える》.</div>\r\n","<div class=\"hw\">triscurrium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tri-/scurra]</div><div class=\"def\">ひどいおどけ.</div>\r\n","<div class=\"hw\">trismus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙開口障害.</div>\r\n","<div class=\"hw\">trissō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"def\">(ツバメが)さえずる.</div>\r\n","<div class=\"hw\">triste</div><div class=\"pos\"><i>adv</i>(<i>neut</i>)</div><div class=\"ori\">[tristis]</div><div class=\"def\"><num>①</num> 悲しんで, 悲しく.</div><div class=\"def\"><num>②</num> 難しく, 困難で.</div><div class=\"def\"><num>③</num> 厳しく.</div>\r\n","<div class=\"hw\">tristega</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(建物の)3階.</div>\r\n","<div class=\"hw\">tristiculus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[tristis]</div><div class=\"def\">悲しみ[憂い]を帯びている.</div>\r\n","<div class=\"hw\">tristificus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tristis/facio]</div><div class=\"def\">悲しませる, 意気消沈させる.</div>\r\n","<div class=\"hw\">tristificō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[tristis/facio]</div><div class=\"def\">悲しませる.</div>\r\n","<div class=\"hw\">tristimōnia</div><div class=\"pos\">-ae, <i>f</i>, <B>-ium</B> -ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tristis\">tristis</a>]</div><div class=\"def\">悲しみ, 憂鬱.</div>\r\n","<div class=\"hw\">tristis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\"><num>①</num> 悲しんでいる, 意気消沈した, 憂鬱な 〈re〉.</div><div class=\"def\"><num>②</num> (状況・行為などが)悲しむべき, 悲惨な, 痛ましい.</div><div class=\"def\"><num>③</num> 不機嫌な, 気むずかしい, 敵対的な.</div><div class=\"def\"><num>④</num> 厳しい, 厳格な, いかめしい.</div><div class=\"def\"><num>⑤</num> (文体が)荘重な, 重々しい.</div><div class=\"def\"><num>⑥</num> 恐るべき, 禍いの</div><div class=\"ex\"><i>tristia dedit omina bubo</i> (<author>O<small>V</small></author>)<span class=\"ext\">フクロウが(ボーボーと鳴いて)不吉な前兆を下した.</span></div><div class=\"def\"><num>⑦</num> 陰鬱な;うす暗い.</div><div class=\"def\"><num>⑧</num> (自然力などが)激しい, 苛酷な, 荒れ狂う.</div><div class=\"def\"><num>⑨</num> 厭うべき, 不快な;いやな味[匂い, 音]の.</div>\r\n","<div class=\"hw\">tristitia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tristis]</div><div class=\"def\"><num>①</num> 悲しみ, 意気消沈;憂鬱な状況[日々].</div><div class=\"def\"><num>②</num> 不機嫌, 気むずかしさ;陰鬱な外観[様子].</div><div class=\"def\"><num>③</num> 厳しさ, 厳格.</div><div class=\"def\"><num>④</num> (自然力の)苛烈, 苛酷.</div>\r\n","<div class=\"hw\">tristitiēs</div><div class=\"pos\">-ēī, <i>f</i></div><div class=\"ori\">[tristis]</div><div class=\"def\">悲しみ, 悲嘆.</div>\r\n","<div class=\"hw\">tristitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://tristis\">tristis</a>]</div><div class=\"def\">悲しみ, 憂鬱, 不機嫌.</div>\r\n","<div class=\"hw\">tristitūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[tristis]</div><div class=\"def\">悲しみ, 憂鬱.</div>\r\n","<div class=\"hw\">tristor</div><div class=\"pos\">-ārī, <SUP>◇</SUP><i>intr dep</i></div><div class=\"ori\">[tristis]</div><div class=\"def\">悲しむ.</div>\r\n","<div class=\"hw\">trisulcus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tri-/sulcus]</div><div class=\"def\">(先端が)三つに裂けた, 三叉の</div><div class=\"ex\"><i>tela trisulca Jovis</i> (<author>O<small>V</small></author>)<span class=\"ext\">Juppiter の(放つ)稲妻.</span></div>\r\n","<div class=\"hw\">trisyllabus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">3音節の[から成る].</div>\r\n","<div class=\"hw\">trisēmus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘詩〙(脚が長短(<img class=\"font\" src=\"img/A134.png\"><img class=\"font\" src=\"img/A13C.png\">)または短長(<img class=\"font\" src=\"img/A13C.png\"><img class=\"font\" src=\"img/A134.png\">)のような)3音節相当の音節から成る.</div>\r\n","<div class=\"hw\">trisōmum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">《碑》三遺体用石棺.</div>\r\n","<div class=\"hw\">tritanōpia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙第三色盲(青黄色盲).</div>\r\n","<div class=\"hw\">tritavia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://tritavus\">tritavus</a>]</div><div class=\"def\">曾祖父母の曾祖母.</div>\r\n","<div class=\"hw\">tritavus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>▷τρ<img class=\"font\" src=\"img/A14E.png\">το<img class=\"font\" src=\"img/A153.png\">◁/avus]</div><div class=\"def\"><num>①</num> 曾祖父母の曾祖父.</div><div class=\"def\"><num>②</num> 遠い先祖, 遠祖.</div>\r\n","<div class=\"hw\">tritocerebrum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘動〙後大脳.</div>\r\n","<div class=\"hw\">trittilis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">(小鳥がさえずるように)ペチャクチャおしゃべりする人.</div>\r\n","<div class=\"hw\">tritēmoria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘音〙三度(音程).</div>\r\n","<div class=\"hw\">triumphus (古形 triumpus)</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 凱旋式, 凱旋行進 〈+<i>gen</i>;ex [de]+<i>abl</i>〉</div><div class=\"ex\"><i>Pharsalicae pugnae triumphum agere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Pharsalus の合戦の凱旋式を挙げる.</span></div><div class=\"def\"><num>②</num> 凱旋;勝利.</div><div class=\"def\"><num>③</num> 凱歌, 勝利の雄叫び</div><div class=\"ex\"><i>io triumphe</i> (<author>H<small>OR</small></author>)<span class=\"ext\">凱旋万歳!《凱旋行進中の兵士たちと観衆があげる叫び声》.</span></div>\r\n","<div class=\"hw\">triumphālia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://triumphālis\">triumphālis</a>]</div><div class=\"def\">(<i>sc. </i> ornamenta)凱旋将軍の栄誉のしるし.</div>\r\n","<div class=\"hw\">triumphālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[triumphus]</div><div class=\"def\"><num>①</num> 凱旋の</div><div class=\"ex\"><i>porta ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">凱旋門《Campus Martius から Capitolinus 丘の Juppiter 神殿に向かう凱旋行進で最初にくぐる門》.</span></div><div class=\"def\"><num>②</num> 凱旋式を行なったことのある;凱旋将軍の栄誉を授けられたことのある.</div><div class=\"def\"><num>③</num> 祝勝の, 勝ち誇る.</div>\r\n","<div class=\"hw\">triumphātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[triumpho]</div><div class=\"def\"><num>①</num> 凱旋者.</div><div class=\"def\"><num>②</num> Juppiter の呼称の一つ.</div>\r\n","<div class=\"hw\">triumphātōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">凱旋の.</div>\r\n","<div class=\"hw\">triumphō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://triumphus\">triumphus (古形 triumpus)</a>]</div><div class=\"def\"><num>①</num> 凱旋する, 凱旋式を挙げる, 凱旋行進をする 〈ex [de]+<i>abl</i>〉</div><div class=\"ex\"><i>triumphavit Murena de Mithridate</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Murena は Mithridates に勝利して凱旋した</span></div><div class=\"ex\">(impers pass)<i>sine auctoritate senatūs populi jussu triumphatum est</i> (<author>L<small>IV</small></author>)<span class=\"ext\">元老院の決議なしに人民に命令により凱旋式が行なわれた.</span></div><div class=\"def\"><num>②</num> (<i>pass</i>(通例 <i>pp</i>))凱旋行進で見世物にされる;(国・町・民族などが)征服される, 打ち負かされる;捕獲される</div><div class=\"ex\"><i>Roma triumphati caput urbis</i> (<author>O<small>V</small></author>)<span class=\"ext\">征服された世界の首都たるローマ.</span></div><div class=\"def\"><num>③</num> 凱歌をあげる;歓喜する</div><div class=\"ex\"><i>Caesar triumphat de sententia Catonis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Caesar は Cato の意見に大喜びしている.</span></div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 征服する 〈alqm〉.</div>\r\n","<div class=\"hw\">triumvir</div><div class=\"def\">(iii vir とも表記)</div><div class=\"pos\">-virī, <i>m</i>(<i>pl</i><b>triumvirī, trēsvirī</b> triumvirōrum [-um])</div><div class=\"ori\">[tres/vir]</div><div class=\"def\"><num>①</num> (<i>sg</i>)三人委員の一人;(<i>pl</i>)三人委員会</div><div class=\"ex\"><i>～ capitalis</i> (<author>P<small>OMPON</small></author>)<span class=\"ext\">監獄委員《処刑も監督する》</span></div><div class=\"ex\"><i>～ monetalis</i> (<author>P<small>OMPON</small></author>)<span class=\"ext\">造幣委員</span></div><div class=\"ex\"><i>～ coloniae deducendae</i> (<author>L<small>IV</small></author>)<span class=\"ext\">植民地新設委員</span></div><div class=\"ex\"><i>～ agro dando</i> (<author>L<small>IV</small></author>)<span class=\"ext\">(新植民地の)土地配分委員</span></div><div class=\"ex\"><i>～ mensarius</i> (<author>L<small>IV</small></author>)<span class=\"ext\">国家財政委員.</span></div><div class=\"def\"><num>②</num> </div><div class=\"ex\"><i>～ rei publicae constituendae</i> (<author>G<small>ELL</small></author>)<span class=\"ext\">国家再建三人委員《第2回(前43)三頭政治を行なった Antonius, Octavianus, Lepidus のいずれか》.</span></div>\r\n","<div class=\"hw\">triumvirālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://triumvir\">triumvir</a>]</div><div class=\"def\"><num>①</num> 三人委員(会)の.</div><div class=\"def\"><num>②</num> (第2回)三頭政治の.</div>\r\n","<div class=\"hw\">triumvirātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[triumvir]</div><div class=\"def\"><num>①</num> 三人委員の身分[職務].</div><div class=\"def\"><num>②</num> (第2回)三頭政治.</div>\r\n","<div class=\"hw\">trivenēfica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tri-/venefica]</div><div class=\"def\">(喜劇中のののしりことば)極悪の毒盛り女.</div>\r\n","<div class=\"hw\">Trivia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[trivius]</div><div class=\"def\">Diana の添え名《その神殿がしばしば3本の道の合流点にあったことから》</div><div class=\"ex\"><i>lacus Triviae</i><span class=\"ext\">トリウィアの湖《Latium の Aricia 付近の lacus Nemorensis(現 Nemi 湖)の別称;湖畔に Diana の聖林があった》.</span></div>\r\n","<div class=\"hw\">trivium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tri-/via]</div><div class=\"def\"><num>①</num> 3本の道路の合流点, 三叉路.</div><div class=\"def\"><num>②</num> 人通りの多い街路</div><div class=\"ex\"><i>arripere maledictum ex trivio</i> (<author>C<small>IC</small></author>)<span class=\"ext\">悪口を往来の雑踏から拾って来る.</span></div><div class=\"def\"><num>③</num> <SUP>◇</SUP>(初等)三学《中世の大学での七教養科目中, 最初に学ぶ文法・修辞学・論理学の3科目》.</div>\r\n","<div class=\"hw\">trivius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://trivium\">trivium</a>]</div><div class=\"def\">三叉路の</div><div class=\"ex\"><i>trivia virgo</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">三叉路の処女(=<a href=\"entry://Diāna\">Diana</a> または <a href=\"entry://Hecatē\">Hecate</a>).</span></div>\r\n","<div class=\"hw\">triviālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[trivium]</div><div class=\"def\">ありふれた, 普通の, 平俗な.</div>\r\n","<div class=\"hw\">triviāliter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://triviālis\">triviālis</a>]</div><div class=\"def\">普通の仕方で, 通俗的に.</div>\r\n","<div class=\"hw\">triviātim</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[trivium]</div><div class=\"def\">大通りで.</div>\r\n","<div class=\"hw\">Trivīcum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">トリウィークム《Samnium と Apulia の間の山中の小さな町》.</div>\r\n","<div class=\"hw\">triācontas</div><div class=\"pos\">-adis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">30(=<a href=\"entry://trīgintā\">triginta</a>).</div>\r\n","<div class=\"hw\">triāriī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[tres]</div><div class=\"def\">第三戦列(兵)《古参兵から成り, 第一戦列(hastati), 第二戦列(principes)の後ろに位置した》;予備隊[軍].</div>\r\n","<div class=\"hw\">triērarchus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">三段櫂<SUB>かい</SUB>船の船長.</div>\r\n","<div class=\"hw\">triēris<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">三段櫂の.</div><hr><div class=\"hw\">triēris<SUP>2</SUP></div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">三段櫂船.</div>\r\n","<div class=\"hw\">triōbolum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (ギリシアの)3 oboli 貨幣;わずかな金額, 少額.</div><div class=\"def\"><num>②</num> (重量)<img class=\"font\" src=\"img/B151.png\"> drachma.</div>\r\n","<div class=\"hw\">Triōcala</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トリオーカラ《Sicilia 島西部の内陸の町》.</div>\r\n","<div class=\"hw\">Triōcalīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Triocala の.</div><div class=\"hw2\"><b>Triōcalīnī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Triocala の住民.</div>\r\n","<div class=\"hw\">triōnymus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">三つの名をもつ(=<a href=\"entry://trinōminis\">trinominis</a>).</div>\r\n","<div class=\"hw\">triōnēs</div><div class=\"pos\">-ōnum, <i>m pl</i></div><div class=\"def\"><num>①</num> 農耕牛.</div><div class=\"def\"><num>②</num> 〘天〙大熊座と小熊座.</div>\r\n","<div class=\"hw\">trochaeus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘詩〙</div><div class=\"def\"><num>①</num> 長短格(<img class=\"font\" src=\"img/A134.png\"><img class=\"font\" src=\"img/A13C.png\">).</div><div class=\"def\"><num>②</num> 三短格, 短短短格(<img class=\"font\" src=\"img/A13C.png\"><img class=\"font\" src=\"img/A13C.png\"><img class=\"font\" src=\"img/A13C.png\">)(=<a href=\"entry://tribrachys\">tribrachys</a>).</div>\r\n","<div class=\"hw\">trochaicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">長短格から成る.</div>\r\n","<div class=\"hw\">trochantēr</div><div class=\"pos\">-teris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘解・動〙転子.</div><div class=\"def\"><num>②</num> 〘昆〙転節.</div>\r\n","<div class=\"hw\">trochiscus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘薬〙トローチ, 口内錠.</div>\r\n","<div class=\"hw\">troc(h)lea, trochilēa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">滑車.</div>\r\n","<div class=\"hw\">trochleātim</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://troc(h)lea\">troc(h)lea, trochilēa</a>]</div><div class=\"def\">滑車によって.</div>\r\n","<div class=\"hw\">trochoīdeus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘解〙滑車状の.</div>\r\n","<div class=\"hw\">trochus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (遊戯用の)鉄の輪.</div><div class=\"def\"><num>②</num> 〘魚〙「輪魚」《不詳》.</div>\r\n","<div class=\"hw\">Trocmī, Trogmī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トロクミー《小アジア中央部の Galatia 地方にいた一部族》.</div>\r\n","<div class=\"hw\">Troesmis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トロエスミス, <SUP>*</SUP>トロイ-《Moesia Inferior(=東部)の Danubius 川沿いの町》.</div>\r\n","<div class=\"hw\">Troezēn</div><div class=\"pos\">-ēnis [-ēnos], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トロエゼーン, <SUP>*</SUP>トロイ-《Argolis の町;Theseus の生地》.</div>\r\n","<div class=\"hw\">Troezēnius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Troezen の.</div>\r\n","<div class=\"hw\">Troezēnē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トロエゼーネー, <SUP>*</SUP>トロイ-《 (1) =<a href=\"entry://Troezēn\">Troezen</a>.(2) Caria の町》.</div>\r\n","<div class=\"hw\">tropa<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">《碑》至点, (夏・冬)至.</div><hr><div class=\"hw\">tropa<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ころがして</div><div class=\"ex\"><i>～ ludere talo</i> (<author>M<small>ART</small></author>)<span class=\"ext\">さいころ遊びをする.</span></div>\r\n","<div class=\"hw\">tropaeophorus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">勝利の表象を携えている者《Juppiter の呼称の一つ》.</div>\r\n","<div class=\"hw\">tropaeum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 戦勝記念碑《古くは木の幹に敗走させた敵の武具などを吊るしただけのもの;のちに大理石や青銅製となった》</div><div class=\"ex\"><i>sistere Romae tropaea de Parthis</i> (<author>T<small>AC</small></author>)<span class=\"ext\">ローマ市に Parthia 征服の記念碑を築く.</span></div><div class=\"def\"><num>②</num> 勝利.</div><div class=\"def\"><num>③</num> 記念(品), しるし.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 墓.</div>\r\n","<div class=\"hw\">Trophōnius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トロポーニウス, <SUP>*</SUP>-オス《 (1) 〘伝説〙兄弟の Agamedes とともに Delphi の Apollo 神殿を建てた建築家.(2) 〘神話〙Boeotia の Lebadia に近い地下の洞穴で神託を下した神》.</div>\r\n","<div class=\"hw\">Trophōniānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Trophonius の.</div>\r\n","<div class=\"hw\">tropica</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[tropicus<SUP>1</SUP>]</div><div class=\"def\">(趣味・風俗などの)変化, 変遷.</div>\r\n","<div class=\"hw\">tropicus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tropus]</div><div class=\"def\"><num>①</num> 〘天〙分点の, 至点の;回帰線の.</div><div class=\"def\"><num>②</num> 〘修〙転義的な, 比喩的な.</div><hr><div class=\"hw\">tropicus<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">(<i>sc. </i> circulus)回帰線.</div>\r\n","<div class=\"hw\">tropicē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://tropicus\">tropicus<SUP>1</SUP></a>]</div><div class=\"def\">比喩的に.</div>\r\n","<div class=\"hw\">tropis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ぶどう酒の滓<SUB>おり</SUB>.</div>\r\n","<div class=\"hw\">tropologia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">比喩的表現[語法].</div>\r\n","<div class=\"hw\">tropologicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tropologia]</div><div class=\"def\">比喩的な.</div>\r\n","<div class=\"hw\">tropologicē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://tropologicus\">tropologicus</a>]</div><div class=\"def\">比喩的に.</div>\r\n","<div class=\"hw\">tropus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘修〙(語の)転義的使用, 比喩.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 歌, 旋律;旋法.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 典礼聖歌に付け加えられた旋律および説明的歌詞.</div>\r\n","<div class=\"hw\">trossulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 初期ローマの騎士《その名は彼らが Etruria の町 Trossulum を歩兵の支援なしに征服したことに由来するという》.</div><div class=\"def\"><num>②</num> (蔑称として)めかし屋, だて男.</div>\r\n","<div class=\"hw\">troxallis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘昆〙イナゴの一種.</div>\r\n","<div class=\"hw\">Tr. Pl.</div><div class=\"def\">《略》=tribunus plebis.</div>\r\n","<div class=\"hw\">trua</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 攪拌用大さじ, 杓子<SUB>しゃくし</SUB>, ひしゃく.</div><div class=\"def\"><num>②</num> (台所の)排水管[溝].</div>\r\n","<div class=\"hw\">tructa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i>, <B>tructus</B> -ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘魚〙マス(鱒)の一種.</div>\r\n","<div class=\"hw\">truculente</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[truculentus]</div><div class=\"def\">荒々しく, 獰猛に.</div>\r\n","<div class=\"hw\">truculenter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"def\">=<a href=\"entry://truculente\">truculente</a>.</div>\r\n","<div class=\"hw\">truculentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://truculentus\">truculentus</a>]</div><div class=\"def\"><num>①</num> 凶暴, 残忍.</div><div class=\"def\"><num>②</num> (気候の)厳しさ.</div>\r\n","<div class=\"hw\">truculentus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[trux]</div><div class=\"def\"><num>①</num> 狂暴な, 獰猛<SUB>どうもう</SUB>な, 残忍な</div><div class=\"ex\"><i>Galatea fetā truculentior ursā</i> (<author>O<small>V</small></author>)<span class=\"ext\">腹に仔をもつ雌熊よりも凶暴な Galatea.</span></div><div class=\"def\"><num>②</num> 過激な, 激しい.</div>\r\n","<div class=\"hw\">trucīdātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[trucido]</div><div class=\"def\"><num>①</num> 虐殺, 殺戮<SUB>さつりく</SUB>.</div><div class=\"def\"><num>②</num> 剪定.</div>\r\n","<div class=\"hw\">trucīdātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://trucīdō\">trucīdō</a>]</div><div class=\"def\">殺害者.</div>\r\n","<div class=\"hw\">trucīdō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[trux/caedo]</div><div class=\"def\"><num>①</num> 虐殺する, 殺戮する;(動物を)屠殺する.</div><div class=\"def\"><num>②</num> ひどい目にあわせる</div><div class=\"ex\"><i>faenore trucidari</i> (<author>C<small>IC</small></author>)<span class=\"ext\">高利の借金で身代をつぶす.</span></div><div class=\"def\"><num>③</num> 《詩》(火を)消す.</div>\r\n","<div class=\"hw\">trudis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://trūdō\">trūdō</a>]</div><div class=\"def\">先端がとがった棒, 突き棒.</div>\r\n","<div class=\"hw\">Truentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">トルエントゥム《Picenum の Truentus(現 Tronto)川の河口の町;Castrum Truentinum とも呼ばれた》.</div>\r\n","<div class=\"hw\">trulla</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[trua]</div><div class=\"def\"><num>①</num> (小さな)ひしゃく, 杓子.</div><div class=\"def\"><num>②</num> おまる《室内用便器》.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 小鍋.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>(左官の)鏝<SUB>こて</SUB>.</div>\r\n","<div class=\"hw\">trulleus</div><div class=\"pos\">-ī, <i>m</i>, <B>-um</B> -ī, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://trulla\">trulla</a>]</div><div class=\"def\">たらい[洗面器](状の容器).</div>\r\n","<div class=\"hw\">trullissātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://trullissō\">trullissō</a>]</div><div class=\"def\">(漆喰などの)下塗り.</div>\r\n","<div class=\"hw\">trullissō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[trulla]</div><div class=\"def\">(漆喰<SUB>しっくい</SUB>などで)下塗りをする.</div>\r\n","<div class=\"hw\">trulliō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>m</i></div><div class=\"def\">=<a href=\"entry://trulleus\">trulleus</a>.</div>\r\n","<div class=\"hw\">truncus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> (身体の一部を切り取られて[奪われて])不具にされた, もぎ取られた.</div><div class=\"def\"><num>②</num> (枝を)払われた.</div><div class=\"def\"><num>③</num> 生長の止まった;(...を)欠いている 〈+<i>gen [abl]</i>〉</div><div class=\"ex\"><i>animalia trunca pedum</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">脚のない生き物.</span></div><div class=\"def\"><num>④</num> 完全でない, 不備な.</div><hr><div class=\"hw\">truncus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://truncus\">truncus<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> (人間の)胴, 胴体.</div><div class=\"def\"><num>②</num> 木の幹, 樹幹.</div><div class=\"def\"><num>③</num> でくのぼう, のろま.</div><div class=\"def\"><num>④</num> 〘建〙(円柱の)柱身;台胴.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘解〙(血管・神経などの)幹.</div>\r\n","<div class=\"hw\">truncātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://truncō\">truncō</a>]</div><div class=\"def\">(手足などの)切断.</div>\r\n","<div class=\"hw\">truncō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://truncus\">truncus<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> (手足などを切り取って身体を)不具にする, 切り殺す;ひどくそこなう</div><div class=\"ex\"><i>semusta</i>, <i>truncata simulacra deum</i> (<author>L<small>IV</small></author>)<span class=\"ext\">半分焼けて見る影もなくなった神々の像.</span></div><div class=\"def\"><num>②</num> (木を)切り倒す;(枝葉を)払う.</div>\r\n","<div class=\"hw\">trutina</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">秤<SUB>はかり</SUB>, 天秤<SUB>てんびん</SUB>.</div>\r\n","<div class=\"hw\">trutinātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[trutino]</div><div class=\"def\">(重さを)量ること, 秤量<SUB>ひょうりょう</SUB>.</div>\r\n","<div class=\"hw\">trutinātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://trutinō\">trutinō</a>]</div><div class=\"def\">量る人;評価[判定]する人.</div>\r\n","<div class=\"hw\">trutinō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[trutina]</div><div class=\"def\">(重さを)量る;評定する.</div>\r\n","<div class=\"hw\">trux</div><div class=\"pos\">-ucis, <i>adj</i></div><div class=\"def\"><num>①</num> 恐ろしい, ぞっとさせる;情け容赦もない, 残忍な.</div><div class=\"def\"><num>②</num> (動物が)凶暴な, 獰猛<SUB>どうもう</SUB>な.</div><div class=\"def\"><num>③</num> (天候などが)厳しい, 荒々しい, 激しい.</div>\r\n","<div class=\"hw\">truō<SUP>1</SUP></div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[<i>cf. </i> trua]</div><div class=\"def\">(さじで)かきまわす.</div><hr><div class=\"hw\">truō<SUP>2</SUP></div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">〘鳥〙ペリカン.</div>\r\n","<div class=\"hw\">tryblium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">皿[盆]の一種.</div>\r\n","<div class=\"hw\">trychnum, -on</div><div class=\"pos\">-ī, <i>n</i>, <B>-os</B> -ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://strychnos\">strychnos</a>.</div>\r\n","<div class=\"hw\">tryginon</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(ぶどう酒の澱<SUB>おり</SUB>で作られる)黒の顔料.</div>\r\n","<div class=\"hw\">trygētus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ブドウの収穫;新しいぶどう酒.</div>\r\n","<div class=\"hw\">tryx</div><div class=\"pos\">-ygis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">新しいぶどう酒;発酵前のブドウ液.</div>\r\n","<div class=\"hw\">trȳgōn</div><div class=\"pos\">-onis [-onos], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘魚〙アカエイ.</div><div class=\"def\"><num>②</num> 〘鳥〙コキジバト.</div>\r\n","<div class=\"hw\">trȳgōnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://trȳgōn\">trygon 1</a>.</div>\r\n","<div class=\"hw\">trā-</div><div class=\"pos\"><i>pref</i></div><div class=\"def\">⇒<a href=\"entry://trans-\">trans-</a>.</div>\r\n","<div class=\"hw\">Trāchās</div><div class=\"pos\">-antis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://Tarracīna\">Tarracina</a>.</div>\r\n","<div class=\"hw\">trāchēa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> =<a href=\"entry://trāchīa\">trachia</a>.</div><div class=\"def\"><num>②</num> 〘植〙導管.</div>\r\n","<div class=\"hw\">trāchēītis</div><div class=\"pos\">-tidis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙気管炎.</div>\r\n","<div class=\"hw\">trāchīa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘解〙気管.</div>\r\n","<div class=\"hw\">Trāchīn</div><div class=\"pos\">-īnis [-īnos], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トラーキーン, <SUP>*</SUP>トラーキース《Thessalia の Oeta 山麓の町》.</div>\r\n","<div class=\"hw\">Trāchīniae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[↓<a href=\"entry://Trāchīnius\">Trāchīnius</a>]</div><div class=\"def\">「トラーキースの女たち」《Sophocles の悲劇の題名》.</div>\r\n","<div class=\"hw\">Trāchīnius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Trachin の.</div>\r\n","<div class=\"hw\">trāchōma</div><div class=\"pos\">-atis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙トラコーマ, トラホーム《眼病》.</div>\r\n","<div class=\"hw\">trādidī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://trādō\">trado</a>.</div>\r\n","<div class=\"hw\">trāditiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[trado]</div><div class=\"def\"><num>①</num> (商品などの)引渡し.</div><div class=\"def\"><num>②</num> (降服時の身柄・領土などの)引渡し, 明渡し.</div><div class=\"def\"><num>③</num> (知識などを)伝えること, 教育;伝承.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 翻訳.</div>\r\n","<div class=\"hw\">trāditor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[trado]</div><div class=\"def\"><num>①</num> 裏切り者(=<a href=\"entry://prōditor\">proditor</a>).</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 伝える人;教師.</div>\r\n","<div class=\"hw\">trāditus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://trādō\">trado</a>.</div><hr><div class=\"hw\">trāditus<SUP>2</SUP></div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"def\">伝承, 伝統.</div>\r\n","<div class=\"hw\">trāductiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://trādūcō\">trādūcō</a>]</div><div class=\"def\"><num>①</num> (ある場所から他へ)運ぶ[運搬する]こと.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 凱旋<SUB>がいせん</SUB>式で(捕虜を)行進させること.</div><div class=\"def\"><num>③</num> さらしものにすること.</div><div class=\"def\"><num>④</num> (時の)経過.</div><div class=\"def\"><num>⑤</num> (身分の)変更, 移籍.</div><div class=\"def\"><num>⑥</num> 〘修〙換喩.</div><div class=\"def\"><num>⑦</num> 〘修〙同一語の反復.</div>\r\n","<div class=\"hw\">trāductor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[traduco]</div><div class=\"def\">(身分を)移籍させる者.</div>\r\n","<div class=\"hw\">trāductus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://trādūcō\">traduco</a>.</div><hr><div class=\"hw\">trāductus<SUP>2</SUP></div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"def\">通路.</div>\r\n","<div class=\"hw\">trādux</div><div class=\"pos\">-ucis, <i>m</i></div><div class=\"ori\">[traduco]</div><div class=\"def\"><num>①</num> 〘植〙(ブドウ園内の木から木へ渡した)ブドウのつる.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 媒介.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>(原罪の)継承.</div>\r\n","<div class=\"hw\">trāduxī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://trādūcō\">traduco</a>.</div>\r\n","<div class=\"hw\">trādō</div><div class=\"pos\">-ere -didī -ditum, <i>tr</i></div><div class=\"ori\">[trans-/do]</div><div class=\"def\"><num>①</num> 手渡す, 与える.</div><div class=\"def\"><num>②</num> 引き[明け]渡す</div><div class=\"ex\"><i>armis traditis </i>(<author>C<small>AES</small></author>)<span class=\"ext\">武器を引き渡して.</span></div><div class=\"def\"><num>③</num> ゆだねる, 託す</div><div class=\"ex\"><i>alci neptem tradere</i> (<author>T<small>AC</small></author>)<span class=\"ext\">孫娘をある男の嫁にやる.</span></div><div class=\"def\"><num>④</num> 紹介する, 推薦する 〈alqm alci〉.</div><div class=\"def\"><num>⑤</num> 残す, 伝える;報告する, 物語る</div><div class=\"ex\"><i>traditum est</i> 〈+<i>acc c. inf</i>〉 (<author>C<small>IC</small></author>) = <i>traditur memoriae</i> 〈+<i>acc c. inf</i>〉 (<author>L<small>IV</small></author>)<span class=\"ext\">...と伝えられている.</span></div><div class=\"def\"><num>⑥</num> 教える.</div><div class=\"def\"><num>⑦</num> (<i>refl</i>)身をまかせる[差し出す];降服する</div><div class=\"ex\"><i>se totos voluptatibus tradere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">すっかり快楽にふけっている.</span></div>\r\n","<div class=\"hw\">trādūciānī</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://trādūcō\">trādūcō</a>]</div><div class=\"def\">原罪の継承を信じる人々《ペラギウス派の人々がカトリック教徒に与えた名称》.</div>\r\n","<div class=\"hw\">trādūcō</div><div class=\"pos\">-ere -duxī -ductum, <i>tr</i></div><div class=\"ori\">[trans-/duco]</div><div class=\"def\"><num>①</num> (ある場所から他へ)連れて来る, 連行する.</div><div class=\"def\"><num>②</num> (物のある場所を)変える, 移す.</div><div class=\"def\"><num>③</num> 横断させる, 渡らせる</div><div class=\"ex\"><i>vadis partem copiarum traducere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">浅瀬で軍勢の一部を渡河させる</span></div><div class=\"ex\">(渡る対象の <i>acc</i> と)<i>flumen Axonam exercitum traducere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">軍隊に Axona 川を渡らせる.</span></div><div class=\"def\"><num>④</num> (見世物[さらしもの]にするために)行進させる, 運ぶ.</div><div class=\"def\"><num>⑤</num> </div><div class=\"ex\"><i>equum traducere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(ローマ騎士が自分の)馬を引いて通る(=<a href=\"entry://censor\">censor</a> による身分審査に合格した).</span></div><div class=\"def\"><num>⑥</num> 見せる, 示す, 公表する.</div><div class=\"def\"><num>⑦</num> (ある時期を)過ごす.</div><div class=\"def\"><num>⑧</num> 遂行する.</div><div class=\"def\"><num>⑨</num> (習慣・態度などを)変えさせる, (別の物へと)向かわせる.</div><div class=\"def\"><num>⑩</num> (別な身分・地位に)つける, 置く</div><div class=\"ex\"><i>Clodium a patribus ad plebem traducere</i> (<author>S<small>UET</small></author>)<span class=\"ext\">Clodius を貴族から平民に移籍する.</span></div><div class=\"def\"><num>⑪</num> 翻訳する.</div><div class=\"def\"><num>⑫</num> 〘文〙(語を)派生させる, 派生語をつくる.</div><div class=\"def\"><num>⑬</num> <SUP>◇</SUP> 非難する.</div><div class=\"def\"><num>⑭</num> <SUP>◇</SUP>(原罪を)受け継ぐ.</div><div class=\"def\"><num>⑮</num> <SUP>◇</SUP> 惑わす, 堕落させる.</div>\r\n","<div class=\"hw\">trāgula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[traho]</div><div class=\"def\"><num>①</num> (Gallia 人や Hispania 人の)革ひも付きの投げ槍.</div><div class=\"def\"><num>②</num> 一種の引網.</div><div class=\"def\"><num>③</num> (牛馬に引かせる農作物運搬用の)そり.</div><div class=\"def\"><num>④</num> わな, 策略.</div>\r\n","<div class=\"hw\">trāgum<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">引網.</div>\r\n","<div class=\"hw\">trāiciō</div><div class=\"pos\">-cere, <i>tr</i></div><div class=\"def\">=<a href=\"entry://trājiciō\">trajicio</a>.</div>\r\n","<div class=\"hw\">trājectiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[trajicio]</div><div class=\"def\"><num>①</num> 移動;横断.</div><div class=\"def\"><num>②</num> 〘修〙(語・文字の)転置, 転位.</div><div class=\"def\"><num>③</num> 〘修〙(責任などの)転嫁(法).</div><div class=\"def\"><num>④</num> 〘修〙誇張(法).</div>\r\n","<div class=\"hw\">trājector</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[trajicio]</div><div class=\"def\">貫通するもの.</div>\r\n","<div class=\"hw\">trājectus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://trājiciō\">trajicio</a>.</div><hr><div class=\"hw\">trājectus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 渡ること, 横断.</div><div class=\"def\"><num>②</num> 船着き場.</div>\r\n","<div class=\"hw\">trājectīcius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[trajicio]</div><div class=\"def\">商品の海上輸送のために融資された</div><div class=\"ex\"><i>trajecticia pecunia</i><span class=\"ext\">〘法〙冒険貸借《船舶が無事帰還した場合に返済する高利の金銭貸借》.</span></div>\r\n","<div class=\"hw\">trājectūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[trajicio]</div><div class=\"def\">突出部.</div>\r\n","<div class=\"hw\">trājicere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://trājiciō\">trajicio</a>.</div>\r\n","<div class=\"hw\">trājiciō</div><div class=\"pos\">-cere -jēcī -jectum, <i>tr</i>(<i>intr</i>)</div><div class=\"ori\">[trans-/jacio]</div><div class=\"def\"><num>①</num> (向こうへ)投げる.</div><div class=\"def\"><num>②</num> (橋などを)かけ渡す, 渡す.</div><div class=\"def\"><num>③</num> 貫く, 突き通す, 射抜く;突き刺す[立てる].</div><div class=\"def\"><num>④</num> 移す, 移動させる;渡らせる, 移動[横断]させる</div><div class=\"ex\"><i>legiones in Siciliam trajicere</i> (<author>L<small>IV</small></author>)<span class=\"ext\">軍団を Sicilia へ渡海させる</span></div><div class=\"ex\">(渡る場所の <i>acc</i> と)<i>equitum magnam partem flumen trajecit</i> (<author>C<small>AES</small></author>)<span class=\"ext\">彼は騎兵の大部分を対岸へ渡した.</span></div><div class=\"def\"><num>⑤</num> 渡る, 横断する.</div><div class=\"def\"><num>⑥</num> 〘修〙(語の)位置を変える, 転置させる.</div>\r\n","<div class=\"hw\">Trājānus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トライヤーヌス, <SUP>∥</SUP>トラヤヌス《<i>M. Ulpius ～</i>, ローマ皇帝(在位98‐117)》.</div>\r\n","<div class=\"hw\">trājēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://trājiciō\">trajicio</a>.</div>\r\n","<div class=\"hw\">trāl-</div><div class=\"def\">⇒transl-.</div>\r\n","<div class=\"hw\">trām-</div><div class=\"def\">⇒transm-.</div>\r\n","<div class=\"hw\">trāma</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf</i>. traho]</div><div class=\"def\"><num>①</num> 縦糸.</div><div class=\"def\"><num>②</num> (クモの)巣.</div><div class=\"def\"><num>③</num> </div><div class=\"ex\"><i>～ figurae</i> (<author>P<small>ERS</small></author>)<span class=\"ext\">やせてひょろひょろした人</span></div><div class=\"ex\"><i>tramae putidae</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">腐ったくず糸(=一文の値打ちもない物).</span></div>\r\n","<div class=\"hw\">trāmen</div><div class=\"pos\">-minis, <SUP>◇</SUP><i>n</i></div><div class=\"def\"><num>①</num> 横糸.</div><div class=\"def\"><num>②</num> より糸.</div>\r\n","<div class=\"hw\">trāmes</div><div class=\"pos\">-mitis, <i>m</i></div><div class=\"ori\">[trans-/meo]</div><div class=\"def\"><num>①</num> 脇道, 間道, 小道.</div><div class=\"def\"><num>②</num> 川床, 水路.</div><div class=\"def\"><num>③</num> 進路, 行路.</div><div class=\"def\"><num>④</num> 狭く細長い土地.</div><div class=\"def\"><num>⑤</num> (家族の)分家.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP>(本のページの)縦の欄.</div>\r\n","<div class=\"hw\">trāmosēricus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[trama/Sericus]</div><div class=\"def\">縦糸が亜麻で横糸が絹の.</div>\r\n","<div class=\"hw\">trānatō, trānō</div><div class=\"def\">⇒<a href=\"entry://transnatō\">transnato</a>, <a href=\"entry://transnō\">transno</a>.</div>\r\n","<div class=\"hw\">trāv-</div><div class=\"def\">⇒transv-.</div>\r\n","<div class=\"hw\">Trēbula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">トレーブラ《 (1) Campania の町.(2) Sabini 族の町》.</div>\r\n","<div class=\"hw\">Trēbulānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Trebula の.</div><div class=\"hw2\"><b>Trēbulānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Trebula の住民.</div>\r\n","<div class=\"hw\">trēs</div><div class=\"pos\">trēs tria, <i>num card</i></div><div class=\"def\">3(の);三つの.</div>\r\n","<div class=\"hw\">Trēs Tabernae</div><div class=\"pos\">-ium -ārum, <i>f pl</i></div><div class=\"def\">トレース・タベルナエ《Latium にあった Via Appia 沿いの地名;「三軒茶屋」 の意》.</div>\r\n","<div class=\"hw\">trēsvirī</div><div class=\"pos\">triumvirōrum, <i>m pl</i></div><div class=\"def\">=triumviri(⇒ <a href=\"entry://triumvir\">triumvir</a>).</div>\r\n","<div class=\"hw\">Trēvericus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Treveri 族の.</div>\r\n","<div class=\"hw\">Trēverī, Trēvirī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">トレーウェリー《Gallia Belgica にいた一部族》</div><div class=\"ex\"><i>Augusta Treverorum</i> (<author>M<small>ELA</small></author>)<span class=\"ext\">アウグスタ・トレーウェロールム《Treveri 族の町;現 Trier》.</span></div>\r\n","<div class=\"hw\">trībula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://trībulum\">tribulum</a>.</div>\r\n","<div class=\"hw\">trībulum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tero]</div><div class=\"def\">脱穀板.</div>\r\n","<div class=\"hw\">trībulātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tribulo]</div><div class=\"def\">苦難, 苦しみ.</div>\r\n","<div class=\"hw\">trībulō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[tribulum]</div><div class=\"def\"><num>①</num> 強く押す, 搾り出す.</div><div class=\"def\"><num>②</num> (税を)きびしく取り立てる.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 苦しめる, さいなむ.</div>\r\n","<div class=\"hw\">trīcae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\"><num>①</num> つまらないこと[物].</div><div class=\"def\"><num>②</num> 面倒[厄介]なこと.</div>\r\n","<div class=\"hw\">trīcennium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[triginta/annus]</div><div class=\"def\">30年(間).</div>\r\n","<div class=\"hw\">trīcennālia</div><div class=\"pos\">-ium [-iōrum], <SUP>◇</SUP><i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://trīcennālis\">trīcennālis</a>]</div><div class=\"def\">皇帝統治30周年記念祭.</div>\r\n","<div class=\"hw\">trīcennālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://trīcennium\">trīcennium</a>]</div><div class=\"def\">30年の.</div>\r\n","<div class=\"hw\">trīcensimus, -cēsimus</div><div class=\"pos\">-a -um, <i>num ord</i></div><div class=\"ori\">[triginta]</div><div class=\"def\">第30の, 30番目の;30分の1の.</div>\r\n","<div class=\"hw\">trīcessis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[triginta/as]</div><div class=\"def\">30 asses 貨.</div>\r\n","<div class=\"hw\">trīciens, -ēs</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[triginta]</div><div class=\"def\">30回[度・倍].</div>\r\n","<div class=\"hw\">trīclīniarchēs, -a</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">食堂の支配人.</div>\r\n","<div class=\"hw\">trīclīnium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 食事用臥台.</div><div class=\"def\"><num>②</num> 食堂.</div>\r\n","<div class=\"hw\">trīclīniāria</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://trīclīniāris\">trīclīniāris</a>]</div><div class=\"def\"><num>①</num> 食堂.</div><div class=\"def\"><num>②</num> 食事用臥台<SUB>がだい</SUB>の掛け布.</div>\r\n","<div class=\"hw\">trīclīniāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[triclinium]</div><div class=\"def\"><num>①</num> 食堂の.</div><div class=\"def\"><num>②</num> 食事用臥台の.</div>\r\n","<div class=\"hw\">trīclīniārius</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://trīclīnium\">trīclīnium</a>]</div><div class=\"def\">給仕奴隷.</div>\r\n","<div class=\"hw\">trīclīnār-</div><div class=\"def\">⇒tricliniar-.</div>\r\n","<div class=\"hw\">trīcor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[tricae]</div><div class=\"def\">言いのがれをする</div><div class=\"ex\"><i>tecum tricatus est</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼はきみをうまくごまかした.</span></div>\r\n","<div class=\"hw\">trīcēnārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://trīcēnī\">trīcēnī</a>]</div><div class=\"def\"><num>①</num> 30の, 30から成る.</div><div class=\"def\"><num>②</num> 30歳の.</div>\r\n","<div class=\"hw\">trīcēnī</div><div class=\"pos\">-ae -a, <i>num distrib</i></div><div class=\"ori\">[triginta]</div><div class=\"def\"><num>①</num> 30ずつの, それぞれ30の.</div><div class=\"def\"><num>②</num> 30の(=<a href=\"entry://trīgintā\">triginta</a>).</div>\r\n","<div class=\"hw\">trīcēsima</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tricensimus]</div><div class=\"def\">新月.</div>\r\n","<div class=\"hw\">trīcēsimārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tricensimus]</div><div class=\"def\">毎月の, 30日ごとの.</div>\r\n","<div class=\"hw\">trīcō<SUP>1</SUP></div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"def\">(<i>refl</i>)</div><div class=\"def\"><num>①</num> ぐずぐずする, 遅れる.</div><div class=\"def\"><num>②</num> 苦しむ, 苦悩する.</div><hr><div class=\"hw\">trīcō<SUP>2</SUP></div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[tricae]</div><div class=\"def\">言いのがれをする[うまくごまかす]者.</div>\r\n","<div class=\"hw\">trīcōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tricae]</div><div class=\"def\">ごまかし上手な, ずる賢い.</div>\r\n","<div class=\"hw\">trīduum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tri-/dies]</div><div class=\"def\"><num>①</num> 3日間.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 3日間の断食.</div>\r\n","<div class=\"hw\">trīduānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://trīduum\">trīduum</a>]</div><div class=\"def\">3日間の, 3日続く.</div>\r\n","<div class=\"hw\">trīga</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tri-/<i>cf</i>. bigae]</div><div class=\"def\"><num>①</num> 3頭立て(の戦車).</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 三つ一組のもの, 三つ組.</div>\r\n","<div class=\"hw\">trīgintā</div><div class=\"pos\"><i>indecl num card</i></div><div class=\"def\">30(の).</div>\r\n","<div class=\"hw\">trīgārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[triga]</div><div class=\"def\"><num>①</num> (戦車用馬の)調教場, 調馬場.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 三つ一組.</div>\r\n","<div class=\"hw\">trīgārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">triga (1) の御者.</div>\r\n","<div class=\"hw\">trīmulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://trīmus\">trīmus</a>]</div><div class=\"def\">3歳の, 生後3年の.</div>\r\n","<div class=\"hw\">trīmus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tri-/hiems]</div><div class=\"def\">3歳の.</div>\r\n","<div class=\"hw\">trīmātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[trimus]</div><div class=\"def\">3歳.</div>\r\n","<div class=\"hw\">Trīnacria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Sicilia 島の古名.</div>\r\n","<div class=\"hw\">Trīnacris<SUP>1</SUP></div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"def\">Trinacria(=<a href=\"entry://Sicilia\">Sicilia</a>)の.</div><hr><div class=\"hw\">Trīnacris<SUP>2</SUP></div><div class=\"pos\">-idis, <i>f</i></div><div class=\"def\">=<a href=\"entry://Trīnacria\">Trinacria</a>.</div>\r\n","<div class=\"hw\">Trīnacrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Trinacria(=<a href=\"entry://Sicilia\">Sicilia</a>)の.</div>\r\n","<div class=\"hw\">trīnitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://trīnī\">trīnī</a>]</div><div class=\"def\"><num>①</num> 三つ一組, 三つ揃い.</div><div class=\"def\"><num>②</num> 〘神学〙三位一体.</div>\r\n","<div class=\"hw\">trīnus</div><div class=\"pos\">-a -um, <i>adj</i>(trini の <i>sg</i>(稀用))</div><div class=\"def\"><num>①</num> 3度(目)の;三つの部分から成る.</div><div class=\"def\"><num>②</num> <i>trinum nundinum</i> ⇒ <a href=\"entry://nundinum\">nundinum</a>.</div>\r\n","<div class=\"hw\">trīnī</div><div class=\"pos\">-ae -a, <i>num distrib</i></div><div class=\"ori\">[tres]</div><div class=\"def\"><num>①</num> 三つずつの, 一度[一時期]に三つの.</div><div class=\"def\"><num>②</num> 三つの, 3の.</div><div class=\"def\"><num>③</num> 3倍[3重]の.</div>\r\n","<div class=\"hw\">trīticeus, -cius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[triticum]</div><div class=\"def\"><num>①</num> 小麦の, 小麦でつくった.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘病〙麦粒様の.</div>\r\n","<div class=\"hw\">trīticiārius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[triticum]</div><div class=\"def\">小麦に関する.</div>\r\n","<div class=\"hw\">trīticum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tritus<SUP>1</SUP>]</div><div class=\"def\">〘植〙小麦.</div>\r\n","<div class=\"hw\">trīticīnus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://trīticeus\">triticeus 1</a>.</div>\r\n","<div class=\"hw\">Trītogenīa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Minerva の添え名《女神が Triton 川のほとりで誕生したとの伝承があることから》.</div>\r\n","<div class=\"hw\">trītor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[tero]</div><div class=\"def\"><num>①</num> すり減らす者.</div><div class=\"def\"><num>②</num> (顔料を)する[砕く]人.</div>\r\n","<div class=\"hw\">trītus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[tero]</div><div class=\"def\"><num>①</num> すりへった, すりきれた;(道が)踏みならされた.</div><div class=\"def\"><num>②</num> よく用いられる, ありふれた.</div><div class=\"def\"><num>③</num> 経験を積んだ, 熟練した</div><div class=\"ex\"><i>aures tritae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(文学的に)とぎすまされた耳.</span></div><div class=\"def\"><num>④</num> 碾<SUB>ひ</SUB>いた, 粉にした.</div><hr><div class=\"hw\">trītus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">こすること, 摩擦.</div>\r\n","<div class=\"hw\">Trītōn</div><div class=\"pos\">-ōnis [-ōnos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トリートーン《 (1) 〘神話〙Neptunus の息子;父神の言いつけでほら貝を吹き鳴らして波を立てたり静めたりする半人半魚の海神.(2) Africa の Tritonis 湖から Syrtis minor に注ぐ川.(3) <SUP>◇</SUP>Thracia の湖沼》.</div>\r\n","<div class=\"hw\">Trītōnia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Minerva の添え名.</div>\r\n","<div class=\"hw\">Trītōniacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Tritonia(=<a href=\"entry://Minerva\">Minerva</a>)の</div><div class=\"ex\"><i>Tritoniaca harundo</i> (<author>O<small>V</small></author>)<span class=\"ext\">Minerva の考案したアシ(葦)笛</span></div><div class=\"ex\"><i>Tritoniaca palus</i> (<author>O<small>V</small></author>)<span class=\"ext\">Pallene 付近の湖沼.</span></div>\r\n","<div class=\"hw\">Trītōnis<SUP>1</SUP></div><div class=\"pos\">-idis, <i>adj f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Tritonis 湖の.</div><div class=\"def\"><num>②</num> Minerva の</div><div class=\"ex\">～ <i>pinus</i> (<author>O<small>V</small></author>)<span class=\"ext\">Minerva の(指示で)松(材から建造された Argo 船).</span></div><hr><div class=\"hw\">Trītōnis<SUP>2</SUP></div><div class=\"pos\">-idis [-idos], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> トリートーニス《Africa の湖》.</div><div class=\"def\"><num>②</num> =<a href=\"entry://Minerva\">Minerva</a>.</div><div class=\"def\"><num>③</num> オリーブの木《Minerva の聖木》.</div>\r\n","<div class=\"hw\">Trītōnius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Triton 川の</div><div class=\"ex\"><i>Tritonia Pallas [virgo]</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">=<a href=\"entry://Minerva\">Minerva</a>.</span></div>\r\n","<div class=\"hw\">trītūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tero]</div><div class=\"def\"><num>①</num> こすること.</div><div class=\"def\"><num>②</num> 脱穀.</div><div class=\"def\"><num>③</num> こねる[練る]こと.</div>\r\n","<div class=\"hw\">trītūrātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[trituro]</div><div class=\"def\">脱穀.</div>\r\n","<div class=\"hw\">trītūrātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://trītūrō\">trītūrō</a>]</div><div class=\"def\">脱穀する人.</div>\r\n","<div class=\"hw\">trītūrō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[tritura]</div><div class=\"def\"><num>①</num> 脱穀する.</div><div class=\"def\"><num>②</num> 責めさいなむ.</div>\r\n","<div class=\"hw\">trīvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://terō\">tero</a>.</div>\r\n","<div class=\"hw\">Trōas<SUP>1</SUP></div><div class=\"pos\">-adis [-ados], <i>adj f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Troja の.</div><hr><div class=\"hw\">Trōas<SUP>2</SUP></div><div class=\"pos\">-adis [-ados], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Troja の女.</div><div class=\"def\"><num>②</num> トローアス《Troja を中心とする小アジアの一地方》.</div>\r\n","<div class=\"hw\">Trōes</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">⇒<a href=\"entry://Trōs\">Tros</a>.</div>\r\n","<div class=\"hw\">Trōgilī</div><div class=\"pos\">-orum, <i>m pl</i></div><div class=\"def\">トローギリー《Syracusae 市北部の Trogilus 港の住民》.</div>\r\n","<div class=\"hw\">Trōg(l)odytae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">トローグロデュタエ, <SUP>*</SUP>-タイ《Aethiopia の穴居人》.</div>\r\n","<div class=\"hw\">Trōia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://Trōja\">Troja</a>.</div>\r\n","<div class=\"hw\">Trōiades</div><div class=\"pos\">-um, <i>f pl</i></div><div class=\"def\">⇒<a href=\"entry://Trōas\">Troas<SUP>2</SUP> 1</a>.</div>\r\n","<div class=\"hw\">Trōicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Troja(人)の.</div>\r\n","<div class=\"hw\">Trōilus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙トローイルス, <SUP>*</SUP>-ロス《Troja の王 Priamus の息子;Achilles に殺された》.</div>\r\n","<div class=\"hw\">Trōius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">Troja(人)の.</div>\r\n","<div class=\"hw\">Trōja</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> トロイヤ, <SUP>*</SUP>トロイアー, <SUP>∥</SUP>トロイ《 (1) 小アジア北西部の Phrygia の町;Homerus の叙事詩 <i>Illias</i> の舞台(別名 Ilion, Ilium).(2) Troja を逃れた Aeneas と Helenus がそれぞれ Laurentum 付近と Epirus に建てた町》.</div><div class=\"def\"><num>②</num> ローマの元老院議員の子弟による騎馬模擬戦(別称 lusus Trojae).</div>\r\n","<div class=\"hw\">Trōjugena<SUP>1</SUP></div><div class=\"pos\">-ae, <i>adj m</i>, <i>f</i></div><div class=\"ori\">[Troja/gigno]</div><div class=\"def\">Troja 生まれの.</div><hr><div class=\"hw\">Trōjugena<SUP>2</SUP></div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\"><num>①</num> Troja 人.</div><div class=\"def\"><num>②</num> ローマ人《自らを Troja 人の後裔と主張したことから》.</div>\r\n","<div class=\"hw\">Trōjānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Troja(人)の</div><div class=\"ex\"><i>equus ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">隠された危険《トロイの木馬の故事から》</span></div><div class=\"ex\">～ <i>judex</i> (<author>O<small>V</small></author>)<span class=\"ext\">(美を競う三女神の審判をつとめた)Paris.</span></div><div class=\"def\"><num>②</num> (Aeneas を通じて)Troja 起源の.</div><div class=\"hw2\"><b>Trōjānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Troja の人々.</div>\r\n","<div class=\"hw\">Trōs</div><div class=\"pos\">-ōis, <i>m</i>(<i>pl</i> Trōes -um(<i>acc</i> -as))</div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Troja 人.</div><div class=\"def\"><num>②</num> 〘伝説〙トロース《Dardanus の孫で Phrygia の王;Troja の名祖》.</div>\r\n","<div class=\"hw\">trūdō</div><div class=\"pos\">-ere trūsī trūsum, <i>tr</i></div><div class=\"def\"><num>①</num> 押す, 押しやる[返す, 上げる].</div><div class=\"def\"><num>②</num> (根を)成長させる;(芽を)出させる.</div><div class=\"def\"><num>③</num> (ある行為・状況へ)追い込む, 駆りたてる</div><div class=\"ex\"><i>in arma trudi</i> (<author>T<small>AC</small></author>)<span class=\"ext\">武器を取ることを強いられる.</span></div><div class=\"def\"><num>④</num> (引き続いて)生じさせる</div><div class=\"ex\"><i>truditur dies die</i> (<author>H<small>OR</small></author>)<span class=\"ext\">一日一日と日は過ぎていく.</span></div>\r\n","<div class=\"hw\">trūsus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://trūdō\">trudo</a>.</div>\r\n","<div class=\"hw\">trūsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://trūdō\">trudo</a>.</div>\r\n","<div class=\"hw\">trūsō</div><div class=\"pos\">-āre, <i>tr freq</i></div><div class=\"ori\">[trudo]</div><div class=\"def\">(性交中の男性が)押し[突き]続ける 〈+<i>dat</i>〉.</div>\r\n","<div class=\"hw\">tua</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"def\">⇒<a href=\"entry://tuum\">tuum</a>.</div>\r\n","<div class=\"hw\">tuba</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> (管のまっすぐな)らっぱ;(祭典・競技・葬儀などで用いられる)らっぱ.</div><div class=\"def\"><num>②</num> けしかけるもの</div><div class=\"ex\"><i>～ belli civilis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">内乱の煽動者.</span></div><div class=\"def\"><num>③</num> (象徴的に)戦を語る勇壮な叙事詩.</div><div class=\"def\"><num>④</num> (水圧揚水機の)管.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘解〙管</div><div class=\"ex\"><i>～ auditiva</i><span class=\"ext\">耳管</span></div><div class=\"ex\"><i>～ uterina</i><span class=\"ext\">卵管.</span></div>\r\n","<div class=\"hw\">Tubantēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">トゥバンテース《Germania 北西部, Rhenus 川東岸にいた一部族》.</div>\r\n","<div class=\"hw\">tuber<SUP>2</SUP></div><div class=\"pos\">-eris, <i>m</i>, <i>f</i></div><div class=\"def\"><num>①</num> (<i>f</i>)〘植〙アザロール《バラ科サンザシ属の低木》.</div><div class=\"def\"><num>②</num> (<i>m</i>)その果実《ビワの実に似る》.</div>\r\n","<div class=\"hw\">tubicen</div><div class=\"pos\">-cinis, <i>m</i></div><div class=\"ori\">[tuba/cano]</div><div class=\"def\">らっぱ手.</div>\r\n","<div class=\"hw\">tubicinō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[↑<a href=\"entry://tubicen\">tubicen</a>]</div><div class=\"def\">らっぱを吹き鳴らす.</div>\r\n","<div class=\"hw\">Tubilustrium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tuba/lustro<SUP>2</SUP>]</div><div class=\"def\">らっぱ清浄祭《3月23日と5月23日に犠牲式に使われたらっぱを清めた》.</div>\r\n","<div class=\"hw\">tubula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[tuba]</div><div class=\"def\">(小さな)らっぱ.</div>\r\n","<div class=\"hw\">tubulus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[tubus]</div><div class=\"def\"><num>①</num> 小さな管;(陶製の)導水管.</div><div class=\"def\"><num>②</num> 金属塊.</div>\r\n","<div class=\"hw\">tubulātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[tubulus]</div><div class=\"def\">導管を作ること, 溝切り.</div>\r\n","<div class=\"hw\">tubulātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://tubulus\">tubulus</a>]</div><div class=\"def\"><num>①</num> 管状の.</div><div class=\"def\"><num>②</num> 導管の付いた.</div>\r\n","<div class=\"hw\">tubur</div><div class=\"pos\">-uris, <i>m</i></div><div class=\"def\">=<a href=\"entry://tuber\">tuber<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">tuburc(h)inābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://tuburcinor\">tuburcinor</a>]</div><div class=\"def\">むさぼり食う, 貪食の.</div>\r\n","<div class=\"hw\">tuburcinor</div><div class=\"pos\">-ārī -ātus sum, <i>tr dep</i></div><div class=\"def\">がつがつ食べる, むさぼり食う</div><div class=\"ex\">(<i>pp</i> を <i>pass</i> に用いて)<i>prandio raptim tuburcinato</i> (<author>A<small>PUL</small></author>)<span class=\"ext\">昼飯をあわただしくかき込むと.</span></div>\r\n","<div class=\"hw\">tubus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>cf. </i> tuba]</div><div class=\"def\"><num>①</num> 管, 導管;導水管.</div><div class=\"def\"><num>②</num> (犠牲式用の)らっぱ(=<a href=\"entry://tuba\">tuba 1</a>).</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘解〙管</div><div class=\"ex\"><i>～ digestorius</i><span class=\"ext\">消化管.</span></div>\r\n","<div class=\"hw\">tubārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[tuba]</div><div class=\"def\">(軍隊)らっぱを作る人.</div>\r\n","<div class=\"hw\">Tucca</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">トゥッカ《ローマ人の家名;特に <i>M. Plotius ～</i>, Vergilius の友人;詩人の没後, 残された叙事詩 <i>Aeneis</i> を Varius とともに公刊した》.</div>\r\n","<div class=\"hw\">Tuccia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">トゥッキア《前3世紀の有名な Vesta の巫女<SUB>みこ</SUB>;純潔の証を立てるために, Tiberis 川の水をふるいに入れて Vesta 神殿まで運んだという》.</div>\r\n","<div class=\"hw\">Tuccius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トゥッキウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">tuccētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ソーセージの一種.</div>\r\n","<div class=\"hw\">Tuder</div><div class=\"pos\">-eris, <i>m</i></div><div class=\"def\">トゥデル《Umbria の Tiberis 川沿いの町;現 Todi》.</div>\r\n","<div class=\"hw\">tudes</div><div class=\"pos\">-ditis, <i>m</i></div><div class=\"def\">金槌, ハンマー.</div>\r\n","<div class=\"hw\">tudicula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↑<a href=\"entry://tudes\">tudes</a>]</div><div class=\"def\">オリーブの実をつぶす器具.</div>\r\n","<div class=\"hw\">tudiculō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↑<a href=\"entry://tudicula\">tudicula</a>]</div><div class=\"def\">たたいてつぶす.</div>\r\n","<div class=\"hw\">tuditō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[tudes]</div><div class=\"def\"><num>①</num> 繰り返してたたく[打つ].</div><div class=\"def\"><num>②</num> (仕事を)どんどん片付ける.</div>\r\n","<div class=\"hw\">tueor</div><div class=\"pos\">-ērī tūtus [tuitus] sum, <i>tr dep</i></div><div class=\"def\"><num>①</num> 見つめる, ながめる;目撃する</div><div class=\"ex\">(副詞的に用いられた <i>adj n pl</i> とともに)<i>leo acerba tuens</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">凶暴な目つきでにらみつけるライオン.</span></div><div class=\"def\"><num>②</num> 見守る;保護[防護]する</div><div class=\"ex\"><i>tua ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私はきみに関わることを見守っている.</span></div><div class=\"def\"><num>③</num> 〘軍〙防禦[防衛]する.</div><div class=\"def\"><num>④</num> (良好な状態に)保つ, 維持[管理]する.</div><div class=\"def\"><num>⑤</num> 面倒を見る, 取り計らう.</div><div class=\"def\"><num>⑥</num> (仕事を)怠らず勤める, (義務を)果たす.</div><div class=\"def\"><num>⑦</num> (人の好意を)肝に銘ずる.</div>\r\n","<div class=\"hw\">tueō</div><div class=\"pos\">-ēre, <i>tr</i></div><div class=\"def\">=<a href=\"entry://tueor\">tueor</a>.</div>\r\n","<div class=\"hw\">tuguriolum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://tugurium\">tugurium</a>]</div><div class=\"def\">小屋.</div>\r\n","<div class=\"hw\">tugurium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tego]</div><div class=\"def\">(掘っ建て)小屋, 茅屋<SUB>ぼうおく</SUB>.</div>\r\n","<div class=\"hw\">tuitiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[tueor]</div><div class=\"def\"><num>①</num> (法的)保護.</div><div class=\"def\"><num>②</num> 《碑》(建物などの)維持, 管理.</div>\r\n","<div class=\"hw\">tuitor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[tueor]</div><div class=\"def\">保護者;管理人.</div>\r\n","<div class=\"hw\">tuitus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://tueor\">tueor</a>.</div>\r\n","<div class=\"hw\">Tulingī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">トゥリンギー《Helvetii 族の近隣にいた一部族》.</div>\r\n","<div class=\"hw\">Tullia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">トゥッリア《 (1) ローマ第6代の王 Servius Tullius の娘で第7代の王 Tarquinius Superbus の妻.(2) Cicero の娘》.</div>\r\n","<div class=\"hw\">Tulliola</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"def\">トゥッリオラ《Cicero の娘の愛称;「かわいい Tullia」 の意》.</div>\r\n","<div class=\"hw\">tullius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 噴流.</div><div class=\"def\"><num>②</num> 滝.</div>\r\n","<div class=\"hw\">Tullius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トゥッリウス《ローマ人の氏族名;特に (1) <i>Servius ～</i> ⇒ <a href=\"entry://Servius\">Servius</a>.(2) <i>M. ～ Cicero</i> ⇒ <a href=\"entry://Cicerō\">Cicero</a>》.</div>\r\n","<div class=\"hw\">Tulliānum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://Tulliānus\">Tulliānus</a>]</div><div class=\"def\">ローマ市の牢獄の地下にあった処刑場《Servius Tullius が造らせたという》.</div>\r\n","<div class=\"hw\">Tulliānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Tullius の.</div><div class=\"def\"><num>②</num> M. Tullius Cicero の;Cicero 風の文体の.</div>\r\n","<div class=\"hw\">Tullus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トゥッルス《 (1) ローマ人の古い個人名;特に <i>～ Hostilius</i>, 第3代の王((伝)在位前672‐641).(2)(後に)ローマ人の家名》.</div>\r\n","<div class=\"hw\">tulī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://ferō\">fero</a>.</div>\r\n","<div class=\"hw\">tum</div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> その時(に), その際(に), その当時</div><div class=\"ex\"><i>vastae ～ in his locis solitudines erant</i> (<author>L<small>IV</small></author>)<span class=\"ext\">当時, このあたり一帯は人気のない荒野が広がっていた</span></div><div class=\"ex\"><i>quando essurio</i>, <i>～ crepant</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">腹ぺこになると(その時, 腹の虫が)グーグー鳴く</span></div><div class=\"ex\">(しばしば vero, demum, denique によって強調されて)<i>～ vero</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">まさにその時</span></div><div class=\"ex\"><i>～ demum [denique]</i> (<author>L<small>IV</small></author> [<author>C<small>IC</small></author>])<span class=\"ext\">ようやくその時, その時初めて.</span></div><div class=\"def\"><num>②</num> それから, そこで, その次に</div><div class=\"ex\"><i>primo ... deinde ... ～ ... postremo</i> (<author>C<small>IC</small></author>)<span class=\"ext\">最初に...次いで...それから...最後に</span></div><div class=\"ex\">(新しい話者を示して)<i>～ Cotta ... inquit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">そこで Cotta が...と言った.</span></div><div class=\"def\"><num>③</num> </div><div class=\"def\"><num1>⒜</num1> ～ ... ～ ある時は...(また別の)ある時は, ...ばかりでなく...もまた</div><div class=\"ex\"><i>mihi ～ hoc ～ illud probabilius videtur</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私にはある時はこれが, またある時はそれがより真実らしく思われる.</span></div><div class=\"def\"><num1>⒝</num1> <i>cum ... ～</i> ...ばかりでなく(とりわけ)...もまた</div><div class=\"ex\"><i>multum cum in omnibus rebus ～ in re militari potest fortuna</i> (<author>C<small>AES</small></author>)<span class=\"ext\">何事においてもそうだが, とりわけ軍事においては大きな影響を及ぼすのは運だ.</span></div>\r\n","<div class=\"hw\">tumba</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">墓, 墓地.</div>\r\n","<div class=\"hw\">tumefacere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://tumefaciō\">tumefacio</a>.</div>\r\n","<div class=\"hw\">tumefaciō</div><div class=\"pos\">-cere -fēcī -factum, <i>tr</i></div><div class=\"ori\">[tumeo/facio]</div><div class=\"def\"><num>①</num> ふくれ上がらせる, ふくらませる.</div><div class=\"def\"><num>②</num> 得意がらせる, 慢心させる.</div>\r\n","<div class=\"hw\">tumefactus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://tumefaciō\">tumefacio</a>.</div>\r\n","<div class=\"hw\">tumefēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tumefaciō\">tumefacio</a>.</div>\r\n","<div class=\"hw\">tumentia<SUP>1</SUP></div><div class=\"pos\">-ōrum, <i>n pl</i>(<i>prp</i>)</div><div class=\"ori\">[tumeo]</div><div class=\"def\">(体の表面の)腫れ.</div><hr><div class=\"hw\">tumentia<SUP>2</SUP></div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://tumeō\">tumeō</a>]</div><div class=\"def\">〘病〙腫脹<SUB>しゅちょう</SUB>.</div>\r\n","<div class=\"hw\">tumescō</div><div class=\"pos\">-ere tumuī, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://tumeō\">tumeō</a>]</div><div class=\"def\"><num>①</num> ふくれ[盛り上がり]始める, ふくれる, 盛り上がる</div><div class=\"ex\"><i>tumescentia vulnera</i> (<author>T<small>AC</small></author>)<span class=\"ext\">ふくれ上がっ(て膿みのたまっ)た傷.</span></div><div class=\"def\"><num>②</num> (怒り・自尊心で)ふくれ上がる.</div><div class=\"def\"><num>③</num> (戦争が)勃発寸前である.</div>\r\n","<div class=\"hw\">tumeō</div><div class=\"pos\">-ēre -muī, <i>intr</i></div><div class=\"def\"><num>①</num> ふくれ(上が)る, はれ(上が)る, 盛り上がる.</div><div class=\"def\"><num>②</num> (水位が)上がる, (波が)高くなる.</div><div class=\"def\"><num>③</num> 激情にかられる, 興奮する.</div><div class=\"def\"><num>④</num> 得意になる, 鼻高々である</div><div class=\"ex\"><i>spe vana tumens</i> (<author>T<small>AC</small></author>)<span class=\"ext\">空しい希望で胸をふくらませて.</span></div><div class=\"def\"><num>⑤</num> (状況が)危険な方向へ進んでいる</div><div class=\"ex\"><i>tument negotia</i> (<author>C<small>IC</small></author>)<span class=\"ext\">大変な事態になりつつある.</span></div><div class=\"def\"><num>⑥</num> 〘修〙誇張されている, 大げさである.</div>\r\n","<div class=\"hw\">tumiditās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://tumidus\">tumidus</a>]</div><div class=\"def\"><num>①</num> 〘病〙腫脹;腫瘍.</div><div class=\"def\"><num>②</num> うぬぼれ, 慢心.</div>\r\n","<div class=\"hw\">tumidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tumeo]</div><div class=\"def\"><num>①</num> ふくれ[盛り]上がった;(水位が)高まった.</div><div class=\"def\"><num>②</num> 激情にかられた, 興奮した.</div><div class=\"def\"><num>③</num> 思い上がった, 鼻高々の</div><div class=\"ex\"><i>successu ～</i> (<author>O<small>V</small></author>)<span class=\"ext\">成功で意気揚々とした.</span></div><div class=\"def\"><num>④</num> (語り口・文体が)誇張された, 大げさな.</div><div class=\"def\"><num>⑤</num> 《詩》ふくらませる</div><div class=\"ex\"><i>～ auster</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">(帆を)ふくらませる南風.</span></div>\r\n","<div class=\"hw\">tumidē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tumidus]</div><div class=\"def\"><num>①</num> 尊大に, うぬぼれて.</div><div class=\"def\"><num>②</num> 誇張された[大げさな]語り口で.</div>\r\n","<div class=\"hw\">tumor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[tumeo]</div><div class=\"def\"><num>①</num> ふくれ[はれ]ていること, ふくらみ;(水位の)高まり</div><div class=\"ex\"><i>turpia facit Palladis ora ～</i> (<author>P<small>ROP</small></author>)<span class=\"ext\">(笛を吹くために頬を)ふくらませると Athena の顔もみにくくなる.</span></div><div class=\"def\"><num>②</num> (体の一部[表面]の)はれ, はれもの, 吹き出物.</div><div class=\"def\"><num>③</num> 激怒, 興奮.</div><div class=\"def\"><num>④</num> うぬぼれ, 高慢.</div><div class=\"def\"><num>⑤</num> 騒然とした事態[状況].</div><div class=\"def\"><num>⑥</num> 〘修〙(語り口・文体・話題の)誇張, 誇大.</div><div class=\"def\"><num>⑦</num> <SUP>◇</SUP>〘病〙腫脹, 腫瘍</div><div class=\"ex\"><i>～ albus</i><span class=\"ext\">白腫</span></div><div class=\"ex\"><i>～ vasculosus</i><span class=\"ext\">血管腫.</span></div>\r\n","<div class=\"hw\">tumultuor</div><div class=\"pos\">-ārī -ātus sum, <i>intr</i>(<i>tr</i>)<i>dep</i></div><div class=\"def\"><num>①</num> 騒ぎたてる, 狼狽<SUB>ろうばい</SUB>する</div><div class=\"ex\">(impers pass)<i>nuntiatur in castris tumultuari</i> (<author>C<small>AES</small></author>)<span class=\"ext\">陣営で大きな物音がするとの報告が届く.</span></div><div class=\"def\"><num>②</num> 暴動を起こす, 武装蜂起する.</div><div class=\"def\"><num>③</num> 混乱させる 〈alqd〉.</div>\r\n","<div class=\"hw\">tumultus</div><div class=\"pos\">-ūs [-ī], <i>m</i></div><div class=\"def\"><num>①</num> 大騒ぎ, 混乱.</div><div class=\"def\"><num>②</num> 暴動, 反乱;不意討ち, 急襲.</div><div class=\"def\"><num>③</num> 嵐.</div><div class=\"def\"><num>④</num> 不安, 困惑, 動揺.</div>\r\n","<div class=\"hw\">tumultuārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tumultus]</div><div class=\"def\"><num>①</num> (兵隊が)大急ぎで徴募された.</div><div class=\"def\"><num>②</num> 間に合わせの, 一時しのぎの.</div><div class=\"def\"><num>③</num> (戦闘が)出会い頭の, 予期しない.</div>\r\n","<div class=\"hw\">tumultuāriē, -āriō</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://tumultuārius\">tumultuārius</a>]</div><div class=\"def\">大急ぎで, あわただしく.</div>\r\n","<div class=\"hw\">tumultuātim</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[tumultus]</div><div class=\"def\">大急ぎで, 行き当たりばったりに.</div>\r\n","<div class=\"hw\">tumultuātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[tumultuor]</div><div class=\"def\"><num>①</num> 騒動, 混乱.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(急に徴募された兵隊の)即席の宣誓.</div>\r\n","<div class=\"hw\">tumultuō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"def\">興奮している, 騒ぎたてる.</div>\r\n","<div class=\"hw\">tumultuōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://tumultus\">tumultus</a>]</div><div class=\"def\"><num>①</num> 騒々しい, 混乱した.</div><div class=\"def\"><num>②</num> 不安を与える, 心配させる.</div>\r\n","<div class=\"hw\">tumultuōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://tumultuōsus\">tumultuōsus</a>]</div><div class=\"def\">騒々しく, 混乱して, 無秩序に.</div>\r\n","<div class=\"hw\">tumulum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">《碑》=<a href=\"entry://tumulus\">tumulus</a>.</div>\r\n","<div class=\"hw\">tumulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 小山, 丘.</div><div class=\"def\"><num>②</num> 塚, 墓</div><div class=\"ex\"><i>～ inanis</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">(亡骸<SUB>なきがら</SUB>を埋めていない)空<SUB>から</SUB>の墓.</span></div>\r\n","<div class=\"hw\">tumulāmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[tumulus]</div><div class=\"def\">《碑》塚, 墓.</div>\r\n","<div class=\"hw\">tumulātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://tumulō\">tumulō</a>]</div><div class=\"def\">埋葬.</div>\r\n","<div class=\"hw\">tumulō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[tumulus]</div><div class=\"def\">塚でおおう, 埋葬する.</div>\r\n","<div class=\"hw\">tumulōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tumulus]</div><div class=\"def\">丘[小山]の多い.</div>\r\n","<div class=\"hw\">tumuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tumeō\">tumeo</a>, <a href=\"entry://tumescō\">tumesco</a>.</div>\r\n","<div class=\"hw\">tunc</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tum]</div><div class=\"def\"><num>①</num> その時.</div><div class=\"def\"><num>②</num> それから, その次に.</div><div class=\"def\"><num>③</num> </div><div class=\"def\"><num1>⒜</num1> </div><div class=\"ex\"><i>jam ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">すでにその時.</span></div><div class=\"def\"><num1>⒝</num1> </div><div class=\"ex\"><i>～ primum</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">その時初めて.</span></div><div class=\"def\"><num1>⒞</num1> </div><div class=\"ex\"><i>～ demum [denique]</i> (<author>S<small>UET</small></author> [<author>V<small>ARR</small></author>])<span class=\"ext\">ようやく[やっと]その時.</span></div>\r\n","<div class=\"hw\">tundō</div><div class=\"pos\">-ere tutudī tūsum [tunsum], <i>tr</i></div><div class=\"def\"><num>①</num> (繰り返し)打つ, たたく</div><div class=\"ex\"><i>pectora manu tundere</i> (<author>O<small>V</small></author>)<span class=\"ext\">(悲しみの表現として)手で胸をぶつ.</span></div><div class=\"def\"><num>②</num> たたいて[打って]粉にする, すりつぶす, 砕く.</div><div class=\"def\"><num>③</num> しつこく要求する, うるさくせがむ.</div>\r\n","<div class=\"hw\">Tungrī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">トゥングリー《Gallia Belgica の現 Liège 付近にいた一部族》.</div>\r\n","<div class=\"hw\">tunica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> トゥニカ, チュニック《ローマ人が用いた貫頭衣;通例, 男性用は半袖で丈は膝まで, 女性用は長袖で丈は足もとまで;正装時には, その上に男は toga, 女は palla などを着用した》.</div><div class=\"def\"><num>②</num> (動植物の器官の)皮膜, 薄膜;(昆虫などの)殻, 外皮.</div>\r\n","<div class=\"hw\">tunicella</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[tunica]</div><div class=\"def\">〘カト〙副助祭の祭服.</div>\r\n","<div class=\"hw\">tunicula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[tunica]</div><div class=\"def\"><num>①</num> 薄手の[短い] tunica.</div><div class=\"def\"><num>②</num> 保護膜, 外皮.</div>\r\n","<div class=\"hw\">tunicātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[tunico]</div><div class=\"def\">tunica を着た</div><div class=\"ex\"><i>～ popellus</i> (<author>H<small>OR</small></author>)<span class=\"ext\">(上衣の toga をまとわず)tunica のみで暮らしている貧乏人ども.</span></div>\r\n","<div class=\"hw\">tunicō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"def\">tunica を着せる.</div>\r\n","<div class=\"hw\">tunsiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tundo]</div><div class=\"def\">打つ[たたく]こと.</div>\r\n","<div class=\"hw\">tunsus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://tundō\">tundo</a>.</div>\r\n","<div class=\"hw\">tuor<SUP>1</SUP></div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[tueor]</div><div class=\"def\">視覚, 視力.</div><hr><div class=\"hw\">tuor<SUP>2</SUP></div><div class=\"pos\">tuī, <i>tr dep</i></div><div class=\"def\">=<a href=\"entry://tueor\">tueor</a>.</div>\r\n","<div class=\"hw\">turba</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 混乱, 騒動, 大騒ぎ.</div><div class=\"def\"><num>②</num> 暴動, 動乱.</div><div class=\"def\"><num>③</num> 群集, 大衆.</div><div class=\"def\"><num>④</num> 群れ, 大群.</div><div class=\"def\"><num>⑤</num> 徒党, 一味;一族, 同族.</div>\r\n","<div class=\"hw\">turben</div><div class=\"pos\">-binis, <i>m</i></div><div class=\"def\">=<a href=\"entry://turbō\">turbo<SUP>2</SUP> 3</a>.</div>\r\n","<div class=\"hw\">turbidulus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj dim</i></div><div class=\"ori\">[turbidus]</div><div class=\"def\">やや困乱した.</div>\r\n","<div class=\"hw\">turbidum<SUP>1</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[turbidus]</div><div class=\"def\">混沌<SUB>こんとん</SUB>とした情勢[時代].</div><hr><div class=\"hw\">turbidum<SUP>2</SUP></div><div class=\"pos\"><i>adv</i>(<i>neut</i>)</div><div class=\"ori\">[↓<a href=\"entry://turbidus\">turbidus</a>]</div><div class=\"def\">混乱して.</div>\r\n","<div class=\"hw\">turbidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[turba]</div><div class=\"def\"><num>①</num> (天候・海などが)嵐の, 荒れた.</div><div class=\"def\"><num>②</num> (液体が)濁った;(大気・光などが)うす暗い, 曇った</div><div class=\"ex\"><i>auro ～ Hermus</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">砂金で濁った Hermus 川.</span></div><div class=\"def\"><num>③</num> 混乱した, 騒がしい.</div><div class=\"def\"><num>④</num> 不穏な動きを見せる, 暴動を起こしそうな.</div><div class=\"def\"><num>⑤</num> 困惑した, 取り乱した;興奮した, 怒った.</div>\r\n","<div class=\"hw\">turbidē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[turbidus]</div><div class=\"def\"><num>①</num> 混乱して, 無秩序に.</div><div class=\"def\"><num>②</num> 反乱を起こそうとして.</div>\r\n","<div class=\"hw\">turbidō<SUP>1</SUP></div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[turbidus]</div><div class=\"def\"><num>①</num> かき回す, 攪拌<SUB>かくはん</SUB>する.</div><div class=\"def\"><num>②</num> 攪乱する, 混乱させる.</div>\r\n","<div class=\"hw\">turbineus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[turbo<SUP>2</SUP>]</div><div class=\"def\">渦を巻いている.</div>\r\n","<div class=\"hw\">turbinātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://turbinātus\">turbinātus</a>]</div><div class=\"def\">円錐形.</div>\r\n","<div class=\"hw\">turbinātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[turbo<SUP>2</SUP>]</div><div class=\"def\">円錐形の.</div>\r\n","<div class=\"hw\">turbistum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">媒染剤.</div>\r\n","<div class=\"hw\">turbulenter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[turbulentus]</div><div class=\"def\">かっとなって, すてばちな気分で.</div>\r\n","<div class=\"hw\">turbulentia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\"><num>①</num> 混乱, 騒動.</div><div class=\"def\"><num>②</num> (水が)濁っていること.</div>\r\n","<div class=\"hw\">turbulentus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[turba]</div><div class=\"def\"><num>①</num> (天候・海などが)嵐の, 荒れた.</div><div class=\"def\"><num>②</num> (水が)濁った.</div><div class=\"def\"><num>③</num> 混乱した, 騒がしい.</div><div class=\"def\"><num>④</num> 不穏な動きを見せる, 治安を乱す.</div><div class=\"def\"><num>⑤</num> 落ちつきのない, 取り乱した;興奮した.</div>\r\n","<div class=\"hw\">turbulentē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[turbulentus]</div><div class=\"def\">粗暴に, 取り乱して.</div>\r\n","<div class=\"hw\">turbāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[turbo<SUP>1</SUP>]</div><div class=\"def\">攪乱<SUB>かくらん</SUB>の手段.</div>\r\n","<div class=\"hw\">turbātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[turbo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 混乱, 無秩序.</div><div class=\"def\"><num>②</num> (心の)動揺, 不安.</div>\r\n","<div class=\"hw\">turbātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[turbo<SUP>1</SUP>]</div><div class=\"def\">(社会・人心を)攪乱する者;煽動者.</div>\r\n","<div class=\"hw\">turbātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[turbo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> (天候・海が)荒れた.</div><div class=\"def\"><num>②</num> 混乱[動揺]した;怒った.</div>\r\n","<div class=\"hw\">turbātē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[turbatus]</div><div class=\"def\">混乱して.</div>\r\n","<div class=\"hw\">turbīdō<SUP>2</SUP>, turbēdō</div><div class=\"pos\">-dinis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[turbo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 嵐.</div><div class=\"def\"><num>②</num> (ビールが)濁っていること.</div>\r\n","<div class=\"hw\">turbō<SUP>1</SUP></div><div class=\"pos\">-āre -āvī -ātus, <i>tr</i>, <i>intr</i></div><div class=\"def\"><num>①</num> 波立たせる, 揺り動かす.</div><div class=\"def\"><num>②</num> 混濁させる;曇らせる.</div><div class=\"def\"><num>③</num> 混乱させる, 騒がす.</div><div class=\"def\"><num>④</num> 反乱[暴動]を起こさせる, 蜂起させる.</div><div class=\"def\"><num>⑤</num> (人心を)動揺させる, 当惑させる;(熱意を)かきたてる, 興奮させる.</div><div class=\"def\"><num>⑥</num> 混乱する[している], 騒ぎ立てる, 暴れまわる</div><div class=\"ex\">(impers pass)<i>si Hispania turbatum esset</i> (<author>C<small>IC</small></author>)<span class=\"ext\">もし Hispania で反乱が起きたら.</span></div><hr><div class=\"hw\">turbō<SUP>2</SUP></div><div class=\"pos\">-binis, <i>m</i></div><div class=\"ori\">[<i>cf. </i> turba]</div><div class=\"def\"><num>①</num> 旋風, 竜巻;暴風, 嵐.</div><div class=\"def\"><num>②</num> 渦巻.</div><div class=\"def\"><num>③</num> こま;錘<SUB>つむ</SUB>, 紡錘<SUB>ぼうすい</SUB>のはずみ車.</div><div class=\"def\"><num>④</num> 旋回[回転](運動), 螺旋<SUB>らせん</SUB>形(の物).</div>\r\n","<div class=\"hw\">turda</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[turdus]</div><div class=\"def\">〘鳥〙ツグミ(雌).</div>\r\n","<div class=\"hw\">Turda</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">トゥルダ《Hispania Tarraconensis の町》.</div>\r\n","<div class=\"hw\">Turdulī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">トゥルドゥリー《Lusitania 南部にいた一部族;その西方に Turdetani 族がいた》.</div>\r\n","<div class=\"hw\">turdus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 〘鳥〙ツグミ(雄).</div><div class=\"def\"><num>②</num> 〘魚〙ベラ.</div>\r\n","<div class=\"hw\">turdārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[turdus]</div><div class=\"def\">ツグミの飼育場.</div>\r\n","<div class=\"hw\">Turdētānia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">トゥルデーターニア《Turdetani 族の居住地》.</div>\r\n","<div class=\"hw\">Turdētānī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">トゥルデーターニー《Hispania Baetica の南部, Baetis(現 Guadalquivir)川の東西両岸地方にいた一部族》.</div>\r\n","<div class=\"hw\">turgescō</div><div class=\"pos\">-ere, <i>intr</i>, <i>tr inch</i></div><div class=\"ori\">[↑<a href=\"entry://turgeō\">turgeō</a>]</div><div class=\"def\"><num>①</num> ふくれ[ふくらみ]始める, ふくれ上がる.</div><div class=\"def\"><num>②</num> 激しく興奮する.</div><div class=\"def\"><num>③</num> (文体が)誇大である, 大げさである.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> ふくらませる.</div>\r\n","<div class=\"hw\">turgeō</div><div class=\"pos\">-ēre tursī, <i>intr</i></div><div class=\"def\"><num>①</num> ふくれる, ふくらむ, ふくらんでいる</div><div class=\"ex\"><i>turgentia lumina</i> (<author>P<small>ROP</small></author>)<span class=\"ext\">(涙で)はれた目.</span></div><div class=\"def\"><num>②</num> ひどく怒っている.</div><div class=\"def\"><num>③</num> (文体が)誇大である, 大げさである.</div>\r\n","<div class=\"hw\">turgidulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://turgidus\">turgidus</a>]</div><div class=\"def\">(目が)はれぼったい.</div>\r\n","<div class=\"hw\">turgidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[turgeo]</div><div class=\"def\"><num>①</num> ふくれた, はれた, 盛り上がった</div><div class=\"ex\"><i>fluvius hiberna nive ～</i> (<author>H<small>OR</small></author>)<span class=\"ext\">冬の雪に水かさを増した川.</span></div><div class=\"def\"><num>②</num> 激情にかられた, 激怒している.</div><div class=\"def\"><num>③</num> (文体が)誇張した, 大げさな.</div>\r\n","<div class=\"hw\">turgiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>m</i></div><div class=\"def\">=<a href=\"entry://turiō\">turio</a>.</div>\r\n","<div class=\"hw\">Turius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トゥリウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">turiō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>cf. </i> turgeo]</div><div class=\"def\">新芽, 若枝.</div>\r\n","<div class=\"hw\">turma</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 騎兵小隊[分隊]《本来は30騎で, ala の <img class=\"font\" src=\"img/B158.png\"> を構成した》.</div><div class=\"def\"><num>②</num> 一群, 一団.</div>\r\n","<div class=\"hw\">turmālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[turma]</div><div class=\"def\"><num>①</num> 騎兵小隊の.</div><div class=\"def\"><num>②</num> 騎士階級[身分]の.</div>\r\n","<div class=\"hw\">turmālēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://turmālis\">turmālis</a>]</div><div class=\"def\">(同じ)騎兵小隊の騎兵たち.</div>\r\n","<div class=\"hw\">turmātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[turma]</div><div class=\"def\"><num>①</num> 騎兵小隊で.</div><div class=\"def\"><num>②</num> 群をなして.</div>\r\n","<div class=\"hw\">Turnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トゥルヌス《 (1) 〘伝説〙Rutuli 族の王;いいなずけの Lavinia をめぐる争いから Aeneas の率いる Troja 人に戦争を仕掛け, Aeneas に討たれた.(2) 諷刺詩作家(1世紀)》.</div>\r\n","<div class=\"hw\">Turonicensis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">Turones 族の.</div>\r\n","<div class=\"hw\">Turonicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://Turonicensis\">Turonicensis</a>.</div>\r\n","<div class=\"hw\">Turonēs</div><div class=\"pos\">-um, <B>Turonī</B> -ōrum, <i>m pl</i></div><div class=\"def\">トゥロネース《Gallia Lugdunensis の Liger(現 Loire)川中流域にいた一部族;Caesarodunum(現 Tours)がその主要な町》.</div>\r\n","<div class=\"hw\">turpe<SUP>1</SUP></div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[turpis]</div><div class=\"def\">恥辱, 不名誉.</div><hr><div class=\"hw\">turpe<SUP>2</SUP></div><div class=\"pos\"><i>adv</i>(<i>neut</i>)</div><div class=\"def\">=<a href=\"entry://turpiter\">turpiter</a>.</div>\r\n","<div class=\"hw\">turpiculus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[turpis]</div><div class=\"def\"><num>①</num> (鼻の形が)やや不格好な.</div><div class=\"def\"><num>②</num> やや下品な.</div>\r\n","<div class=\"hw\">turpificātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[turpis/facio]</div><div class=\"def\">けがれた, 堕落した.</div>\r\n","<div class=\"hw\">Turpilius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トゥルピリウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">turpiloquium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[turpis/loquor]</div><div class=\"def\">卑猥[みだら]な話.</div>\r\n","<div class=\"hw\">turpilucricupidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[turpis/lucrum/cupidus]</div><div class=\"def\">利益を得ることに汲々としている.</div>\r\n","<div class=\"hw\">turpilucris</div><div class=\"pos\">-is -e, <B> -lucrus</B> -a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[turpis/lucrum]</div><div class=\"def\">不正な利益を得る.</div>\r\n","<div class=\"hw\">turpis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\"><num>①</num> 醜い, 不格好な.</div><div class=\"def\"><num>②</num> 恥ずべき, 不道徳な, 面目をそこなう, 不名誉な.</div><div class=\"def\"><num>③</num> みだらな, 卑猥な.</div>\r\n","<div class=\"hw\">turpiter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://turpis\">turpis</a>]</div><div class=\"def\"><num>①</num> 醜く, 不格好に.</div><div class=\"def\"><num>②</num> 不面目に, 卑劣に.</div>\r\n","<div class=\"hw\">turpitūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[turpis]</div><div class=\"def\"><num>①</num> 醜さ, 不格好.</div><div class=\"def\"><num>②</num> 卑劣(な行為), 不道徳;醜行, 非行.</div><div class=\"def\"><num>③</num> 悪評, 不名誉.</div>\r\n","<div class=\"hw\">Turpiō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">トゥルピオー《<i>L. Ambivus ～</i>, Terentius と同時代の喜劇役者》.</div>\r\n","<div class=\"hw\">turpātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://turpō\">turpo</a>.</div>\r\n","<div class=\"hw\">turpēdō, -īdō</div><div class=\"pos\">-dinis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[turpis]</div><div class=\"def\">醜さ;卑劣(な言動).</div>\r\n","<div class=\"hw\">turpō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[turpis]</div><div class=\"def\"><num>①</num> 醜くする;汚す.</div><div class=\"def\"><num>②</num> 名誉を奪う, はずかしめる.</div>\r\n","<div class=\"hw\">turricula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[turris]</div><div class=\"def\"><num>①</num> 小塔.</div><div class=\"def\"><num>②</num> (塔の形をした)さい筒《さいころを入れて振り出す容器》.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 鳩小屋.</div>\r\n","<div class=\"hw\">turrifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[turris/fero]</div><div class=\"def\">=<a href=\"entry://turriger\">turriger 2</a>.</div>\r\n","<div class=\"hw\">turriger</div><div class=\"pos\">-gera -gerum, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://turris\">turris</a>/gero]</div><div class=\"def\"><num>①</num> 塔を持っている;櫓を運ぶ</div><div class=\"ex\"><i>turrigerae urbes</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">塔のそびえ立つ町々.</span></div><div class=\"def\"><num>②</num> (女神 Cybele について)塔のある城壁の形をした冠をいただく.</div>\r\n","<div class=\"hw\">turris</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 塔.</div><div class=\"def\"><num>②</num> (攻城・攻撃・防御用の)櫓<SUB>やぐら</SUB>.</div><div class=\"def\"><num>③</num> 象の背に取り付けた櫓《その中に兵が配備される》.</div><div class=\"def\"><num>④</num> 城, 宮殿</div><div class=\"ex\"><i>regia ～</i> (<author>O<small>V</small></author>)<span class=\"ext\">王城.</span></div><div class=\"def\"><num>⑤</num> 鳩小屋.</div><div class=\"def\"><num>⑥</num> (戦闘隊形としての)方陣.</div>\r\n","<div class=\"hw\">Turrānius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">トゥッラーニウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">turrītus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://turris\">turris</a>]</div><div class=\"def\"><num>①</num> 塔[櫓]のある.</div><div class=\"def\"><num>②</num> 塔のある城壁の形をした冠をいただく(=<a href=\"entry://turriger\">turriger 2</a>).</div><div class=\"def\"><num>③</num> (象が)背に櫓を取り付けられた.</div><div class=\"def\"><num>④</num> 塔のように高くそびえる.</div>\r\n","<div class=\"hw\">tursiō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">〘魚〙イルカの一種.</div>\r\n","<div class=\"hw\">tursī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://turgeō\">turgeo</a>.</div>\r\n","<div class=\"hw\">turtur</div><div class=\"pos\">-uris, <i>m</i>, <i>f</i></div><div class=\"def\"><num>①</num> (<i>m</i>(<i>f</i>))〘鳥〙キジバト(雉鳩).</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(<i>f</i>)</div><div class=\"ex\"><i>～ marina</i> (<author>D<small>ICT</small></author>)<span class=\"ext\">〘魚〙アカエイ(=<a href=\"entry://trȳgōn\">trygon</a>).</span></div>\r\n","<div class=\"hw\">turturilla</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↑<a href=\"entry://turtur\">turtur</a>]</div><div class=\"def\"><num>①</num> コキジバト.</div><div class=\"def\"><num>②</num> 意気地のない男.</div>\r\n","<div class=\"hw\">turunda</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> (ガチョウ肥育用の)粒状の餌.</div><div class=\"def\"><num>②</num> 供物用の菓子の一種.</div><div class=\"def\"><num>③</num> (傷口に入れておく)栓塞<SUB>せんそく</SUB>子.</div>\r\n","<div class=\"hw\">turundus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">=<a href=\"entry://turunda\">turunda 3</a>.</div>\r\n","<div class=\"hw\">Tuscia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[Tuscus]</div><div class=\"def\">=<a href=\"entry://Etrūria\">Etruria</a>.</div>\r\n","<div class=\"hw\">tusculum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[tus]</div><div class=\"def\">わずかの乳香.</div>\r\n","<div class=\"hw\">Tusculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">トゥスクルム《Latium の町;ローマ市の南東24kmの保養地;現 Frascati 付近》.</div>\r\n","<div class=\"hw\">Tusculus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《詩》Tusculum の.</div>\r\n","<div class=\"hw\">Tusculānensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Tusculum の別荘の.</div>\r\n","<div class=\"hw\">Tusculānum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://Tusculānus\">Tusculānus</a>]</div><div class=\"def\">(<i>sc. </i> praedium)Tusculum の別荘;(特に)Cicero の別荘.</div>\r\n","<div class=\"hw\">Tusculānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tusculum の</div><div class=\"ex\"><i>Tusculanae Disputationes</i><span class=\"ext\">「トゥスクルム荘談義」《Cicero の哲学的幸福論;前45年, Tusculum の別荘で著述された》.</span></div>\r\n","<div class=\"hw\">Tuscus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[Tusci]</div><div class=\"def\">Etruria の.</div>\r\n","<div class=\"hw\">Tuscānicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[Tuscia]</div><div class=\"def\">Etruria 風の.</div>\r\n","<div class=\"hw\">Tuscē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[Tuscus]</div><div class=\"def\">Etruria 風に, Etruria 語で.</div>\r\n","<div class=\"hw\">Tuscī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Etruria 人(=<a href=\"entry://Etruscus\">Etrusci</a>).</div>\r\n","<div class=\"hw\">tussicula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[tussis]</div><div class=\"def\">軽い咳.</div>\r\n","<div class=\"hw\">tussiculāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://tussicula\">tussicula</a>]</div><div class=\"def\">咳止めの.</div>\r\n","<div class=\"hw\">tussiculōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tussicula]</div><div class=\"def\">よく咳をする.</div>\r\n","<div class=\"hw\">tussicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tussis]</div><div class=\"def\">咳に苦しむ.</div>\r\n","<div class=\"hw\">tussilāgō</div><div class=\"pos\">-inis, <i>f</i></div><div class=\"ori\">[tussis]</div><div class=\"def\">〘植〙フキタンポポ《咳止めの薬草として用いられた》.</div>\r\n","<div class=\"hw\">tussis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">咳</div><div class=\"ex\"><i>tussi liberari</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">咳がおさまる, 咳をしなくなる.</span></div>\r\n","<div class=\"hw\">tussiō</div><div class=\"pos\">-īre -īvī -ītum, <i>intr</i></div><div class=\"ori\">[↓<a href=\"entry://tussis\">tussis</a>]</div><div class=\"def\">咳をする.</div>\r\n","<div class=\"hw\">tussēdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[tussis]</div><div class=\"def\">しつこい咳.</div>\r\n","<div class=\"hw\">tutudī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tundō\">tundo</a>.</div>\r\n","<div class=\"hw\">tutulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(神官の妻の)高く円錐形に編み上げた髪形;(神官の)円錐形の帽子.</div>\r\n","<div class=\"hw\">tuum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tuus\">tuus</a>]</div><div class=\"def\"><num>①</num> あなたの持ち物[財産].</div><div class=\"def\"><num>②</num> (<i>pl</i>)あなたの書いた物[事柄, 問題].</div>\r\n","<div class=\"hw\">tuus</div><div class=\"pos\">-a -um, <i>adj poss</i></div><div class=\"ori\">[tu]</div><div class=\"def\"><num>①</num> あなた[きみ, おまえ]の.</div><div class=\"def\"><num>②</num> あなたに好意的[好都合, 有利]な</div><div class=\"ex\"><i>tempore non tuo</i> (<author>M<small>ART</small></author>)<span class=\"ext\">おまえの都合の悪い時に.</span></div><div class=\"def\"><num>③</num> あなたの意のままになる;あなた自身を失っていない</div><div class=\"ex\"><i>semper ～</i> (<author>S<small>TAT</small></author>)<span class=\"ext\">あなたは常に自分だけを頼りにして.</span></div><div class=\"def\"><num>④</num> (tui(<i>object gen</i>)の代用)あなたを</div><div class=\"ex\"><i>neque neglegentiā tuā neque odio tuo</i> (<author>T<small>ER</small></author>)<span class=\"ext\">あなたを無視したからでも, あなたを憎んだりしたからでもなく.</span></div>\r\n","<div class=\"hw\">tuxtax</div><div class=\"pos\"><i>int</i></div><div class=\"def\">(鞭打ちの擬音語)ビシッ, バシッ.</div>\r\n","<div class=\"hw\">tuātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tuus]</div><div class=\"def\">きみの流儀[やり方]で.</div>\r\n","<div class=\"hw\">tuī<SUP>1</SUP></div><div class=\"pos\"><i>pron pers</i>(<i>gen</i>)</div><div class=\"def\">⇒<a href=\"entry://tū\">tu</a>.</div><hr><div class=\"hw\">tuī<SUP>2</SUP></div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[tuus]</div><div class=\"def\">あなたの身内[仲間, 部下].</div>\r\n","<div class=\"hw\">Tyana</div><div class=\"pos\">-ōrum, <i>n pl</i>, <B>-a</B> -ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テュアナ《Cappadocia の町》.</div>\r\n","<div class=\"hw\">Tyanaeus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://Tyanēius\">Tyaneius</a>.</div>\r\n","<div class=\"hw\">Tyanēius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tyana の.</div>\r\n","<div class=\"hw\">Tyanī</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>m pl</i></div><div class=\"def\">Tyana の住民.</div>\r\n","<div class=\"hw\">Tyba</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">テュバ《Syria の Cyrrhestica の町》.</div>\r\n","<div class=\"hw\">Tycha</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テュカ《Syracusae 市の一地区;その名はここに運命の女神(ギリシア語で Tychē)の神殿があったことにちなむ》.</div>\r\n","<div class=\"hw\">Tychius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テュキウス, <SUP>*</SUP>-オス《Boeotia の革細工師;大 Ajax の盾の製作者》.</div>\r\n","<div class=\"hw\">tympanicus<SUP>1</SUP></div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tympanum]</div><div class=\"def\">〘解〙鼓膜の, 鼓室の.</div><hr><div class=\"hw\">tympanicus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">tympanites の患者.</div>\r\n","<div class=\"hw\">tympaniolum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[tympanum]</div><div class=\"def\">(Phrygia の)小太鼓.</div>\r\n","<div class=\"hw\">tympanista, -ēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[tympanum]</div><div class=\"def\">太鼓をたたく人.</div>\r\n","<div class=\"hw\">tympanistria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tympanum]</div><div class=\"def\">太鼓をたたく人《女性》.</div>\r\n","<div class=\"hw\">tympanium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">真珠の一種《片面は丸く, もう片面は平たい》.</div>\r\n","<div class=\"hw\">tympanizō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">太鼓をたたく.</div>\r\n","<div class=\"hw\">tympanotriba</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">太鼓たたき《柔弱な男に対する非難のことば》.</div>\r\n","<div class=\"hw\">tympanum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (Cybele の神官, Bacchus の信徒などが用いた)小太鼓, タンバリン《しばしば柔弱な用具と見なされた》.</div><div class=\"def\"><num>②</num> (荷車の)鼓形の車輪;(起重機・揚水装置などの)胴, 円盤.</div><div class=\"def\"><num>③</num> 〘建〙(ペディメントの)三角小間.</div><div class=\"def\"><num>④</num> (戸の)鏡板.</div><div class=\"def\"><num>⑤</num> 〘病〙鼓張, 腹部張満.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP>〘解〙鼓室, 中耳;鼓膜(=membrana tympani).</div>\r\n","<div class=\"hw\">tympanīticus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">tympanites の患者.</div>\r\n","<div class=\"hw\">tympanītis</div><div class=\"pos\">-tidis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tympanum]</div><div class=\"def\">〘病〙鼓室炎, 中耳炎.</div>\r\n","<div class=\"hw\">tympanītēs</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙鼓脹, 腹部張満.</div>\r\n","<div class=\"hw\">Tyndareum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://Tyndaris\">Tyndaris<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">Tyndareus<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テュンダレウス, <SUP>*</SUP>-オス《Sparta の王;Leda の夫で Castor と Pollux, Helena と Clytaemnestra の父》.</div><hr><div class=\"hw\">Tyndareus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> Tyndareus の.</div><div class=\"def\"><num>②</num> 《詩》Sparta の.</div>\r\n","<div class=\"hw\">Tyndaridēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">〘伝説〙</div><div class=\"def\"><num>①</num> Tyndareus の息子(子孫).</div><div class=\"def\"><num>②</num> (<i>pl</i>)Castor と Pollux;Tyndareus のすべての子.</div>\r\n","<div class=\"hw\">Tyndaris<SUP>1</SUP></div><div class=\"pos\">-idis, <i>f</i></div><div class=\"def\">〘伝説〙Tyndareus の娘(=<a href=\"entry://Helena\">Helena</a> か <a href=\"entry://Clytaem(n)ēstra\">Clytaemnestra</a>).</div><hr><div class=\"hw\">Tyndaris<SUP>2</SUP></div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テュンダリス《Sicilia 島北岸の町》.</div>\r\n","<div class=\"hw\">Tyndaritānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tyndaris<SUP>2</SUP> の.</div><div class=\"hw2\"><b>Tyndaritānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Tyndaris<SUP>2</SUP> の住民.</div>\r\n","<div class=\"hw\">Tyndarius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Tyndareus\">Tyndareus<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">Tyndarus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Tyndareus\">Tyndareus<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">typanum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://tympanum\">tympanum</a>.</div>\r\n","<div class=\"hw\">typhlon</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘解〙盲腸(=<a href=\"entry://caecum\">intestinum caecum</a>).</div>\r\n","<div class=\"hw\">typhlītis</div><div class=\"pos\">-tidis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘病〙盲腸炎(=<a href=\"entry://appendicītis\">appendicitis</a>).</div>\r\n","<div class=\"hw\">typhlōsis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘医〙盲目, 失明.</div>\r\n","<div class=\"hw\">Typhōeus<SUP>1</SUP></div><div class=\"pos\">-eī [-eos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙テュポーエウス《巨人の一人;Juppiter に雷電で打ち殺され, Aetna 火山の下に埋められた》.</div><hr><div class=\"hw\">Typhōeus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Typhoeus の.</div>\r\n","<div class=\"hw\">Typhōis</div><div class=\"pos\">-idis [-idos], <i>adj f</i></div><div class=\"def\">=<a href=\"entry://Typhōeus\">Typhoeus<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">Typhōius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Typhōeus\">Typhoeus<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">typicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 典型的な, 象徴的な, 比喩的な.</div><div class=\"def\"><num>②</num> 間欠的な.</div>\r\n","<div class=\"hw\">typicē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[typicus]</div><div class=\"def\">象徴的に, 比喩的に.</div>\r\n","<div class=\"hw\">typicī</div><div class=\"pos\">-ōrum, <SUP>◇</SUP><i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://typicus\">typicus</a>]</div><div class=\"def\">〘病〙間欠熱で苦しんでいる人々.</div>\r\n","<div class=\"hw\">typographia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">印刷(術).</div>\r\n","<div class=\"hw\">typographicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">印刷の.</div>\r\n","<div class=\"hw\">typographus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">印刷(業)者.</div>\r\n","<div class=\"hw\">typus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> (壁面を飾る)浮彫り.</div><div class=\"def\"><num>②</num> (測量士の)平面図.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘医〙(間欠熱の)規則的な発熱と解熱の繰返し;病型.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 典型, 象徴.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘カト〙前表, 予示.</div>\r\n","<div class=\"hw\">Tyra</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">=<a href=\"entry://Tyrās\">Tyras</a>.</div>\r\n","<div class=\"hw\">tyranna</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tyrannus]</div><div class=\"def\">女性の専制君主.</div>\r\n","<div class=\"hw\">tyrannicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 僭主政治の.</div><div class=\"def\"><num>②</num> 暴虐な, 専制的な.</div>\r\n","<div class=\"hw\">tyrannicē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tyrannicus]</div><div class=\"def\">暴君のように, 専制的に.</div>\r\n","<div class=\"hw\">tyrannicīda</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[tyrannus/caedo]</div><div class=\"def\">僭主[暴君]殺害者.</div>\r\n","<div class=\"hw\">tyrannicīdium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://tyrannicīda\">tyrannicīda</a>]</div><div class=\"def\">僭主殺害.</div>\r\n","<div class=\"hw\">tyrannis</div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 僭主政治;僭主政治が行なわれている地域.</div><div class=\"def\"><num>②</num> 暴政, 虐政.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> =<a href=\"entry://tyranna\">tyranna</a>.</div>\r\n","<div class=\"hw\">Tyranniō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テュランニオー(ン)《ギリシアの地理・文法学者;Cicero, Caesar らの友人》.</div>\r\n","<div class=\"hw\">tyrannoctonus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://tyrannicīda\">tyrannicida</a>.</div>\r\n","<div class=\"hw\">tyrannopolīta</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">専制君主の従属民.</div>\r\n","<div class=\"hw\">tyrannus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 王, 支配者.</div><div class=\"def\"><num>②</num> (ギリシアのポリスで非合法に政権を握った)僭主<SUB>せんしゅ</SUB>;(<i>pl</i>)三十人僭主《前404年に Athenae に樹立された政権》.</div><div class=\"def\"><num>③</num> 専制君主, 独裁者, 暴君.</div>\r\n","<div class=\"hw\">tyrianthina</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://tyrianthinus\">tyrianthinus</a>]</div><div class=\"def\">tyrianthinus 色に染めた衣服.</div>\r\n","<div class=\"hw\">tyrianthinus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">紫がかった深紅色の.</div>\r\n","<div class=\"hw\">Tyrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Tyrus(人)の</div><div class=\"ex\"><i>Tyria puella</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Eurōpa\">Europa</a>.</span></div><div class=\"def\"><num>②</num> (アクキガイ(murex)から採った)紫がかった深紅色染料の;その染料で染められた.</div><div class=\"def\"><num>③</num> 《詩》(Cadmus が創建した)Thebae の.</div><div class=\"def\"><num>④</num> 《詩》(Dido が創建した)Carthago の</div><div class=\"ex\"><i>～ ductor</i> (<author>S<small>IL</small></author>)<span class=\"ext\">=<a href=\"entry://Hannibal\">Hannibal</a>.</span></div>\r\n","<div class=\"hw\">Tyriī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://Tyrius\">Tyrius</a>]</div><div class=\"def\"><num>①</num> Tyrus の住民.</div><div class=\"def\"><num>②</num> 《詩》Thebae の人々.</div><div class=\"def\"><num>③</num> 《詩》Carthago 人たち.</div>\r\n","<div class=\"hw\">Tyrrhus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘伝説〙テュッルス《Latinus 王の家畜番》.</div>\r\n","<div class=\"hw\">Tyrrhēnia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://Etrūria\">Etruria</a>.</div>\r\n","<div class=\"hw\">Tyrr(h)ēnicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">=<a href=\"entry://Tyrr(h)ēnus\">Tyrrhenus 1</a>.</div>\r\n","<div class=\"hw\">Tyrr(h)ēnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Tyrrhenia(=<a href=\"entry://Etrūria\">Etruria</a>)の</div><div class=\"ex\"><i>Tyrrhenum mare</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">ティレニア海.</span></div><div class=\"def\"><num>②</num> 《詩》ローマ[イタリア]の.</div><div class=\"def\"><num>③</num> </div><div class=\"ex\"><i>～ piscis</i> (<author>S<small>EN</small></author>)<span class=\"ext\">イルカ《Bacchus がティレニア海の海賊をイルカに変身させたとの神話から》.</span></div>\r\n","<div class=\"hw\">Tyrrhēnī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テュッレーニー《Tyrrhenia(=<a href=\"entry://Etrūria\">Etruria</a>)の人々》.</div>\r\n","<div class=\"hw\">Tyrrhīdae</div><div class=\"pos\">-ārum, <i>m pl</i></div><div class=\"def\">〘伝説〙Tyrrhus の息子たち.</div>\r\n","<div class=\"hw\">Tyrtaeus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">テュルタエウス, <SUP>*</SUP>-タイオス《尚武詩で名高い Sparta の詩人(前7世紀)》.</div>\r\n","<div class=\"hw\">Tyrus, -os</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テュルス, <SUP>*</SUP>-ロス, 〘聖〙ツロ《Phoenicia の商都で海港;鮮やかな紫がかった深紅色染料で有名;現 Sur》.</div>\r\n","<div class=\"hw\">Tyrās</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テュラース《Sarmatia の川;現 Dniester》.</div>\r\n","<div class=\"hw\">Tȳdeus</div><div class=\"pos\">-eī [-eos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テューデウス《Calydon の王 Oeneus の息子で Diomedes の父;Thebae 攻めの七将の一人》.</div>\r\n","<div class=\"hw\">Tȳdēius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tydeus(の子孫)の.</div>\r\n","<div class=\"hw\">Tȳdīdēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">Tydeus の息子(=<a href=\"entry://Diomēdēs\">Diomedes</a>).</div>\r\n","<div class=\"hw\">Tȳnēs</div><div class=\"pos\">-ētis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テューネース《Africa の沿岸の町;現 Tunis》.</div>\r\n","<div class=\"hw\">tȳphus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> はれ, むくみ.</div><div class=\"def\"><num>②</num> 傲慢, 不遜.</div><div class=\"def\"><num>③</num> 〘病〙チフス</div><div class=\"ex\"><i>～ abdominalis</i><span class=\"ext\">腸チフス</span></div><div class=\"ex\"><i>～ exanthematicus</i><span class=\"ext\">発疹チフス.</span></div>\r\n","<div class=\"hw\">tȳphōn</div><div class=\"pos\">-ōnis [-ōnos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 激しい旋風, 台風.</div><div class=\"def\"><num>②</num> 彗星の一つ.</div>\r\n","<div class=\"hw\">Tȳphōn</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テューポーン(=<a href=\"entry://Typhōeus\">Typhoeus<SUP>1</SUP></a>).</div>\r\n","<div class=\"hw\">Tȳphōneus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Typhon(=<a href=\"entry://Typhōeus\">Typhoeus<SUP>1</SUP></a>)の.</div>\r\n","<div class=\"hw\">tȳphōnicus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[typhon]</div><div class=\"def\">旋風の, 台風の.</div>\r\n","<div class=\"hw\">tȳropatina</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>Gk</i>▷τυρ<img class=\"font\" src=\"img/A152.png\"><img class=\"font\" src=\"img/A153.png\">◁/patina]</div><div class=\"def\">チーズケーキの一種.</div>\r\n","<div class=\"hw\">tȳrotarīchum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">塩漬け魚とチーズの料理(=質素な食事).</div>\r\n","<div class=\"hw\">tābefacere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://tābefaciō\">tabefacio</a>.</div>\r\n","<div class=\"hw\">tābefaciō</div><div class=\"pos\">-cere -fēcī -factum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[tabes/facio]</div><div class=\"def\"><num>①</num> 溶かす, 溶解させる.</div><div class=\"def\"><num>②</num> 弱める.</div>\r\n","<div class=\"hw\">tābefactus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://tābefaciō\">tabefacio</a>.</div>\r\n","<div class=\"hw\">tābefēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tābefaciō\">tabefacio</a>.</div>\r\n","<div class=\"hw\">tābescō</div><div class=\"pos\">-ere -buī, <i>intr inch</i></div><div class=\"ori\">[tabeo]</div><div class=\"def\"><num>①</num> 溶ける;融解する.</div><div class=\"def\"><num>②</num> 腐る, 分解する.</div><div class=\"def\"><num>③</num> 衰弱[憔悴]する, やつれる.</div>\r\n","<div class=\"hw\">tābeō</div><div class=\"pos\">-ēre, <i>intr</i></div><div class=\"ori\">[tabes]</div><div class=\"def\"><num>①</num> 衰える, 弱くなる, 細る.</div><div class=\"def\"><num>②</num> 滴<SUB>したた</SUB>る.</div>\r\n","<div class=\"hw\">tābidulus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://tābidus\">tābidus</a>]</div><div class=\"def\">衰弱[消滅]させる.</div>\r\n","<div class=\"hw\">tābidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tabeo]</div><div class=\"def\"><num>①</num> 腐りかけた, 溶けかかった.</div><div class=\"def\"><num>②</num> 衰弱[憔悴]した.</div><div class=\"def\"><num>③</num> 衰弱させる.</div>\r\n","<div class=\"hw\">tābidōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tabidus]</div><div class=\"def\">腐った, 腐る.</div>\r\n","<div class=\"hw\">tābificus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tabes/facio]</div><div class=\"def\"><num>①</num> 腐敗させる, 溶解させる.</div><div class=\"def\"><num>②</num> 衰弱させる.</div>\r\n","<div class=\"hw\">tābificābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://tābificō\">tābificō</a>]</div><div class=\"def\">衰弱[憔悴]させる.</div>\r\n","<div class=\"hw\">tābificō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[tabes/facio]</div><div class=\"def\">消耗[衰弱]させる.</div>\r\n","<div class=\"hw\">tābifluus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tabes/fluo]</div><div class=\"def\"><num>①</num> 腐りつつある.</div><div class=\"def\"><num>②</num> 消耗[衰弱]させる.</div>\r\n","<div class=\"hw\">tābitūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[tabidus]</div><div class=\"def\"><num>①</num> 衰弱.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 朽ちる[滅びる]こと.</div>\r\n","<div class=\"hw\">tābum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tabeo]</div><div class=\"def\"><num>①</num> 膿<SUB>うみ</SUB>, 血膿;(流れ出た)血, 血糊.</div><div class=\"def\"><num>②</num> (染料として用いられた紫貝の)液汁.</div><div class=\"def\"><num>③</num> 疾病.</div>\r\n","<div class=\"hw\">tābuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://tābescō\">tabesco</a>.</div>\r\n","<div class=\"hw\">tābēs</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\"><num>①</num> 腐敗, 分解.</div><div class=\"def\"><num>②</num> 腐ったもの, 溶け[にじみ]出たもの</div><div class=\"ex\"><i>～ sanguinis</i> (<author>L<small>IV</small></author>)<span class=\"ext\">血の海</span></div><div class=\"ex\"><i>～ liquescentis nivis</i> (<author>L<small>IV</small></author>)<span class=\"ext\">雪どけのぬかるみ.</span></div><div class=\"def\"><num>③</num> 病気, 疾病.</div><div class=\"def\"><num>④</num> 堕落, 退廃.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘病〙癆<SUB>ろう</SUB>.</div>\r\n","<div class=\"hw\">tālea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 棒, 杭<SUB>くい</SUB></div><div class=\"ex\"><i>～ ferrea</i> (<author>C<small>AES</small></author>)<span class=\"ext\">(Britannia で硬貨の代わりに用いられた)鉄の棒.</span></div><div class=\"def\"><num>②</num> 挿し木, 接<SUB>つ</SUB>ぎ木.</div>\r\n","<div class=\"hw\">tāliatūra</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">割れ目, 裂け目.</div>\r\n","<div class=\"hw\">tālipedō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[talus/pes]</div><div class=\"def\">(足が)ふらつく.</div>\r\n","<div class=\"hw\">tālipēs</div><div class=\"pos\">-edis, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[talus/pes]</div><div class=\"def\">〘医〙湾足.</div>\r\n","<div class=\"hw\">tālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\"><num>①</num> この[その]ような, こんな[そんな]性質[種類]の</div><div class=\"ex\"><i>talia dicta</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">そのような発言.</span></div><div class=\"def\"><num>②</num> これ[それ]ほどすぐれた[重要な, 悪い, ひどい]</div><div class=\"ex\"><i>pro tali facinore</i> (<author>C<small>AES</small></author>)<span class=\"ext\">これほどの(憎むべき)悪行の報いに.</span></div><div class=\"def\"><num>③</num> 前述の.</div><div class=\"def\"><num>④</num> 次に述べる, 以下の.</div><div class=\"def\"><num>⑤</num> (qualis, ut, qui, ac [atque] とともに)</div><div class=\"ex\"><i>non esse eum talem qualem putassem</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼は私が思っていたような人物ではない</span></div><div class=\"ex\"><i>tales nos esse putamus ut jure laudemur</i> (<author>C<small>IC</small></author>)<span class=\"ext\">われわれは自分をほめられて当然のような人間と思っている</span></div><div class=\"ex\"><i>faxo(=faciam)tali eum mactatum atque hic est infortunio</i> (<author>T<small>ER</small></author>)<span class=\"ext\">そんな奴はこいつと同じように災難で痛めつけてやる.</span></div>\r\n","<div class=\"hw\">tāliscumque</div><div class=\"pos\">tāliscumque tālecumque, <i>adj</i></div><div class=\"def\">ほぼそのような(性質の).</div>\r\n","<div class=\"hw\">tāliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[talis]</div><div class=\"def\">そのよう(な具合)に.</div>\r\n","<div class=\"hw\">tālitrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[talus]</div><div class=\"def\">指ではじくこと.</div>\r\n","<div class=\"hw\">tāliō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[talis]</div><div class=\"def\">〘法〙タリオ, 同害報復, 同罪刑.</div>\r\n","<div class=\"hw\">tālocrūrālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙距腿の.</div>\r\n","<div class=\"hw\">tālonāviculāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙距舟の.</div>\r\n","<div class=\"hw\">tālus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> くるぶし, 足首;〘解〙距骨.</div><div class=\"def\"><num>②</num> (動物の距骨で作った)さいころ;(<i>pl</i>)さいころ遊び.</div>\r\n","<div class=\"hw\">tālāria</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://tālāris\">tālāris</a>]</div><div class=\"def\"><num>①</num> くるぶし, 足首.</div><div class=\"def\"><num>②</num> (Mercurius, Perseus などが履く)翼のついた靴[サンダル].</div><div class=\"def\"><num>③</num> (くるぶしまで届く)長衣.</div><div class=\"def\"><num>④</num> 足かせ.</div>\r\n","<div class=\"hw\">tālāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[talus]</div><div class=\"def\"><num>①</num> くるぶしまで届く.</div><div class=\"def\"><num>②</num> 足首についた.</div><div class=\"def\"><num>③</num> =<a href=\"entry://tālārius\">talarius</a>.</div>\r\n","<div class=\"hw\">tālārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[talus]</div><div class=\"def\">(長衣を着て踊る)低俗な演芸の.</div>\r\n","<div class=\"hw\">tāminō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"def\">よごす;けがす.</div>\r\n","<div class=\"hw\">Tāygeta<SUP>1</SUP></div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"def\">=<a href=\"entry://Tāygetus\">Taygetus</a>.</div>\r\n","<div class=\"hw\">Tāygetus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ターユゲトゥス, <SUP>*</SUP>-ゲトン《Laconia の山脈;Messenia との境をなす》.</div>\r\n","<div class=\"hw\">Tāygetē</div><div class=\"pos\">-ēs, <B>-a<SUP>2</SUP></B> -ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙ターユゲテー《Pleiades7姉妹の一人》.</div>\r\n","<div class=\"hw\">tē</div><div class=\"pos\"><i>pron pers</i>(<i>acc</i>, <i>abl</i>)</div><div class=\"def\">⇒<a href=\"entry://tū\">tu</a>.</div>\r\n","<div class=\"hw\">tēcum</div><div class=\"def\">=cum te.</div>\r\n","<div class=\"hw\">tēda</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://taeda\">taeda</a>.</div>\r\n","<div class=\"hw\">tēgula<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://tegō\">tegō</a>]</div><div class=\"def\"><num>①</num> (屋根)瓦.</div><div class=\"def\"><num>②</num> (特に <i>pl</i>)(瓦)屋根.</div><div class=\"def\"><num>③</num> (<i>pl</i>)(壁の)化粧タイル.</div><hr><div class=\"hw\">tēgula<SUP>2</SUP></div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">揚げ物なべ, フライパン.</div>\r\n","<div class=\"hw\">tēgulum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tego]</div><div class=\"def\">屋根葺き;屋根.</div>\r\n","<div class=\"hw\">tēgulārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tegula<SUP>1</SUP>]</div><div class=\"def\">瓦(造り)の.</div><hr><div class=\"hw\">tēgulārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">瓦師, 瓦屋.</div>\r\n","<div class=\"hw\">Tēius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Teos の.</div><div class=\"hw2\"><b>Tēiī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Teos の住民.</div>\r\n","<div class=\"hw\">tēla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<<SUP>*</SUP>texla(texo)]</div><div class=\"def\"><num>①</num> 織物, 布.</div><div class=\"def\"><num>②</num> くもの巣.</div><div class=\"def\"><num>③</num> (織物の)縦糸.</div><div class=\"def\"><num>④</num> 織機, 機<SUB>はた</SUB>.</div><div class=\"def\"><num>⑤</num> 策略, 計略.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP>〘解〙組織</div><div class=\"ex\"><i>～ choroidea</i><span class=\"ext\">(脳室の)脈絡組織.</span></div>\r\n","<div class=\"hw\">Tēleboae</div><div class=\"pos\">-ārum [-um], <i>m pl</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テーレボアエ, <SUP>*</SUP>-アイ《Acarnania の一部族;後に Capreae 島に植民した》.</div>\r\n","<div class=\"hw\">Tēlegonus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テーレゴヌス, <SUP>*</SUP>-ノス《Ulixes と Circe の息子;それと知らずに父を殺した;Tusculum の建設者といわれる》.</div>\r\n","<div class=\"hw\">Tēlemachus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テーレマクス, <SUP>*</SUP>-コス《Ulixes と Penelope の息子》.</div>\r\n","<div class=\"hw\">Tēlemus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テーレムス, <SUP>*</SUP>-モス《Cyclopes の一人 Polyphemus に Ulixes が彼を盲目にすると告げた予言者》.</div>\r\n","<div class=\"hw\">Tēlephus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テーレプス, <SUP>*</SUP>-ポス《Mysia の王;Hercules と Tegea の Minerva の巫女 Auge の息子;Achilles の槍で傷つけられたが, そのさびで癒やされた》.</div>\r\n","<div class=\"hw\">tēlinum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">コロハ(telis)から製する高価な香油.</div>\r\n","<div class=\"hw\">tēlis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘植〙コロハ《マメ科の一年草;種子は芳香があり薬用》.</div>\r\n","<div class=\"hw\">tēlum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 飛び道具《矢・投げ槍・石など》.</div><div class=\"def\"><num>②</num> 武器;(特に)槍, 剣.</div><div class=\"def\"><num>③</num> 稲妻;陽光.</div><div class=\"def\"><num>④</num> 男根(=membrum virile).</div>\r\n","<div class=\"hw\">Tēmniī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Tēmnītēs\">Temnitae</a>.</div>\r\n","<div class=\"hw\">Tēmnos</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テームノス《Aeolis の町》.</div>\r\n","<div class=\"hw\">Tēmnītēs</div><div class=\"pos\">-ae, <i>adj m</i></div><div class=\"def\">Temnos の.</div><div class=\"hw2\"><b>Tēmnītae</b></div><div class=\"pos2\">-ārum, <i>m pl</i></div><div class=\"def2\">Temnos の住民.</div>\r\n","<div class=\"hw\">tēmulenter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[temulentus]</div><div class=\"def\">酔酊して.</div>\r\n","<div class=\"hw\">tēmulentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://tēmulentus\">tēmulentus</a>]</div><div class=\"def\">酩酊.</div>\r\n","<div class=\"hw\">tēmulentus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">酔っ払った, 酩酊した.</div>\r\n","<div class=\"hw\">tēmētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">強い酒;(水で割ってない生の)ぶどう酒.</div>\r\n","<div class=\"hw\">tēmō<SUP>1</SUP></div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\"><num>①</num> 轅<SUB>ながえ</SUB>, 梶棒.</div><div class=\"def\"><num>②</num> (細長い)棒.</div><div class=\"def\"><num>③</num> (T-)〘天〙大熊座.</div>\r\n","<div class=\"hw\">tēnesmus, -os</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘病〙しぶり腹.</div>\r\n","<div class=\"hw\">Tēniī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Tenos の住民.</div>\r\n","<div class=\"hw\">Tēnos, -us</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">テーノス《Cyclades 諸島の一つ》.</div>\r\n","<div class=\"hw\">Tēreidēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙Tereus の息子(=<a href=\"entry://Itys\">Itys</a>).</div>\r\n","<div class=\"hw\">Tērentīnus, Tērēt-</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">ローマの Tere(n)tina 部族の.</div>\r\n","<div class=\"hw\">Tēreus</div><div class=\"pos\">-eī [eos], <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙テーレウス《Thracia の王;Philomela の姉 Procne の夫;Philomela を犯したために妻によって息子 Itys の肉を食わされ, ヤツガシラ(epops)に変えられた》.</div>\r\n","<div class=\"hw\">tēter</div><div class=\"pos\">-tra -trum, <i>adj</i></div><div class=\"def\">=<a href=\"entry://taeter\">taeter</a>.</div>\r\n","<div class=\"hw\">tēthea</div><div class=\"pos\">-ae, <i>f</i>, <B>tētheon</B> -ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘動〙ホヤ《原索動物》.</div>\r\n","<div class=\"hw\">Tēthys</div><div class=\"pos\">-yos, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘神話〙テーテュス《海の女神;Oceanus の妻》.</div><div class=\"def\"><num>②</num> 海, 大洋.</div>\r\n","<div class=\"hw\">tībia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 笛, 葦笛.</div><div class=\"def\"><num>②</num> 〘解・動〙脛骨.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘昆〙脛節.</div>\r\n","<div class=\"hw\">tībiofībulāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙脛腓の.</div>\r\n","<div class=\"hw\">tībionāviculāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙脛舟の.</div>\r\n","<div class=\"hw\">tībizō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"def\">=<a href=\"entry://tībīcinō\">tibicino 1</a>.</div>\r\n","<div class=\"hw\">tībiāle</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tībiālis\">tībiālis</a>]</div><div class=\"def\">脚絆<SUB>きゃはん</SUB>, すね当て.</div>\r\n","<div class=\"hw\">tībiālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[tibia]</div><div class=\"def\"><num>①</num> 笛用の.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙脛骨の.</div>\r\n","<div class=\"hw\">tībiārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[tibia]</div><div class=\"def\">《碑》笛商人;笛作り.</div>\r\n","<div class=\"hw\">Tībur</div><div class=\"pos\">-uris, <i>n</i></div><div class=\"def\">ティーブル《ローマ市の東約30km の Anio 河畔の町;別荘地として有名;現 Tivoli》.</div>\r\n","<div class=\"hw\">Tīburnus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tibur の.</div><hr><div class=\"hw\">Tīburnus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ティーブルヌス《Tibur の伝説上の創建者》.</div>\r\n","<div class=\"hw\">Tīburs</div><div class=\"pos\">-urtis, <i>adj</i></div><div class=\"def\">Tibur の.</div><div class=\"hw2\"><b>Tīburtēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Tibur の住民.</div>\r\n","<div class=\"hw\">Tīburtus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Tīburnus\">Tiburnus<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">Tīburtīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[Tiburtinus]</div><div class=\"def\">(<i>sc. </i> via)ティーブル街道《Roma から Tibur に到る道路》.</div>\r\n","<div class=\"hw\">Tīburtīnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://Tīburtīnus\">Tīburtīnus</a>]</div><div class=\"def\">Tibur にある別荘.</div>\r\n","<div class=\"hw\">Tīburtīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tibur の.</div>\r\n","<div class=\"hw\">tībīcen</div><div class=\"pos\">-cinis, <i>m</i></div><div class=\"ori\">[tibia/cano]</div><div class=\"def\"><num>①</num> 笛を吹く人.</div><div class=\"def\"><num>②</num> (建物の)支柱.</div>\r\n","<div class=\"hw\">tībīcina</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://tībīcen\">tībīcen</a>]</div><div class=\"def\">笛を吹く人《女性》.</div>\r\n","<div class=\"hw\">tībīcinium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tibicen]</div><div class=\"def\">笛を吹くこと, 笛の練習.</div>\r\n","<div class=\"hw\">tībīcināria</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tibicen]</div><div class=\"def\">笛の吹奏法.</div>\r\n","<div class=\"hw\">tībīcinō</div><div class=\"pos\">-āre -āvī, <SUP>◇</SUP><i>intr</i>, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[tibicen]</div><div class=\"def\"><num>①</num> 笛を吹く.</div><div class=\"def\"><num>②</num> (建物に)支柱を付ける.</div>\r\n","<div class=\"hw\">tībīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tibia]</div><div class=\"def\">笛の.</div>\r\n","<div class=\"hw\">Tīcīnensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Ticinus 川の.</div>\r\n","<div class=\"hw\">Tīcīnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ティーキーヌム《Gallia Cisalpina の Ticinus 河畔の町;Padus 川との合流点に近い;現 Pavia;この近くでローマ軍が Hannibal に大敗した(前218)》.</div>\r\n","<div class=\"hw\">Tīcīnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ティーキーヌス《Gallia Cisalpina の川;Padus 川の支流;現 Ticino》.</div>\r\n","<div class=\"hw\">Tīfernum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ティーフェルヌム《 (1) Umbria 北部の Tiberis 河畔の町.(2) Umbria の Metaurus 河畔の町.(3) Samnium の町》.</div>\r\n","<div class=\"hw\">Tīfernus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ティーフェルヌス《 (1) Samnium の山;現 Matese.(2)  (1) に発してアドリア海に注ぐ川;現 Biferno》.</div>\r\n","<div class=\"hw\">Tīfernātēs</div><div class=\"pos\">-um [-ium], <i>m pl</i></div><div class=\"def\">Tifernum (1)  (2) の住民.</div>\r\n","<div class=\"hw\">Tīfāta</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"def\">ティーファータ《Campania の Capua 北方の山;山腹に Diana 神殿があった》.</div>\r\n","<div class=\"hw\">Tīfātīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">《碑》Tifata 山の《Diana の添え名》.</div>\r\n","<div class=\"hw\">Tīmaeus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティーマエウス, <SUP>*</SUP>-マイオス《 (1) 南イタリアの Locri Epizephyrii 出身の Pythagoras 学派哲学者;Plato の対話篇 ‘Timaeus' の主要登場人物.(2) Sicilia 島の Tauromenium 出身のギリシアの歴史家(前356?‐?260)》.</div>\r\n","<div class=\"hw\">Tīmanthēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティーマンテース《Cythnus 島出身のギリシアの画家(前5世紀後半)》.</div>\r\n","<div class=\"hw\">Tīmocratēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティーモクラテース《Epicurus 学派の哲学者(前3世紀)》.</div>\r\n","<div class=\"hw\">Tīmoleontēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Timoleon の.</div>\r\n","<div class=\"hw\">Tīmoleōn</div><div class=\"pos\">-ontis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティーモレオーン《Corinthus の将軍(前334? 没);Syracusae の僭主 Dionysius II を追放して市民を救った》.</div>\r\n","<div class=\"hw\">Tīmomachus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティーモマクス, <SUP>*</SUP>-コス《Byzantium の画家(前1世紀)》.</div>\r\n","<div class=\"hw\">Tīmosthenēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティーモステネース《エジプト王 Ptolemaeus II の艦隊司令官(前3世紀)》.</div>\r\n","<div class=\"hw\">Tīmotheus</div><div class=\"pos\">-eī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティーモテウス, <SUP>*</SUP>-オス《 (1) Conon の息子;Athenae の将軍(前354没).(2) Miletus 生まれの音楽家(前450頃‐360頃).(3) <SUP>◇</SUP>〘聖〙パウロの弟子のテモテ》.</div>\r\n","<div class=\"hw\">Tīmāgenēs</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティーマーゲネース《Alexandria 出身の修辞学者・歴史家;Augustus 帝の時代にローマで活躍した》.</div>\r\n","<div class=\"hw\">Tīmōn</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティーモーン《Pericles 時代の Athenae 人;「人間ぎらい」 として有名》.</div>\r\n","<div class=\"hw\">Tīmōnēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Timon の[にふさわしい].</div>\r\n","<div class=\"hw\">tīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">(首の長い, ふた付きの)酒瓶<SUB>びん</SUB>.</div>\r\n","<div class=\"hw\">tīnus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"def\">〘植〙ガマズミ属の常緑低木.</div>\r\n","<div class=\"hw\">Tīphys</div><div class=\"pos\">-yos, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ティーピュス《Argo 船の舵手》.</div>\r\n","<div class=\"hw\">Tīresiās</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘伝説〙ティーレシアース, <SUP>*</SUP>テイレ-《Thebae の盲目の予言者》.</div>\r\n","<div class=\"hw\">Tīridātēs</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティーリダーテース《Armenia の数人の王の名》.</div>\r\n","<div class=\"hw\">tīruncula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://tīrunculus\">tīrunculus</a>]</div><div class=\"def\"><num>①</num> (初めて子を産んだ)雌犬.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘キ教〙新帰依者《女性》.</div>\r\n","<div class=\"hw\">tīrunculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[tiro]</div><div class=\"def\"><num>①</num> 初心者, 新米;新兵.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘キ教〙洗礼志願者, 公教要理受講者.</div>\r\n","<div class=\"hw\">Tīryns</div><div class=\"pos\">Tirynthis [-os], <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティーリュンス, <SUP>∥</SUP>ティリンス《Argolis の古い町;Hercules はここで育ったという》.</div>\r\n","<div class=\"hw\">Tīrynthia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://Tīrynthius\">Tīrynthius<SUP>1</SUP></a>]</div><div class=\"def\">=<a href=\"entry://Herculēs\">Hercules</a> の母 <a href=\"entry://Alcmēna\">Alcmena</a>.</div>\r\n","<div class=\"hw\">Tīrynthius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tiryns の;Hercules の.</div><div class=\"hw2\"><b>Tīrynthiī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Tiryns の住民.</div><hr><div class=\"hw\">Tīrynthius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Herculēs\">Hercules</a>.</div>\r\n","<div class=\"hw\">tīrō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\"><num>①</num> 新兵.</div><div class=\"def\"><num>②</num> 初心者, 新米 〈in re〉.</div><div class=\"def\"><num>③</num> 成年に達したばかりの若者.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘キ教〙洗礼志願者, 公教要理受講者.</div>\r\n","<div class=\"hw\">Tīrō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">ティーロー《<i>M. Tullius ～</i>, Cicero の学識ある解放奴隷》.</div>\r\n","<div class=\"hw\">tīrōcinium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tiro]</div><div class=\"def\"><num>①</num> 新兵であること;新兵.</div><div class=\"def\"><num>②</num> 未経験, 未熟, 新米[見習い]であること.</div><div class=\"def\"><num>③</num> 初めての試み 〈alcis rei〉.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘キ教〙洗礼志願期, 公教要理受講期間.</div>\r\n","<div class=\"hw\">Tīsaeum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティーサエウム, <SUP>*</SUP>-サイオン《Thessalia の山》.</div>\r\n","<div class=\"hw\">Tīsiphonē</div><div class=\"pos\">-ēs, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙ティーシポネー《Furiae の一人;「殺人の復讐者」 の意》.</div>\r\n","<div class=\"hw\">Tīsiphonēus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tisiphone の.</div>\r\n","<div class=\"hw\">Tīsiās</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティーシアース《Sicilia 島生まれの弁論術教師(前5世紀初)》.</div>\r\n","<div class=\"hw\">Tīthōnia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘神話〙Tithonus の妻(=あけぼのの女神 Aurora).</div>\r\n","<div class=\"hw\">Tīthōnis</div><div class=\"pos\">-idos [-idis], <i>f</i></div><div class=\"def\">=<a href=\"entry://Tīthōnia\">Tithonia</a>.</div>\r\n","<div class=\"hw\">Tīthōnius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Tithonus の</div><div class=\"ex\"><i>～ ortus</i> (<author>G<small>ERM</small></author>)<span class=\"ext\">夜明け, あけぼの.</span></div>\r\n","<div class=\"hw\">Tīthōnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">〘神話〙ティートーヌス, <SUP>*</SUP>-ノス《Laomedon の息子で Aurora の夫;不死の生命を与えられたが, 永遠の若さの約束を取りつけていなかったため, 老いさらばえていつまでも生きている彼を女神はセミ(蝉)に変えたという》.</div>\r\n","<div class=\"hw\">tītillus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">=<a href=\"entry://tītillātiō\">titillatio</a>.</div>\r\n","<div class=\"hw\">tītillāmentum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">=<a href=\"entry://tītillātiō\">titillatio</a>.</div>\r\n","<div class=\"hw\">tītillātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[titillo]</div><div class=\"def\">くすぐること;快感, 快い刺激.</div>\r\n","<div class=\"hw\">tītillātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">=<a href=\"entry://tītillātiō\">titillatio</a>.</div>\r\n","<div class=\"hw\">tītillō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\">くすぐる;快く刺激する, 快感を与える.</div>\r\n","<div class=\"hw\">tītivillītium, -cium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">無価値な[くだらぬ]もの.</div>\r\n","<div class=\"hw\">tītyrus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">鈴付き雄羊《首に鈴を付けて群れを導く》.</div>\r\n","<div class=\"hw\">Tītyrus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">ティーテュルス, <SUP>*</SUP>-ロス《Vergilius の <i>Eclogae</i> 「牧歌」 に登場する牧人の名;Vergilius の 「牧歌」 また Vergilius その人も指す》.</div>\r\n","<div class=\"hw\">Tītān</div><div class=\"pos\">-nos [-nis], <B>Tītānus</B> -ī, <i>m</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> Titanes の一人《特に太陽神 Sol(Hyperion の子);Prometheus(Iapetus の子)》.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘天〙タイタン《土星の第6衛星》.</div>\r\n","<div class=\"hw\">Tītānes</div><div class=\"pos\">-um, <B>Tītānī</B> -ōrum, <i>m pl</i></div><div class=\"def\">ティーターネス《Uranus(Caelus)と Gaea(Tellus)から生まれた巨人神族;その一人の Cronos(Saturnus)の子 Zeus(Juppiter)らから成る Olympus の神々と戦い, 敗れて Tartarus に幽閉された》.</div>\r\n","<div class=\"hw\">Tītānia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[Titan]</div><div class=\"def\">〘神話〙Titanes の女系子孫《Latona, Pyrrha, Diana, Circe のいずれか》.</div>\r\n","<div class=\"hw\">Tītāniacus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Tītānius\">Titanius<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">Tītānis<SUP>1</SUP></div><div class=\"pos\">-idis [-idos], <i>adj f</i></div><div class=\"def\"><num>①</num> Titanes の一人(女神)の.</div><div class=\"def\"><num>②</num> Titanes の女系子孫の.</div><hr><div class=\"hw\">Tītānis<SUP>2</SUP></div><div class=\"pos\">-idis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://Tītānis\">Tītānis<SUP>1</SUP></a>]</div><div class=\"def\">Titanes の女系子孫《Circe, Diana のいずれか》.</div>\r\n","<div class=\"hw\">Tītānius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Titanes の;Titanes の血を引く.</div><hr><div class=\"hw\">Tītānius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">Titanes の子孫(=太陽神 Sol).</div>\r\n","<div class=\"hw\">tōficius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tofus]</div><div class=\"def\">凝灰岩のような.</div>\r\n","<div class=\"hw\">tōfus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘鉱〙凝灰岩.</div>\r\n","<div class=\"hw\">tōfāceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tofus]</div><div class=\"def\">凝灰岩の.</div>\r\n","<div class=\"hw\">tōfīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://tōfāceus\">tofaceus</a>.</div>\r\n","<div class=\"hw\">tōfōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://tōfus\">tōfus</a>]</div><div class=\"def\">凝灰岩のように小孔の多い.</div>\r\n","<div class=\"hw\">tōlēs</div><div class=\"pos\">-ium, <i>f pl</i></div><div class=\"def\">〘病〙甲状腺腫(=<a href=\"entry://strūma\">struma</a>).</div>\r\n","<div class=\"hw\">tōmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>cf. </i> tumeo]</div><div class=\"def\">(クッション用の)詰め物.</div>\r\n","<div class=\"hw\">tōmix</div><div class=\"pos\">-icis, <i>f</i></div><div class=\"def\">=<a href=\"entry://thōmix\">thomix</a>.</div>\r\n","<div class=\"hw\">tōph-</div><div class=\"def\">⇒tof-.</div>\r\n","<div class=\"hw\">tōsilla, tōsillae</div><div class=\"def\">⇒<a href=\"entry://tonsilla\">tonsilla</a>, <a href=\"entry://tonsillae\">tonsillae</a>.</div>\r\n","<div class=\"hw\">tōtum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tōtus\">tōtus</a>]</div><div class=\"def\">全体, 全部</div><div class=\"ex\"><i>ex toto</i> (<author>S<small>EN</small></author>)<span class=\"ext\">完全に, すっかり</span></div><div class=\"ex\"><i>in toto</i> (<author>C<small>IC</small></author>)<span class=\"ext\">だいたい, 概して</span></div><div class=\"ex\"><i>in ～</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">全く, 全然.</span></div>\r\n","<div class=\"hw\">tōtus</div><div class=\"pos\">-a -um(<i>gen</i> -tīus, <i>dat</i> -tī), <i>adj</i></div><div class=\"def\"><num>①</num> 全体[全部]の</div><div class=\"ex\"><i>sex menses totos</i> (<author>T<small>ER</small></author>)<span class=\"ext\">まるまる6か月間</span></div><div class=\"ex\"><i>totā nocte</i> (<author>C<small>AES</small></author>)<span class=\"ext\">一晩中.</span></div><div class=\"def\"><num>②</num> (人について)心からの, 没頭している</div><div class=\"ex\"><i>sum ～ vester</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私は身も心もあなた方のものです</span></div><div class=\"ex\"><i>in prece ～ eram</i> (<author>O<small>V</small></author>)<span class=\"ext\">私は一心不乱に祈っていた.</span></div><div class=\"def\"><num>③</num> 完全[完璧]な, 欠陥のない</div><div class=\"ex\"><i>tota libertas</i> (<author>T<small>AC</small></author>)<span class=\"ext\">完全な自由.</span></div>\r\n","<div class=\"hw\">tōtālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[totus]</div><div class=\"def\">全体の.</div>\r\n","<div class=\"hw\">tōtāliter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://tōtālis\">tōtālis</a>]</div><div class=\"def\">全く, すっかり.</div>\r\n","<div class=\"hw\">tōtē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"def\">=<a href=\"entry://tōtāliter\">totaliter</a>.</div>\r\n","<div class=\"hw\">tū</div><div class=\"pos\">(<i>gen</i> tuī, <i>dat</i> tib<img class=\"font\" src=\"img/A130.png\">, <i>acc</i>, <i>abl</i> tē, <i>pl nom</i>, <i>acc</i> vōs, <i>gen</i> vestrum, vestrī, <i>dat</i>, <i>abl</i> vōbīs), <i>pron pers</i></div><div class=\"def\">(二人称)あなた, きみ, おまえ.</div>\r\n","<div class=\"hw\">tūber<SUP>1</SUP></div><div class=\"pos\">-eris, <i>n</i></div><div class=\"def\"><num>①</num> こぶ, できもの, 腫れもの.</div><div class=\"def\"><num>②</num> (木の)こぶ;塊茎.</div><div class=\"def\"><num>③</num> 〘植〙フランスショウロ(松露).</div><div class=\"def\"><num>④</num> 〘植〙</div><div class=\"ex\"><i>～ terrae</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">(a) =3; (b) シクラメン.</span></div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘解〙隆起, 結節</div><div class=\"ex\"><i>～ calcanei</i><span class=\"ext\">踵骨隆起</span></div><div class=\"ex\"><i>～ parietale</i><span class=\"ext\">頭頂結節.</span></div>\r\n","<div class=\"hw\">tūberculum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[tuber<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> (小さな)こぶ, はれもの, 突起(物).</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙(小)結節.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘植〙小塊茎.</div>\r\n","<div class=\"hw\">tūberculōsis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tuber<SUP>1</SUP>]</div><div class=\"def\">〘病〙結核</div><div class=\"ex\"><i>～ pulmonalis</i><span class=\"ext\">肺結核(=<a href=\"entry://phthisis\">phthisis</a>).</span></div>\r\n","<div class=\"hw\">tūberō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[tuber<SUP>1</SUP>]</div><div class=\"def\">ふくらむ.</div>\r\n","<div class=\"hw\">Tūberō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">トゥーベロー《Aelia 氏族に属する家名》.</div>\r\n","<div class=\"hw\">tūberōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tuber<SUP>1</SUP>]</div><div class=\"def\">こぶの多い.</div>\r\n","<div class=\"hw\">tūfa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">かぶとの羽根飾りの一種.</div>\r\n","<div class=\"hw\">tūn</div><div class=\"def\">=tune(⇒ <a href=\"entry://tū\">tu</a>, <a href=\"entry://-ne\">-ne</a>).</div>\r\n","<div class=\"hw\">Tūnēs</div><div class=\"pos\">-ētis, <i>m</i></div><div class=\"def\">=<a href=\"entry://Tȳnēs\">Tynes</a>.</div>\r\n","<div class=\"hw\">tūreus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tus]</div><div class=\"def\">乳香の</div><div class=\"ex\"><i>turea virga</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">乳香の採れる木.</span></div>\r\n","<div class=\"hw\">Tūria</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">トゥーリア《Hispania Tarraconensis の川(現名同じ);Valentia(現 Valencia)で海に注ぐ》.</div>\r\n","<div class=\"hw\">tūribulum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[tus]</div><div class=\"def\"><num>①</num> 香炉.</div><div class=\"def\"><num>②</num> (T-)〘天〙祭壇座(=<a href=\"entry://āra\">Ara</a>).</div>\r\n","<div class=\"hw\">tūricremus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tus/cremo]</div><div class=\"def\">香をたく.</div>\r\n","<div class=\"hw\">Tūriensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Turia 川の.</div>\r\n","<div class=\"hw\">tūrifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[tus/fero]</div><div class=\"def\"><num>①</num> 乳香を産する.</div><div class=\"def\"><num>②</num> 乳香が捧げられた.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>(キリスト教の神以外の神々に)香を捧げる, 偶像崇拝の.</div>\r\n","<div class=\"hw\">tūrificātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[turifico]</div><div class=\"def\">香を捧げること.</div>\r\n","<div class=\"hw\">tūrificātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://tūrificō\">tūrificō</a>]</div><div class=\"def\">(キリスト教の神以外の神々に)香を捧げる者, 偶像崇拝者.</div>\r\n","<div class=\"hw\">tūrificō</div><div class=\"pos\">-āre -āvī, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[tus/facio]</div><div class=\"def\">香をたく[捧げる], 偶像を崇拝する.</div>\r\n","<div class=\"hw\">tūrilegus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[tus/lego<SUP>2</SUP>]</div><div class=\"def\">乳香を集める.</div>\r\n","<div class=\"hw\">tūrinum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tūrinus\">tūrinus</a>]</div><div class=\"def\">《碑》乳香から作られた眼病用軟膏.</div>\r\n","<div class=\"hw\">tūrinus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tus]</div><div class=\"def\">乳香の.</div>\r\n","<div class=\"hw\">Tūrium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://Tūria\">Turia</a>.</div>\r\n","<div class=\"hw\">tūrābulum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[tus]</div><div class=\"def\">(宗教的儀式用の)吊り香炉.</div>\r\n","<div class=\"hw\">tūrārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[tus]</div><div class=\"def\">香をたくときに使用される.</div><hr><div class=\"hw\">tūrārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">《碑》乳香商人.</div>\r\n","<div class=\"hw\">tūs</div><div class=\"pos\">tūris, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 香, 乳香.</div><div class=\"def\"><num>②</num> 〘植〙</div><div class=\"ex\"><i>～ terrae</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">キランソウ(=<a href=\"entry://chamaepitys\">chamaepitys</a>).</span></div>\r\n","<div class=\"hw\">tūsillae, tussillae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘解〙扁桃腺(=<a href=\"entry://tonsillae\">tonsillae</a>).</div>\r\n","<div class=\"hw\">tūsus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://tundō\">tundo</a>.</div>\r\n","<div class=\"hw\">tūte<SUP>1</SUP></div><div class=\"pos\"><i>pron pers</i></div><div class=\"ori\">[tu/-te]</div><div class=\"def\">《強意形》あなた自身.</div>\r\n","<div class=\"hw\">tūtemet</div><div class=\"pos\"><i>pron pers</i></div><div class=\"ori\">[tu/-te/-met]</div><div class=\"def\">《強意形》まさしくあなた自身.</div>\r\n","<div class=\"hw\">tūticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">公けの</div><div class=\"ex\"><i>meddix ～</i> (<author>L<small>IV</small></author>)<span class=\"ext\">(Osci 人の)最高長官.</span></div>\r\n","<div class=\"hw\">tūtor<SUP>1</SUP></div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[tueor]</div><div class=\"def\"><num>①</num> 保護者, 番人.</div><div class=\"def\"><num>②</num> 〘法〙後見人.</div><hr><div class=\"hw\">tūtor<SUP>2</SUP></div><div class=\"pos\">-ārī -ātus sum, <i>tr dep freq</i></div><div class=\"ori\">[tueor]</div><div class=\"def\"><num>①</num> 守る, 保護する;防衛する 〈alqm [alqd] a re;contra [adversus, ad] alqd〉.</div><div class=\"def\"><num>②</num> (代理[弁護]人として)弁護する, 擁護する.</div><div class=\"def\"><num>③</num> ...に備えて警戒[用心]する, 回避する</div><div class=\"ex\"><i>praesentem inopiam tutabatur</i> (<author>C<small>AES</small></author>)<span class=\"ext\">彼は目下の窮状を打開しようとした.</span></div>\r\n","<div class=\"hw\">tūtrix</div><div class=\"pos\">-īcis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[tutor<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 〘法〙代理人《女性》.</div><div class=\"def\"><num>②</num> 保護[擁護]者《女性》.</div>\r\n","<div class=\"hw\">tūtum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://tūtus\">tūtus</a>]</div><div class=\"def\">安全, 安全な場所[立場].</div>\r\n","<div class=\"hw\">tūtus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[tueor]</div><div class=\"def\"><num>①</num> 危険[危害]から守られた, 安全な, 確かな 〈(a)re;adversus [ad] alqd〉</div><div class=\"ex\"><i>tutae aures</i> (<author>H<small>OR</small></author>)<span class=\"ext\">秘密のもれない耳.</span></div><div class=\"def\"><num>②</num> 警戒[用心]している;安心している.</div>\r\n","<div class=\"hw\">tūtāmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[tutor<SUP>2</SUP>]</div><div class=\"def\">防備, 守り, 頼みの綱.</div>\r\n","<div class=\"hw\">tūtāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://tūtāmen\">tutamen</a>.</div>\r\n","<div class=\"hw\">tūtātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[tutor<SUP>2</SUP>]</div><div class=\"def\">防衛者, 守り手.</div>\r\n","<div class=\"hw\">tūtātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://tūtor\">tutor<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">tūtē<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[tutus]</div><div class=\"def\">安全に, 無事に, 確実に.</div>\r\n","<div class=\"hw\">tūtēla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[tueor]</div><div class=\"def\"><num>①</num> 保護, 庇護, 監督</div><div class=\"ex\"><i>tutelam januae gerere</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">入口の見張りをする.</span></div><div class=\"def\"><num>②</num> 養育;(動物の)飼育.</div><div class=\"def\"><num>③</num> (建物の)保存, 維持, 管理.</div><div class=\"def\"><num>④</num> 保護者;守護神.</div><div class=\"def\"><num>⑤</num> 後見(人の役目)</div><div class=\"ex\"><i>in suam tutelam venire</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(被後見者が)自分の財産を管理できるようになる, 成年に達する.</span></div><div class=\"def\"><num>⑥</num> 被後見人(の財産).</div>\r\n","<div class=\"hw\">tūtēlāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://tūtēla\">tūtēla</a>]</div><div class=\"def\"><num>①</num> 保護の.</div><div class=\"def\"><num>②</num> 〘法〙後見の.</div>\r\n"]);
